window.STUDY_DATA = {"meta":{"title":"Ngân hàng câu hỏi Lịch sử Đảng Cộng sản Việt Nam","source":"https://github.com/nhulsd-creator/ontaptthcm-lsd","sourcePage":"https://nhulsd-creator.github.io/ontaptthcm-lsd/","commit":"37aace003f06a10a8746ecd7be02e565dd352382","retrievedAt":"2026-11-06","total":793,"note":"Giữ nguyên câu hỏi, lựa chọn, đáp án và giải thích từ nguồn. Các câu có nội dung tương tự vẫn giữ lại theo mã gốc."},"chapters":[{"id":"mo-dau","name":"Chương mở đầu","title":"Bắt đầu từ nền tảng","description":"Đối tượng, chức năng, nhiệm vụ và phương pháp nghiên cứu.","range":"Nhập môn","sections":["mo-dau"],"color":"sage","number":"00"},{"id":"ch1","name":"Chương 1","title":"Đảng ra đời & giành chính quyền","description":"Đảng Cộng sản Việt Nam ra đời và lãnh đạo đấu tranh giành chính quyền.","range":"1930 – 1945","sections":["ch1-1","ch1-2"],"color":"peach","number":"01"},{"id":"ch2","name":"Chương 2","title":"Đấu tranh giành độc lập, thống nhất","description":"Lãnh đạo hai cuộc kháng chiến, bảo vệ và thống nhất đất nước.","range":"1945 – 1975","sections":["ch2-1","ch2-2"],"color":"lavender","number":"02"},{"id":"ch3","name":"Chương 3","title":"Xây dựng đất nước & Đổi mới","description":"Cả nước quá độ lên chủ nghĩa xã hội và thực hiện công cuộc Đổi mới.","range":"1975 – nay","sections":["ch3-1","ch3-2"],"color":"sand","number":"03"}],"sections":{"mo-dau":"Chương mở đầu","ch1-1":"Chương 1 · Phần I","ch1-2":"Chương 1 · Phần II","ch2-1":"Chương 2 · Phần I","ch2-2":"Chương 2 · Phần II","ch3-1":"Chương 3 · Phần I","ch3-2":"Chương 3 · Phần II"},"questions":[{"id":1,"section":"mo-dau","q":"Đảng Cộng sản Việt Nam do ai sáng lập và vào thời điểm nào?","options":["Chủ tịch Hồ Chí Minh sáng lập, ngày 3/2/1930","Tổng Bí thư Trần Phú sáng lập, tháng 10/1930","Nguyễn Thái Học sáng lập, ngày 25/12/1927","Tổng Bí thư Lê Hồng Phong sáng lập, năm 1935"],"answer":0,"explain":"Đảng Cộng sản Việt Nam do Chủ tịch Hồ Chí Minh sáng lập ngày 3/2/1930."},{"id":2,"section":"mo-dau","q":"Đối tượng nghiên cứu của khoa học Lịch sử Đảng Cộng sản Việt Nam là gì?","options":["Sự ra đời, phát triển và hoạt động lãnh đạo của Đảng","Chỉ hệ thống văn kiện của các kỳ Đại hội Đảng","Chỉ quá trình đấu tranh vũ trang của lực lượng quân đội","Lịch sử tư tưởng chính trị của các giai cấp ở Việt Nam"],"answer":0,"explain":"Đối tượng nghiên cứu là sự ra đời, phát triển và hoạt động lãnh đạo của Đảng qua các thời kỳ lịch sử."},{"id":3,"section":"mo-dau","q":"Lịch sử Đảng Cộng sản Việt Nam là một chuyên ngành thuộc bộ phận khoa học nào?","options":["Khoa học lịch sử","Khoa học chính trị","Kinh tế chính trị học","Xã hội học chính trị"],"answer":0,"explain":"Lịch sử Đảng Cộng sản Việt Nam là một chuyên ngành, một bộ phận của khoa học lịch sử."},{"id":4,"section":"mo-dau","q":"Ai là tác giả tác phẩm \"Sơ thảo lịch sử phong trào cộng sản Đông Dương\" (1933)?","options":["Hồng Thế Công (Hà Huy Tập)","Trường Chinh (Đặng Xuân Khu)","Trần Phú (Tổng Bí thư đầu tiên)","Lê Duẩn (Bí thư thứ nhất)"],"answer":0,"explain":"Năm 1933, Hồng Thế Công (tức Hà Huy Tập) công bố tác phẩm Sơ thảo lịch sử phong trào cộng sản Đông Dương."},{"id":5,"section":"mo-dau","q":"Đại hội nào của Đảng đã nêu rõ nhiệm vụ nghiên cứu, tổng kết lịch sử Đảng?","options":["Đại hội III (1960)","Đại hội II (1951)","Đại hội IV (1976)","Đại hội VI (1986)"],"answer":0,"explain":"Đại hội đại biểu toàn quốc lần thứ III của Đảng (1960) đã nêu rõ nhiệm vụ nghiên cứu, tổng kết lịch sử Đảng."},{"id":6,"section":"mo-dau","q":"Cơ quan chuyên trách nghiên cứu, biên soạn lịch sử Đảng được thành lập năm nào và tên gọi ban đầu là gì?","options":["Năm 1962, Ban Nghiên cứu Lịch sử Đảng Trung ương","Năm 1951, Ban Tuyên huấn Trung ương Đảng Lao động","Năm 1953, Viện Nghiên cứu Sử học Trung ương","Năm 1975, Ban Nghiên cứu Lý luận của Trung ương"],"answer":0,"explain":"Năm 1962, cơ quan chuyên trách là Ban Nghiên cứu Lịch sử Đảng Trung ương được thành lập (nay là Viện Lịch sử Đảng)."},{"id":7,"section":"mo-dau","q":"Chức năng nào KHÔNG thuộc ba chức năng cơ bản của khoa học Lịch sử Đảng?","options":["Chức năng lập pháp","Chức năng nhận thức","Chức năng giáo dục","Chức năng dự báo và phê phán"],"answer":0,"explain":"Ba chức năng cơ bản là nhận thức, giáo dục, dự báo và phê phán; không có chức năng lập pháp."},{"id":8,"section":"mo-dau","q":"Trong tác phẩm \"Lịch sử nước ta\" (1942), Hồ Chí Minh đã dự báo điều gì?","options":["Năm 1945 Việt Nam độc lập","Năm 1954 thắng lợi Điện Biên Phủ","Năm 1975 thống nhất đất nước","Năm 1930 Đảng được thành lập"],"answer":0,"explain":"Năm 1942, trong tác phẩm Lịch sử nước ta, Hồ Chí Minh dự báo: \"Năm 1945 Việt Nam độc lập\"."},{"id":9,"section":"mo-dau","q":"Chủ tịch Hồ Chí Minh khẳng định phẩm chất của Đảng ta như thế nào?","options":["\"Đảng ta là đạo đức, là văn minh\"","\"Đảng ta là trí tuệ, là lương tâm\"","\"Đảng ta là sức mạnh, là niềm tin\"","\"Đảng ta là kỷ luật, là sức chiến đấu\""],"answer":0,"explain":"Hồ Chí Minh khẳng định: \"Đảng ta là đạo đức, là văn minh\"."},{"id":10,"section":"mo-dau","q":"Nhiệm vụ hàng đầu của khoa học Lịch sử Đảng là gì?","options":["Trình bày có hệ thống Cương lĩnh, đường lối của Đảng","Biên soạn hệ thống sách giáo khoa cho bậc phổ thông","Nghiên cứu lịch sử thế giới cận đại và hiện đại","Xây dựng hệ thống bảo tàng lịch sử trong cả nước"],"answer":0,"explain":"Nhiệm vụ hàng đầu là trình bày có hệ thống, khẳng định, chứng minh giá trị khoa học và hiện thực của Cương lĩnh, đường lối của Đảng."},{"id":11,"section":"mo-dau","q":"Hai phương pháp cơ bản trong nghiên cứu khoa học Lịch sử Đảng là gì?","options":["Phương pháp lịch sử và phương pháp logic","Phương pháp định tính và phương pháp định lượng","Phương pháp so sánh và phương pháp thống kê","Phương pháp quy nạp và phương pháp diễn dịch"],"answer":0,"explain":"Khoa học lịch sử và chuyên ngành Lịch sử Đảng sử dụng hai phương pháp cơ bản: phương pháp lịch sử và phương pháp logic."},{"id":12,"section":"mo-dau","q":"Phương pháp lịch sử trong nghiên cứu Lịch sử Đảng có đặc điểm gì?","options":["Tái hiện tiến trình với tính cụ thể, sinh động, quanh co","Chỉ tập trung vào các con số thống kê của từng thời kỳ","Bỏ qua bối cảnh không gian, thời gian của sự kiện lịch sử","Chỉ sử dụng tài liệu của nước ngoài để trình bày sự kiện"],"answer":0,"explain":"Phương pháp lịch sử là cách thức tìm hiểu, trình bày quá trình phát triển với đầy đủ tính cụ thể, sinh động, quanh co của các sự vật, hiện tượng."},{"id":13,"section":"mo-dau","q":"Phương pháp logic trong nghiên cứu lịch sử Đảng nhằm mục đích gì?","options":["Vạch ra bản chất, quy luật, khuynh hướng chung của hiện tượng lịch sử","Chỉ liệt kê các sự kiện lịch sử theo đúng trình tự thời gian diễn ra của chúng","Ghi chép chi tiết tiểu sử từng nhân vật lịch sử tiêu biểu trong mỗi thời kỳ","Sao chép nguyên văn các văn kiện của Đảng qua các kỳ Đại hội toàn quốc"],"answer":0,"explain":"Phương pháp logic nghiên cứu các hiện tượng lịch sử trong hình thức tổng quát nhằm vạch ra bản chất, quy luật, khuynh hướng chung."},{"id":14,"section":"mo-dau","q":"Nền tảng tư tưởng, kim chỉ nam cho hành động của Đảng Cộng sản Việt Nam là gì?","options":["Chủ nghĩa Mác - Lênin và tư tưởng Hồ Chí Minh","Chủ nghĩa dân tộc và chủ nghĩa dân chủ tư sản","Chủ nghĩa Tam dân và học thuyết Tôn Trung Sơn","Chủ nghĩa tự do và chủ nghĩa thực dụng phương Tây"],"answer":0,"explain":"Đảng lấy chủ nghĩa Mác - Lênin và tư tưởng Hồ Chí Minh làm nền tảng tư tưởng, kim chỉ nam cho hành động."},{"id":15,"section":"mo-dau","q":"Môn học Lịch sử Đảng Cộng sản Việt Nam dành cho bậc đại học hệ không chuyên lý luận chính trị được phân bổ bao nhiêu tín chỉ?","options":["2 tín chỉ (30 tiết giảng lý thuyết)","3 tín chỉ (45 tiết giảng lý thuyết)","4 tín chỉ (60 tiết giảng lý thuyết)","1 tín chỉ (15 tiết giảng lý thuyết)"],"answer":0,"explain":"Đối với bậc đại học hệ không chuyên lý luận chính trị, môn học được phân bổ 2 tín chỉ (30 tiết giảng lý thuyết)."},{"id":16,"section":"mo-dau","q":"Nội dung môn học Lịch sử Đảng (hệ không chuyên) tập trung vào mấy thời kỳ nổi bật?","options":["3 thời kỳ","2 thời kỳ","4 thời kỳ","5 thời kỳ"],"answer":0,"explain":"Chương trình tập trung nghiên cứu 3 thời kỳ: 1930-1945, 1945-1975, và từ 1975 đến nay."},{"id":17,"section":"mo-dau","q":"Bộ tài liệu lý luận chính trị dành cho bậc đại học do Bộ GD&ĐT phối hợp Nhà xuất bản Chính trị quốc gia Sự thật xuất bản gồm mấy môn?","options":["5 môn","3 môn","4 môn","6 môn"],"answer":0,"explain":"Bộ tài liệu gồm 5 môn: Triết học Mác-Lênin, Kinh tế chính trị Mác-Lênin, Chủ nghĩa xã hội khoa học, Tư tưởng Hồ Chí Minh, và Lịch sử Đảng Cộng sản Việt Nam."},{"id":18,"section":"mo-dau","q":"Kết luận số 94-KL/TW ngày 28/3/2014 của Ban Bí thư đề cập nội dung gì?","options":["Đổi mới việc học tập lý luận chính trị trong hệ thống giáo dục","Thành lập Viện Lịch sử Đảng trực thuộc Ban Chấp hành Trung ương","Tổ chức lại hệ thống các trường Đảng từ Trung ương đến địa phương","Ban hành chương trình cải cách ruộng đất trong thời kỳ kháng chiến"],"answer":0,"explain":"Kết luận số 94-KL/TW (28/3/2014) về việc tiếp tục đổi mới việc học tập lý luận chính trị trong hệ thống giáo dục quốc dân."},{"id":19,"section":"mo-dau","q":"Đảng Cộng sản Việt Nam là đội tiên phong của giai cấp nào, đồng thời là đội tiên phong của ai theo Cương lĩnh?","options":["Giai cấp công nhân, đồng thời là đội tiên phong của nhân dân lao động, dân tộc","Chỉ giai cấp công nhân, không đại diện cho các tầng lớp khác trong xã hội ta","Giai cấp nông dân, đồng thời là đội tiên phong của trí thức và tiểu tư sản","Toàn thể nhân dân không phân biệt giai cấp, tôn giáo hay dân tộc nào cả"],"answer":0,"explain":"Đảng Cộng sản Việt Nam là đội tiên phong của giai cấp công nhân, đồng thời là đội tiên phong của nhân dân lao động và của dân tộc Việt Nam."},{"id":20,"section":"mo-dau","q":"Chức năng giáo dục của khoa học Lịch sử Đảng nhấn mạnh giáo dục điều gì?","options":["Tinh thần yêu nước, ý chí tự lực tự cường, lý tưởng cách mạng","Kỹ năng lao động sản xuất và kỹ năng quản lý kinh doanh giỏi","Trình độ ngoại ngữ, tin học và các kỹ năng làm việc theo nhóm","Kiến thức pháp luật quốc tế và luật thương mại toàn cầu"],"answer":0,"explain":"Chức năng giáo dục là giáo dục sâu sắc tinh thần yêu nước, ý thức, niềm tự hào, tự tôn, ý chí tự lực, tự cường dân tộc."},{"id":21,"section":"mo-dau","q":"Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên CNXH được Đảng thông qua vào thời điểm nào?","options":["6/1991 (Đại hội VII)","2/1930 (Hội nghị hợp nhất)","9/1960 (Đại hội III)","12/1986 (Đại hội VI)"],"answer":0,"explain":"Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên CNXH được thông qua tại Đại hội VII, tháng 6/1991 (sau đó bổ sung, phát triển năm 2011 tại Đại hội XI)."},{"id":22,"section":"mo-dau","q":"Chính cương của Đảng năm 1951 được thông qua tại Đại hội nào?","options":["Đại hội II của Đảng (2/1951)","Đại hội I của Đảng (3/1935)","Đại hội III của Đảng (9/1960)","Đại hội IV của Đảng (12/1976)"],"answer":0,"explain":"Chính cương của Đảng (2/1951) được thông qua tại Đại hội đại biểu toàn quốc lần thứ II của Đảng."},{"id":23,"section":"mo-dau","q":"Khi nghiên cứu lịch sử Đảng, cần phân biệt rõ điều gì?","options":["Sự kiện lịch sử Đảng gắn với sự lãnh đạo của Đảng, khác sự kiện lịch sử dân tộc","Không cần phân biệt, mọi sự kiện lịch sử trong cùng thời điểm đều như nhau cả","Chỉ cần ghi nhớ ngày tháng của sự kiện, không cần hiểu rõ nội dung của chúng","Chỉ nghiên cứu các sự kiện diễn ra trong nước, bỏ qua mọi bối cảnh quốc tế"],"answer":0,"explain":"Cần phân biệt rõ sự kiện lịch sử Đảng gắn trực tiếp với sự lãnh đạo của Đảng, phân biệt với sự kiện lịch sử dân tộc và lịch sử quân sự cùng thời điểm."},{"id":24,"section":"mo-dau","q":"Phương pháp nghiên cứu, học tập Lịch sử Đảng cần dựa trên nền tảng phương pháp luận nào?","options":["Chủ nghĩa duy vật biện chứng và chủ nghĩa duy vật lịch sử","Chủ nghĩa duy tâm khách quan và chủ nghĩa duy tâm chủ quan","Chủ nghĩa thực chứng và phương pháp luận thực dụng","Chủ nghĩa kinh nghiệm và chủ nghĩa hoài nghi khoa học"],"answer":0,"explain":"Phương pháp nghiên cứu cần dựa trên phương pháp luận khoa học mácxít, đặc biệt là chủ nghĩa duy vật biện chứng và chủ nghĩa duy vật lịch sử."},{"id":25,"section":"mo-dau","q":"Ngoài hai phương pháp cơ bản, cần chú trọng thêm những phương pháp cụ thể nào khác?","options":["Phương pháp tổng kết thực tiễn lịch sử và phương pháp so sánh","Phương pháp thực nghiệm hóa học và phương pháp mô phỏng sinh học","Phương pháp khảo cổ học và phương pháp địa chất học","Phương pháp thí nghiệm sinh học và phương pháp đo đạc địa hình"],"answer":0,"explain":"Cần coi trọng phương pháp tổng kết thực tiễn lịch sử gắn với nghiên cứu lý luận và phương pháp so sánh giữa các giai đoạn, thời kỳ lịch sử."},{"id":26,"section":"mo-dau","q":"Tính đảng và tính khoa học trong nghiên cứu lịch sử Đảng có mối quan hệ như thế nào?","options":["Thống nhất, đều hướng tới phục vụ nhiệm vụ chính trị của Đảng","Đối lập nhau, loại trừ lẫn nhau trong mọi trường hợp nghiên cứu","Hoàn toàn không liên quan đến nhau trong công tác nghiên cứu","Chỉ tính khoa học là quan trọng, còn tính đảng là không cần thiết"],"answer":0,"explain":"Tính khoa học và tính đảng là thống nhất và đều hướng tới phục vụ nhiệm vụ chính trị của Đảng, của cách mạng, vì lý tưởng độc lập dân tộc và chủ nghĩa xã hội."},{"id":27,"section":"mo-dau","q":"Nghị quyết Trung ương 4 khóa XII (10/2016) đã khẳng định điều gì về Đảng?","options":["Đảng ta có bản chất tốt đẹp, truyền thống anh hùng, lịch sử vẻ vang","Cần giải tán toàn bộ các tổ chức đảng yếu kém ở các địa phương","Cần đổi tên Đảng Cộng sản Việt Nam cho phù hợp với thời đại mới","Chỉ tập trung phát triển kinh tế, bỏ qua công tác xây dựng Đảng"],"answer":0,"explain":"Nghị quyết Trung ương 4 khóa XII khẳng định: \"Chúng ta có quyền tự hào về bản chất tốt đẹp, truyền thống anh hùng và lịch sử vẻ vang của Đảng ta - Đảng của Chủ tịch Hồ Chí Minh vĩ đại\"."},{"id":28,"section":"mo-dau","q":"Mục đích, yêu cầu của môn học Lịch sử Đảng đòi hỏi tính khoa học phải phản ánh điều gì?","options":["Lịch sử khách quan, trung thực, tôn trọng hiện thực lịch sử","Chỉ phản ánh những thành tựu, bỏ qua những hạn chế, khuyết điểm","Quan điểm cá nhân và cảm tính riêng của người nghiên cứu","Ý kiến chung của dư luận xã hội ở từng thời điểm cụ thể"],"answer":0,"explain":"Tính khoa học đòi hỏi phản ánh lịch sử khách quan, trung thực với những đánh giá kết hợp trên luận cứ khoa học, tôn trọng hiện thực lịch sử."},{"id":29,"section":"mo-dau","q":"Theo mục tiêu về kỹ năng của chương Nhập môn, sinh viên cần được trang bị điều gì?","options":["Phương pháp nhận thức biện chứng, khách quan về vai trò của Đảng","Kỹ năng lập trình máy tính và thiết kế phần mềm ứng dụng cao","Kỹ năng ngoại ngữ chuyên ngành và dịch thuật tài liệu gốc","Kỹ năng thuyết trình đa phương tiện và thiết kế đồ họa mỹ thuật"],"answer":0,"explain":"Sinh viên cần được trang bị phương pháp nhận thức biện chứng, khách quan về quá trình Đảng ra đời và vai trò lãnh đạo của Đảng."},{"id":30,"section":"mo-dau","q":"Theo Quyết định của Chủ tịch Hội đồng Bộ trưởng (nay là Thủ tướng Chính phủ), việc thành lập Hội đồng chỉ đạo biên soạn tài liệu quốc gia các bộ môn khoa học Mác-Lênin diễn ra vào ngày tháng năm nào?","options":["13/7/1992","2/2/1930","3/2/1951","19/5/1941"],"answer":0,"explain":"Ngày 13/7/1992, Chủ tịch Hội đồng Bộ trưởng (nay là Thủ tướng Chính phủ) ban hành Quyết định số 255/CT thành lập Hội đồng chỉ đạo biên soạn tài liệu quốc gia các bộ môn khoa học Mác-Lênin."},{"id":546,"section":"mo-dau","q":"Khoa học Lịch sử Đảng Cộng sản Việt Nam có chức năng cơ bản nào sau đây?","options":["Nhận thức, giáo dục tư tưởng chính trị, dự báo và phê phán","Chỉ có chức năng tuyên truyền, cổ động và vận động quần chúng","Chỉ có chức năng lưu trữ, bảo quản tư liệu lịch sử của Đảng","Chỉ có chức năng nghiên cứu, hoạch định chính sách kinh tế"],"answer":0,"explain":"Khoa học Lịch sử Đảng có các chức năng cơ bản: nhận thức, giáo dục tư tưởng - chính trị, đạo đức và dự báo, phê phán."},{"id":547,"section":"mo-dau","q":"Chức năng dự báo, phê phán của khoa học Lịch sử Đảng được thể hiện như thế nào?","options":["Trên cơ sở tổng kết thực tiễn lịch sử, dự báo xu hướng và phê phán nhận thức, hành động sai lệch","Chỉ dự báo các hiện tượng thời tiết và biến động kinh tế thuần túy, không liên quan đến chính trị","Chỉ mang tính chất phê phán một chiều đối với quá khứ, không có giá trị dự báo cho tương lai","Chỉ áp dụng trong lĩnh vực công tác đối ngoại của Đảng, không áp dụng ở trong nước"],"answer":0,"explain":"Chức năng dự báo, phê phán của khoa học Lịch sử Đảng thể hiện ở việc trên cơ sở tổng kết những bài học kinh nghiệm lịch sử, góp phần dự báo xu hướng vận động và phê phán những nhận thức, quan điểm, hành vi sai trái, lệch lạc với đường lối, quan điểm của Đảng."},{"id":548,"section":"mo-dau","q":"Nhiệm vụ nghiên cứu, trình bày có hệ thống Cương lĩnh, đường lối của Đảng thuộc nhóm nhiệm vụ nào của khoa học Lịch sử Đảng?","options":["Trình bày hệ thống Cương lĩnh, đường lối của Đảng","Trình bày diễn biến các trận đánh quân sự lớn","Nghiên cứu văn hóa dân gian của các dân tộc Việt Nam","Nghiên cứu ngôn ngữ học so sánh các ngữ hệ châu Á"],"answer":0,"explain":"Một trong những nhiệm vụ hàng đầu là trình bày có hệ thống Cương lĩnh, đường lối, chủ trương của Đảng qua các thời kỳ."},{"id":549,"section":"mo-dau","q":"Phương pháp nghiên cứu chuyên ngành cơ bản, đặc thù của khoa học Lịch sử Đảng là gì?","options":["Phương pháp lịch sử kết hợp phương pháp logic","Chỉ phương pháp thống kê toán học và xác suất","Chỉ phương pháp thực nghiệm khoa học tự nhiên","Chỉ phương pháp điều tra xã hội học định lượng"],"answer":0,"explain":"Phương pháp lịch sử và phương pháp logic là hai phương pháp chuyên ngành cơ bản, đặc thù, được vận dụng kết hợp trong nghiên cứu Lịch sử Đảng."},{"id":550,"section":"mo-dau","q":"So với phương pháp lịch sử, phương pháp logic trong nghiên cứu Lịch sử Đảng có đặc trưng khác biệt nào?","options":["Đi sâu tìm hiểu bản chất, quy luật vận động, không câu nệ trình tự thời gian","Chỉ đơn thuần liệt kê sự kiện theo trình tự thời gian giống hệt phương pháp lịch sử","Chỉ áp dụng nghiên cứu các văn kiện Đại hội, không áp dụng cho các thời kỳ lịch sử khác","Chỉ dùng để nghiên cứu lịch sử thế giới, không áp dụng cho lịch sử Đảng Việt Nam"],"answer":0,"explain":"Khác với phương pháp lịch sử chú trọng trình tự thời gian, phương pháp logic đi sâu tìm hiểu bản chất, mối liên hệ nội tại và quy luật vận động, phát triển của các sự kiện, hiện tượng trong lịch sử Đảng."},{"id":551,"section":"mo-dau","q":"Ngoài phương pháp lịch sử và phương pháp logic, khoa học Lịch sử Đảng còn sử dụng phương pháp liên ngành nào?","options":["Phương pháp phân tích, tổng hợp, so sánh, thống kê","Chỉ phương pháp thực nghiệm hóa học và vật lý","Chỉ phương pháp mô phỏng máy tính và lập trình","Chỉ phương pháp trắc địa và đo đạc bản đồ"],"answer":0,"explain":"Bên cạnh hai phương pháp chuyên ngành, môn học còn kết hợp các phương pháp liên ngành như phân tích, tổng hợp, so sánh, thống kê, điều tra xã hội học phù hợp với từng nội dung của môn học."},{"id":552,"section":"mo-dau","q":"Ý nghĩa của việc học tập, nghiên cứu Lịch sử Đảng Cộng sản Việt Nam đối với sinh viên là gì?","options":["Trang bị tri thức khoa học, củng cố niềm tin, nâng cao trách nhiệm công dân","Chỉ nhằm phục vụ việc thi cử, lấy điểm, không có giá trị thực tiễn gì","Chỉ dành cho sinh viên ngành Lịch sử, không liên quan các ngành khác","Chỉ nhằm mục đích tuyên truyền đối ngoại, không liên quan đến sinh viên"],"answer":0,"explain":"Học tập Lịch sử Đảng trang bị tri thức khoa học về quá trình lãnh đạo cách mạng của Đảng, củng cố niềm tin vào sự lãnh đạo của Đảng, nâng cao ý thức, trách nhiệm công dân trước những nhiệm vụ trọng đại của đất nước."},{"id":553,"section":"mo-dau","q":"Đối tượng nghiên cứu của khoa học Lịch sử Đảng KHÔNG bao gồm nội dung nào sau đây?","options":["Cương lĩnh, đường lối, chủ trương của Đảng qua các thời kỳ","Quá trình lãnh đạo, chỉ đạo của Đảng đối với cách mạng Việt Nam","Hệ thống các định lý và phương pháp chứng minh toán học cao cấp","Kết quả, ý nghĩa lịch sử từ hoạt động lãnh đạo của Đảng"],"answer":2,"explain":"Đối tượng nghiên cứu của Lịch sử Đảng là Cương lĩnh, đường lối, quá trình lãnh đạo và kết quả hoạt động lãnh đạo của Đảng; không liên quan tới các định lý toán học."},{"id":554,"section":"mo-dau","q":"Sản phẩm nghiên cứu khoa học Lịch sử Đảng phải bảo đảm nguyên tắc nào hàng đầu?","options":["Tính đảng và tính khoa học thống nhất với nhau","Chỉ cần bảo đảm tính hấp dẫn, sinh động, dễ đọc","Chỉ cần bảo đảm tính ngắn gọn, súc tích, dễ nhớ","Chỉ cần bảo đảm phù hợp với thị hiếu của độc giả"],"answer":0,"explain":"Nghiên cứu, biên soạn, giảng dạy, học tập Lịch sử Đảng phải đảm bảo tính đảng và tính khoa học thống nhất với nhau."},{"id":555,"section":"mo-dau","q":"Việc phân kỳ lịch sử Đảng Cộng sản Việt Nam thành các giai đoạn 1930-1945, 1945-1954, 1954-1975, 1975-1986 và từ 1986 đến nay chủ yếu dựa trên căn cứ nào?","options":["Các bước ngoặt và nhiệm vụ chiến lược của cách mạng","Chỉ dựa vào thời điểm diễn ra các kỳ Đại hội Đảng","Chỉ dựa vào tuổi tác và nhiệm kỳ của các Tổng Bí thư","Chỉ dựa vào các mốc thời gian tròn 10 năm một lần"],"answer":0,"explain":"Phân kỳ lịch sử Đảng dựa trên những bước ngoặt, sự chuyển biến về nhiệm vụ chiến lược của cách mạng Việt Nam qua từng thời kỳ."},{"id":556,"section":"mo-dau","q":"Nguồn sử liệu nào được coi là quan trọng, có giá trị pháp lý cao nhất khi nghiên cứu Lịch sử Đảng?","options":["Văn kiện, nghị quyết chính thức của Đảng qua các kỳ Đại hội","Tin đồn truyền miệng trong dân gian về các sự kiện lịch sử","Các bài viết trên mạng xã hội không rõ nguồn gốc xuất xứ","Các tác phẩm tiểu thuyết hư cấu về đề tài lịch sử Đảng"],"answer":0,"explain":"Văn kiện, nghị quyết chính thức của Đảng là nguồn sử liệu gốc, có giá trị pháp lý và độ tin cậy cao nhất trong nghiên cứu Lịch sử Đảng."},{"id":557,"section":"mo-dau","q":"Môn Lịch sử Đảng Cộng sản Việt Nam có quan hệ mật thiết với môn học nào sau đây trong hệ thống các môn lý luận chính trị ở đại học?","options":["Tư tưởng Hồ Chí Minh và Chủ nghĩa xã hội khoa học","Toán cao cấp và Vật lý đại cương cho khối kỹ thuật","Hóa học hữu cơ và Sinh học phân tử đại cương","Kỹ thuật lập trình và Cấu trúc dữ liệu, giải thuật"],"answer":0,"explain":"Lịch sử Đảng có quan hệ mật thiết với các môn lý luận chính trị khác như Tư tưởng Hồ Chí Minh, Chủ nghĩa xã hội khoa học, Kinh tế chính trị Mác - Lênin, cùng làm rõ sự vận dụng sáng tạo chủ nghĩa Mác - Lênin vào thực tiễn Việt Nam."},{"id":558,"section":"mo-dau","q":"Học tập Lịch sử Đảng giúp sinh viên rút ra điều gì có ý nghĩa thực tiễn trực tiếp nhất?","options":["Bài học kinh nghiệm để vận dụng vào nhận thức và hành động hiện nay","Chỉ để ghi nhớ chính xác các mốc ngày tháng năm của từng sự kiện lịch sử","Chỉ để đối chiếu, so sánh với lịch sử của các nước khác trên thế giới","Chỉ để phục vụ cho công tác nghiên cứu khảo cổ học và bảo tàng"],"answer":0,"explain":"Một ý nghĩa quan trọng của việc học Lịch sử Đảng là rút ra những bài học kinh nghiệm quý báu để vận dụng vào nhận thức và hành động trong công cuộc đổi mới, xây dựng và bảo vệ Tổ quốc hiện nay."},{"id":31,"section":"ch1-1","q":"Thực dân Pháp nổ súng tấn công Đà Nẵng, mở đầu cuộc xâm lược Việt Nam vào ngày nào?","options":["1/9/1858","6/6/1884","17/10/1887","5/6/1911"],"answer":0,"explain":"Ngày 1/9/1858, thực dân Pháp nổ súng tấn công Đà Nẵng, mở đầu quá trình xâm lược Việt Nam."},{"id":32,"section":"ch1-1","q":"Triều đình nhà Nguyễn ký Hiệp ước Patơnốt đầu hàng hoàn toàn thực dân Pháp vào ngày nào?","options":["6/6/1884","1/9/1858","17/10/1887","3/2/1930"],"answer":0,"explain":"Ngày 6/6/1884, triều đình nhà Nguyễn ký Hiệp ước Patơnốt, đầu hàng hoàn toàn thực dân Pháp."},{"id":33,"section":"ch1-1","q":"Liên bang Đông Dương thuộc Pháp (Union Indochinoise) được thành lập theo sắc lệnh nào, vào thời gian nào?","options":["Sắc lệnh của Tổng thống Pháp, ngày 17/10/1887","Hiệp ước Patơnốt với triều đình Huế, ngày 6/6/1884","Hiệp ước Hácmăng với triều đình Huế, ngày 25/8/1883","Nghị định của Toàn quyền Đông Dương, năm 1897"],"answer":0,"explain":"Liên bang Đông Dương thuộc Pháp được thành lập ngày 17/10/1887 theo sắc lệnh của Tổng thống Pháp."},{"id":34,"section":"ch1-1","q":"Thực dân Pháp tiến hành mấy cuộc khai thác thuộc địa lớn ở Việt Nam trước năm 1930?","options":["Hai cuộc (1897-1914 và 1919-1929)","Một cuộc (kéo dài từ 1897 đến 1929)","Ba cuộc (1897-1914, 1919-1929, 1930-1939)","Bốn cuộc (1887-1897, 1897-1914, 1919-1939)"],"answer":0,"explain":"Từ năm 1897, Pháp tiến hành cuộc khai thác thuộc địa lần thứ nhất (1897-1914) và lần thứ hai (1919-1929)."},{"id":35,"section":"ch1-1","q":"Giai cấp nào ở Việt Nam đầu thế kỷ XX chiếm khoảng hơn 90% dân số?","options":["Giai cấp nông dân","Giai cấp công nhân","Giai cấp tư sản","Giai cấp địa chủ"],"answer":0,"explain":"Giai cấp nông dân chiếm số lượng đông đảo nhất, khoảng hơn 90% dân số."},{"id":36,"section":"ch1-1","q":"Phong trào Cần Vương do ai khởi xướng, diễn ra trong khoảng thời gian nào?","options":["Vua Hàm Nghi và Tôn Thất Thuyết khởi xướng, 1885-1896","Phan Bội Châu và Cường Để khởi xướng, 1905-1908","Phan Châu Trinh và Huỳnh Thúc Kháng khởi xướng, 1906-1908","Hoàng Hoa Thám và Đề Nắm khởi xướng, 1884-1913"],"answer":0,"explain":"Phong trào Cần Vương do vua Hàm Nghi và Tôn Thất Thuyết khởi xướng, diễn ra từ 1885 đến 1896."},{"id":37,"section":"ch1-1","q":"Phong trào nông dân Yên Thế (Bắc Giang) do ai lãnh đạo, kéo dài gần bao nhiêu năm?","options":["Hoàng Hoa Thám lãnh đạo, gần 30 năm","Phan Bội Châu lãnh đạo, 20 năm","Nguyễn Thái Học lãnh đạo, 10 năm","Phan Châu Trinh lãnh đạo, 15 năm"],"answer":0,"explain":"Phong trào nông dân Yên Thế do Hoàng Hoa Thám lãnh đạo, đấu tranh kiên cường suốt gần 30 năm."},{"id":38,"section":"ch1-1","q":"Phan Bội Châu chủ trương xu hướng đấu tranh nào, với phong trào tiêu biểu nào?","options":["Xu hướng bạo động, tổ chức phong trào Đông Du","Xu hướng cải cách, tổ chức phong trào Duy Tân","Xu hướng ôn hòa, phong trào Đông Kinh Nghĩa Thục","Xu hướng nghị trường, lập Việt Nam Quốc dân Đảng"],"answer":0,"explain":"Phan Bội Châu chủ trương xu hướng bạo động, tổ chức phong trào Đông Du đưa thanh niên yêu nước Việt Nam sang Nhật Bản học tập."},{"id":39,"section":"ch1-1","q":"Phan Châu Trinh chủ trương đường lối cứu nước như thế nào?","options":["\"Khai dân trí, chấn dân khí, hậu dân sinh\", bất bạo động","Vũ trang bạo động, dựa vào sức mạnh quân sự đánh đuổi Pháp","Dựa vào Nhật Bản, cầu viện nước ngoài để đánh đuổi Pháp","Liên minh với Trung Quốc Quốc dân Đảng để đấu tranh vũ trang"],"answer":0,"explain":"Phan Châu Trinh chủ trương \"khai dân trí, chấn dân khí, hậu dân sinh\", theo xu hướng cải cách, bất bạo động."},{"id":40,"section":"ch1-1","q":"Việt Nam Quốc dân Đảng được thành lập chính thức vào thời gian nào, do ai lãnh đạo?","options":["Tháng 12/1927, do Nguyễn Thái Học lãnh đạo","Tháng 6/1925, do Nguyễn Ái Quốc lãnh đạo","Tháng 2/1930, do Trần Phú lãnh đạo","Tháng 5/1941, do Trường Chinh lãnh đạo"],"answer":0,"explain":"Việt Nam Quốc dân Đảng được chính thức thành lập tháng 12/1927 tại Bắc Kỳ, do Nguyễn Thái Học lãnh đạo."},{"id":41,"section":"ch1-1","q":"Cuộc khởi nghĩa của Việt Nam Quốc dân Đảng nổ ra ở đâu, vào thời gian nào, kết quả ra sao?","options":["Khởi nghĩa Yên Bái (2/1930), thất bại nhanh chóng","Khởi nghĩa Bắc Sơn (9/1940), giành thắng lợi hoàn toàn","Khởi nghĩa Nam Kỳ (11/1940), giành thắng lợi hoàn toàn","Khởi nghĩa Ba Tơ (3/1945), giành thắng lợi hoàn toàn"],"answer":0,"explain":"Cuộc khởi nghĩa Yên Bái (2/1930) của Việt Nam Quốc dân Đảng oanh liệt nhưng nhanh chóng thất bại."},{"id":42,"section":"ch1-1","q":"Nguyễn Tất Thành ra đi tìm đường cứu nước vào năm nào, từ bến cảng nào?","options":["Năm 1911, từ bến cảng Nhà Rồng (Sài Gòn)","Năm 1920, từ bến cảng Mácxây (Pháp)","Năm 1917, từ bến cảng Pêtrograt (Nga)","Năm 1925, từ bến cảng Thượng Hải (Trung Quốc)"],"answer":0,"explain":"Năm 1911, Nguyễn Tất Thành ra đi tìm đường cứu nước, giải phóng dân tộc."},{"id":43,"section":"ch1-1","q":"Nguyễn Ái Quốc đọc bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lênin vào thời gian nào?","options":["Tháng 7/1920","Tháng 6/1919","Tháng 12/1920","Tháng 2/1930"],"answer":0,"explain":"Tháng 7/1920, Nguyễn Ái Quốc đọc bản Sơ thảo luận cương của Lênin về vấn đề dân tộc và thuộc địa, đăng trên báo L'Humanité."},{"id":44,"section":"ch1-1","q":"Nguyễn Ái Quốc tham gia sáng lập Đảng Cộng sản Pháp tại sự kiện nào?","options":["Đại hội XVIII của Đảng Xã hội Pháp tại Tours (12/1920)","Đại hội V của Quốc tế Cộng sản tại Mátxcơva (1924)","Hội nghị Versailles của các nước thắng trận tại Pháp (6/1919)","Đại hội II của Quốc tế Cộng sản tại Mátxcơva (1920)"],"answer":0,"explain":"Tại Đại hội XVIII của Đảng Xã hội Pháp họp ở Tours (12/1920), Nguyễn Ái Quốc bỏ phiếu tán thành Quốc tế Cộng sản (Quốc tế III) và trở thành một trong những người sáng lập Đảng Cộng sản Pháp."},{"id":45,"section":"ch1-1","q":"Bản Yêu sách của nhân dân An Nam được Nguyễn Tất Thành (lấy tên Nguyễn Ái Quốc) gửi tới đâu, vào thời gian nào?","options":["Hội nghị Versailles, ngày 18/6/1919","Đại hội Tours, tháng 12/1920","Quốc tế Cộng sản, tháng 7/1920","Đại hội V Quốc tế Cộng sản, 1924"],"answer":0,"explain":"Tháng 6/1919, tại Hội nghị Versailles, Nguyễn Tất Thành lấy tên Nguyễn Ái Quốc gửi bản Yêu sách của nhân dân An Nam."},{"id":46,"section":"ch1-1","q":"Tác phẩm \"Đường cách mệnh\" của Nguyễn Ái Quốc được xuất bản năm nào?","options":["Năm 1927","Năm 1920","Năm 1925","Năm 1930"],"answer":0,"explain":"Năm 1927, tác phẩm Đường cách mệnh của Nguyễn Ái Quốc được Hội Liên hiệp các dân tộc bị áp bức ở Á Đông xuất bản."},{"id":47,"section":"ch1-1","q":"Hội Việt Nam Cách mạng Thanh niên được Nguyễn Ái Quốc thành lập vào thời gian nào, ở đâu?","options":["Tháng 6/1925, tại Quảng Châu (Trung Quốc)","Tháng 2/1930, tại Hương Cảng (Hồng Kông)","Tháng 5/1929, tại Hà Nội (Bắc Kỳ)","Tháng 12/1927, tại Sài Gòn (Nam Kỳ)"],"answer":0,"explain":"Tháng 6/1925, Nguyễn Ái Quốc thành lập Hội Việt Nam Cách mạng Thanh niên tại Quảng Châu (Trung Quốc)."},{"id":48,"section":"ch1-1","q":"Cơ quan ngôn luận (báo) do Nguyễn Ái Quốc sáng lập để tuyên truyền tôn chỉ của Hội Việt Nam Cách mạng Thanh niên có tên là gì?","options":["Báo Thanh niên (ra năm 1925)","Báo Người cùng khổ (Le Paria)","Báo Nhân đạo (L'Humanité)","Báo Búa liềm (ra năm 1929)"],"answer":0,"explain":"Hội xuất bản tờ báo Thanh niên do Nguyễn Ái Quốc sáng lập và trực tiếp chỉ đạo, ra số đầu tiên ngày 21/6/1925."},{"id":49,"section":"ch1-1","q":"Ba tổ chức cộng sản ra đời ở Việt Nam trong năm 1929 gồm những tổ chức nào?","options":["Đông Dương Cộng sản Đảng, An Nam Cộng sản Đảng, Đông Dương Cộng sản Liên đoàn","Đông Dương Cộng sản Đảng, Việt Nam Quốc dân Đảng, Tân Việt Cách mạng Đảng","Hội Việt Nam Cách mạng Thanh niên, Tâm Tâm Xã, Việt Nam Quang phục Hội","Đảng Lao động Việt Nam, Mặt trận Việt Minh, Đảng Dân chủ Việt Nam"],"answer":0,"explain":"Ba tổ chức cộng sản: Đông Dương Cộng sản Đảng (6/1929), An Nam Cộng sản Đảng (11/1929), Đông Dương Cộng sản Liên đoàn (9/1929)."},{"id":50,"section":"ch1-1","q":"Đông Dương Cộng sản Đảng được thành lập vào thời gian nào, tại đâu?","options":["Ngày 17/6/1929, tại phố Khâm Thiên, Hà Nội","Tháng 11/1929, tại phố Khánh Hội, Sài Gòn","Tháng 9/1929, tại thành phố Huế, Trung Kỳ","Ngày 6/1/1930, tại Cửu Long, Hương Cảng"],"answer":0,"explain":"Ngày 17/6/1929, đại biểu các tổ chức cộng sản ở Bắc Kỳ họp tại số nhà 312, phố Khâm Thiên (Hà Nội), quyết định thành lập Đông Dương Cộng sản Đảng."},{"id":51,"section":"ch1-1","q":"An Nam Cộng sản Đảng được thành lập vào tháng nào năm 1929, tại đâu?","options":["Tháng 11/1929, tại Khánh Hội, Sài Gòn","Tháng 6/1929, tại phố Khâm Thiên, Hà Nội","Tháng 9/1929, tại thành phố Huế, Trung Kỳ","Tháng 2/1930, tại Cửu Long, Hương Cảng"],"answer":0,"explain":"Tháng 11/1929, An Nam Cộng sản Đảng được thành lập tại Khánh Hội, Sài Gòn, trên cơ sở các chi bộ cộng sản ở Nam Kỳ."},{"id":52,"section":"ch1-1","q":"Hội nghị hợp nhất các tổ chức cộng sản thành lập Đảng Cộng sản Việt Nam diễn ra ở đâu, do ai chủ trì?","options":["Tại Hương Cảng (Trung Quốc), do Nguyễn Ái Quốc chủ trì","Tại Hà Nội (Bắc Kỳ), do đồng chí Trần Phú chủ trì","Tại Ma Cao (Trung Quốc), do Lê Hồng Phong chủ trì","Tại Quảng Châu (Trung Quốc), do Hồ Tùng Mậu chủ trì"],"answer":0,"explain":"Hội nghị hợp nhất diễn ra tại Cửu Long (Hương Cảng, Trung Quốc), từ 6/1 đến 7/2/1930, do lãnh tụ Nguyễn Ái Quốc - đại biểu của Quốc tế Cộng sản - chủ trì."},{"id":53,"section":"ch1-1","q":"Hội nghị thành lập Đảng Cộng sản Việt Nam diễn ra trong khoảng thời gian nào?","options":["Từ ngày 6/1 đến ngày 7/2/1930","Từ ngày 3/2 đến ngày 7/2/1930","Từ ngày 14/10 đến ngày 31/10/1930","Từ ngày 27/9/1929 đến ngày 8/2/1930"],"answer":0,"explain":"Hội nghị hợp nhất diễn ra từ ngày 6/1 đến ngày 7/2/1930 (sau này Đảng lấy ngày 3/2 dương lịch hằng năm làm ngày kỷ niệm thành lập Đảng)."},{"id":54,"section":"ch1-1","q":"Những văn kiện nào được thông qua tại Hội nghị thành lập Đảng do Nguyễn Ái Quốc soạn thảo?","options":["Chánh cương vắn tắt, Sách lược vắn tắt, Chương trình tóm tắt, Điều lệ vắn tắt","Luận cương chính trị, Điều lệ Đảng, Tuyên ngôn thành lập Đảng, Lời kêu gọi toàn quốc","Cương lĩnh xây dựng đất nước, Điều lệ Đảng, Nghị quyết Trung ương, Chương trình hành động","Nghị quyết Trung ương 8, Chương trình Việt Minh, Tuyên ngôn độc lập, Điều lệ Đảng"],"answer":0,"explain":"Hội nghị thông qua các văn kiện: Chánh cương vắn tắt, Sách lược vắn tắt, Chương trình tóm tắt và Điều lệ vắn tắt của Đảng Cộng sản Việt Nam."},{"id":55,"section":"ch1-1","q":"Cương lĩnh chính trị đầu tiên của Đảng xác định nhiệm vụ chủ yếu trước mắt của cách mạng là gì?","options":["Đánh đổ đế quốc Pháp và phong kiến, làm cho nước Nam hoàn toàn độc lập","Chỉ tập trung cải cách ruộng đất, chưa đặt nhiệm vụ giành độc lập dân tộc","Xây dựng chủ nghĩa xã hội ngay lập tức, bỏ qua giai đoạn cách mạng dân tộc","Liên minh với Việt Nam Quốc dân Đảng để đánh đuổi quân Pháp khỏi Đông Dương"],"answer":0,"explain":"Cương lĩnh xác định nhiệm vụ chủ yếu trước mắt: \"Đánh đổ đế quốc chủ nghĩa Pháp và bọn phong kiến, làm cho nước Nam được hoàn toàn độc lập\"."},{"id":56,"section":"ch1-1","q":"Về lực lượng cách mạng, Cương lĩnh chính trị đầu tiên xác định lực lượng cơ bản là ai?","options":["Công nhân và nông dân, do giai cấp công nhân lãnh đạo","Chỉ giai cấp tư sản dân tộc, do tầng lớp trí thức lãnh đạo","Chỉ tầng lớp trí thức tiểu tư sản, do giai cấp tư sản lãnh đạo","Toàn bộ địa chủ và tư sản, do giai cấp địa chủ lãnh đạo"],"answer":0,"explain":"Cương lĩnh xác định lực lượng cách mạng là công nhân, nông dân - lực lượng cơ bản, trong đó giai cấp công nhân lãnh đạo."},{"id":57,"section":"ch1-1","q":"Cương lĩnh chính trị đầu tiên xác định phương pháp tiến hành cách mạng giải phóng dân tộc như thế nào?","options":["Bằng con đường bạo lực cách mạng của quần chúng, không thỏa hiệp","Thông qua đàm phán ngoại giao hòa bình với chính quyền thực dân","Dựa vào sự giúp đỡ của các cường quốc để giành độc lập dân tộc","Cải lương dần dần trong khuôn khổ pháp luật của chính quyền thuộc địa"],"answer":0,"explain":"Cương lĩnh khẳng định phải bằng con đường bạo lực cách mạng của quần chúng, trong bất cứ hoàn cảnh nào cũng không được thỏa hiệp."},{"id":58,"section":"ch1-1","q":"Tổng Bí thư đầu tiên của Đảng Cộng sản Việt Nam (sau khi đổi tên thành Đảng Cộng sản Đông Dương, 10/1930) là ai?","options":["Trần Phú","Nguyễn Ái Quốc","Lê Hồng Phong","Hà Huy Tập"],"answer":0,"explain":"Tại Hội nghị Trung ương tháng 10/1930, đồng chí Trần Phú được bầu làm Tổng Bí thư của Đảng."},{"id":59,"section":"ch1-1","q":"Ý nghĩa lịch sử của việc thành lập Đảng Cộng sản Việt Nam là gì?","options":["Chấm dứt khủng hoảng đường lối cứu nước, mở bước ngoặt vĩ đại cho cách mạng","Chỉ có ý nghĩa đối với phong trào công nhân, chưa tác động đến phong trào yêu nước","Chưa có ý nghĩa quyết định vì Đảng còn non trẻ, chưa đủ sức lãnh đạo cách mạng","Chỉ là một sự kiện tổ chức đơn thuần, chưa thay đổi tình hình cách mạng"],"answer":0,"explain":"Đảng Cộng sản Việt Nam ra đời chấm dứt sự khủng hoảng về đường lối cứu nước, đưa cách mạng Việt Nam sang một bước ngoặt lịch sử vĩ đại."},{"id":60,"section":"ch1-1","q":"Đảng Cộng sản Việt Nam ra đời là sản phẩm của sự kết hợp những yếu tố nào?","options":["Chủ nghĩa Mác - Lênin với phong trào công nhân và phong trào yêu nước Việt Nam","Chỉ chủ nghĩa Mác - Lênin với phong trào công nhân, không có phong trào yêu nước","Chỉ phong trào yêu nước với phong trào nông dân, chưa có chủ nghĩa Mác - Lênin","Chủ nghĩa Tam dân với phong trào công nhân và phong trào yêu nước Việt Nam"],"answer":0,"explain":"Hồ Chí Minh khẳng định: Chủ nghĩa Mác - Lênin kết hợp với phong trào công nhân và phong trào yêu nước đã dẫn tới việc thành lập Đảng."},{"id":62,"section":"ch1-1","q":"Trước khi thành lập Đảng, Nguyễn Ái Quốc lập ra nhóm nào tại Quảng Châu vào tháng 2/1925?","options":["Nhóm Cộng sản đoàn","Việt Nam Quốc dân Đảng","Tân Việt Cách mạng Đảng","An Nam Cộng sản Đảng"],"answer":0,"explain":"Tháng 2/1925, Nguyễn Ái Quốc lựa chọn một số thanh niên tích cực trong Tâm tâm xã, lập ra nhóm Cộng sản đoàn."},{"id":63,"section":"ch1-1","q":"Đông Dương Cộng sản Liên đoàn được thành lập vào tháng nào năm 1929, có nguồn gốc từ tổ chức nào?","options":["Tháng 9/1929, từ Tân Việt Cách mạng Đảng","Tháng 6/1929, từ Hội Việt Nam Cách mạng Thanh niên","Tháng 11/1929, từ Việt Nam Quốc dân Đảng","Tháng 2/1930, từ Đông Dương Cộng sản Đảng"],"answer":0,"explain":"Tháng 9/1929, những người tiên tiến trong Tân Việt Cách mạng Đảng tuyên bố thành lập Đông Dương Cộng sản Liên đoàn."},{"id":65,"section":"ch1-1","q":"Cương lĩnh chính trị đầu tiên xác định về phương diện xã hội, dân chúng được hưởng quyền gì?","options":["Tự do tổ chức, nam nữ bình quyền, phổ thông giáo dục theo công nông hóa","Chỉ quyền tự do tôn giáo, tín ngưỡng và quyền bầu cử hạn chế cho dân chúng","Chỉ quyền bầu cử hạn chế, tự do buôn bán và học tập theo chương trình Pháp","Không đề cập vấn đề xã hội mà chỉ nêu nhiệm vụ chính trị và kinh tế"],"answer":0,"explain":"Về phương diện xã hội, Cương lĩnh xác định: dân chúng được tự do tổ chức, nam nữ bình quyền, phổ thông giáo dục theo công nông hóa."},{"id":66,"section":"ch1-1","q":"Về phương diện kinh tế, Cương lĩnh chính trị đầu tiên chủ trương thu hồi sản nghiệp lớn của ai giao cho ai quản lý?","options":["Thu sản nghiệp lớn của tư bản đế quốc Pháp giao cho Chính phủ công nông binh","Thu sản nghiệp lớn của tư bản đế quốc Pháp giao cho giai cấp tư sản dân tộc","Thu sản nghiệp lớn của tư bản Pháp chia cho giai cấp địa chủ phong kiến","Giữ nguyên quyền sở hữu sản nghiệp lớn của Pháp, chỉ đánh thuế nặng hơn"],"answer":0,"explain":"Cương lĩnh chủ trương thâu hết sản nghiệp lớn (công nghiệp, vận tải, ngân hàng...) của tư bản đế quốc Pháp giao cho Chính phủ công nông binh quản lý."},{"id":67,"section":"ch1-1","q":"Tân Việt Cách mạng Đảng là tổ chức có sự tham gia của những nhân vật cách mạng tiêu biểu nào?","options":["Trần Phú, Nguyễn Thị Minh Khai","Nguyễn Ái Quốc, Trường Chinh","Nguyễn Thái Học, Phó Đức Chính","Lê Hồng Phong, Hà Huy Tập"],"answer":0,"explain":"Tân Việt Cách mạng Đảng là tổ chức thanh niên yêu nước có cả Trần Phú, Nguyễn Thị Minh Khai, chịu ảnh hưởng mạnh mẽ của Hội Việt Nam Cách mạng Thanh niên."},{"id":68,"section":"ch1-1","q":"Cách mạng Tháng Mười Nga (1917) có tác động như thế nào đến việc Nguyễn Ái Quốc lựa chọn con đường cứu nước?","options":["Tác động mạnh mẽ, giúp Người xác định con đường cách mạng vô sản","Không có tác động đáng kể, Người vẫn theo con đường cứu nước cũ","Khiến Người quay sang xu hướng cải lương trong khuôn khổ thuộc địa","Làm Người từ bỏ con đường cứu nước để ở lại làm việc ở nước ngoài"],"answer":0,"explain":"Năm 1917, thắng lợi Cách mạng Tháng Mười Nga tác động mạnh mẽ tới nhận thức của Nguyễn Tất Thành, thúc đẩy Người tìm hiểu về V.I.Lênin và con đường cách mạng vô sản."},{"id":69,"section":"ch1-1","q":"Hội nghị thành lập Đảng đã cử ra cơ quan lãnh đạo lâm thời nào?","options":["Ban Chấp hành Trung ương lâm thời","Ban Thường vụ Trung ương chính thức","Bộ Chính trị Trung ương lâm thời","Ban Bí thư Quốc hội lâm thời"],"answer":0,"explain":"Hội nghị chủ trương các đại biểu về nước phải tổ chức một Ban Chấp hành Trung ương lâm thời để lãnh đạo cách mạng Việt Nam."},{"id":70,"section":"ch1-1","q":"Sau Hội nghị thành lập Đảng, Nguyễn Ái Quốc ra văn kiện gì nhân dịp thành lập Đảng?","options":["Lời kêu gọi nhân dịp thành lập Đảng","Luận cương chính trị tháng 10/1930","Lời kêu gọi toàn quốc kháng chiến","Tuyên ngôn độc lập ngày 2/9/1945"],"answer":0,"explain":"Sau Hội nghị, Nguyễn Ái Quốc ra Lời kêu gọi nhân dịp thành lập Đảng, mở đầu: \"Nhận chỉ thị của Quốc tế Cộng sản giải quyết vấn đề cách mạng nước ta, tôi đã hoàn thành nhiệm vụ\"."},{"id":71,"section":"ch1-1","q":"Trong bài viết \"Đường cách mệnh\", Nguyễn Ái Quốc khẳng định điều gì về vai trò của chủ nghĩa đối với Đảng?","options":["\"Đảng muốn vững thì phải có chủ nghĩa làm cốt\"","Đảng không cần chủ nghĩa, chỉ cần tổ chức chặt chẽ","Chủ nghĩa chỉ quan trọng đối với lãnh tụ, không cần với đảng viên","Đảng cần nhiều chủ nghĩa khác nhau để linh hoạt"],"answer":0,"explain":"Trong Đường cách mệnh, Nguyễn Ái Quốc khẳng định: \"Đảng muốn vững thì phải có chủ nghĩa làm cốt, trong đảng ai cũng phải hiểu, ai cũng phải theo chủ nghĩa ấy\"."},{"id":72,"section":"ch1-1","q":"Tờ báo Búa liềm là cơ quan ngôn luận của tổ chức cộng sản nào?","options":["Đông Dương Cộng sản Đảng","An Nam Cộng sản Đảng","Đông Dương Cộng sản Liên đoàn","Việt Nam Quốc dân Đảng"],"answer":0,"explain":"Đông Dương Cộng sản Đảng lấy cờ đỏ búa liềm làm Đảng kỳ và quyết định xuất bản báo Búa liềm làm cơ quan ngôn luận."},{"id":73,"section":"ch1-1","q":"Phong trào \"Vô sản hóa\" do tổ chức nào phát động từ tháng 9/1928?","options":["Kỳ bộ Bắc Kỳ Hội Việt Nam Cách mạng Thanh niên","Đông Dương Cộng sản Đảng ở Bắc Kỳ","Ban lãnh đạo Việt Nam Quốc dân Đảng ở Bắc Kỳ","Ban lãnh đạo Tân Việt Cách mạng Đảng ở Trung Kỳ"],"answer":0,"explain":"Phong trào \"Vô sản hóa\" do Kỳ bộ Bắc Kỳ Hội Việt Nam Cách mạng Thanh niên phát động từ ngày 29/9/1928, nhằm truyền bá tư tưởng vô sản, rèn luyện cán bộ."},{"id":74,"section":"ch1-1","q":"Cương lĩnh chính trị đầu tiên xác định vai trò lãnh đạo cách mạng thuộc về ai?","options":["Đảng - đội tiên phong của giai cấp vô sản Việt Nam","Mặt trận dân tộc thống nhất do giai cấp tư sản đứng đầu","Chính phủ lâm thời của các giai cấp, tầng lớp yêu nước","Quốc tế Cộng sản trực tiếp chỉ huy cách mạng Việt Nam"],"answer":0,"explain":"Cương lĩnh xác định: \"Đảng là đội tiên phong của vô sản giai cấp phải thu phục cho được đại bộ phận giai cấp mình, phải làm cho giai cấp mình lãnh đạo được dân chúng\"."},{"id":75,"section":"ch1-1","q":"Trước khi bị thực dân Anh bắt giam ở Hồng Kông (6/6/1931), Nguyễn Ái Quốc đã làm gì để chuẩn bị và lãnh đạo cách mạng Việt Nam?","options":["Chủ trì Hội nghị hợp nhất thành lập Đảng Cộng sản Việt Nam (1930)","Chủ trì Đại hội lần thứ I của Đảng Cộng sản Đông Dương (3/1935)","Chủ trì Hội nghị Trung ương lần thứ tám tại Pác Bó (5/1941)","Chủ trì Đại hội Quốc dân Tân Trào, bầu Ủy ban Dân tộc giải phóng"],"answer":0,"explain":"Trước khi bị bắt giam ở Hồng Kông năm 1931, Nguyễn Ái Quốc đã chủ trì Hội nghị hợp nhất các tổ chức cộng sản, thành lập Đảng Cộng sản Việt Nam đầu năm 1930."},{"id":401,"section":"ch1-1","q":"Điểm nào dưới đây không thuộc về bối cảnh lịch sử thế giới cuối thế kỷ XIX, đầu thế kỷ XX đã tác động đến sự ra đời của Đảng Cộng sản Việt Nam?","options":["Cách mạng Việt Nam khủng hoảng sâu sắc về đường lối cứu nước","Phong trào giải phóng dân tộc phát triển mạnh mẽ, rộng khắp ở châu Á","Thắng lợi của Cách mạng Tháng Mười Nga năm 1917, mở ra thời đại mới","Quốc tế Cộng sản (Quốc tế III) thành lập năm 1919 ở Mát-xcơ-va"],"answer":0,"explain":"Ba yếu tố còn lại đều thuộc bối cảnh thế giới cuối XIX đầu XX; riêng việc cách mạng Việt Nam khủng hoảng đường lối là tình hình trong nước, không thuộc bối cảnh thế giới."},{"id":402,"section":"ch1-1","q":"Trước khi thực dân Pháp xâm lược (trước năm 1858), Việt Nam là một xã hội như thế nào?","options":["Xã hội phong kiến độc lập","Xã hội thuộc địa nửa phong kiến","Xã hội thuộc địa của Pháp","Xã hội tư bản chủ nghĩa"],"answer":0,"explain":"Trước năm 1858, Việt Nam là một xã hội phong kiến độc lập, có chủ quyền."},{"id":403,"section":"ch1-1","q":"Mưu đồ kinh tế của thực dân Pháp khi xâm lược Việt Nam nói riêng và Đông Dương nói chung là gì?","options":["Biến Đông Dương thành thị trường, vơ vét tài nguyên và bóc lột sức lao động giá rẻ","Chỉ phát triển nông nghiệp tự cấp cho dân bản xứ, không khai thác tài nguyên, nhân công","Xây dựng nền kinh tế độc lập cho Đông Dương, không phụ thuộc vào chính quốc","Chia đều lợi nhuận khai thác thuộc địa cho nhân dân Đông Dương, giảm thuế khoá"],"answer":0,"explain":"Mưu đồ kinh tế của Pháp gồm: biến Việt Nam - Đông Dương thành thị trường tiêu thụ hàng hoá, vơ vét tài nguyên, bóc lột sức lao động giá rẻ và áp đặt nhiều hình thức thuế khoá."},{"id":404,"section":"ch1-1","q":"Trong những điểm sau đây nói về tác động của chính sách cai trị của thực dân Pháp đối với nhân dân Việt Nam, điểm nào nói về phân hóa giai cấp ở nước ta?","options":["Tạo ra những giai cấp, tầng lớp mới (công nhân, tư sản dân tộc, tiểu tư sản)","Biến xã hội phong kiến độc lập thành xã hội thuộc địa nửa phong kiến","Nảy sinh mâu thuẫn giữa toàn thể dân tộc Việt Nam với thực dân Pháp xâm lược","Chống đế quốc, giải phóng dân tộc trở thành nhiệm vụ hàng đầu của cách mạng"],"answer":0,"explain":"Chính sách cai trị của Pháp làm phân hóa xã hội Việt Nam, tạo ra những giai cấp, tầng lớp mới như công nhân, tư sản dân tộc, tiểu tư sản, bên cạnh địa chủ và nông dân vốn có."},{"id":405,"section":"ch1-1","q":"Đặc điểm nổi bật của giai cấp công nhân Việt Nam là gì?","options":["Ra đời trước giai cấp tư sản dân tộc, sớm tiếp thu ánh sáng của chủ nghĩa Mác - Lênin","Ra đời sau giai cấp tư sản dân tộc, sớm tiếp thu ánh sáng của chủ nghĩa Mác - Lênin","Ra đời trước giai cấp địa chủ phong kiến, sớm tiếp thu ánh sáng của chủ nghĩa Mác - Lênin","Ra đời cùng lúc với giai cấp tư sản dân tộc, sớm tiếp thu ánh sáng của chủ nghĩa Mác - Lênin"],"answer":0,"explain":"Giai cấp công nhân Việt Nam ra đời trước giai cấp tư sản dân tộc, ngay từ khi mới hình thành đã sớm tiếp thu ánh sáng cách mạng của chủ nghĩa Mác - Lênin."},{"id":406,"section":"ch1-1","q":"Dưới sự thống trị của thực dân Pháp, giai cấp, tầng lớp nào ở Việt Nam được đánh giá là: có tinh thần dân tộc, yêu nước và rất nhạy cảm về chính trị và thời cuộc?","options":["Tầng lớp tiểu tư sản","Giai cấp tư sản","Giai cấp địa chủ","Giai cấp công nhân"],"answer":0,"explain":"Tầng lớp tiểu tư sản (học sinh, sinh viên, trí thức, viên chức...) có tinh thần dân tộc, yêu nước và rất nhạy cảm về chính trị, thời cuộc."},{"id":407,"section":"ch1-1","q":"Phong trào Cần Vương thuộc khuynh hướng cứu nước nào?","options":["Khuynh hướng phong kiến","Khuynh hướng dân chủ tư sản","Khuynh hướng cách mạng vô sản","Khuynh hướng cải lương tư sản"],"answer":0,"explain":"Phong trào Cần Vương do vua Hàm Nghi và Tôn Thất Thuyết khởi xướng, mang danh nghĩa “phò vua cứu nước”, thuộc khuynh hướng phong kiến."},{"id":408,"section":"ch1-1","q":"Phong trào khởi nghĩa Yên Thế thuộc khuynh hướng cứu nước nào?","options":["Phong kiến","Cải lương","Dân chủ tư sản","Vô sản"],"answer":0,"explain":"Phong trào nông dân Yên Thế nổ ra trước khi có ảnh hưởng của các trào lưu tư sản, dân chủ mới, được xếp vào khuynh hướng phong kiến, nông dân tự phát."},{"id":409,"section":"ch1-1","q":"Phong trào yêu nước do Phan Bội Châu khởi xướng và lãnh đạo thuộc khuynh hướng cứu nước nào?","options":["Dân chủ tư sản","Cải lương","Phong kiến","Vô sản"],"answer":0,"explain":"Phan Bội Châu chủ trương bạo động vũ trang theo khuynh hướng dân chủ tư sản, tiêu biểu là phong trào Đông Du."},{"id":410,"section":"ch1-1","q":"“Không thành công cũng thành nhân” là khẩu hiệu đấu tranh của tổ chức nào?","options":["Việt Nam Quốc dân Đảng (1927)","Hội Việt Nam Cách mạng Thanh niên","An Nam Cộng sản Đảng (1929)","Đông Dương Cộng sản Đảng (1929)"],"answer":0,"explain":"“Không thành công cũng thành nhân” là khẩu hiệu đấu tranh nổi tiếng của Việt Nam Quốc dân Đảng, gắn với cuộc khởi nghĩa Yên Bái."},{"id":411,"section":"ch1-1","q":"Khẩu hiệu đấu tranh “Không thành công cũng thành nhân” của Việt Nam quốc dân Đảng, theo Lê Duẩn biểu hiện điều gì?","options":["Tính hấp tấp tiểu tư sản, hăng hái nhất thời, non yếu của phong trào tư sản","Quyết tử cho Tổ quốc quyết sinh, tinh thần xả thân của toàn dân kháng chiến","Sự anh hùng, gan dạ, bất khuất trong đấu tranh giải phóng dân tộc của quần chúng","Dám hi sinh vì nền độc lập, tự do của Tổ quốc, sẵn sàng đối mặt với kẻ thù"],"answer":0,"explain":"Theo đánh giá của đồng chí Lê Duẩn, khẩu hiệu này biểu hiện tính hấp tấp tiểu tư sản, tính hăng hái nhất thời và sự non yếu, thiếu vững chắc của phong trào dân chủ tư sản."},{"id":412,"section":"ch1-1","q":"Mục đích hoạt động của tổ chức Việt Nam quốc dân Đảng là gì?","options":["Đánh đuổi thực dân Pháp xâm lược, giành độc lập dân tộc, xây dựng chế độ cộng hoà tư sản","Đánh đổ đế quốc xâm lược, giành độc lập dân tộc và tiến lên xây dựng chủ nghĩa xã hội","Đánh đuổi thực dân Pháp xâm lược, khôi phục chế độ phong kiến quân chủ ở Việt Nam","Đánh đổ chế độ thực dân và phong kiến, thành lập Nhà nước của dân, do dân và vì dân"],"answer":0,"explain":"Việt Nam Quốc dân Đảng theo khuynh hướng dân chủ tư sản, chủ trương đánh đuổi thực dân Pháp, giành độc lập dân tộc và xây dựng chế độ cộng hoà tư sản."},{"id":413,"section":"ch1-1","q":"Nguyễn Ái Quốc tham gia Đảng Xã hội Pháp thời gian nào?","options":["Năm 1919","Năm 1918","Năm 1920","Năm 1921"],"answer":0,"explain":"Năm 1919, Nguyễn Ái Quốc gia nhập Đảng Xã hội Pháp, vì đây là tổ chức duy nhất ở Pháp bênh vực quyền lợi các dân tộc thuộc địa."},{"id":414,"section":"ch1-1","q":"“Dù màu da có khác nhau, trên đời này chỉ có hai giống người: Giống người bóc lột và giống người bị bóc lột”. Nhận xét trên của Nguyễn Ái Quốc có ý nghĩa gì đối với các dân tộc bị áp bức?","options":["Xác định rõ kẻ thù và lực lượng đồng minh của cách mạng","Xác định rõ kẻ thù, nhưng chưa chỉ ra lực lượng đồng minh","Xác định rõ con đường cứu nước và phương pháp cách mạng","Xác định rõ giai cấp lãnh đạo và lực lượng nòng cốt của cách mạng"],"answer":0,"explain":"Nhận xét của Nguyễn Ái Quốc vừa xác định rõ kẻ thù (giống người bóc lột) vừa xác định lực lượng đồng minh (giống người bị bóc lột ở khắp nơi), có ý nghĩa quốc tế sâu sắc."},{"id":415,"section":"ch1-1","q":"Theo Nguyễn Ái Quốc, kẻ thù chung của nhân dân các nước thuộc địa, của giai cấp công nhân và nhân dân lao động trên thế giới là ai?","options":["Chủ nghĩa đế quốc","Chủ nghĩa tư bản","Chủ nghĩa thực dân","Chủ nghĩa phát-xít"],"answer":0,"explain":"Nguyễn Ái Quốc xác định chủ nghĩa đế quốc là kẻ thù chung của nhân dân các nước thuộc địa, của giai cấp công nhân và nhân dân lao động toàn thế giới."},{"id":416,"section":"ch1-1","q":"Tác phẩm nào của Nguyễn Ái Quốc thể hiện rõ sự chuẩn bị về tư tưởng, lý luận, chính trị và tổ chức để thành lập Đảng Cộng sản Việt Nam?","options":["Tác phẩm Đường Cách mệnh (1927)","Yêu sách của nhân dân An Nam (1919)","Vở kịch Con rồng tre (1922)","Bản án chế độ thực dân Pháp (1925)"],"answer":0,"explain":"Đường Cách mệnh (1927) là tác phẩm thể hiện rõ nhất sự chuẩn bị toàn diện về tư tưởng, lý luận, chính trị và tổ chức của Nguyễn Ái Quốc cho sự ra đời của Đảng."},{"id":417,"section":"ch1-1","q":"“Dù màu da có khác nhau, trên đời này chỉ có hai giống người...”. Hãy chọn đáp án đúng để hoàn thiện nhận định trên của Nguyễn Ái Quốc?","options":["Giống người bóc lột và giống người bị bóc lột","Giống người giàu có và giống người nghèo khổ","Giống người xâm lược và giống người bị xâm lược","Giống người thống trị và giống người bị trị"],"answer":0,"explain":"Nguyên văn nhận định của Nguyễn Ái Quốc: “trên đời này chỉ có hai giống người: giống người bóc lột và giống người bị bóc lột”."},{"id":418,"section":"ch1-1","q":"Việc làm nào của Nguyễn Ái Quốc là sự chuẩn bị quan trọng về tổ chức để tiến tới thành lập chính đảng của giai cấp công nhân?","options":["Mở các lớp huấn luyện chính trị đào tạo cán bộ cách mạng","Viết báo, xuất bản sách và ra các tờ báo tuyên truyền cách mạng","Gửi Bản yêu sách của nhân dân An Nam tới Hội nghị Véc-xây","Viết tác phẩm Đường Cách mệnh để truyền bá lý luận cách mạng"],"answer":0,"explain":"Việc mở các lớp huấn luyện chính trị tại Quảng Châu để đào tạo cán bộ là sự chuẩn bị quan trọng về mặt tổ chức, cán bộ cho việc thành lập chính đảng của giai cấp công nhân."},{"id":419,"section":"ch1-1","q":"Trong tác phẩm Đường Cách mệnh, Nguyễn Ái Quốc chỉ rõ giai cấp nào là gốc của cách mệnh?","options":["Công nhân và nông dân","Công nhân và tư sản","Địa chủ và nông dân","Tư sản và nông dân"],"answer":0,"explain":"Trong Đường Cách mệnh, Nguyễn Ái Quốc khẳng định công nông là gốc của cách mệnh, còn học trò, nhà buôn nhỏ, điền chủ nhỏ chỉ là bầu bạn của cách mệnh."},{"id":420,"section":"ch1-1","q":"Cuốn sách chính trị đầu tiên của cách mạng Việt Nam là?","options":["Đường Cách mệnh (1927) của Nguyễn Ái Quốc","Bản án chế độ thực dân Pháp (1925) của Người","Cương lĩnh chính trị đầu tiên của Đảng (1930)","Luận cương chính trị tháng 10/1930 của Đảng"],"answer":0,"explain":"Đường Cách mệnh (1927), tập hợp các bài giảng của Nguyễn Ái Quốc tại các lớp huấn luyện ở Quảng Châu, được coi là cuốn sách chính trị đầu tiên của cách mạng Việt Nam."},{"id":421,"section":"ch1-1","q":"Hội Liên hiệp thuộc địa được thành lập vào năm nào?","options":["Năm 1921","Năm 1920","Năm 1923","Năm 1924"],"answer":0,"explain":"Năm 1921, Nguyễn Ái Quốc cùng một số nhà cách mạng ở các nước thuộc địa Pháp lập ra Hội Liên hiệp thuộc địa tại Paris."},{"id":422,"section":"ch1-1","q":"Trong các tác phẩm sau đây, tác phẩm nào vạch trần bản chất phản động của đế quốc Pháp đối với các dân tộc thuộc địa?","options":["“Bản án chế độ thực dân Pháp” của Nguyễn Ái Quốc (1925)","Bản “Yêu sách 8 điểm” gửi Hội nghị Véc-xây của Nguyễn Ái Quốc (1919)","“Luận cương về vấn đề dân tộc và thuộc địa” của V.I.Lênin (1920)","“Đường cách mệnh” (tập bài giảng) của Nguyễn Ái Quốc (1927)"],"answer":0,"explain":"“Bản án chế độ thực dân Pháp” (1925) của Nguyễn Ái Quốc vạch trần bản chất phản động, tàn bạo của chủ nghĩa thực dân Pháp đối với các dân tộc thuộc địa."},{"id":423,"section":"ch1-1","q":"Trực tiếp phụ trách các lớp huấn luyện chính trị ở Quảng Châu (Trung Quốc) của Hội Việt Nam Cách mạng thanh niên là ai?","options":["Nguyễn Ái Quốc","Lâm Đức Thụ","Lê Hồng Sơn","Phùng Chí Kiên"],"answer":0,"explain":"Nguyễn Ái Quốc trực tiếp mở lớp và giảng dạy tại các lớp huấn luyện chính trị ở Quảng Châu để đào tạo cán bộ cho cách mạng Việt Nam."},{"id":424,"section":"ch1-1","q":"Trong Cương lĩnh chính trị đầu tiên, ngoài giai cấp công nhân và nông dân, Đảng chủ trương phải hết sức liên lạc với giai cấp, tầng lớp nào?","options":["Tiểu tư sản, trí thức, trung nông","Đại địa chủ, trí thức, trung nông","Đại địa chủ, tiểu tư sản, thanh niên","Đại địa chủ, trung địa chủ, trí thức"],"answer":0,"explain":"Cương lĩnh chính trị đầu tiên xác định Đảng phải hết sức liên lạc với tiểu tư sản, trí thức, trung nông để kéo họ về phe giai cấp vô sản."},{"id":425,"section":"ch1-1","q":"Sự kiện nào đánh dấu “giai cấp vô sản ta đã trưởng thành và đủ sức lãnh đạo cách mạng”?","options":["Thành lập Đảng Cộng sản Việt Nam (1930)","Hội Việt Nam Cách mạng Thanh niên ra đời (1925)","Thành lập Chi bộ cộng sản đầu tiên (1929)","Ba tổ chức cộng sản lần lượt ra đời (1929)"],"answer":0,"explain":"Sự ra đời của Đảng Cộng sản Việt Nam (1930) đánh dấu giai cấp công nhân Việt Nam đã trưởng thành và đủ sức lãnh đạo cách mạng."},{"id":426,"section":"ch1-1","q":"Chi bộ Cộng sản đầu tiên ở Việt Nam được thành lập thời gian nào, ở đâu?","options":["Tháng 3/1929, tại Hà Nội","Tháng 5/1929, tại Hà Nội","Tháng 6/1929, tại Sài Gòn","Tháng 9/1929, tại Huế"],"answer":0,"explain":"Tháng 3/1929, tại số nhà 5D phố Hàm Long (Hà Nội), chi bộ cộng sản đầu tiên ở Việt Nam được thành lập."},{"id":427,"section":"ch1-1","q":"Tiền thân của Đông Dương Cộng sản Đảng và An Nam Cộng sản Đảng là tổ chức nào?","options":["Hội Việt Nam Cách mạng Thanh niên","Tân Việt Cách mạng Đảng (1925)","Việt Nam Quang phục Hội (1912)","Việt Nam Quốc dân Đảng (1927)"],"answer":0,"explain":"Đông Dương Cộng sản Đảng và An Nam Cộng sản Đảng đều ra đời từ sự phân hoá của Hội Việt Nam Cách mạng Thanh niên."},{"id":428,"section":"ch1-1","q":"Đại biểu những tổ chức cộng sản nào đã tham dự Hội nghị thành lập Đảng Cộng sản Việt Nam năm 1930?","options":["Đông Dương Cộng sản Đảng và An Nam Cộng sản Đảng","Cả ba tổ chức cộng sản xuất hiện trong năm 1929","An Nam Cộng sản Đảng và Đông Dương Cộng sản Liên đoàn","Đông Dương Cộng sản Đảng và Đông Dương Cộng sản Liên đoàn"],"answer":0,"explain":"Hội nghị hợp nhất (6/1-7/2/1930) chỉ có đại biểu của Đông Dương Cộng sản Đảng và An Nam Cộng sản Đảng; Đông Dương Cộng sản Liên đoàn xin gia nhập và được chấp nhận sau, vào ngày 24/2/1930."},{"id":429,"section":"ch1-1","q":"Hội nghị thành lập Đảng Cộng sản Việt Nam năm 1930 xác định tôn chỉ mục đích của Đảng là gì?","options":["Lãnh đạo quần chúng lao khổ làm giai cấp tranh đấu để tiêu trừ tư bản đế quốc chủ nghĩa, thực hiện xã hội cộng sản","Lãnh đạo quần chúng làm cách mạng ruộng đất và xây dựng xã hội tư bản chủ nghĩa độc lập ở Đông Dương, không đặt vấn đề giai cấp","Lãnh đạo quần chúng lao khổ thực hiện giải phóng giai cấp, giải phóng dân tộc, giải phóng xã hội, giải phóng con người","Lãnh đạo quần chúng lao khổ đánh đổ đế quốc, đánh đổ phong kiến thực hiện người cày có ruộng, xóa bỏ mọi thứ thuế"],"answer":0,"explain":"Điều lệ vắn tắt của Đảng xác định tôn chỉ, mục đích: lãnh đạo quần chúng lao khổ làm giai cấp tranh đấu để tiêu trừ tư bản đế quốc chủ nghĩa, làm cho thực hiện xã hội cộng sản."},{"id":430,"section":"ch1-1","q":"Trong Cương lĩnh chính trị đầu tiên của Đảng, nội dung nào đã làm rõ cách mạng giải phóng dân tộc ở thuộc địa nằm trong phạm trù của cách mạng vô sản?","options":["Mục tiêu chiến lược","Nhiệm vụ chủ yếu, trước mắt","Lực lượng cách mạng","Tinh thần đoàn kết quốc tế"],"answer":0,"explain":"Mục tiêu chiến lược của Cương lĩnh là “làm tư sản dân quyền cách mạng và thổ địa cách mạng để đi tới xã hội cộng sản”, xác định con đường đi lên chủ nghĩa xã hội, đặt cách mạng giải phóng dân tộc ở thuộc địa trong phạm trù cách mạng vô sản."},{"id":431,"section":"ch1-1","q":"Cương lĩnh chính trị đầu tiên của Đảng Cộng sản Việt Nam xác định mục tiêu chiến lược của cách mạng Việt Nam là?","options":["Làm tư sản dân quyền cách mạng và thổ địa cách mạng để đi tới xã hội cộng sản","Xây dựng một nước Việt Nam dân giàu, nước mạnh, xã hội công bằng, dân chủ, văn minh","Cách mạng tư sản dân quyền - phản đế và điền địa, lập chính quyền Xô-viết công nông","Làm cách mạng tư sản dân quyền có tính chất thổ địa, giải phóng ruộng đất cho nông dân"],"answer":0,"explain":"Cương lĩnh chính trị đầu tiên (2/1930) xác định mục tiêu chiến lược: “làm tư sản dân quyền cách mạng và thổ địa cách mạng để đi tới xã hội cộng sản”."},{"id":443,"section":"ch1-1","q":"Từ nửa sau thế kỉ XIX, chủ nghĩa tư bản phương Tây đã chuyển từ giai đoạn tự do cạnh tranh sang giai đoạn","options":["đế quốc chủ nghĩa.","phát triển cực thịnh.","hợp tác liên châu lục.","khủng hoảng toàn diện."],"answer":0,"explain":"Từ nửa sau thế kỉ XIX, các nước tư bản phương Tây chuyển từ giai đoạn tự do cạnh tranh sang giai đoạn đế quốc chủ nghĩa, đẩy mạnh xâm chiếm thuộc địa trên toàn thế giới."},{"id":444,"section":"ch1-1","q":"Quá trình xâm lược và nô dịch các nước nhỏ yếu ở châu Phi, Mỹ Latinh, châu Á của các nước đế quốc đã dẫn tới mâu thuẫn cơ bản mang tính quốc tế nào sau đây?","options":["Giữa các nước đế quốc đi xâm lược và các nước thuộc địa.","Giữa các dân tộc thuộc địa với nhau trong cùng một khu vực.","Giữa giai cấp công nhân với giai cấp tư sản ở chính quốc.","Giữa giai cấp tư sản chính quốc và công nhân thuộc địa."],"answer":0,"explain":"Quá trình xâm lược, nô dịch thuộc địa của các nước đế quốc đã làm nảy sinh mâu thuẫn mang tính thời đại giữa các dân tộc thuộc địa với các nước đế quốc đi xâm lược."},{"id":445,"section":"ch1-1","q":"Sự kiện nào sau đây tác động lớn, trực tiếp đến phong trào giải phóng dân tộc của các nước thuộc địa?","options":["Thắng lợi của Cách mạng Tháng Mười Nga (1917).","Sự ra đời Tuyên ngôn của Đảng Cộng sản (1848).","Cuộc khởi nghĩa Công xã Pari năm 1871.","Nguyễn Ái Quốc ra đi tìm đường cứu nước (1911)."],"answer":0,"explain":"Cách mạng Tháng Mười Nga (1917) đã mở ra một thời đại mới, tác động trực tiếp, cổ vũ mạnh mẽ phong trào giải phóng dân tộc ở các nước thuộc địa, trong đó có Việt Nam."},{"id":446,"section":"ch1-1","q":"Sơ thảo lần thứ nhất Luận cương về dân tộc và thuộc địa do V.I.Lênin khởi xướng được thông qua tại sự kiện","options":["Đại hội II của Quốc tế Cộng sản (1920).","sự ra đời của Quốc tế Cộng sản (1919).","Đại hội V Quốc tế Cộng sản (7/1935).","Đại hội Quốc tế nông dân (1923)."],"answer":0,"explain":"Bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của V.I.Lênin được thông qua tại Đại hội II Quốc tế Cộng sản (1920) — văn kiện mà Nguyễn Ái Quốc đọc được ngay trong năm này."},{"id":447,"section":"ch1-1","q":"Cuối thế kỉ XIX đầu thế kỉ XX, tính chất xã hội Việt Nam là","options":["xã hội thuộc địa, nửa phong kiến, mất độc lập về chính trị.","xã hội nửa thuộc địa, nửa phong kiến, còn giữ độc lập chủ quyền.","xã hội dân chủ, nửa phong kiến, có nền kinh tế tư bản phát triển.","xã hội dân chủ nhân dân, một phần thuộc địa, nửa phong kiến."],"answer":0,"explain":"Cuối thế kỉ XIX đầu thế kỉ XX, thực dân Pháp đã hoàn thành xâm lược và đặt ách thống trị lên toàn bộ Việt Nam, biến Việt Nam từ một nước phong kiến độc lập thành một xã hội thuộc địa, nửa phong kiến."},{"id":448,"section":"ch1-1","q":"Sự kiện nào sau đây mở đầu quá trình biến Việt Nam từ một nước phong kiến độc lập thành nước thuộc địa?","options":["Thực dân Pháp nổ súng xâm lược Việt Nam tại Đà Nẵng (1858).","Triều đình nhà Nguyễn từng bước thỏa hiệp với Pháp bằng Hiệp ước (1862).","Triều đình nhà Nguyễn kí với Pháp Hiệp ước Patơnốt (6/6/1884).","Triều đình nhà Nguyễn từng bước thỏa hiệp với Pháp bằng Hiệp ước (1883)."],"answer":0,"explain":"Ngày 1/9/1858, thực dân Pháp nổ súng tấn công Đà Nẵng, mở đầu quá trình xâm lược và biến Việt Nam từ một nước phong kiến độc lập thành thuộc địa của Pháp."},{"id":449,"section":"ch1-1","q":"Sự kiện nào sau đây đã chính thức biến Việt Nam thành xứ thuộc địa?","options":["Triều đình nhà Nguyễn kí với Pháp Hiệp ước Patơnốt (6/6/1884).","Năm 1858, thực dân Pháp nổ súng xâm lược Việt Nam tại Đà Nẵng.","Triều đình nhà Nguyễn từng bước thỏa hiệp với Pháp bằng Hiệp ước (1862).","Triều đình nhà Nguyễn từng bước thỏa hiệp với Pháp bằng Hiệp ước (1883)."],"answer":0,"explain":"Hiệp ước Patơnốt (6/6/1884) là văn kiện đánh dấu việc triều đình nhà Nguyễn đầu hàng hoàn toàn, chính thức biến Việt Nam thành xứ thuộc địa của thực dân Pháp."},{"id":450,"section":"ch1-1","q":"Thực dân Pháp thực hiện chính sách chia để trị ở Việt Nam nhằm mục đích chính là","options":["phá vỡ khối đại đoàn kết dân tộc Việt Nam để dễ bề thống trị.","dễ bề cai trị về hành chính, tiết kiệm chi phí bộ máy quản lý.","dễ kiểm soát về quân sự, thuận lợi cho việc đóng quân trên cả nước.","tạo điều kiện thuận lợi trong quản lý kinh tế và khai thác tài nguyên."],"answer":0,"explain":"Thực dân Pháp thực hiện chính sách chia để trị (chia Việt Nam thành ba kỳ với chế độ cai trị khác nhau, chia rẽ các dân tộc, tôn giáo) nhằm phá vỡ khối đại đoàn kết dân tộc, dễ bề thống trị lâu dài."},{"id":452,"section":"ch1-1","q":"Thực dân Pháp đã thực hiện chính sách nào sau đây để cai trị về văn hoá ở Việt Nam?","options":["Chính sách ngu dân.","Chính sách khai hoá.","Chính sách bình dân.","Chính sách an dân."],"answer":0,"explain":"Về văn hoá, thực dân Pháp thi hành chính sách ngu dân, hạn chế mở trường học, khuyến khích các tệ nạn xã hội nhằm dễ bề cai trị."},{"id":453,"section":"ch1-1","q":"Nhận định nào sau đây không phù hợp với chính sách khai thác thuộc địa và cai trị của thực dân Pháp về kinh tế?","options":["Pháp du nhập trọn vẹn phương thức sản xuất tư bản chủ nghĩa vào Việt Nam.","Pháp độc quyền xuất nhập khẩu, làm kinh tế Việt Nam lệ thuộc vào kinh tế Pháp.","Pháp vơ vét tài nguyên, cướp đoạt ruộng đất, bần cùng hoá giai cấp nông dân.","Pháp bóc lột nhân dân Việt Nam bằng sưu cao, thuế nặng, lương công nhân thấp."],"answer":0,"explain":"Trong khai thác thuộc địa, Pháp chỉ du nhập một cách hạn chế phương thức sản xuất tư bản chủ nghĩa (nhằm phục vụ khai thác, vơ vét), không phát triển kinh tế Việt Nam theo hướng tư bản chủ nghĩa một cách trọn vẹn, đầy đủ."},{"id":454,"section":"ch1-1","q":"Dưới sự tác động qua quá trình khai thác thuộc địa của thực dân Pháp, các giai cấp, tầng lớp trong xã hội Việt Nam đã phân hoá sâu sắc. Bộ phận nào sau đây không có tinh thần chống Pháp giành độc lập cho dân tộc?","options":["Tư sản mại bản, đại địa chủ.","Công nhân, tiểu tư sản.","Nông dân, địa chủ vừa và nhỏ.","Tiểu tư sản, tư sản dân tộc."],"answer":0,"explain":"Tư sản mại bản và đại địa chủ có quyền lợi gắn chặt với thực dân Pháp nên câu kết với Pháp, không có tinh thần chống Pháp giành độc lập dân tộc."},{"id":455,"section":"ch1-1","q":"Ở Việt Nam những năm 20 của thế kỉ XX, giai cấp, tầng lớp nào sau đây chiếm số lượng đông đảo trong xã hội, tinh thần cách mạng rất cao nhưng không thể lãnh đạo được phong trào cách mạng?","options":["Nông dân.","Công nhân.","Tiểu tư sản.","Địa chủ vừa và nhỏ."],"answer":0,"explain":"Nông dân chiếm số lượng đông đảo nhất, có tinh thần cách mạng và chống đế quốc phong kiến rất cao, nhưng do không đại diện cho một phương thức sản xuất tiên tiến nên không thể tự mình lãnh đạo phong trào cách mạng."},{"id":456,"section":"ch1-1","q":"Trong xã hội Việt Nam những năm 20 của thế kỉ XX, giai cấp nào phần lớn xuất thân từ nông dân, sớm được vũ trang bởi vũ khí lý luận (Chủ nghĩa Mác – Lênin) và vươn lên lãnh đạo phong trào cách mạng Việt Nam?","options":["Giai cấp công nhân.","Giai cấp nông dân.","Giai cấp tư sản.","Địa chủ vừa và nhỏ."],"answer":0,"explain":"Giai cấp công nhân Việt Nam phần lớn xuất thân từ nông dân, sớm tiếp thu chủ nghĩa Mác – Lênin, trở thành giai cấp duy nhất có đủ tư cách lãnh đạo cách mạng Việt Nam."},{"id":457,"section":"ch1-1","q":"Trong xã hội Việt Nam những năm 20 của thế kỉ XX, giai cấp, tầng lớp nào sau đây bị thực dân Pháp chèn ép, kìm hãm về kinh tế không đủ khả năng tập hợp đông đảo các giai cấp, tầng lớp nhân dân làm cách mạng?","options":["Tư sản dân tộc.","Công nhân.","Nông dân.","Tiểu tư sản."],"answer":0,"explain":"Giai cấp tư sản dân tộc Việt Nam nhỏ yếu về kinh tế, bị tư bản Pháp chèn ép nên không đủ khả năng tập hợp các giai cấp, tầng lớp khác để lãnh đạo cách mạng."},{"id":458,"section":"ch1-1","q":"Nguyên nhân chính khiến tầng lớp tiểu tư sản Việt Nam trong những năm 20 của thế kỉ XX dù yêu nước, nhạy bén về chính trị nhưng không thể lãnh đạo cách mạng là do","options":["địa vị kinh tế bấp bênh nên hay dao động, thiếu kiên định.","bị thực dân Pháp theo dõi, quản chế chặt chẽ về chính trị.","thiếu tri thức, chưa tiếp cận được lý luận cách mạng nào.","tư tưởng phong kiến ăn sâu vào tư duy, khó tiếp thu cái mới."],"answer":0,"explain":"Tiểu tư sản tuy yêu nước, nhạy bén với thời cuộc nhưng địa vị kinh tế bấp bênh, thái độ hay dao động, thiếu kiên định nên không thể đảm đương vai trò lãnh đạo cách mạng."},{"id":459,"section":"ch1-1","q":"Cuối thế kỉ XIX, đầu thế kỉ XX, mâu thuẫn chủ yếu trong xã hội Việt Nam là","options":["mâu thuẫn giữa dân tộc Việt Nam với Pháp và phong kiến tay sai.","mâu thuẫn giữa giai cấp nông dân với giai cấp địa chủ phong kiến.","mâu thuẫn giữa giai cấp công nhân với giai cấp tư sản bản xứ.","mâu thuẫn giữa giai cấp tư sản dân tộc và thực dân Pháp xâm lược."],"answer":0,"explain":"Cuối thế kỉ XIX đầu thế kỉ XX, bên cạnh mâu thuẫn giai cấp vốn có, xã hội Việt Nam nổi lên mâu thuẫn chủ yếu là mâu thuẫn giữa toàn thể dân tộc Việt Nam với thực dân Pháp và phong kiến tay sai."},{"id":460,"section":"ch1-1","q":"Cuối thế kỉ XIX, đầu thế kỉ XX, nhu cầu bức thiết nhất của giai cấp nông dân Việt Nam là","options":["sở hữu ruộng đất.","độc lập dân tộc.","tự do ngôn luận.","giảm sưu thuế."],"answer":1,"explain":"Việt Nam khi đó đã mất độc lập, nên mọi tầng lớp nhân dân – kể cả nông dân – trước hết đều bị áp bức bởi ách thống trị của thực dân Pháp. Chừng nào dân tộc chưa được giải phóng thì quyền lợi giai cấp, kể cả vấn đề ruộng đất của nông dân, cũng không thể giải quyết triệt để. Vì vậy, nhu cầu bức thiết nhất, bao trùm nhất đối với nông dân lúc này chính là độc lập dân tộc – có độc lập mới có cơ sở giành lại ruộng đất và các quyền lợi khác."},{"id":461,"section":"ch1-1","q":"Phong trào yêu nước nào sau đây theo khuynh hướng phong kiến?","options":["Phong trào Cần Vương, khởi nghĩa nông dân Yên Thế, khởi nghĩa Phan Đình Phùng.","Đông Du của Phan Bội Châu, Duy Tân của Phan Châu Trinh, khởi nghĩa Yên Bái.","Phong trào công nhân Ba Son, phong trào của Hội Việt Nam Cách mạng Thanh niên.","Phong trào đấu tranh của các đảng phái tư sản và tiểu tư sản Việt Nam."],"answer":0,"explain":"Cần Vương, khởi nghĩa nông dân Yên Thế, khởi nghĩa Phan Đình Phùng là các phong trào yêu nước cuối thế kỉ XIX theo khuynh hướng phong kiến (gắn với ý thức hệ trung quân, khôi phục vương triều)."},{"id":462,"section":"ch1-1","q":"Phong trào yêu nước nào sau đây theo khuynh hướng vô sản?","options":["Phong trào công nhân Ba Son, phong trào của Hội Việt Nam Cách mạng Thanh niên.","Phong trào Cần Vương, khởi nghĩa nông dân Yên Thế, khởi nghĩa Phan Đình Phùng.","Đông Du của Phan Bội Châu, Duy Tân của Phan Châu Trinh, khởi nghĩa Yên Bái.","Phong trào đấu tranh của các đảng phái tư sản và tiểu tư sản Việt Nam."],"answer":0,"explain":"Phong trào công nhân Ba Son và phong trào của Hội Việt Nam Cách mạng Thanh niên là các phong trào theo khuynh hướng vô sản, gắn với sự truyền bá chủ nghĩa Mác – Lênin vào Việt Nam."},{"id":463,"section":"ch1-1","q":"Tổ chức Việt Nam Quang phục hội với tôn chỉ là vũ trang đánh đuổi thực dân Pháp, khôi phục Việt Nam, thành lập nước Cộng hòa dân quốc Việt Nam do ai lập ra?","options":["Phan Bội Châu.","Nguyễn Ái Quốc.","Phan Châu Trinh.","Đào Duy Anh."],"answer":0,"explain":"Phan Bội Châu là người sáng lập Việt Nam Quang phục hội (1912) với tôn chỉ dùng vũ trang bạo động đánh đuổi thực dân Pháp, khôi phục nước Việt Nam, thành lập nước Cộng hoà Dân quốc Việt Nam."},{"id":464,"section":"ch1-1","q":"Nhà yêu nước nào theo khuynh hướng dân chủ tư sản đưa ra chủ trương dựa vào Nhật, bạo động đánh Pháp giành độc lập?","options":["Phan Bội Châu.","Phan Châu Trinh.","Nguyễn Thái Học.","Tôn Đức Thắng."],"answer":0,"explain":"Phan Bội Châu theo khuynh hướng dân chủ tư sản, chủ trương dựa vào Nhật Bản (phong trào Đông Du), tiến hành bạo động vũ trang để đánh Pháp giành độc lập."},{"id":465,"section":"ch1-1","q":"Nhà yêu nước nào theo khuynh hướng dân chủ tư sản đưa ra chủ trương \"khai dân trí, chấn dân khí, hậu dân sinh\"?","options":["Phan Châu Trinh.","Phan Bội Châu.","Nguyễn Thái Học.","Tôn Đức Thắng."],"answer":0,"explain":"Phan Châu Trinh chủ trương cải cách theo con đường ôn hoà, công khai, với phương châm “khai dân trí, chấn dân khí, hậu dân sinh”, không tán thành bạo động vũ trang."},{"id":466,"section":"ch1-1","q":"Lãnh tụ của Việt Nam Quốc dân Đảng là","options":["Nguyễn Thái Học.","Nguyễn Ái Quốc.","Phan Châu Trinh.","Tôn Đức Thắng."],"answer":0,"explain":"Nguyễn Thái Học là lãnh tụ sáng lập và lãnh đạo tổ chức Việt Nam Quốc dân Đảng (1927)."},{"id":467,"section":"ch1-1","q":"Khẩu hiệu “không thành công thì thành nhân” được nhân vật nào trong tổ chức Việt Nam Quốc dân Đảng đưa ra?","options":["Nguyễn Thái Học.","Nguyễn Bình.","Trần Huy Liệu.","Phó Đức Chính."],"answer":0,"explain":"Nguyễn Thái Học, trước khi bị thực dân Pháp xử chém sau khởi nghĩa Yên Bái (1930), đã để lại câu nói nổi tiếng “Không thành công thì thành nhân”."},{"id":468,"section":"ch1-1","q":"Nhân vật nào dưới đây từng là thành viên của tổ chức Việt Nam Quốc dân Đảng sau tham gia Đảng Cộng sản Đông Dương và từng giữ quân hàm trung tướng trong quân đội Việt Nam Dân chủ Cộng hoà?","options":["Nguyễn Bình.","Trần Huy Liệu.","Tôn Đức Thắng.","Phạm Văn Đồng."],"answer":0,"explain":"Nguyễn Bình từng là thành viên Việt Nam Quốc dân Đảng, sau đó tham gia cách mạng do Đảng Cộng sản Đông Dương lãnh đạo và trở thành vị Trung tướng đầu tiên của Quân đội nhân dân Việt Nam."},{"id":469,"section":"ch1-1","q":"Luận điểm nào sau đây không phù hợp với ý nghĩa của phong trào yêu nước theo khuynh hướng phong kiến và dân chủ tư sản trước khi ĐCSVN ra đời?","options":["Bước đầu đánh bại ý chí và dã tâm đô hộ của thực dân Pháp ở Đông Dương.","Thể hiện tinh thần yêu nước và ý chí bất khuất của dân tộc Việt Nam.","Cổ vũ mạnh mẽ tinh thần yêu nước trong quần chúng nhân dân.","Thúc đẩy các nhà yêu nước tìm kiếm con đường cứu nước mới cho dân tộc."],"answer":0,"explain":"Các phong trào yêu nước theo khuynh hướng phong kiến và dân chủ tư sản trước khi Đảng ra đời tuy thể hiện tinh thần yêu nước, cổ vũ quần chúng, thúc đẩy tìm đường cứu nước mới, nhưng đều lần lượt thất bại nên không thể coi là đã bước đầu đánh bại được ý chí, dã tâm đô hộ của thực dân Pháp."},{"id":470,"section":"ch1-1","q":"Nguyên nhân chủ yếu dẫn tới thất bại của các phong trào yêu nước theo khuynh hướng phong kiến, dân chủ tư sản cuối thế kỉ XIX, đầu thế kỉ XX ở Việt Nam là","options":["thiếu tổ chức lãnh đạo có đường lối phản ánh đúng quy luật lịch sử.","thiếu những lãnh tụ có uy tín và tài năng tổ chức phong trào.","thực dân Pháp quá mạnh về quân sự, vũ khí và tiềm lực kinh tế.","tinh thần yêu nước chưa đủ lớn, thiếu sự liên kết với các nước láng giềng."],"answer":0,"explain":"Các phong trào yêu nước theo khuynh hướng phong kiến, dân chủ tư sản đều thất bại chủ yếu do thiếu một tổ chức cách mạng với đường lối đúng đắn, phản ánh đúng yêu cầu khách quan của lịch sử dân tộc."},{"id":471,"section":"ch1-1","q":"Những bài viết của Nguyễn Ái Quốc trên các báo Nhân đạo, Đời sống công nhân, Tạp chí Cộng sản, Tập san Thư tín quốc tế đóng vai trò","options":["chuẩn bị về tư tưởng cho sự ra đời của Đảng.","chuẩn bị về tổ chức cho sự ra đời của Đảng.","chuẩn bị về lực lượng cho sự ra đời của Đảng.","tìm kiếm kinh phí cho hoạt động của Đảng."],"answer":0,"explain":"Những bài viết của Nguyễn Ái Quốc trên báo Nhân đạo, Đời sống công nhân, Tạp chí Cộng sản, Tập san Thư tín Quốc tế... đã truyền bá chủ nghĩa Mác – Lênin về Việt Nam, góp phần chuẩn bị về tư tưởng cho sự ra đời của Đảng."},{"id":472,"section":"ch1-1","q":"Hoạt động truyền bá chủ nghĩa Mác – Lênin của Nguyễn Ái Quốc góp phần chuẩn bị nội dung nào sau đây cho sự ra đời của Đảng?","options":["Chuẩn bị về tư tưởng cho sự ra đời của Đảng.","Chuẩn bị về tổ chức cho sự ra đời của Đảng.","Chuẩn bị về lực lượng cho sự ra đời của Đảng.","Tìm kiếm kinh phí cho hoạt động của Đảng."],"answer":0,"explain":"Hoạt động truyền bá chủ nghĩa Mác – Lênin của Nguyễn Ái Quốc trong những năm 1920 chủ yếu góp phần chuẩn bị về mặt tư tưởng cho sự ra đời của Đảng Cộng sản Việt Nam."},{"id":473,"section":"ch1-1","q":"Nội dung nào sau đây không phù hợp với việc chuẩn bị về chính trị của Nguyễn Ái Quốc cho sự ra đời của Đảng?","options":["Cách mạng giải phóng dân tộc phải do đảng của giai cấp tư sản lãnh đạo.","Khẳng định con đường cách mạng của các dân tộc bị áp bức là cách mạng vô sản.","Cách mạng vô sản ở thuộc địa và chính quốc có mối quan hệ mật thiết với nhau.","Sự nghiệp cách mạng là của chung toàn dân chúng chứ không phải ít người."],"answer":0,"explain":"Nguyễn Ái Quốc luôn khẳng định cách mạng giải phóng dân tộc phải do chính đảng của giai cấp công nhân (Đảng Cộng sản) lãnh đạo, chứ không phải một đảng tư sản."},{"id":474,"section":"ch1-1","q":"Sắp xếp theo đúng trình tự thời gian ra đời của các tổ chức sau","options":["Tâm tâm xã – Cộng sản đoàn – Hội Việt Nam Cách mạng Thanh niên.","Cộng sản đoàn - Tâm tâm xã – Hội Việt Nam Cách mạng Thanh niên.","Cộng sản đoàn - Hội Việt Nam Cách mạng Thanh niên – Tâm tâm xã.","Tâm tâm xã – Hội Việt Nam Cách mạng Thanh niên – Cộng sản đoàn."],"answer":0,"explain":"Trình tự ra đời đúng là: Tâm tâm xã (1923) – Cộng sản đoàn (2/1925) – Hội Việt Nam Cách mạng Thanh niên (6/1925)."},{"id":475,"section":"ch1-1","q":"Tổ chức nào sau đây được coi là tiền thân của Đảng Cộng sản Việt Nam?","options":["Hội Việt Nam Cách mạng Thanh niên (1925).","Tân Việt Cách mạng Đảng (Trung Kỳ, 1928).","Cộng sản đoàn (Quảng Châu, 2/1925).","Tâm tâm xã (Quảng Châu, năm 1923)."],"answer":0,"explain":"Hội Việt Nam Cách mạng Thanh niên (thành lập 6/1925) được coi là tổ chức tiền thân trực tiếp của Đảng Cộng sản Việt Nam."},{"id":476,"section":"ch1-1","q":"Tôn chỉ, mục đích của Báo Thanh niên (6/1925) do Nguyễn Ái Quốc sáng lập là","options":["truyền bá chủ nghĩa Mác – Lênin, chỉ rõ phương hướng giải phóng dân tộc.","cổ động thanh niên yêu nước tham gia cải cách giáo dục ôn hòa trong nước.","truyền bá tư tưởng dân chủ tư sản và chủ trương cải cách ôn hòa.","vận động Việt kiều ở hải ngoại quyên góp ủng hộ phong trào Đông Du."],"answer":0,"explain":"Báo Thanh niên (6/1925, cơ quan ngôn luận của Hội Việt Nam Cách mạng Thanh niên) có tôn chỉ truyền bá chủ nghĩa Mác – Lênin và phương hướng phát triển của cuộc vận động giải phóng dân tộc Việt Nam."},{"id":477,"section":"ch1-1","q":"Tờ báo đánh dấu sự ra đời báo chí cách mạng Việt Nam là","options":["báo Thanh niên.","báo Nhân dân.","báo Tiền phong.","báo Tuổi trẻ."],"answer":0,"explain":"Báo Thanh niên, do Nguyễn Ái Quốc sáng lập (6/1925), được coi là tờ báo đánh dấu sự ra đời của báo chí cách mạng Việt Nam."},{"id":478,"section":"ch1-1","q":"Hội Liên hiệp các dân tộc bị áp bức ở Á Đông xuất bản tác phẩm nào sau đây là tập hợp các bài giảng của Nguyễn Ái Quốc ở Quảng Châu?","options":["Tác phẩm Đường cách mệnh.","Bản án chế độ thực dân Pháp.","Vở kịch Con rồng tre.","Tác phẩm Đông Dương."],"answer":0,"explain":"“Đường Cách mệnh” (1927), tập hợp các bài giảng của Nguyễn Ái Quốc tại các lớp huấn luyện ở Quảng Châu, được Hội Liên hiệp các dân tộc bị áp bức ở Á Đông xuất bản."},{"id":479,"section":"ch1-1","q":"Trong những năm 1928 – 1929, phong trào nào sau đây góp phần quan trọng truyền bá chủ nghĩa Mác – Lênin vào phong trào công nhân và phong trào yêu nước ở Việt Nam?","options":["Phong trào vô sản hoá của hội viên Thanh niên.","Cuộc bãi công của công nhân Ba Son ở Sài Gòn.","Phong trào Duy Tân do Phan Châu Trinh khởi xướng.","Phong trào của Tân Việt cách mạng Đảng ở Trung Kỳ."],"answer":0,"explain":"Phong trào “vô sản hoá” (1928-1929) của Hội Việt Nam Cách mạng Thanh niên đã đưa hội viên vào sống, lao động cùng công nhân, góp phần quan trọng truyền bá chủ nghĩa Mác – Lênin vào phong trào công nhân và phong trào yêu nước."},{"id":480,"section":"ch1-1","q":"Chi bộ Cộng sản đầu tiên ở Việt Nam được thành lập tại số nhà 5D, phố Hàm Long, Hà Nội do ai làm bí thư?","options":["Trần Văn Cung.","Ngô Gia Tự.","Nguyễn Đức Cảnh.","Trịnh Đình Cửu."],"answer":0,"explain":"Chi bộ Cộng sản đầu tiên ở Việt Nam được thành lập (3/1929) tại số nhà 5D, phố Hàm Long, Hà Nội, do đồng chí Trần Văn Cung làm Bí thư."},{"id":481,"section":"ch1-1","q":"Tổ chức cộng sản nào sau đây được thành lập ở Bắc kì?","options":["Đông Dương Cộng sản Đảng (6/1929).","An Nam Cộng sản Đảng (11/1929).","Đông Dương Cộng sản Liên đoàn (9/1929).","Tân Việt cách mạng Đảng (7/1928)."],"answer":0,"explain":"Đông Dương Cộng sản Đảng (thành lập 6/1929, tại Bắc Kỳ) là một trong ba tổ chức cộng sản ra đời năm 1929."},{"id":483,"section":"ch1-1","q":"Nhận định nào sau đây phù hợp với ý nghĩa ra đời ba tổ chức cộng sản ở Việt Nam vào năm 1929?","options":["Khẳng định phong trào yêu nước đã chuyển hẳn sang khuynh hướng vô sản.","Khẳng định phong trào yêu nước đã chuyển hẳn sang khuynh hướng tư sản.","Khẳng định phong trào công nhân đã đủ sức giành chính quyền trong cả nước.","Khẳng định sự suy yếu của phong trào cách mạng Việt Nam trước thực dân Pháp."],"answer":0,"explain":"Sự ra đời của ba tổ chức cộng sản năm 1929 khẳng định bước phát triển về chất của phong trào yêu nước Việt Nam, chuyển hẳn sang khuynh hướng cách mạng vô sản."},{"id":484,"section":"ch1-1","q":"Sự ra đời của ba tổ chức cộng sản năm 1929 ở Việt Nam đặt ra yêu cầu bức thiết cần","options":["thành lập một chính đảng duy nhất đủ khả năng tập hợp lực lượng toàn dân tộc.","làm rõ ranh giới hoạt động của từng tổ chức để tránh tranh giành ảnh hưởng.","làm rõ hệ tư tưởng của từng tổ chức làm căn cứ lựa chọn tổ chức lãnh đạo.","lựa chọn một lãnh tụ có đủ khả năng tập hợp lực lượng giải phóng dân tộc."],"answer":0,"explain":"Ba tổ chức cộng sản hoạt động riêng rẽ, thậm chí công kích lẫn nhau, đặt ra yêu cầu bức thiết phải hợp nhất thành một chính đảng duy nhất, đủ sức tập hợp lực lượng toàn dân tộc thực hiện nhiệm vụ giải phóng dân tộc."},{"id":485,"section":"ch1-1","q":"Từ ngày 6/1/1930 đến ngày 7/2/1930 Hội nghị thành lập Đảng diễn ra tại Hồng Kông (Trung Quốc). Tham dự hội nghị không có đại diện của tổ chức nào sau đây?","options":["Đông Dương Cộng sản Liên đoàn (9/1929).","Đông Dương Cộng sản Đảng (Bắc Kỳ, 6/1929).","An Nam Cộng sản Đảng (Nam Kỳ, 11/1929).","Quốc tế Cộng sản (Quốc tế III, 1919)."],"answer":0,"explain":"Hội nghị hợp nhất các tổ chức cộng sản (6/1-7/2/1930) có đại diện của Đông Dương Cộng sản Đảng và An Nam Cộng sản Đảng; Đông Dương Cộng sản Liên đoàn (thành lập 9/1929) chưa kịp cử đại biểu tham dự, chỉ gia nhập Đảng sau đó (24/2/1930)."},{"id":486,"section":"ch1-1","q":"Cương lĩnh chính trị đầu tiên của Đảng (2/1930) là của ai?","options":["Lãnh tụ Nguyễn Ái Quốc.","Đồng chí Trịnh Đình Cửu.","Tổng Bí thư Trần Phú.","Đồng chí Hồ Tùng Mậu."],"answer":0,"explain":"Cương lĩnh chính trị đầu tiên của Đảng (2/1930) do Nguyễn Ái Quốc soạn thảo và được thông qua tại Hội nghị hợp nhất thành lập Đảng."},{"id":487,"section":"ch1-1","q":"Ngày 24/2/1930 Quyết nghị của Lâm thời chấp ủy Đảng Cộng sản Việt Nam, chấp nhận tổ chức nào sau đây gia nhập Đảng Cộng sản Việt Nam?","options":["Đông Dương Cộng sản Liên đoàn (9/1929).","Đông Dương Cộng sản Đảng (Bắc Kỳ, 6/1929).","An Nam Cộng sản Đảng (Nam Kỳ, 11/1929).","Tân Việt cách mạng Đảng (Trung Kỳ, 1928)."],"answer":0,"explain":"Ngày 24/2/1930, Lâm thời chấp uỷ Đảng Cộng sản Việt Nam ra quyết nghị chấp nhận Đông Dương Cộng sản Liên đoàn gia nhập Đảng Cộng sản Việt Nam, hoàn tất việc hợp nhất cả ba tổ chức cộng sản."},{"id":488,"section":"ch1-1","q":"Phương hướng chiến lược cách mạng được xác định trong Cương lĩnh chính trị tháng 2/1930 là","options":["làm tư sản dân quyền cách mạng và thổ địa cách mạng để đi tới xã hội cộng sản.","làm dân tộc cách mạng, bỏ qua thổ địa cách mạng, để đi tới xã hội cộng sản.","làm thổ địa cách mạng làm tiền đề giải phóng dân tộc để đi tới xã hội cộng sản.","làm thổ địa cách mạng triệt để, bỏ qua giai đoạn dân tộc, đi lên chủ nghĩa xã hội."],"answer":0,"explain":"Cương lĩnh chính trị đầu tiên (2/1930) xác định phương hướng chiến lược là làm tư sản dân quyền cách mạng và thổ địa cách mạng để đi tới xã hội cộng sản."},{"id":489,"section":"ch1-1","q":"Trong sách lược tập hợp lực lượng cách mạng thể hiện trong Cương lĩnh (2/1930), bộ phận nào là gốc của liên minh?","options":["Giai cấp công nhân và nông dân.","Chỉ riêng giai cấp công nhân.","Chỉ riêng giai cấp nông dân.","Công nhân và tiểu tư sản trí thức."],"answer":0,"explain":"Trong sách lược tập hợp lực lượng của Cương lĩnh chính trị đầu tiên, công nhân và nông dân được xác định là gốc của khối liên minh cách mạng."},{"id":490,"section":"ch1-1","q":"Nội dung nào sau đây phù hợp với chủ trương tập hợp lực lượng cách mạng trong Cương lĩnh (2/1930)?","options":["Đoàn kết mọi giai cấp, lực lượng tiến bộ, yêu nước để chống đế quốc và tay sai.","Chỉ đoàn kết giai cấp công nhân, nông dân để chống đế quốc và tay sai phong kiến.","Đoàn kết giai cấp công nhân, nông dân, tư sản để chống đế quốc và phong kiến.","Đoàn kết giai cấp công nhân, nông dân, tư sản, địa chủ để chống đế quốc Pháp."],"answer":0,"explain":"Cương lĩnh chính trị đầu tiên chủ trương đoàn kết tất cả các giai cấp, các lực lượng tiến bộ, yêu nước để tập trung chống đế quốc và tay sai, chứ không chỉ giới hạn ở công nhân, nông dân."},{"id":491,"section":"ch1-1","q":"Trong sách lược tập hợp lực lượng cách mạng nêu ra trong Cương lĩnh (2/1930) Đảng chủ trương lợi dụng, trung lập bộ phận nào sau đây?","options":["Trung, tiểu địa chủ và tư bản An Nam.","Đại bộ phận giai cấp nông dân nghèo.","Giai cấp công nhân thành thị và hầm mỏ.","Tiểu tư sản, trí thức, trung nông."],"answer":0,"explain":"Cương lĩnh chủ trương lợi dụng hoặc làm cho trung lập bộ phận trung, tiểu địa chủ và tư bản An Nam khi họ chưa lộ rõ mặt phản cách mạng."},{"id":492,"section":"ch1-1","q":"Nội dung nào sau đây phù hợp với phương pháp cách mạng được nêu ra trong Cương lĩnh (2/1930)?","options":["Kết hợp lực lượng chính trị quần chúng với lực lượng vũ trang nhân dân.","Chỉ sử dụng vũ lực của tổ chức đảng để lật đổ chính quyền thực dân.","Chỉ sử dụng lực lượng chính trị quần chúng, kiên trì đấu tranh hòa bình.","Kết hợp lực lượng vũ trang trong nước và lực lượng vũ trang quốc tế."],"answer":0,"explain":"Cương lĩnh chính trị đầu tiên xác định phương pháp cách mạng là dùng bạo lực cách mạng, kết hợp lực lượng chính trị của quần chúng với lực lượng vũ trang nhân dân."},{"id":493,"section":"ch1-1","q":"Theo Cương lĩnh (2/1930), luận điểm nào không phù hợp với vị trí của cách mạng Việt Nam trong mối quan hệ với cách mạng thế giới?","options":["Cách mạng Việt Nam chỉ giành được thắng lợi khi cách mạng ở chính quốc thắng lợi.","Cách mạng Việt Nam là một bộ phận khăng khít của cách mạng vô sản thế giới.","Cách mạng Việt Nam phải liên lạc với các dân tộc bị áp bức và vô sản thế giới.","Cách mạng Việt Nam cần tranh thủ sự ủng hộ của các dân tộc bị áp bức và vô sản thế giới."],"answer":0,"explain":"Cương lĩnh không đặt điều kiện cách mạng Việt Nam chỉ thắng lợi khi cách mạng ở chính quốc thắng lợi, mà xác định cách mạng Việt Nam là một bộ phận của cách mạng thế giới, có thể giành thắng lợi trong sự đoàn kết, ủng hộ lẫn nhau với cách mạng thế giới."},{"id":494,"section":"ch1-1","q":"Sự kiện nào sau đây đã chấm dứt thời kì khủng hoảng, bế tắc về đường lối cứu nước ở Việt Nam đầu thế kỉ XX?","options":["Sự ra đời của Đảng Cộng sản Việt Nam (1930).","Cuộc bãi công của công nhân Ba Son (1925).","Nguyễn Ái Quốc về nước lãnh đạo cách mạng (1941).","Thắng lợi của Cách mạng Tháng Tám (1945)."],"answer":0,"explain":"Sự ra đời của Đảng Cộng sản Việt Nam (1930) đã chấm dứt thời kỳ khủng hoảng về đường lối cứu nước kéo dài từ cuối thế kỉ XIX đến đầu thế kỉ XX."},{"id":495,"section":"ch1-1","q":"Nội dung nào sau đây đúng với quy luật ra đời của ĐCSVN?","options":["ĐCSVN ra đời là sự kết hợp giữa chủ nghĩa Mác – Lênin với phong trào công nhân và phong trào yêu nước.","ĐCSVN ra đời là sự kết hợp giữa chủ nghĩa Mác – Lênin với phong trào công nhân.","ĐCSVN ra đời là sự kết hợp giữa chủ nghĩa Mác – Lênin với phong trào dân tộc chủ nghĩa ở Việt Nam.","ĐCSVN ra đời là sự kết hợp giữa chủ nghĩa Mác – Lênin với phong trào nông dân và phong trào tư sản Việt Nam."],"answer":0,"explain":"Khác với các nước tư bản phương Tây, ở Việt Nam Đảng Cộng sản ra đời là sản phẩm của sự kết hợp giữa chủ nghĩa Mác – Lênin với phong trào công nhân và phong trào yêu nước."},{"id":496,"section":"ch1-1","q":"Chọn nhận định sai về ý nghĩa ra đời của ĐCSVN.","options":["Sự ra đời của ĐCSVN khẳng định khả năng lãnh đạo của giai cấp tư sản dân tộc Việt Nam.","ĐCSVN ra đời phản ánh khát vọng độc lập dân tộc và tự do cho nhân dân Việt Nam.","ĐCSVN là nhân tố hàng đầu quyết định thắng lợi của cách mạng Việt Nam.","Sự ra đời của ĐCSVN đã khẳng định cách mạng Việt Nam là một bộ phận của cách mạng thế giới."],"answer":0,"explain":"Sự ra đời của Đảng Cộng sản Việt Nam khẳng định vai trò lãnh đạo thuộc về giai cấp công nhân thông qua đội tiền phong của mình, chứ không phải giai cấp tư sản dân tộc."},{"id":497,"section":"ch1-1","q":"Cuộc khủng hoảng kinh tế thế giới (1929 -1933) diễn ra chủ yếu ở các nước tư bản là","options":["khủng hoảng thừa.","khủng hoảng thiếu.","khủng hoảng nhân sự.","khủng hoảng dầu mỏ."],"answer":0,"explain":"Cuộc khủng hoảng kinh tế thế giới 1929-1933 là cuộc khủng hoảng thừa (sản xuất vượt quá sức mua của xã hội) diễn ra trầm trọng ở các nước tư bản chủ nghĩa."},{"id":559,"section":"ch1-1","q":"Trước khi thực dân Pháp nổ súng xâm lược (1858), chế độ phong kiến Việt Nam dưới triều Nguyễn đang ở trong tình trạng như thế nào?","options":["Khủng hoảng, suy yếu nghiêm trọng về kinh tế, chính trị, xã hội","Đang ở thời kỳ cực thịnh, hùng mạnh bậc nhất khu vực Đông Nam Á","Đã hoàn thành công nghiệp hóa, trở thành nước tư bản phát triển","Đã thiết lập quan hệ ngoại giao bình đẳng với các nước phương Tây"],"answer":0,"explain":"Giữa thế kỷ XIX, chế độ phong kiến nhà Nguyễn lâm vào khủng hoảng, suy yếu nghiêm trọng, tạo điều kiện cho thực dân Pháp xâm lược."},{"id":560,"section":"ch1-1","q":"Sau khi hoàn thành xâm lược, thực dân Pháp thiết lập chế độ cai trị nào ở Việt Nam?","options":["Chế độ thuộc địa nửa phong kiến, chia nước thành ba kỳ cai trị riêng","Chế độ cộng hòa dân chủ, nhân dân có quyền tự do bầu cử và ứng cử","Trao trả độc lập hoàn toàn cho triều đình Huế và rút quân về nước","Sáp nhập Việt Nam làm một tỉnh của Pháp có quyền bầu cử ngang Pháp"],"answer":0,"explain":"Pháp thiết lập chế độ thuộc địa nửa phong kiến, chia Việt Nam thành ba kỳ (Bắc Kỳ, Trung Kỳ, Nam Kỳ) với ba chế độ cai trị khác nhau nhằm chia rẽ dân tộc."},{"id":561,"section":"ch1-1","q":"Mâu thuẫn cơ bản, chủ yếu trong xã hội Việt Nam đầu thế kỷ XX là gì?","options":["Mâu thuẫn giữa dân tộc Việt Nam với thực dân Pháp và giữa nông dân với địa chủ","Mâu thuẫn giữa giai cấp tư sản dân tộc với giai cấp tư sản mại bản người Việt","Mâu thuẫn giữa nhân dân Bắc Kỳ với nhân dân Nam Kỳ do chính sách chia để trị","Mâu thuẫn giữa tín đồ Phật giáo với tín đồ Công giáo trong cộng đồng dân tộc"],"answer":0,"explain":"Xã hội Việt Nam đầu thế kỷ XX tồn tại hai mâu thuẫn cơ bản: dân tộc Việt Nam với thực dân Pháp xâm lược, và nông dân với địa chủ phong kiến, trong đó mâu thuẫn dân tộc là chủ yếu, gay gắt nhất."},{"id":562,"section":"ch1-1","q":"Phong trào Đông Du do Phan Bội Châu tổ chức có chủ trương chính là gì?","options":["Đưa thanh niên sang Nhật Bản học tập, chuẩn bị lực lượng bạo động đánh Pháp","Kêu gọi cải cách ôn hòa, dựa vào Pháp để khai hóa dân trí, nâng cao dân khí","Vận động thành lập nghị viện lập hiến trong khuôn khổ chế độ thuộc địa Pháp","Tổ chức tổng bãi công của công nhân các thành phố lớn trên toàn quốc"],"answer":0,"explain":"Phong trào Đông Du (đầu thế kỷ XX) do Phan Bội Châu khởi xướng, đưa thanh niên sang Nhật Bản du học nhằm đào tạo nhân tài, chuẩn bị lực lượng cho bạo động vũ trang giành độc lập."},{"id":563,"section":"ch1-1","q":"Điểm khác biệt cơ bản giữa chủ trương cứu nước của Phan Châu Trinh so với Phan Bội Châu là gì?","options":["Phan Châu Trinh chủ trương cải cách ôn hòa, dựa vào Pháp để khai dân trí","Phan Châu Trinh chủ trương bạo động vũ trang ngay lập tức, không chờ thời cơ","Phan Châu Trinh chủ trương cầu viện nước ngoài đưa quân vào đánh đuổi Pháp","Phan Châu Trinh chủ trương thành lập chính đảng vô sản để lãnh đạo cách mạng"],"answer":0,"explain":"Khác với xu hướng bạo động của Phan Bội Châu, Phan Châu Trinh chủ trương cải cách xã hội theo hướng ôn hòa, công khai, hô hào duy tân, khai dân trí, chấn dân khí, hậu dân sinh."},{"id":564,"section":"ch1-1","q":"Tất cả các phong trào yêu nước theo khuynh hướng phong kiến và tư sản cuối thế kỷ XIX, đầu thế kỷ XX ở Việt Nam đều có kết cục chung như thế nào?","options":["Đều lần lượt thất bại do thiếu đường lối đúng đắn và giai cấp lãnh đạo","Đều giành được thắng lợi bước đầu nhưng chưa triệt để về chính trị","Đều buộc thực dân Pháp chấp nhận trao trả độc lập từng phần cho Việt Nam","Đều chuyển hóa thành công thành các đảng cộng sản ngay sau khi thất bại"],"answer":0,"explain":"Do thiếu một đường lối cứu nước đúng đắn và một giai cấp lãnh đạo tiên tiến, các phong trào yêu nước theo khuynh hướng phong kiến và tư sản đều lần lượt thất bại, đặt ra yêu cầu bức thiết về con đường cứu nước mới."},{"id":565,"section":"ch1-1","q":"Trong quá trình bôn ba tìm đường cứu nước, Nguyễn Tất Thành đã làm nhiều nghề để kiếm sống và tìm hiểu thực tế xã hội các nước, trong đó có công việc nào tại Pháp?","options":["Làm các nghề lao động phổ thông như phụ bếp, rửa ảnh, làm vườn","Làm quan chức cấp cao trong bộ máy chính quyền thuộc địa Pháp","Làm giảng viên đại học tại Paris để kiếm sống và nghiên cứu","Làm chủ một xưởng sản xuất công nghiệp lớn ở ngoại ô Paris"],"answer":0,"explain":"Trong những năm bôn ba ở nước ngoài, Nguyễn Tất Thành đã làm nhiều nghề lao động phổ thông (phụ bếp trên tàu, quét tuyết, làm vườn, rửa ảnh...) để có điều kiện sinh sống, hoạt động và tìm hiểu thực tế đời sống của nhân dân lao động các nước."},{"id":566,"section":"ch1-1","q":"Điểm khác biệt căn bản trong hướng đi tìm đường cứu nước của Nguyễn Tất Thành so với các bậc tiền bối là gì?","options":["Sang phương Tây, đến chính nước Pháp đang đô hộ Việt Nam để tìm hiểu","Sang phương Đông cầu viện các nước đồng văn, đồng chủng để đánh Pháp","Ở lại trong nước tổ chức bạo động vũ trang để giành chính quyền","Chỉ nghiên cứu qua sách vở kinh điển Nho giáo tại quê hương"],"answer":0,"explain":"Khác với hướng Đông Du, Nguyễn Tất Thành sang phương Tây, đến nước Pháp và nhiều nước khác, hòa mình vào phong trào công nhân và các dân tộc thuộc địa để khảo sát thực tiễn, tìm con đường cứu nước mới."},{"id":567,"section":"ch1-1","q":"Sau khi tìm ra con đường cứu nước đúng đắn (7/1920), Nguyễn Ái Quốc đã tích cực chuẩn bị những điều kiện gì để truyền bá chủ nghĩa Mác - Lênin về Việt Nam?","options":["Viết bài cho báo chí cách mạng, sáng lập tổ chức của Việt kiều, mở lớp huấn luyện","Trực tiếp về nước lãnh đạo khởi nghĩa vũ trang giành chính quyền ngay lập tức","Chỉ tập trung học tập lý luận ở thư viện, chưa có hoạt động thực tiễn nào","Hợp tác với chính quyền thực dân Pháp để thực hiện cải cách ôn hòa ở thuộc địa"],"answer":0,"explain":"Sau khi tìm ra con đường cứu nước đúng đắn, Nguyễn Ái Quốc tích cực chuẩn bị về tư tưởng, chính trị và tổ chức: viết bài cho báo chí cách mạng (Người cùng khổ, Nhân đạo...), tham gia sáng lập các tổ chức yêu nước của Việt kiều, sau đó thành lập Hội Việt Nam Cách mạng Thanh niên, mở các lớp huấn luyện chính trị đào tạo cán bộ để chuẩn bị cho việc thành lập chính đảng vô sản."},{"id":568,"section":"ch1-1","q":"Sau khi trở thành người cộng sản (1920), Nguyễn Ái Quốc tích cực hoạt động trong tổ chức nào của những người Việt Nam yêu nước tại Pháp?","options":["Hội những người Việt Nam yêu nước","Việt Nam Quang phục hội ở Quảng Châu","Hội Việt Nam Cách mạng Thanh niên","Tân Việt Cách mạng đảng ở Trung Kỳ"],"answer":0,"explain":"Tại Pháp, Nguyễn Ái Quốc tích cực hoạt động trong Hội những người Việt Nam yêu nước, đồng thời tham gia sáng lập Hội Liên hiệp thuộc địa và là linh hồn của tờ báo Le Paria (Người cùng khổ), tuyên truyền tư tưởng yêu nước, cách mạng."},{"id":569,"section":"ch1-1","q":"Tác phẩm \"Bản án chế độ thực dân Pháp\" của Nguyễn Ái Quốc được xuất bản lần đầu vào năm nào, tại đâu?","options":["Năm 1925, tại Paris (Pháp)","Năm 1927, tại Quảng Châu","Năm 1930, tại Hương Cảng","Năm 1941, tại Cao Bằng"],"answer":0,"explain":"Tác phẩm \"Bản án chế độ thực dân Pháp\" được Nguyễn Ái Quốc viết bằng tiếng Pháp, xuất bản lần đầu tại Paris năm 1925, tố cáo tội ác của chủ nghĩa thực dân."},{"id":570,"section":"ch1-1","q":"Hội Việt Nam Cách mạng Thanh niên do Nguyễn Ái Quốc thành lập vào tháng 6/1925 có vai trò lịch sử gì?","options":["Là tổ chức tiền thân của Đảng, truyền bá chủ nghĩa Mác - Lênin, chuẩn bị tư tưởng, tổ chức cho Đảng","Là chính đảng vô sản đầu tiên, lãnh đạo cách mạng Việt Nam đi tới thắng lợi hoàn toàn và triệt để","Là mặt trận dân tộc thống nhất đầu tiên, tập hợp mọi giai tầng yêu nước để chống đế quốc Pháp","Là tổ chức quân sự đầu tiên của cách mạng, trực tiếp chỉ huy các cuộc khởi nghĩa vũ trang lớn"],"answer":0,"explain":"Hội Việt Nam Cách mạng Thanh niên tại Quảng Châu (6/1925) là tổ chức tiền thân, có vai trò truyền bá chủ nghĩa Mác - Lênin về nước, đào tạo cán bộ, chuẩn bị về chính trị, tư tưởng và tổ chức cho việc thành lập chính đảng vô sản sau này."},{"id":571,"section":"ch1-1","q":"Sự ra đời của ba tổ chức cộng sản ở Việt Nam trong năm 1929 phản ánh điều gì về phong trào cách mạng lúc bấy giờ?","options":["Phong trào vô sản phát triển mạnh, đòi hỏi phải sớm thống nhất thành một chính đảng duy nhất","Phong trào cách mạng Việt Nam đã bị thực dân Pháp dập tắt hoàn toàn và phải chấm dứt hoạt động","Ba miền Bắc, Trung, Nam có ba đường lối cách mạng khác nhau, vĩnh viễn không thể thống nhất","Chủ nghĩa Mác - Lênin chưa được truyền bá vào Việt Nam nên chưa có cơ sở thành lập chính đảng"],"answer":0,"explain":"Việc ba tổ chức cộng sản cùng ra đời trong năm 1929 cho thấy sự phát triển mạnh mẽ, tất yếu của phong trào cách mạng theo khuynh hướng vô sản, nhưng tình trạng ba tổ chức hoạt động riêng rẽ đặt ra yêu cầu bức thiết phải hợp nhất thành một đảng duy nhất để thống nhất lãnh đạo."},{"id":572,"section":"ch1-1","q":"Nguyễn Ái Quốc được Quốc tế Cộng sản giao nhiệm vụ hợp nhất các tổ chức cộng sản ở Việt Nam với tư cách gì?","options":["Phái viên của Quốc tế Cộng sản, chủ trì Hội nghị hợp nhất","Đại diện của Quốc dân Đảng Trung Hoa, chủ trì Hội nghị hợp nhất","Đại diện triều đình nhà Nguyễn, giám sát Hội nghị hợp nhất","Đại biểu chính quyền thực dân Pháp, giám sát Hội nghị hợp nhất"],"answer":0,"explain":"Với tư cách là phái viên của Quốc tế Cộng sản, Nguyễn Ái Quốc chủ động triệu tập và chủ trì Hội nghị hợp nhất các tổ chức cộng sản, thành lập Đảng Cộng sản Việt Nam."},{"id":573,"section":"ch1-1","q":"Cương lĩnh chính trị đầu tiên của Đảng (2/1930) xác định phương diện chính trị của cách mạng tư sản dân quyền bao gồm nội dung gì?","options":["Đánh đổ đế quốc chủ nghĩa Pháp và bọn phong kiến, làm cho nước Việt Nam hoàn toàn độc lập","Chỉ tập trung cải cách bộ máy hành chính thuộc địa để cải thiện đời sống cho nhân dân","Duy trì quan hệ với chính quyền thực dân Pháp, đòi Pháp trao quyền tự trị cho Việt Nam","Chỉ đề cập tới việc thành lập chính phủ liên hiệp với các đảng phái tư sản và địa chủ"],"answer":0,"explain":"Về phương diện chính trị, Cương lĩnh xác định: đánh đổ đế quốc chủ nghĩa Pháp và bọn phong kiến, làm cho nước Việt Nam được hoàn toàn độc lập, dựng ra chính phủ công nông binh, tổ chức quân đội công nông."},{"id":574,"section":"ch1-1","q":"Cương lĩnh chính trị đầu tiên của Đảng khẳng định cách mạng Việt Nam là một bộ phận của phong trào nào trên thế giới?","options":["Phong trào cách mạng vô sản thế giới, gắn bó mật thiết với vô sản Pháp và các dân tộc bị áp bức","Phong trào Duy tân của các nước châu Á, gắn bó chặt chẽ với Nhật Bản, Trung Hoa và Xiêm","Phong trào dân chủ tư sản thế giới, có quan hệ mật thiết với giai cấp tư sản Pháp và Anh","Phong trào ly khai của các nước thuộc địa Anh, gắn bó chặt chẽ với Ấn Độ, Ai Cập và Miến Điện"],"answer":0,"explain":"Cương lĩnh khẳng định cách mạng Việt Nam là một bộ phận khăng khít của cách mạng vô sản thế giới, phải liên lạc mật thiết với vô sản và các dân tộc bị áp bức trên thế giới."},{"id":575,"section":"ch1-1","q":"So với Luận cương chính trị (10/1930), Cương lĩnh chính trị đầu tiên (2/1930) có ưu điểm nổi bật gì về xác định mâu thuẫn và nhiệm vụ cách mạng?","options":["Đặt nhiệm vụ giải phóng dân tộc lên hàng đầu, sát thực tiễn một nước thuộc địa nửa phong kiến","Coi nhẹ hoàn toàn vấn đề dân tộc, chỉ tập trung đấu tranh giai cấp và cách mạng ruộng đất","Chủ trương liên minh với đế quốc Pháp để cùng chống lại phong kiến trong thời gian dài","Không đề cập vai trò lãnh đạo của Đảng, giao nhiệm vụ lãnh đạo cho giai cấp tư sản"],"answer":0,"explain":"Cương lĩnh chính trị đầu tiên đặt nhiệm vụ chống đế quốc, giải phóng dân tộc lên hàng đầu, thể hiện sự vận dụng sáng tạo, sát đúng với thực tiễn một nước thuộc địa nửa phong kiến như Việt Nam, khắc phục được hạn chế \"tả khuynh\" sau này của Luận cương 10/1930 về việc đặt nặng đấu tranh giai cấp."},{"id":576,"section":"ch1-1","q":"Đảng Cộng sản Việt Nam ra đời đầu năm 1930 đã chấm dứt tình trạng gì trong phong trào cách mạng Việt Nam?","options":["Khủng hoảng sâu sắc về đường lối cứu nước và về giai cấp lãnh đạo cách mạng","Ách thống trị tàn bạo của thực dân Pháp trên khắp lãnh thổ Việt Nam","Mọi mâu thuẫn giai cấp trong xã hội Việt Nam từ đầu thế kỷ XX","Sự tồn tại của giai cấp địa chủ phong kiến ở các vùng nông thôn Việt Nam"],"answer":0,"explain":"Đảng Cộng sản Việt Nam ra đời chấm dứt tình trạng khủng hoảng sâu sắc, kéo dài về đường lối cứu nước và giai cấp lãnh đạo cách mạng Việt Nam đầu thế kỷ XX, mở ra bước ngoặt lịch sử vĩ đại."},{"id":746,"section":"ch1-1","q":"Năm 1862, thực dân Pháp đã cho xây dựng nhà tù nào sau đây để giam cầm những người Việt Nam yêu nước?","options":["Nhà tù Hoả Lò.","Khám Chí Hoà.","Nhà tù Côn Đảo.","Nhà tù Sơn La."],"answer":2,"explain":"Năm 1862, ngay sau khi chiếm Côn Đảo theo Hòa ước Nhâm Tuất, thực dân Pháp đã cho xây dựng nhà tù Côn Đảo để giam cầm những người Việt Nam yêu nước, cách mạng."},{"id":747,"section":"ch1-1","q":"Những ai sau đây từng là thành viên của Tân Việt Cách mạng Đảng?","options":["Trịnh Đình Cửu, Ngô Gia Tự, Châu Văn Liêm.","Võ Nguyên Giáp, Nguyễn Thị Minh Khai, Hà Huy Tập.","Trần Văn Cung, Nguyễn Đức Cảnh, Hồ Tùng Mậu.","Lê Hồng Sơn, Trần Não, Phạm Hồng Thái, Hồ Học Lãm."],"answer":1,"explain":"Võ Nguyên Giáp, Nguyễn Thị Minh Khai và Hà Huy Tập đều từng tham gia Tân Việt Cách mạng Đảng trước khi theo con đường cộng sản."},{"id":76,"section":"ch1-2","q":"Cuộc biểu tình của nông dân Hưng Nguyên (Nghệ An) bị đàn áp dữ dội, máy bay Pháp ném bom giết chết bao nhiêu người, vào ngày nào?","options":["171 người, ngày 12/9/1930","500 người, ngày 1/5/1930","50 người, ngày 9/2/1930","1000 người, ngày 17/6/1930"],"answer":0,"explain":"Ngày 12/9/1930, cuộc biểu tình của nông dân Hưng Nguyên bị đàn áp dữ dội, máy bay Pháp ném bom giết chết 171 người."},{"id":77,"section":"ch1-2","q":"Đỉnh cao của phong trào cách mạng 1930-1931 là sự kiện nào?","options":["Xô viết Nghệ - Tĩnh","Khởi nghĩa Bắc Sơn","Khởi nghĩa Nam Kỳ","Cao trào kháng Nhật"],"answer":0,"explain":"Phong trào cách mạng 1930-1931 phát triển đến đỉnh cao với sự ra đời của chính quyền Xô viết ở Nghệ An và Hà Tĩnh."},{"id":78,"section":"ch1-2","q":"Hội nghị Ban Chấp hành Trung ương lần thứ nhất (10/1930) đã thông qua văn kiện nào và đổi tên Đảng ra sao?","options":["Luận cương chính trị, đổi tên thành Đảng Cộng sản Đông Dương","Chính cương vắn tắt, đổi tên thành Đảng Lao động Việt Nam","Chương trình hành động, giữ nguyên tên Đảng Cộng sản Việt Nam","Nghị quyết Hội nghị Trung ương 8, đổi tên thành Việt Minh"],"answer":0,"explain":"Từ 14 đến 31/10/1930, Hội nghị Trung ương họp tại Hương Cảng, thông qua Luận cương chính trị và đổi tên Đảng Cộng sản Việt Nam thành Đảng Cộng sản Đông Dương."},{"id":79,"section":"ch1-2","q":"Ai được bầu làm Tổng Bí thư đầu tiên của Đảng tại Hội nghị Trung ương tháng 10/1930?","options":["Trần Phú","Lê Hồng Phong","Hà Huy Tập","Nguyễn Văn Cừ"],"answer":0,"explain":"Tại Hội nghị Trung ương tháng 10/1930, đồng chí Trần Phú được bầu làm Tổng Bí thư của Đảng."},{"id":80,"section":"ch1-2","q":"Tổng Bí thư Trần Phú hy sinh vào ngày nào, tại đâu?","options":["Ngày 6/9/1931, tại Nhà thương Chợ Quán (Sài Gòn)","Ngày 12/9/1930, tại huyện Hưng Nguyên (Nghệ An)","Ngày 18/11/1930, tại Nhà tù Hỏa Lò ở Hà Nội","Ngày 8/9/1942, tại Trại giam Côn Đảo (Bà Rịa)"],"answer":0,"explain":"Tổng Bí thư Trần Phú hy sinh ngày 6/9/1931 tại Nhà thương Chợ Quán (Sài Gòn) với lời căn dặn: \"Hãy giữ vững chí khí chiến đấu!\"."},{"id":81,"section":"ch1-2","q":"Hạn chế của Luận cương chính trị tháng 10/1930 so với Cương lĩnh chính trị đầu tiên là gì?","options":["Không nêu rõ mâu thuẫn dân tộc, nặng về đấu tranh giai cấp và cách mạng ruộng đất","Không đề cập đến vấn đề đấu tranh giai cấp, chỉ chú trọng nhiệm vụ giải phóng dân tộc","Xác định sai kẻ thù của cách mạng là đế quốc Mỹ và phát xít Nhật trong năm 1930","Chủ trương thỏa hiệp với thực dân Pháp để tập hợp lực lượng trong thời gian dài"],"answer":0,"explain":"Luận cương không nêu rõ mâu thuẫn chủ yếu của xã hội Việt Nam thuộc địa, không nhấn mạnh nhiệm vụ giải phóng dân tộc mà nặng về đấu tranh giai cấp và cách mạng ruộng đất."},{"id":82,"section":"ch1-2","q":"Đại hội đại biểu lần thứ I của Đảng họp vào thời gian nào, ở đâu?","options":["Tháng 3/1935, tại Ma Cao (Trung Quốc)","Tháng 10/1930, tại Hương Cảng (Trung Quốc)","Tháng 9/1960, tại Hà Nội (Việt Nam)","Tháng 2/1951, tại Tuyên Quang (Việt Bắc)"],"answer":0,"explain":"Tháng 3/1935, Đại hội đại biểu lần thứ I của Đảng họp tại Ma Cao (Trung Quốc)."},{"id":83,"section":"ch1-2","q":"Ai được bầu làm Tổng Bí thư tại Đại hội lần thứ I của Đảng (3/1935)?","options":["Lê Hồng Phong","Trần Phú","Nguyễn Văn Cừ","Hà Huy Tập"],"answer":0,"explain":"Đại hội lần thứ I bầu Ban Chấp hành Trung ương do đồng chí Lê Hồng Phong làm Tổng Bí thư."},{"id":84,"section":"ch1-2","q":"Hội nghị Trung ương Đảng (7/1936) họp tại Thượng Hải, do ai chủ trì, nhằm mục đích gì?","options":["Do Lê Hồng Phong chủ trì, nhằm sửa chữa sai lầm và định ra chính sách mới","Do Nguyễn Ái Quốc chủ trì, nhằm thành lập Mặt trận Việt Minh và xây dựng căn cứ địa","Do Trường Chinh chủ trì, nhằm phát động Tổng khởi nghĩa giành chính quyền toàn quốc","Do Hà Huy Tập chủ trì, nhằm giải tán Đảng và chuyển sang hoạt động hợp pháp"],"answer":0,"explain":"Ngày 26/7/1936, Ban Chấp hành Trung ương Đảng họp Hội nghị tại Thượng Hải, do Lê Hồng Phong chủ trì, nhằm sửa chữa sai lầm trước đó và định lại chính sách mới theo Đại hội VII Quốc tế Cộng sản."},{"id":85,"section":"ch1-2","q":"Ai làm Tổng Bí thư của Đảng từ tháng 8/1936 đến tháng 3/1938?","options":["Hà Huy Tập","Lê Hồng Phong","Nguyễn Văn Cừ","Trường Chinh"],"answer":0,"explain":"Đồng chí Hà Huy Tập là Tổng Bí thư của Đảng từ tháng 8/1936 đến tháng 3/1938."},{"id":86,"section":"ch1-2","q":"Hội nghị Trung ương Đảng (29-30/3/1938) quyết định lập mặt trận nào, bầu ai làm Tổng Bí thư?","options":["Mặt trận Dân chủ Đông Dương, bầu Nguyễn Văn Cừ làm Tổng Bí thư","Mặt trận Việt Minh, bầu Trường Chinh làm Tổng Bí thư của Đảng","Mặt trận Liên Việt, bầu Lê Duẩn làm Tổng Bí thư của Đảng","Mặt trận Tổ quốc, bầu Phạm Văn Đồng làm Tổng Bí thư của Đảng"],"answer":0,"explain":"Hội nghị Trung ương Đảng (29-30/3/1938) quyết định lập Mặt trận Dân chủ Đông Dương và bầu đồng chí Nguyễn Văn Cừ làm Tổng Bí thư."},{"id":87,"section":"ch1-2","q":"Tác phẩm \"Tự chỉ trích\" (1939) là của ai, có ý nghĩa gì?","options":["Của Nguyễn Văn Cừ, chỉ rõ khuyết điểm và rút bài học trong lãnh đạo của Đảng","Của Nguyễn Ái Quốc, vạch ra đường lối cách mạng giải phóng dân tộc cho toàn Đảng","Của Trường Chinh, tổng kết kinh nghiệm cuộc kháng chiến chống thực dân Pháp","Của Lê Duẩn, phân tích đặc điểm và con đường cách mạng ở miền Nam Việt Nam"],"answer":0,"explain":"Năm 1939, Tổng Bí thư Nguyễn Văn Cừ xuất bản cuốn Tự chỉ trích, thẳng thắn chỉ rõ những sai lầm, khuyết điểm, nêu rõ bài học cần thiết trong lãnh đạo, chỉ đạo của Đảng."},{"id":88,"section":"ch1-2","q":"Hội nghị Ban Chấp hành Trung ương Đảng (11/1939) họp ở đâu, đánh dấu bước chuyển hướng chỉ đạo chiến lược nào?","options":["Tại Bà Điểm (Gia Định), đặt nhiệm vụ giải phóng dân tộc lên hàng đầu","Tại Pác Bó (Cao Bằng), thành lập Mặt trận Việt Minh để tập hợp lực lượng","Tại Tân Trào (Tuyên Quang), phát động Tổng khởi nghĩa giành chính quyền","Tại Võng La (Đông Anh), chuẩn bị ngay khởi nghĩa vũ trang trong cả nước"],"answer":0,"explain":"Hội nghị Ban Chấp hành Trung ương Đảng (11/1939) họp tại Bà Điểm (Hóc Môn, Gia Định), đặt nhiệm vụ giải phóng dân tộc lên hàng đầu, chủ trương thành lập Mặt trận Thống nhất dân tộc phản đế Đông Dương."},{"id":89,"section":"ch1-2","q":"Hội nghị Ban Chấp hành Trung ương Đảng lần thứ tám (5/1941) do ai chủ trì, tại đâu?","options":["Do Nguyễn Ái Quốc chủ trì, tại Pác Bó (Cao Bằng)","Do Trường Chinh chủ trì, tại Bà Điểm (Gia Định)","Do Lê Hồng Phong chủ trì, tại Ma Cao (Trung Quốc)","Do Hà Huy Tập chủ trì, tại Thượng Hải (Trung Quốc)"],"answer":0,"explain":"Tháng 5/1941, Nguyễn Ái Quốc chủ trì Hội nghị lần thứ tám Ban Chấp hành Trung ương Đảng (tại Pác Bó, Cao Bằng)."},{"id":90,"section":"ch1-2","q":"Hội nghị Trung ương 8 (5/1941) quyết định thành lập mặt trận nào và bầu ai làm Tổng Bí thư?","options":["Mặt trận Việt Minh, bầu Trường Chinh làm Tổng Bí thư","Mặt trận Dân chủ Đông Dương, bầu Nguyễn Văn Cừ làm Tổng Bí thư","Mặt trận Liên Việt, bầu Lê Duẩn làm Tổng Bí thư","Mặt trận phản đế, bầu Hà Huy Tập làm Tổng Bí thư"],"answer":0,"explain":"Hội nghị Trung ương 8 (5/1941) quyết định lập Mặt trận Việt Minh, bầu đồng chí Trường Chinh làm Tổng Bí thư."},{"id":91,"section":"ch1-2","q":"Mặt trận Việt Minh (Việt Nam độc lập đồng minh) chính thức ra đời vào ngày nào?","options":["Ngày 19/5/1941","Ngày 25/10/1941","Ngày 22/12/1944","Ngày 16/8/1945"],"answer":0,"explain":"Ngày 19/5/1941, Mặt trận Việt Minh chính thức ra đời theo quyết định của Hội nghị Trung ương 8."},{"id":92,"section":"ch1-2","q":"Đội Việt Nam Tuyên truyền Giải phóng quân được thành lập vào ngày nào, ở đâu?","options":["Ngày 22/12/1944, tại Cao Bằng","Ngày 19/5/1941, tại Pác Bó","Ngày 16/8/1945, tại Tân Trào","Ngày 4/6/1945, tại Việt Bắc"],"answer":0,"explain":"Ngày 22/12/1944, Đội Việt Nam Tuyên truyền Giải phóng quân ra đời ở Cao Bằng, theo Chỉ thị của Hồ Chí Minh."},{"id":93,"section":"ch1-2","q":"Nhật đảo chính Pháp, độc chiếm Đông Dương vào ngày nào?","options":["Ngày 9/3/1945","Ngày 22/12/1944","Ngày 12/3/1945","Ngày 15/8/1945"],"answer":0,"explain":"Ngày 9/3/1945, Nhật nổ súng đảo chính lật đổ Pháp, độc chiếm Đông Dương."},{"id":94,"section":"ch1-2","q":"Ban Thường vụ Trung ương Đảng ra Chỉ thị \"Nhật - Pháp bắn nhau và hành động của chúng ta\" vào ngày nào?","options":["Ngày 12/3/1945","Ngày 9/3/1945","Ngày 16/4/1945","Ngày 4/6/1945"],"answer":0,"explain":"Ngày 12/3/1945, Ban Thường vụ Trung ương Đảng ra Chỉ thị Nhật - Pháp bắn nhau và hành động của chúng ta, phát động cao trào kháng Nhật cứu nước."},{"id":95,"section":"ch1-2","q":"Chỉ thị 12/3/1945 thay khẩu hiệu \"Đánh đuổi phátxít Nhật - Pháp\" bằng khẩu hiệu nào?","options":["\"Đánh đuổi phátxít Nhật\"","\"Đánh đổ đế quốc Pháp\"","\"Người cày có ruộng\"","\"Tất cả cho tiền tuyến\""],"answer":0,"explain":"Chỉ thị 12/3/1945 thay khẩu hiệu \"Đánh đuổi phátxít Nhật - Pháp\" bằng khẩu hiệu \"Đánh đuổi phátxít Nhật\"."},{"id":96,"section":"ch1-2","q":"Khu giải phóng Việt Bắc được chính thức thành lập vào ngày nào?","options":["Ngày 4/6/1945","Ngày 16/4/1945","Ngày 15/5/1945","Ngày 22/12/1944"],"answer":0,"explain":"Ngày 4/6/1945, Khu giải phóng chính thức được thành lập, gồm hầu hết các tỉnh Cao Bằng, Bắc Kạn, Lạng Sơn, Tuyên Quang, Thái Nguyên và một số vùng lân cận."},{"id":97,"section":"ch1-2","q":"Mỹ ném hai quả bom nguyên tử xuống Nhật Bản vào các thành phố nào, thời gian nào?","options":["Hiroshima (6/8/1945) và Nagasaki (9/8/1945)","Tokyo (6/8/1945) và Yokohama (9/8/1945)","Hiroshima (9/9/1945) và Tokyo (15/9/1945)","Nagasaki (7/7/1945) và Kyoto (15/7/1945)"],"answer":0,"explain":"Mỹ ném hai quả bom nguyên tử xuống Hiroshima (6/8/1945) và Nagasaki (9/8/1945), buộc Nhật đầu hàng Đồng minh không điều kiện ngày 15/8/1945."},{"id":98,"section":"ch1-2","q":"Ủy ban Khởi nghĩa toàn quốc được thành lập vào ngày nào, ban bố văn kiện gì?","options":["Ngày 13/8/1945, ban bố Quân lệnh số 1 tổng khởi nghĩa","Ngày 16/8/1945, ban bố 10 chính sách lớn của Việt Minh","Ngày 19/8/1945, ban bố Tuyên ngôn độc lập của dân tộc","Ngày 25/8/1945, ban bố danh sách Chính phủ lâm thời"],"answer":0,"explain":"Ngày 13/8/1945, Trung ương Đảng và Tổng bộ Việt Minh thành lập Ủy ban Khởi nghĩa toàn quốc; 23 giờ cùng ngày ban bố \"Quân lệnh số 1\"."},{"id":99,"section":"ch1-2","q":"Hội nghị toàn quốc của Đảng họp ở Tân Trào vào thời gian nào, do ai chủ trì?","options":["Ngày 14-15/8/1945, do Hồ Chí Minh và Trường Chinh chủ trì","Ngày 16/8/1945, do Võ Nguyên Giáp và Lê Duẩn chủ trì","Ngày 19/8/1945, do Trần Phú và Hà Huy Tập chủ trì","Ngày 2/9/1945, do Phạm Văn Đồng và Hoàng Quốc Việt chủ trì"],"answer":0,"explain":"Ngày 14 và 15/8/1945, Hội nghị toàn quốc của Đảng họp ở Tân Trào, do lãnh tụ Hồ Chí Minh và Tổng Bí thư Trường Chinh chủ trì."},{"id":100,"section":"ch1-2","q":"Đại hội Quốc dân họp tại Tân Trào (16-17/8/1945) đã bầu ai làm Chủ tịch Ủy ban Dân tộc giải phóng Việt Nam?","options":["Hồ Chí Minh","Trường Chinh","Võ Nguyên Giáp","Tôn Đức Thắng"],"answer":0,"explain":"Đại hội Quốc dân tán thành chủ trương tổng khởi nghĩa, lập Ủy ban Giải phóng dân tộc Việt Nam do Hồ Chí Minh làm Chủ tịch."},{"id":101,"section":"ch1-2","q":"Thủ đô Hà Nội khởi nghĩa giành chính quyền thắng lợi vào ngày nào?","options":["Ngày 19/8/1945","Ngày 23/8/1945","Ngày 25/8/1945","Ngày 30/8/1945"],"answer":0,"explain":"Sáng ngày 19/8/1945, quần chúng cách mạng Hà Nội tổng khởi nghĩa, giành chính quyền thắng lợi."},{"id":102,"section":"ch1-2","q":"Khởi nghĩa giành chính quyền thắng lợi ở Huế và Sài Gòn lần lượt vào những ngày nào?","options":["Huế: 23/8/1945; Sài Gòn: 25/8/1945","Huế: 19/8/1945; Sài Gòn: 23/8/1945","Huế: 2/9/1945; Sài Gòn: 19/8/1945","Huế: 25/8/1945; Sài Gòn: 30/8/1945"],"answer":0,"explain":"Khởi nghĩa giành chính quyền thắng lợi ở Huế ngày 23/8/1945 và ở Sài Gòn ngày 25/8/1945."},{"id":103,"section":"ch1-2","q":"Bốn tỉnh giành chính quyền sớm nhất trong Cách mạng Tháng Tám là những tỉnh nào?","options":["Hải Dương, Bắc Giang, Hà Tĩnh, Quảng Nam","Nghệ An, Hà Tĩnh, Thanh Hóa, Quảng Trị","Cao Bằng, Bắc Kạn, Lạng Sơn, Thái Nguyên","Hà Nội, Huế, Sài Gòn, Đà Nẵng"],"answer":0,"explain":"Từ ngày 14 đến 18/8/1945, bốn tỉnh giành chính quyền sớm nhất là Hải Dương, Bắc Giang, Hà Tĩnh, Quảng Nam."},{"id":104,"section":"ch1-2","q":"Vua Bảo Đại tuyên bố thoái vị, trao ấn kiếm cho đại diện Chính phủ lâm thời vào ngày nào, tại đâu?","options":["Ngày 30/8/1945, tại Ngọ Môn (Huế)","Ngày 2/9/1945, tại Ba Đình (Hà Nội)","Ngày 19/8/1945, tại Phú Xuân (Huế)","Ngày 25/8/1945, tại Sài Gòn (Nam Kỳ)"],"answer":0,"explain":"Ngày 30/8/1945, tại cuộc mít tinh ở Ngọ Môn (Huế), Bảo Đại tuyên bố thoái vị, giao nộp ấn kiếm cho đại diện Chính phủ lâm thời."},{"id":105,"section":"ch1-2","q":"Chủ tịch Hồ Chí Minh đọc bản Tuyên ngôn độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa vào ngày nào, tại đâu?","options":["Ngày 2/9/1945, tại Quảng trường Ba Đình (Hà Nội)","Ngày 19/8/1945, tại Nhà hát lớn thành phố (Hà Nội)","Ngày 30/8/1945, tại Ngọ Môn, kinh thành Huế","Ngày 25/8/1945, tại Dinh Norodom (Sài Gòn)"],"answer":0,"explain":"Ngày 2/9/1945, tại Quảng trường Ba Đình, Hà Nội, Chủ tịch Hồ Chí Minh đọc Tuyên ngôn độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa."},{"id":106,"section":"ch1-2","q":"Bản Tuyên ngôn độc lập được Hồ Chí Minh soạn thảo tại địa điểm nào ở Hà Nội?","options":["Căn phòng trên gác nhà số 48, phố Hàng Ngang","Căn phòng trong Bắc Bộ phủ, phố Ngô Quyền","Căn phòng trên gác nhà số 5D, phố Hàm Long","Căn phòng trên gác nhà số 312, phố Khâm Thiên"],"answer":0,"explain":"Tại một căn phòng trên gác nhà số 48, phố Hàng Ngang, Hà Nội, Hồ Chí Minh đã soạn thảo bản Tuyên ngôn độc lập."},{"id":107,"section":"ch1-2","q":"Cách mạng Tháng Tám năm 1945 là cuộc cách mạng mang tính chất gì?","options":["Cách mạng giải phóng dân tộc mang tính chất dân chủ mới","Cách mạng xã hội chủ nghĩa hoàn chỉnh trên cả nước","Cách mạng ruộng đất triệt để xóa bỏ chế độ phong kiến","Cách mạng tư sản điển hình theo mô hình phương Tây"],"answer":0,"explain":"Cách mạng Tháng Tám năm 1945 là \"một cuộc cách mạng giải phóng dân tộc mang tính chất dân chủ mới\"."},{"id":108,"section":"ch1-2","q":"Vì sao nói Cách mạng Tháng Tám có tính chất dân chủ chưa đầy đủ, sâu sắc?","options":["Vì chưa giải quyết được vấn đề ruộng đất cho nông dân","Vì chưa giành được độc lập hoàn toàn cho dân tộc","Vì chưa xóa bỏ được chế độ quân chủ phong kiến ở Việt Nam","Vì chưa thành lập được chính quyền nhà nước của nhân dân"],"answer":0,"explain":"Cách mạng Tháng Tám chưa làm cách mạng ruộng đất, chưa thực hiện khẩu hiệu người cày có ruộng, nên có tính chất dân chủ nhưng chưa đầy đủ, sâu sắc."},{"id":109,"section":"ch1-2","q":"Theo Hồ Chí Minh, ý nghĩa của việc một Đảng mới 15 tuổi lãnh đạo Cách mạng Tháng Tám thành công là gì?","options":["Lần đầu tiên ở các nước thuộc địa, nửa thuộc địa, một Đảng mới 15 tuổi lãnh đạo cách mạng thành công","Chứng tỏ cách mạng ở các nước thuộc địa có thể thắng lợi mà không cần sự lãnh đạo của Đảng","Chỉ có ý nghĩa trong phạm vi khu vực Đông Dương, chưa tác động tới phong trào giải phóng dân tộc thế giới","Chứng tỏ vai trò quyết định của các nước lớn đối với thắng lợi của cách mạng ở Việt Nam"],"answer":0,"explain":"Hồ Chí Minh viết: \"Lần này là lần đầu tiên trong lịch sử cách mạng của các dân tộc thuộc địa và nửa thuộc địa, một Đảng mới 15 tuổi đã lãnh đạo cách mạng thành công, đã nắm chính quyền toàn quốc\"."},{"id":110,"section":"ch1-2","q":"Bài học kinh nghiệm thứ nhất về chỉ đạo chiến lược của Cách mạng Tháng Tám là gì?","options":["Phải giương cao ngọn cờ giải phóng dân tộc, giải quyết đúng đắn quan hệ dân tộc và ruộng đất","Phải xây dựng quân đội chính quy hiện đại, trang bị vũ khí hạng nặng trước khi khởi nghĩa","Phải liên minh với các nước tư bản phương Tây để được viện trợ quân sự và kinh tế lâu dài","Phải ưu tiên phát triển kinh tế, xây dựng chủ nghĩa xã hội ngay trước khi giành chính quyền"],"answer":0,"explain":"Bài học thứ nhất về chỉ đạo chiến lược: phải giương cao ngọn cờ giải phóng dân tộc, giải quyết đúng đắn mối quan hệ giữa hai nhiệm vụ độc lập dân tộc và cách mạng ruộng đất."},{"id":111,"section":"ch1-2","q":"Cách mạng Tháng Tám 1945 đã lập nên nhà nước gì, có ý nghĩa như thế nào ở khu vực?","options":["Nước Việt Nam Dân chủ Cộng hòa, nhà nước dân chủ nhân dân đầu tiên ở Đông Nam Á","Nước Cộng hòa xã hội chủ nghĩa Việt Nam, nhà nước xã hội chủ nghĩa đầu tiên ở châu Á","Liên bang Đông Dương độc lập, nhà nước liên bang đầu tiên ở Đông Nam Á","Vương quốc Việt Nam lập hiến, nhà nước quân chủ lập hiến đầu tiên ở Đông Nam Á"],"answer":0,"explain":"Cách mạng Tháng Tám lập nên nước Việt Nam Dân chủ Cộng hòa, nhà nước của nhân dân đầu tiên ở Đông Nam Á."},{"id":112,"section":"ch1-2","q":"Từ tháng 1 đến tháng 4/1930, phong trào bãi công của công nhân nổ ra liên tiếp ở những nơi nào?","options":["Xi măng Hải Phòng, dầu Nhà Bè, đồn điền Phú Riềng, dệt Nam Định","Chỉ ở các nhà máy, hầm mỏ trong khu vực Sài Gòn - Chợ Lớn","Chỉ ở các đồn điền cao su và hầm mỏ ở các tỉnh miền núi phía Bắc","Chỉ ở các bến cảng và nhà ga trong khu vực Huế và Đà Nẵng"],"answer":0,"explain":"Từ tháng 1 đến tháng 4/1930, bãi công nổ ra liên tiếp ở nhà máy ximăng Hải Phòng, hãng dầu Nhà Bè, đồn điền Phú Riềng, Dầu Tiếng, nhà máy dệt Nam Định..."},{"id":113,"section":"ch1-2","q":"Tháng 4/1931, tình hình tổ chức Đảng bị tổn thất nghiêm trọng như thế nào?","options":["Toàn bộ Ban Chấp hành Trung ương bị bắt, không còn một ủy viên nào","Đảng bị giải tán hoàn toàn, các tổ chức cơ sở không còn hoạt động","Chỉ Tổng Bí thư bị bắt, các ủy viên khác vẫn hoạt động bình thường","Đảng chuyển toàn bộ hoạt động ra nước ngoài, bỏ lại phong trào trong nước"],"answer":0,"explain":"Tháng 4/1931, toàn bộ Ban Chấp hành Trung ương Đảng bị bắt, không còn lại một ủy viên nào, tổ chức Đảng và quần chúng tan rã hầu hết."},{"id":114,"section":"ch1-2","q":"Chương trình hành động của Đảng Cộng sản Đông Dương được công bố vào ngày nào, nhằm mục đích gì?","options":["Ngày 15/6/1932, nhằm khôi phục tổ chức Đảng và phong trào cách mạng","Ngày 3/2/1930, nhằm thống nhất các tổ chức cộng sản thành một đảng","Ngày 19/5/1941, nhằm thành lập Mặt trận Việt Minh để đoàn kết dân tộc","Ngày 12/3/1945, nhằm phát động cao trào kháng Nhật cứu nước"],"answer":0,"explain":"Chương trình hành động của Đảng Cộng sản Đông Dương (15/6/1932) vạch ra nhiệm vụ trước mắt là khôi phục hệ thống tổ chức của Đảng và phong trào cách mạng."},{"id":115,"section":"ch1-2","q":"Đại hội VII Quốc tế Cộng sản họp tại Mátxcơva vào thời gian nào, xác định kẻ thù nguy hiểm trước mắt là ai?","options":["Tháng 7/1935, xác định chủ nghĩa phátxít là kẻ thù chính","Tháng 3/1935, xác định thực dân Pháp là kẻ thù duy nhất","Tháng 10/1930, xác định đế quốc và phong kiến là kẻ thù","Tháng 5/1941, xác định phátxít Nhật là kẻ thù duy nhất"],"answer":0,"explain":"Tháng 7/1935, Quốc tế Cộng sản họp Đại hội VII tại Mátxcơva, xác định kẻ thù nguy hiểm trước mắt của nhân dân thế giới là chủ nghĩa phátxít."},{"id":116,"section":"ch1-2","q":"Cuộc vận động dân chủ 1936-1939 kết thúc khi nào và vì sao?","options":["Năm 1939, khi Chiến tranh thế giới thứ hai bùng nổ, Pháp đàn áp cách mạng","Năm 1935, khi Đại hội I của Đảng quyết định chuyển sang đấu tranh vũ trang","Năm 1941, khi Mặt trận Việt Minh ra đời và thay thế các hình thức đấu tranh","Năm 1945, khi Nhật đảo chính Pháp, thay đổi hoàn toàn tình hình Đông Dương"],"answer":0,"explain":"Khi Chiến tranh thế giới thứ hai bùng nổ (9/1939), thực dân Pháp đàn áp cách mạng, Đảng rút vào hoạt động bí mật, cuộc vận động dân chủ kết thúc."},{"id":117,"section":"ch1-2","q":"Khởi nghĩa Bắc Sơn nổ ra vào thời gian nào?","options":["Ngày 27/9/1940","Ngày 23/11/1940","Ngày 13/1/1941","Ngày 9/3/1945"],"answer":0,"explain":"Ngày 27/9/1940, nhân việc quân Pháp ở Lạng Sơn bị Nhật tiến đánh phải rút chạy, nhân dân Bắc Sơn nổi dậy khởi nghĩa."},{"id":118,"section":"ch1-2","q":"Khởi nghĩa Nam Kỳ nổ ra vào đêm nào?","options":["Đêm 23/11/1940","Đêm 27/9/1940","Đêm 13/1/1941","Đêm 9/3/1945"],"answer":0,"explain":"Đêm 23/11/1940, cuộc khởi nghĩa Nam Kỳ nổ ra, đánh chiếm nhiều đồn bốt và tiến công nhiều quận lỵ."},{"id":119,"section":"ch1-2","q":"Cuộc binh biến Đô Lương (Nghệ An) do ai chỉ huy, nổ ra vào ngày nào?","options":["Do Đội Cung chỉ huy, ngày 13/1/1941","Do Nguyễn Bình chỉ huy, ngày 23/11/1940","Do Trần Đăng Ninh chỉ huy, ngày 9/3/1945","Do Chu Văn Tấn chỉ huy, ngày 27/9/1940"],"answer":0,"explain":"Ngày 13/1/1941, cuộc binh biến nổ ra ở đồn Chợ Rạng (Đô Lương, Nghệ An) do Đội Cung chỉ huy, nhưng bị thực dân Pháp dập tắt nhanh chóng."},{"id":120,"section":"ch1-2","q":"Lãnh tụ Nguyễn Ái Quốc về nước và dừng chân ở đâu, vào ngày nào?","options":["Cao Bằng, ngày 28/1/1941","Tân Trào, ngày 4/6/1945","Pác Bó, ngày 22/12/1944","Hà Nội, ngày 19/8/1945"],"answer":0,"explain":"Ngày 28/1/1941, sau 30 năm hoạt động ở nước ngoài, lãnh tụ Nguyễn Ái Quốc về nước, dừng chân ở Cao Bằng."},{"id":121,"section":"ch1-2","q":"Hội nghị Trung ương 8 (5/1941) khẳng định nhiệm vụ giải phóng dân tộc là nhiệm vụ như thế nào?","options":["Nhiệm vụ bức thiết nhất, đặt lên hàng đầu, tạm gác khẩu hiệu ruộng đất","Nhiệm vụ ngang hàng với cách mạng ruộng đất, phải làm đồng thời","Nhiệm vụ thứ yếu so với nhiệm vụ xây dựng chủ nghĩa xã hội ở Đông Dương","Nhiệm vụ chỉ của riêng giai cấp công nhân, không liên quan đến nông dân"],"answer":0,"explain":"Hội nghị khẳng định chủ trương \"Chưa chủ trương làm cách mạng tư sản dân quyền mà chủ trương làm cách mạng giải phóng dân tộc\", tạm gác khẩu hiệu cách mạng ruộng đất."},{"id":122,"section":"ch1-2","q":"Hội nghị Trung ương 8 quyết định thành lập ở mỗi nước Đông Dương điều gì?","options":["Một mặt trận riêng, đoàn kết từng dân tộc và ba dân tộc chống kẻ thù chung","Một chính phủ liên hiệp chung của Đông Dương, do ba Đảng cùng cử đại biểu","Một quân đội thống nhất của ba nước, đặt dưới quyền chỉ huy chung của Trung ương","Một Đảng Cộng sản riêng cho mỗi nước, tách hẳn khỏi Đảng Cộng sản Đông Dương"],"answer":0,"explain":"Hội nghị quyết định thành lập ở mỗi nước Đông Dương một mặt trận riêng, thực hiện đoàn kết từng dân tộc, đồng thời đoàn kết ba dân tộc chống kẻ thù chung."},{"id":123,"section":"ch1-2","q":"Hội nghị quân sự cách mạng Bắc Kỳ họp tại Hiệp Hòa (Bắc Giang) vào ngày nào, chủ trương gì?","options":["Ngày 15/4/1945, thống nhất các lực lượng vũ trang thành Giải phóng quân","Ngày 4/6/1945, thành lập Khu giải phóng và Ủy ban lâm thời Khu giải phóng","Ngày 16/8/1945, thành lập Ủy ban dân tộc giải phóng Việt Nam","Ngày 9/3/1945, phát động cao trào kháng Nhật cứu nước trong cả nước"],"answer":0,"explain":"Ngày 15/4/1945, Ban Thường vụ Trung ương Đảng triệu tập Hội nghị quân sự cách mạng Bắc Kỳ tại Hiệp Hòa (Bắc Giang), chủ trương thống nhất các lực lượng vũ trang thành Việt Nam Giải phóng quân."},{"id":124,"section":"ch1-2","q":"Hai trận đánh thắng đầu tiên của Đội Việt Nam Tuyên truyền Giải phóng quân là ở đâu?","options":["Phai Khắt (25/12/1944) và Nà Ngần (26/12/1944)","Bắc Sơn (27/9/1940) và Đô Lương (13/1/1941)","Điện Biên Phủ (7/5/1954) và Đông Khê (18/9/1950)","Hà Nội (19/8/1945) và Sài Gòn (25/8/1945)"],"answer":0,"explain":"Ba ngày sau khi thành lập, đội đánh thắng liên tiếp hai trận ở Phai Khắt (25/12/1944) và Nà Ngần (26/12/1944)."},{"id":125,"section":"ch1-2","q":"Trước Cách mạng Tháng Tám, nạn đói cuối năm 1944 đầu năm 1945 đã làm bao nhiêu người dân chết đói?","options":["2 triệu người","500 nghìn người","5 triệu người","1 triệu người"],"answer":0,"explain":"Nạn đói cuối năm 1944, đầu năm 1945 làm 2 triệu người dân chết đói."},{"id":126,"section":"ch1-2","q":"Theo Hội nghị Pốtxđam (7/1945), quân đội nước nào vào giải giáp quân Nhật từ vĩ tuyến 16 trở ra Bắc?","options":["Quân đội Trung Hoa","Quân đội Liên hiệp Anh","Quân đội Hoa Kỳ","Quân đội Liên Xô"],"answer":0,"explain":"Theo quyết định Hội nghị Pốtxđam (7/1945), quân đội Trung Hoa dân quốc vào Bắc Việt Nam từ vĩ tuyến 16 trở ra, quân đội Liên hiệp Anh từ vĩ tuyến 16 trở vào để giải giáp quân Nhật."},{"id":127,"section":"ch1-2","q":"Danh sách Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa được công bố chính thức vào ngày nào?","options":["Ngày 28/8/1945","Ngày 25/8/1945","Ngày 2/9/1945","Ngày 19/8/1945"],"answer":0,"explain":"Ngày 28/8/1945, danh sách Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa được chính thức công bố tại Hà Nội."},{"id":128,"section":"ch1-2","q":"Bài học kinh nghiệm về xây dựng lực lượng của Cách mạng Tháng Tám nhấn mạnh điều gì?","options":["Dựa trên liên minh công nông, tập hợp toàn dân trong mặt trận dân tộc thống nhất","Chỉ dựa vào lực lượng vũ trang chính quy, không cần tập hợp các tầng lớp nhân dân khác","Chỉ dựa vào giai cấp công nhân thành thị, không cần liên minh với nông dân và trí thức","Chỉ dựa vào sự viện trợ của Quốc tế Cộng sản và các nước xã hội chủ nghĩa"],"answer":0,"explain":"Bài học về xây dựng lực lượng: trên cơ sở khối liên minh công nông, cần khơi dậy tinh thần dân tộc trong mọi tầng lớp nhân dân, tập hợp trong Mặt trận dân tộc thống nhất rộng rãi (Việt Minh)."},{"id":129,"section":"ch1-2","q":"Theo cách dùng từ của V.I. Lênin trong tác phẩm \"Tổng kết một cuộc tranh luận về quyền tự quyết\", tổ chức nào trong cách mạng Việt Nam được ví là một \"lò lửa khởi nghĩa dân tộc\"?","options":["Mặt trận Việt Minh, thành lập tháng 5/1941","Hội Việt Nam Cách mạng Thanh niên, lập năm 1925","Mặt trận Dân chủ Đông Dương, lập năm 1938","Đảng Cộng sản Đông Dương, thành lập năm 1930"],"answer":0,"explain":"Theo cách dùng từ của V.I.Lênin trong tác phẩm Tổng kết một cuộc tranh luận về quyền tự quyết, Việt Minh chính là một \"lò lửa khởi nghĩa dân tộc\"."},{"id":130,"section":"ch1-2","q":"Trong 15 năm đấu tranh cách mạng (1930-1945), Đảng đã lãnh đạo giai cấp và dân tộc hoàn thành mục tiêu gì?","options":["Giành độc lập, lập nhà nước dân chủ nhân dân","Hoàn thành xây dựng chủ nghĩa xã hội ở miền Bắc","Hoàn thành thống nhất đất nước hai miền Nam - Bắc","Gia nhập Liên hợp quốc, mở rộng quan hệ quốc tế"],"answer":0,"explain":"Suốt 15 năm đấu tranh cách mạng 1930-1945, Đảng đã lãnh đạo giai cấp và dân tộc hoàn thành mục tiêu giành độc lập dân tộc, thiết lập nhà nước dân chủ nhân dân."},{"id":432,"section":"ch1-2","q":"Tại Hội nghị Ban Chấp hành Trung ương lần thứ 1 (10/1930), Đảng đã đề ra Luận Cương chính trị để thay cho văn kiện nào trước đó?","options":["Chánh cương vắn tắt của Đảng và Sách lược vắn tắt của Đảng","Chánh cương vắn tắt của Đảng và Điều lệ vắn tắt của Đảng","Chánh cương vắn tắt của Đảng và Chương trình tóm tắt của Đảng","Chánh cương vắn tắt của Đảng và Lời kêu gọi nhân dịp thành lập Đảng"],"answer":0,"explain":"Luận cương chính trị tháng 10/1930 được đề ra để thay thế Chánh cương vắn tắt và Sách lược vắn tắt - hai văn kiện hợp thành Cương lĩnh chính trị đầu tiên của Đảng."},{"id":433,"section":"ch1-2","q":"Trong Luận cương chính trị tháng 10/1930, Đảng Cộng sản Đông Dương xác định tính chất của cách mạng lúc đầu là gì?","options":["Cách mạng tư sản dân quyền, có tính chất thổ địa và phản đế","Cách mạng giải phóng dân tộc, có tính chất thổ địa và phản đế","Cách mạng dân tộc dân chủ nhân dân, có tính chất thổ địa và phản đế","Cách mạng xã hội chủ nghĩa, có tính chất thổ địa và phản đế"],"answer":0,"explain":"Luận cương chính trị tháng 10/1930 xác định: lúc đầu cách mạng Đông Dương là cuộc “cách mạng tư sản dân quyền”, có tính chất thổ địa và phản đế."},{"id":434,"section":"ch1-2","q":"Nhiệm vụ trước mắt của cách mạng Đông Dương được thông qua tại Đại hội đại biểu Đảng toàn quốc lần thứ nhất (3/1935) là gì?","options":["Củng cố và phát triển Đảng, thu phục quần chúng, mở rộng tuyên truyền chống đế quốc, chiến tranh, ủng hộ Liên Xô","Xây dựng Mặt trận Dân chủ Đông Dương, đòi tự do, dân chủ, cơm áo, hoà bình, chống bọn phản động thuộc địa tay sai","Tiến hành khởi nghĩa vũ trang, thành lập chính quyền Xô viết, chia ngay ruộng đất của địa chủ cho dân cày nghèo","Chuẩn bị lực lượng tổng khởi nghĩa, xây dựng căn cứ địa, thành lập Mặt trận Việt Minh ở trong cả nước"],"answer":0,"explain":"Đại hội I (3/1935) xác định ba nhiệm vụ trước mắt: củng cố và phát triển Đảng, thu phục đông đảo quần chúng, mở rộng tuyên truyền chống đế quốc, chống chiến tranh, ủng hộ Liên Xô."},{"id":435,"section":"ch1-2","q":"Đại hội lần thứ VII của Quốc tế Cộng sản (7/1935), đã bầu ai trong Đảng Cộng sản Đông Dương làm Uỷ viên Ban Chấp hành Quốc tế Cộng sản?","options":["Lê Hồng Phong","Nguyễn Ái Quốc","Hoàng Văn Nọn","Nguyễn Thị Minh Khai"],"answer":0,"explain":"Tại Đại hội VII Quốc tế Cộng sản (7/1935), đồng chí Lê Hồng Phong được bầu làm Uỷ viên Ban Chấp hành Quốc tế Cộng sản."},{"id":436,"section":"ch1-2","q":"Trong giai đoạn 1936-1939, Đảng xác định nhiệm vụ trước mắt của cách mạng Đông Dương là gì?","options":["Chống phát-xít, chống chiến tranh, đòi tự do, dân chủ, cơm áo, hoà bình","Đánh đuổi đế quốc Pháp, phát-xít Nhật, giành độc lập hoàn toàn cho dân tộc","Tịch thu ruộng đất của địa chủ phong kiến, chia cho dân cày, lập chính quyền Xô viết","Chống đế quốc, phát-xít Pháp - Nhật, giành độc lập dân tộc bằng khởi nghĩa vũ trang"],"answer":0,"explain":"Giai đoạn 1936-1939, Đảng tạm gác khẩu hiệu độc lập dân tộc và cách mạng ruộng đất, xác định nhiệm vụ trước mắt là chống phát-xít, chống chiến tranh đế quốc, chống bọn phản động thuộc địa, đòi tự do, dân chủ, cơm áo, hoà bình."},{"id":437,"section":"ch1-2","q":"Trong giai đoạn 1936-1939, hình thức tổ chức và biện pháp đấu tranh được Đảng xác định là?","options":["công khai và nửa công khai, hợp pháp và nửa hợp pháp","bí mật và bất hợp pháp, chủ yếu là đấu tranh vũ trang","chỉ công khai và hợp pháp, từ bỏ hoàn toàn hoạt động bí mật","công khai, kết hợp đấu tranh chính trị với đấu tranh vũ trang"],"answer":0,"explain":"Giai đoạn 1936-1939, Đảng chủ trương hình thức tổ chức và đấu tranh công khai và nửa công khai, hợp pháp và nửa hợp pháp, kết hợp với bí mật, bất hợp pháp."},{"id":438,"section":"ch1-2","q":"Đội Việt Nam Tuyên truyền Giải phóng quân được thành lập ngày 22/12/1944 có nhiệm vụ?","options":["vũ trang tuyên truyền, gây dựng cơ sở chính trị và quân sự, dìu dắt các đội vũ trang địa phương","tổng tấn công giải phóng Hà Nội và các thành phố lớn, thành lập chính phủ lâm thời cả nước","bảo vệ cơ quan lãnh đạo của Đảng ở Việt Bắc, chỉ chiến đấu phòng ngự khi bị địch tấn công","tổ chức bầu cử Quốc hội, xây dựng chính quyền cách mạng ở toàn bộ các tỉnh miền núi phía Bắc"],"answer":0,"explain":"Nhiệm vụ của Đội Việt Nam Tuyên truyền Giải phóng quân bao gồm: vũ trang tuyên truyền vận động nhân dân, gây dựng cơ sở chính trị và quân sự, đồng thời dìu dắt, giúp đỡ huấn luyện các đội vũ trang địa phương."},{"id":439,"section":"ch1-2","q":"Năm 1943, Đảng đưa ra Đề cương văn hóa Việt Nam xác định nhiệm vụ của các nhà văn hóa Việt Nam giai đoạn này là?","options":["chống văn hóa nô dịch, ngu dân của phát-xít, xây dựng nền văn hóa mới theo ba nguyên tắc: dân tộc, khoa học, đại chúng","bảo tồn nguyên vẹn văn hóa truyền thống phong kiến, khôi phục chế độ khoa cử Nho học và nền giáo dục Hán học cũ","xây dựng nền văn hóa Việt Nam tiên tiến, đậm đà bản sắc dân tộc theo định hướng xã hội chủ nghĩa như hiện nay","tiếp thu toàn bộ văn hóa phương Tây, từ bỏ các nguyên tắc dân tộc, khoa học, đại chúng của nền văn hóa mới ở nước ta"],"answer":0,"explain":"Đề cương văn hóa Việt Nam (1943) xác định nhiệm vụ chống văn hóa nô dịch, ngu dân của phát-xít và tay sai, xây dựng nền văn hóa mới theo ba nguyên tắc: dân tộc hóa, khoa học hóa, đại chúng hóa."},{"id":440,"section":"ch1-2","q":"Trong Chỉ thị “Nhật - Pháp bắn nhau và hành động của chúng ta”, Đảng xác định kẻ thù cụ thể, trước mắt và duy nhất của nhân dân Đông Dương là ai?","options":["Phát-xít Nhật ở Đông Dương","Thực dân Pháp ở Đông Dương","Thực dân, phát-xít Pháp - Nhật","Phong kiến phản động tay sai"],"answer":0,"explain":"Chỉ thị 12/3/1945 xác định phát-xít Nhật là kẻ thù chính, cụ thể, trước mắt và duy nhất của nhân dân Đông Dương lúc này, thay khẩu hiệu “Đánh đuổi phát-xít Nhật - Pháp” bằng “Đánh đuổi phát-xít Nhật”."},{"id":441,"section":"ch1-2","q":"Phương pháp đấu tranh cơ bản trong Cách mạng Tháng Tám năm 1945 là gì?","options":["Kết hợp đấu tranh chính trị và đấu tranh vũ trang","Kết hợp đấu tranh vũ trang và đấu tranh ngoại giao","Kết hợp đấu tranh chính trị với đấu tranh ngoại giao","Đấu tranh chính trị và đấu tranh vũ trang kết hợp với ngoại giao"],"answer":0,"explain":"Phương pháp đấu tranh cơ bản trong Cách mạng Tháng Tám là kết hợp đấu tranh chính trị với đấu tranh vũ trang, lấy lực lượng chính trị của quần chúng làm căn bản."},{"id":442,"section":"ch1-2","q":"Nhân tố chủ yếu nhất, quyết định thắng lợi của Cách mạng Tháng Tám năm 1945 là gì?","options":["Sự lãnh đạo của Đảng Cộng sản Việt Nam","Tác động của khủng hoảng kinh tế thế giới","Sức mạnh của khối liên minh công - nông","Thời cơ quốc tế thuận lợi sau chiến tranh"],"answer":0,"explain":"Nhân tố chủ yếu nhất, quyết định thắng lợi của Cách mạng Tháng Tám là sự lãnh đạo đúng đắn, sáng suốt của Đảng Cộng sản Việt Nam và Chủ tịch Hồ Chí Minh."},{"id":498,"section":"ch1-2","q":"Sự kiện nào sau đây nổ ra vào tháng 2/1930 và bị thực dân Pháp tiến hành chiến dịch khủng bố trắng để đàn áp?","options":["Cuộc khởi nghĩa Yên Bái.","Phong trào Cần Vương.","Khởi nghĩa nông dân Yên Thế.","Bãi công của công nhân Ba Son."],"answer":0,"explain":"Cuộc khởi nghĩa Yên Bái do Việt Nam Quốc dân Đảng phát động nổ ra tháng 2/1930, thất bại và bị thực dân Pháp tiến hành chiến dịch khủng bố trắng đàn áp dữ dội."},{"id":499,"section":"ch1-2","q":"Đâu là nhân tố tác động quyết định đến quy mô, tính chất phong trào đấu tranh của công nhân, nông dân Việt Nam trong những năm 1930 – 1931?","options":["Sự ra đời và lãnh đạo của Đảng.","Sự đàn áp của thực dân Pháp.","Sự ủng hộ của Quốc tế Cộng sản.","Sự khủng hoảng kinh tế thế giới."],"answer":0,"explain":"Sự ra đời và lãnh đạo kịp thời của Đảng Cộng sản Việt Nam (đầu 1930) là nhân tố quyết định đến quy mô và tính chất triệt để của phong trào đấu tranh công nông 1930-1931."},{"id":500,"section":"ch1-2","q":"Đỉnh cao phong trào đấu tranh của công nhân, nông dân dưới sự lãnh đạo của Đảng trong năm 1930 đã dẫn tới sự tan rã chính quyền tay sai của Pháp ở một số nơi thuộc Nghệ An, Hà Tĩnh và ra đời một chính quyền cách mạng với hình thức","options":["Uỷ ban tự quản kiểu Xô Viết ở nông thôn.","Chính quyền liên minh công – nông – địa chủ nhỏ.","Công xã nông thôn kiểu truyền thống.","Chính quyền dân chủ cộng hoà tư sản."],"answer":0,"explain":"Phong trào cách mạng 1930-1931 đạt đỉnh cao ở Nghệ An, Hà Tĩnh, làm tan rã chính quyền tay sai ở nhiều nơi, hình thành chính quyền cách mạng theo hình thức Xô viết (Xô viết Nghệ Tĩnh)."},{"id":501,"section":"ch1-2","q":"Ban Thường vụ Trung ương chỉ ra một trong những nguyên nhân chính quyền Xô viết ở Nghệ An và Hà Tĩnh không duy trì được lâu là do","options":["chủ trương bạo động riêng lẻ khi chưa đủ điều kiện.","không huy động được đông đảo nông dân tham gia.","không nhận được sự ủng hộ của Quốc tế Cộng sản.","chủ trương đấu tranh nghị trường, thoả hiệp với Pháp."],"answer":0,"explain":"Ban Thường vụ Trung ương Đảng chỉ ra rằng một nguyên nhân khiến chính quyền Xô viết Nghệ Tĩnh không duy trì được lâu là do chủ trương đấu tranh, bạo động có phần riêng lẻ khi điều kiện thực tiễn chưa cho phép."},{"id":502,"section":"ch1-2","q":"Nội dung nào sau đây không phù hợp với ý nghĩa của cao trào cách mạng trong những năm 1930 – 1931 mà đỉnh cao là Xô viết Nghệ Tĩnh?","options":["Đánh bại hoàn toàn ý chí đô hộ của thực dân Pháp trên lãnh thổ Việt Nam.","Khẳng định quyền lãnh đạo của giai cấp công nhân thông qua Đảng.","Góp phần rèn luyện cán bộ, đảng viên và quần chúng cách mạng.","Khẳng định sức mạnh của liên minh công – nông trong thực tiễn cách mạng."],"answer":0,"explain":"Cao trào 1930-1931 tuy để lại nhiều bài học quý và khẳng định quyền lãnh đạo của giai cấp công nhân, sức mạnh liên minh công nông, nhưng không thể coi là đã đánh bại được ý chí đô hộ của thực dân Pháp (phong trào cuối cùng bị đàn áp)."},{"id":503,"section":"ch1-2","q":"Hội nghị lần thứ I của Đảng tháng 10/1930 tại Hương Cảng (Trung Quốc) đã quyết định đổi tên Đảng thành","options":["Đảng Cộng sản Đông Dương.","Đảng Cộng sản Việt Nam.","Đảng Lao Động Việt Nam.","Đảng Lao động Đông Dương."],"answer":0,"explain":"Hội nghị Ban Chấp hành Trung ương lần thứ nhất (10/1930), theo chỉ đạo của Quốc tế Cộng sản, quyết định đổi tên Đảng Cộng sản Việt Nam thành Đảng Cộng sản Đông Dương."},{"id":504,"section":"ch1-2","q":"Tổ chức nào sau đây được coi là tiền thân của Mặt trận Tổ quốc Việt Nam?","options":["Hội phản đế Đồng minh (11/1930).","Mặt trận dân chủ Đông Dương (1938).","Mặt trận Việt Minh (1941).","Mặt trận Liên Việt (1946)."],"answer":0,"explain":"Hội Phản đế Đồng minh (thành lập 11/1930) là hình thức mặt trận dân tộc thống nhất đầu tiên do Đảng lãnh đạo, được coi là tổ chức tiền thân của Mặt trận Tổ quốc Việt Nam ngày nay."},{"id":505,"section":"ch1-2","q":"Đảng Cộng sản Đông Dương chính thức trở thành chi bộ độc lập của Quốc tế Cộng sản từ","options":["tháng 4/1931.","tháng 10/1930.","tháng 2/1930.","tháng 9/1931."],"answer":0,"explain":"Tháng 4/1931, tại Hội nghị lần thứ 11 Ban Chấp hành Quốc tế Cộng sản, Đảng Cộng sản Đông Dương chính thức được công nhận là một chi bộ độc lập trực thuộc Quốc tế Cộng sản."},{"id":506,"section":"ch1-2","q":"Đồng chí nào trước lúc hi sinh để lại lời căn dặn các đồng chí của mình “Hãy giữ vững chí khí chiến đấu”?","options":["Trần Phú.","Hà Huy Tập.","Lý Tự Trọng.","Nguyễn Văn Cừ."],"answer":0,"explain":"Trần Phú, Tổng Bí thư đầu tiên của Đảng, trước lúc hi sinh (1931) đã căn dặn các đồng chí “Hãy giữ vững chí khí chiến đấu”."},{"id":507,"section":"ch1-2","q":"Câu nói nổi tiếng: “Con đường của thanh niên chỉ có thể là con đường cách mạng” của đồng chí nào sau đây?","options":["Lý Tự Trọng.","Hà Huy Tập.","Trần Phú.","Nguyễn Đức Cảnh."],"answer":0,"explain":"Lý Tự Trọng, trước khi bị thực dân Pháp xử tử (1931), đã khẳng khái nói: “Con đường của thanh niên chỉ có thể là con đường cách mạng”."},{"id":508,"section":"ch1-2","q":"Được sự chỉ đạo của Quốc tế Cộng sản, đồng chí Lê Hồng Phong cùng một số đồng chí khác đã công bố Chương trình hành động của Đảng Cộng sản Đông Dương (15/6/1932) trong đó vạch ra nhiệm vụ đấu tranh trước mắt là","options":["khôi phục hệ thống tổ chức Đảng và phong trào cách mạng.","tiến hành ngay tổng khởi nghĩa giành độc lập dân tộc trong cả nước.","giải phóng giai cấp, thiết lập chuyên chính vô sản ngay lập tức.","thành lập Mặt trận dân tộc thống nhất chống phát xít, bảo vệ hoà bình."],"answer":0,"explain":"Chương trình hành động của Đảng Cộng sản Đông Dương (15/6/1932), do Lê Hồng Phong cùng một số đồng chí công bố theo chỉ đạo của Quốc tế Cộng sản, đề ra nhiệm vụ trước mắt là khôi phục hệ thống tổ chức của Đảng và phong trào cách mạng sau đợt khủng bố trắng."},{"id":509,"section":"ch1-2","q":"Đầu năm 1934, theo sự chỉ đạo của Quốc tế Cộng sản tổ chức nào sau đây được thành lập có chức năng, trách nhiệm như Ban Chấp hành Trung ương?","options":["Ban Chỉ huy ở ngoài của Đảng Cộng sản.","Ban Chấp hành Tổng Công hội đỏ ở Đông Dương.","Ban Chấp hành Tổng Nông hội đỏ ở Đông Dương.","Hội nghiên cứu chủ nghĩa Mác tại Đông Dương."],"answer":0,"explain":"Đầu năm 1934, theo chỉ đạo của Quốc tế Cộng sản, Ban Chỉ huy ở ngoài của Đảng Cộng sản Đông Dương được thành lập (đặt trụ sở ở nước ngoài), tạm thời đảm nhiệm chức năng, trách nhiệm như Ban Chấp hành Trung ương."},{"id":510,"section":"ch1-2","q":"Sự kiện nào sau đây đánh dấu sự phục hồi các tổ chức Đảng và phong trào cách mạng?","options":["Đại hội đại biểu lần thứ nhất của Đảng (3/1935).","Sự ra đời của Ban chỉ huy ở ngoài (1934).","Sự ra đời của Mặt trận nhân dân phản đế Đông Dương (1936).","Sự ra đời của Mặt trận Dân chủ Đông Dương (1938)."],"answer":0,"explain":"Đại hội đại biểu lần thứ nhất của Đảng (3/1935) đánh dấu hệ thống tổ chức Đảng từ Trung ương đến địa phương được khôi phục, đưa cách mạng vượt qua thời kỳ khó khăn sau cao trào 1930-1931."},{"id":511,"section":"ch1-2","q":"Nội dung nào sau đây không được Đại hội lần thứ nhất của Đảng (3/1935) nêu ra?","options":["Đưa nhiệm vụ giải phóng dân tộc lên hàng đầu.","Đẩy mạnh cuộc vận động và tập hợp quần chúng.","Ủng hộ phong trào cách mạng Liên Xô và Trung Quốc.","Củng cố và phát triển Đảng trong toàn quốc."],"answer":0,"explain":"Đại hội lần thứ nhất của Đảng (3/1935) vẫn theo tinh thần Luận cương chính trị, đề ra nhiệm vụ củng cố phát triển Đảng, đẩy mạnh vận động quần chúng, ủng hộ Liên Xô, Trung Quốc; việc đưa nhiệm vụ giải phóng dân tộc lên hàng đầu chỉ được xác lập sau này, từ Hội nghị Trung ương tháng 11/1939."},{"id":512,"section":"ch1-2","q":"Nguy cơ nào được Đại hội VII Quốc tế Cộng sản xác định khi có sự ra đời của chủ nghĩa phát xít?","options":["Một cuộc chiến tranh thế giới mới.","Nội chiến ở các nước thuộc địa.","Khủng hoảng kinh tế thế giới.","Khủng hoảng lương thực thế giới."],"answer":0,"explain":"Đại hội VII Quốc tế Cộng sản (7/1935) nhận định sự xuất hiện của chủ nghĩa phát xít là nguy cơ trực tiếp dẫn đến một cuộc chiến tranh thế giới mới."},{"id":513,"section":"ch1-2","q":"Đâu không phải nhiệm vụ trước mắt của nhân dân thế giới được Quốc tế Cộng sản họp Đại hội VII tại Mátxcơva (Liên Xô tháng 7/1935)?","options":["Chống chủ nghĩa tư bản.","Chống chiến tranh thế giới.","Chống Chủ nghĩa phát xít.","Bảo vệ hoà bình, dân chủ."],"answer":0,"explain":"Để tập hợp lực lượng rộng rãi chống chủ nghĩa phát xít, Đại hội VII Quốc tế Cộng sản chủ trương tạm gác mục tiêu chống chủ nghĩa tư bản nói chung, tập trung chống phát xít, chiến tranh, bảo vệ hoà bình dân chủ."},{"id":514,"section":"ch1-2","q":"Đồng chí nào thuộc đoàn đại biểu Đảng Cộng sản Đông Dương tham gia Đại hội VII Quốc tế Cộng sản và được bầu làm uỷ viên Ban Chấp hành Quốc tế Cộng sản?","options":["Lê Hồng Phong.","Hoàng Văn Nọn.","Nguyễn Ái Quốc.","Nguyễn Thị Minh Khai."],"answer":0,"explain":"Lê Hồng Phong, đại biểu Đảng Cộng sản Đông Dương, được Đại hội VII Quốc tế Cộng sản (7/1935) bầu làm Uỷ viên Ban Chấp hành Quốc tế Cộng sản."},{"id":515,"section":"ch1-2","q":"Đâu không phải là nhiệm vụ trước mắt của nhân dân Đông Dương được Hội nghị Trung ương Đảng họp tại Thượng Hải (Trung Quốc) tháng 7/1936 xác định?","options":["Đòi độc lập cho các dân tộc Đông Dương.","Chống phát xít, chiến tranh đế quốc.","Đòi tự do, dân chủ, cơm áo, hoà bình.","Chống phản động thuộc địa và tay sai."],"answer":0,"explain":"Hội nghị Trung ương Đảng (7/1936, họp tại Thượng Hải) chủ trương tạm gác khẩu hiệu “độc lập dân tộc” và “cách mạng ruộng đất”, chỉ đấu tranh đòi các quyền dân sinh, dân chủ, chống phát xít và phản động thuộc địa."},{"id":516,"section":"ch1-2","q":"Nội dung nào sau đây phù hợp với hình thức đấu tranh được Đảng sử dụng trong giai đoạn (1936 – 1939)?","options":["Công khai, nửa công khai kết hợp với bí mật, bất hợp pháp.","Chỉ đấu tranh bí mật, bất hợp pháp để bảo toàn lực lượng.","Công khai đấu tranh trên lĩnh vực quân sự, vũ trang.","Chỉ đấu tranh hợp pháp, từ bỏ mọi hoạt động bí mật."],"answer":0,"explain":"Trong những năm 1936-1939, Đảng chủ trương kết hợp các hình thức đấu tranh công khai, nửa công khai, hợp pháp với bí mật, bất hợp pháp cho phù hợp với điều kiện lịch sử mới."},{"id":517,"section":"ch1-2","q":"Luận điểm nào sau đây thể hiện việc nhận thức lại mối quan hệ giữa hai nhiệm vụ phản đế và điền địa được nêu ra trong tác phẩm “Chung quanh vấn đề chiến sách mới” của Đảng 10/1936?","options":["Nếu chia đất mà ngăn trở cuộc tranh đấu phản đế thì phải chọn vấn đề quan trọng hơn mà giải quyết trước.","Cuộc đấu tranh chia đất cho nông dân phải được tiến hành đồng thời, ngang bằng với công cuộc giải phóng dân tộc.","Thổ địa cách mạng là cái cốt của tư sản dân quyền cách mạng, phải được giải quyết trước hết trong mọi hoàn cảnh.","Phải thực hiện xong nhiệm vụ giải phóng dân tộc rồi mới tiến hành cuộc đấu tranh giai cấp, chia ruộng đất."],"answer":0,"explain":"Trong tác phẩm “Chung quanh vấn đề chiến sách mới” (10/1936), Đảng nhận thức lại rằng nếu đấu tranh giai cấp (chia đất) cản trở đấu tranh dân tộc (phản đế) thì phải ưu tiên giải quyết nhiệm vụ nào quan trọng hơn trước."},{"id":518,"section":"ch1-2","q":"Nhóm việc làm nào sau đây thể hiện hình thức đấu tranh trên lĩnh lực chính trị của cách mạng Đông Dương trong những năm 1936 – 1939?","options":["“Đón rước”, mít tinh, biểu tình, đưa “dân nguyện”.","Bãi công, bãi thị, đòi tăng lương, giảm giờ làm.","Bãi khoá, đòi ngày làm 8 giờ, tăng lương.","Xuất bản báo chí, sách truyền bá chủ nghĩa Mác."],"answer":0,"explain":"“Đón rước”, mít tinh, biểu tình, đưa “dân nguyện” là những hình thức đấu tranh trên lĩnh vực chính trị tiêu biểu trong phong trào 1936-1939."},{"id":519,"section":"ch1-2","q":"Để tập hợp đông đảo quần chúng tham gia phát triển phong trào đấu tranh vì dân sinh dân chủ, tháng 3/1938 Đảng chủ trương thành lập","options":["Mặt trận Dân chủ Đông Dương.","Hội phản đế Đồng minh.","Hội truyền bá chữ quốc ngữ.","Mặt trận Việt Minh."],"answer":0,"explain":"Tháng 3/1938, để mở rộng và tập hợp lực lượng, Đảng chủ trương thành lập Mặt trận Dân chủ Đông Dương."},{"id":520,"section":"ch1-2","q":"Đâu không phải là kinh nghiệm được rút ra trong quá trình Đảng lãnh đạo cuộc vận động dân chủ (1936 – 1939)?","options":["Xây dựng lực lượng vũ trang nhân dân để khởi nghĩa giành chính quyền.","Giải quyết mối quan hệ giữa mục tiêu chiến lược và mục tiêu trước mắt.","Xây dựng mặt trận thống nhất phù hợp với yêu cầu của thực tiễn.","Sử dụng linh hoạt các hình thức đấu tranh cách mạng."],"answer":0,"explain":"Cuộc vận động dân chủ 1936-1939 chủ yếu là cuộc đấu tranh chính trị hợp pháp, nửa hợp pháp; việc xây dựng lực lượng vũ trang nhân dân chưa được đặt ra trong giai đoạn này."},{"id":521,"section":"ch1-2","q":"Cao trào cách mạng nào được coi là cuộc tập dượt lần thứ hai cho thắng lợi của Cách mạng Tháng Tám sau này?","options":["Cao trào 1936 – 1939.","Cao trào 1930 – 1931.","Cao trào kháng Nhật cứu nước.","Cao trào 1939 – 1945."],"answer":0,"explain":"Cao trào dân chủ 1936-1939 được coi là cuộc tập dượt lần thứ hai (sau cao trào 1930-1931) chuẩn bị cho thắng lợi của Cách mạng Tháng Tám năm 1945."},{"id":522,"section":"ch1-2","q":"Trong Chiến tranh thế giới lần thứ hai, sau khi Đức tấn công Liên Xô đã hình thành trên thế giới trận tuyến","options":["phe dân chủ chống phát xít.","phe đế quốc chống đế quốc.","phe đế quốc chống phát xít.","phe thuộc địa chống đế quốc."],"answer":0,"explain":"Sau khi phát xít Đức tấn công Liên Xô (6/1941), tính chất cuộc Chiến tranh thế giới thứ hai thay đổi, hình thành trận tuyến giữa phe dân chủ (Đồng minh) chống phe phát xít."},{"id":523,"section":"ch1-2","q":"Trong Chiến tranh thế giới thứ hai, thực dân Pháp ở Đông Dương đã phát xít hoá bộ máy thống trị, đàn áp phong trào cách mạng và thực hiện chính sách kinh tế nào sau đây?","options":["Chính sách kinh tế chỉ huy.","Chính sách kinh tế hợp tác.","Kinh tế hướng vào xuất khẩu.","Kinh tế hướng vào nhập khẩu."],"answer":0,"explain":"Trong Chiến tranh thế giới thứ hai, thực dân Pháp ở Đông Dương phát xít hoá bộ máy thống trị, ráo riết thực hiện chính sách “kinh tế chỉ huy” để phục vụ chiến tranh."},{"id":524,"section":"ch1-2","q":"Việc Nhật vào Đông Dương năm 1940 và câu kết với thực dân Pháp, bọn tay sai phản động đã làm cho nhân dân Đông Dương rơi vào cảnh","options":["cảnh một cổ hai tròng áp bức, bóc lột của Pháp và Nhật.","cảnh bần cùng về chính trị nhưng phát triển về kinh tế.","cảnh một cổ ba tròng áp bức, bóc lột của Pháp, Nhật, Mỹ.","cảnh bần cùng về kinh tế, được tự do về chính trị."],"answer":0,"explain":"Việc phát xít Nhật vào Đông Dương (1940) và câu kết với thực dân Pháp, bọn tay sai đã đẩy nhân dân Đông Dương vào cảnh một cổ hai tròng nô lệ (ách thống trị của cả Pháp và Nhật)."},{"id":525,"section":"ch1-2","q":"Sư kiện nào đánh dấu bước mở đầu của quá trình thay đổi chiến lược cách mạng của Đảng Cộng sản Đông Dương cho phù hợp với tình hình mới khi Chiến tranh thế giới lần thứ hai nổ ra?","options":["Hội nghị Trung ương Đảng (11/1939).","Hội nghị Trung ương Đảng (11/1940).","Hội nghị Trung ương Đảng (5/1941).","Hội nghị Thường vụ Trung ương Đảng (3/1945)."],"answer":0,"explain":"Hội nghị Ban Chấp hành Trung ương Đảng (11/1939) đánh dấu bước mở đầu sự chuyển hướng chỉ đạo chiến lược của Đảng cho phù hợp với tình hình Chiến tranh thế giới thứ hai."},{"id":526,"section":"ch1-2","q":"Hội nghị Trung ương Đảng (11/1939) đã xác định cách mạng lúc này cần đặt lợi ích tối cao là","options":["giải phóng dân tộc khỏi ách đế quốc.","chống chủ nghĩa phát xít thế giới.","bảo vệ hoà bình và dân chủ thế giới.","đòi các quyền dân chủ trước mắt."],"answer":0,"explain":"Hội nghị Trung ương (11/1939) chủ trương đặt nhiệm vụ giải phóng dân tộc lên hàng đầu, là lợi ích tối cao của toàn thể dân tộc lúc này."},{"id":527,"section":"ch1-2","q":"Luận điểm nào sau đây không phải chủ trương của Hội nghị Trung ương Đảng (11/1939) về cách mạng ruộng đất?","options":["Thực hiện triệt để khẩu hiệu người cày có ruộng.","Chống địa tô cao, chống tô thuế nặng nề của địa chủ.","Chống cho vay nặng lãi, chống bóc lột nông dân.","Tịch thu ruộng đất của địa chủ phản bội dân tộc, chia cho dân cày."],"answer":0,"explain":"Ở giai đoạn này, Hội nghị Trung ương (11/1939) mới chủ trương chống địa tô cao, chống cho vay nặng lãi, tịch thu ruộng đất của địa chủ phản bội dân tộc chia cho dân cày nghèo, chưa đặt vấn đề thực hiện triệt để khẩu hiệu người cày có ruộng."},{"id":528,"section":"ch1-2","q":"Ai là người chủ trì Hội nghị Trung ương Đảng (5/1941)?","options":["Nguyễn Ái Quốc.","Tôn Đức Thắng.","Võ Nguyên Giáp.","Phạm Văn Đồng."],"answer":0,"explain":"Hội nghị Trung ương Đảng lần thứ 8 (5/1941), họp tại Pác Bó (Cao Bằng), do lãnh tụ Nguyễn Ái Quốc trực tiếp chủ trì."},{"id":529,"section":"ch1-2","q":"Hội nghị Trung ương Đảng (5/1941) xác định mâu thuẫn chủ yếu lúc này ở Việt Nam là mâu thuẫn giữa","options":["dân tộc Việt Nam với phát xít Pháp - Nhật.","dân tộc Việt Nam với thực dân Pháp xâm lược.","công nhân Việt Nam với giai cấp tư sản Việt Nam.","nông dân với địa chủ phong kiến ở nông thôn."],"answer":0,"explain":"Hội nghị Trung ương 8 (5/1941) xác định mâu thuẫn chủ yếu ở Việt Nam lúc này là mâu thuẫn giữa dân tộc Việt Nam với đế quốc, phát xít Pháp - Nhật."},{"id":530,"section":"ch1-2","q":"Hội nghị Trung ương Đảng (5/1941) xác định nhiệm vụ chủ yếu, trước mắt của nhân dân Việt Nam lúc này là","options":["giải phóng dân tộc khỏi ách Pháp - Nhật.","chống phát xít, bảo vệ hoà bình.","chống chiến tranh đế quốc, bảo vệ Liên Xô.","giành ruộng đất cho dân cày nghèo."],"answer":0,"explain":"Hội nghị Trung ương 8 (5/1941) xác định nhiệm vụ chủ yếu, trước mắt của cách mạng là giải phóng dân tộc, tạm gác khẩu hiệu cách mạng ruộng đất."},{"id":531,"section":"ch1-2","q":"Nội dung nào sau đây phù hợp với chủ trương giải quyết vấn đề dân tộc ở Đông Dương được nêu ra tại Hội nghị Trung ương Đảng (5/1941)?","options":["Các dân tộc ở Đông Dương có quyền tự quyết.","Sáp nhập ba nước thành một quốc gia thống nhất.","Giữ nguyên Liên bang Đông Dương thuộc Pháp.","Việt Nam là trung tâm của khối Đông Dương."],"answer":0,"explain":"Hội nghị Trung ương 8 (5/1941) chủ trương giải quyết vấn đề dân tộc trong khuôn khổ từng nước Đông Dương, thực hiện quyền dân tộc tự quyết cho các dân tộc Đông Dương."},{"id":532,"section":"ch1-2","q":"Hội nghị Trung ương Đảng (5/1941) chủ trương thành lập tổ chức nào để tập hợp các giai cấp, tầng lớp trong xã hội ở Việt Nam hướng tới giải quyết nhiệm vụ chung của cách mạng?","options":["Mặt trận Việt Nam độc lập đồng minh.","Mặt trận Thống nhất dân tộc phản đế.","Hội Liên hiệp quốc dân Việt Nam.","Mặt trận đoàn kết Việt – Miên – Lào."],"answer":0,"explain":"Hội nghị Trung ương 8 (5/1941) chủ trương thành lập Mặt trận Việt Minh để tập hợp mọi giai cấp, tầng lớp nhân dân trong sự nghiệp giải phóng dân tộc."},{"id":534,"section":"ch1-2","q":"Để chuẩn bị lực lượng cách mạng, tổ chức nào sau đây được thành lập với phương châm hành động: “Chính trị trọng hơn quân sự”?","options":["Đội Việt Nam Tuyên truyền Giải phóng quân.","Đội Cứu quốc quân Bắc Sơn - Võ Nhai.","Việt Nam Giải phóng quân (5/1945).","Đội du kích Bắc Sơn (khởi nghĩa 9/1940)."],"answer":0,"explain":"Đội Việt Nam Tuyên truyền Giải phóng quân (22/12/1944) được thành lập theo chỉ thị của Hồ Chí Minh với phương châm “chính trị trọng hơn quân sự”."},{"id":535,"section":"ch1-2","q":"Trong cuộc vận động cách mạng (1941 – 1945), Đảng chủ trương xây dựng căn cứ địa","options":["Bắc Sơn, Võ Nhai.","Rừng Sác (Cần Giờ).","Ấp Bắc (Tiền Giang).","Củ Chi (Tp. Hồ Chí Minh)."],"answer":0,"explain":"Trong cuộc vận động cách mạng 1941-1945, Đảng chủ trương xây dựng căn cứ địa Bắc Sơn - Võ Nhai làm nơi đứng chân, chuẩn bị lực lượng vũ trang."},{"id":536,"section":"ch1-2","q":"Đâu không phải ý nghĩa của Hội nghị Ban Chấp hành Trung ương Đảng (5/1941)?","options":["Mở đầu sự chuyển hướng chiến lược của Đảng khi xác định đặt nhiệm vụ giải phóng dân tộc lên hàng đầu.","Hoàn chỉnh chủ trương chiến lược đưa ra từ Hội nghị lần thứ sáu Ban Chấp hành Trung ương Đảng (11/1939).","Khẳng định tính đúng đắn của Cương lĩnh chính trị (2/1930) trong điều kiện lịch sử mới của cách mạng.","Là ngọn cờ dẫn đường cho toàn Đảng, toàn dân trong sự nghiệp đánh Pháp, đuổi Nhật giành độc lập tự do."],"answer":0,"explain":"Hội nghị Trung ương 8 (5/1941) hoàn chỉnh chủ trương chuyển hướng chiến lược đã được mở đầu từ Hội nghị Trung ương 6 (11/1939), chứ không phải là hội nghị “mở đầu” sự chuyển hướng đó."},{"id":538,"section":"ch1-2","q":"Để đáp ứng yêu cầu chuẩn bị về lực lượng cách mạng, tổ chức nào sau đây ra đời vào năm 1944 và được coi là tiền thân của Quân đội nhân dân Việt Nam?","options":["Đội Việt Nam Tuyên truyền Giải phóng quân (12/1944)","Trung đội Việt Nam Cứu quốc quân (23/2/1941)","Việt Nam Giải phóng quân thống nhất (15/5/1945)","Quân đội Quốc gia Việt Nam (Vệ quốc đoàn, 22/5/1946)"],"answer":0,"explain":"Đội Việt Nam Tuyên truyền Giải phóng quân, thành lập ngày 22/12/1944 theo chỉ thị của Hồ Chí Minh, được coi là tiền thân của Quân đội nhân dân Việt Nam."},{"id":539,"section":"ch1-2","q":"Sự kiện nào mở ra thời cơ tổng khởi nghĩa giành chính quyền trong Cách mạng Tháng Tám năm 1945?","options":["Nhật tuyên bố đầu hàng Đồng minh không điều kiện (15/8/1945).","Đức đầu hàng quân Đồng minh vô điều kiện (5/1945).","Hội nghị Pốtxđam (7/1945) quyết định quân Trung Hoa vào miền Bắc.","Khi quân Đồng minh kéo vào giải giáp quân Nhật ở nước ta."],"answer":0,"explain":"Ngày 15/8/1945, phát xít Nhật tuyên bố đầu hàng Đồng minh không điều kiện, tạo thời cơ “ngàn năm có một” để nhân dân ta tiến hành Tổng khởi nghĩa giành chính quyền."},{"id":540,"section":"ch1-2","q":"Ngày 13/8/1945, Trung ương Đảng và Tổng bộ Việt Minh thành lập Ủy ban Khởi nghĩa toàn quốc và phát lệnh","options":["tổng khởi nghĩa giành chính quyền trong toàn quốc.","tổng tiến công chiến lược trên toàn Đông Dương.","toàn quốc kháng chiến chống thực dân Pháp.","kháng chiến, kiến quốc trên phạm vi toàn quốc."],"answer":0,"explain":"Ngày 13/8/1945, Trung ương Đảng và Tổng bộ Việt Minh thành lập Ủy ban Khởi nghĩa toàn quốc, ra “Quân lệnh số 1” phát lệnh tổng khởi nghĩa trong toàn quốc."},{"id":541,"section":"ch1-2","q":"Ngày 14 và 15/8/1945, Hội nghị toàn quốc của Đảng họp ở Tân Trào xác định nguyên tắc chỉ đạo khởi nghĩa là","options":["tập trung, thống nhất và kịp thời.","tập trung, bất ngờ, kịp thời.","nhanh chóng, táo bạo, chắc thắng.","táo bạo, bất ngờ, chắc thắng."],"answer":0,"explain":"Hội nghị toàn quốc của Đảng (14-15/8/1945) họp tại Tân Trào đã xác định ba nguyên tắc chỉ đạo khởi nghĩa: tập trung, thống nhất và kịp thời."},{"id":542,"section":"ch1-2","q":"Ngày 16/8/1945 Đại hội quốc dân họp tại Tân Trào tán thành quyết định tổng khởi nghĩa, thông qua 10 chính sách lớn của Việt Minh, lập Uỷ ban dân tộc giải phóng Việt Nam do ai làm chủ tịch?","options":["Hồ Chí Minh.","Trường Chinh.","Phạm Văn Đồng.","Võ Nguyên Giáp."],"answer":0,"explain":"Đại hội Quốc dân Tân Trào (16/8/1945) đã lập ra Uỷ ban Dân tộc giải phóng Việt Nam do Hồ Chí Minh làm Chủ tịch."},{"id":543,"section":"ch1-2","q":"Diễn tiến thời gian nào sau đây phù hợp với diễn biến của Cách mạng Tháng Tám năm 1945?","options":["Giành chính quyền ở Hà Nội (19/8/1945), Huế (23/8/1945), Sài Gòn (25/8/1945).","Giành chính quyền ở Hà Nội (18/8/1945), Huế (25/8/1945), Sài Gòn (28/8/1945).","Giành chính quyền ở Huế (19/8/1945), Hà Nội (23/8/1945), Sài Gòn (25/8/1945).","Giành chính quyền ở Sài Gòn (18/8/1945), Huế (23/8/1945), Hà Nội (25/8/1945)."],"answer":0,"explain":"Trong Cách mạng Tháng Tám năm 1945, nhân dân ta giành chính quyền ở Hà Nội (19/8), Huế (23/8) và Sài Gòn (25/8/1945)."},{"id":545,"section":"ch1-2","q":"Nội dung nào không phải ý nghĩa của Cách mạng Tháng Tám năm 1945?","options":["Làm tan rã hoàn toàn chủ nghĩa thực dân cũ trên toàn thế giới, chấm dứt mọi chế độ thuộc địa.","Đập tan xiềng xích nô lệ của đế quốc, chấm dứt chế độ quân chủ chuyên chế hàng ngàn năm ở Việt Nam.","Đưa nhân dân từ thân phận nô lệ lên địa vị người chủ đất nước, có quyền quyết định vận mệnh của mình.","Mở ra kỷ nguyên mới trong lịch sử dân tộc, kỷ nguyên độc lập, tự do và hướng tới chủ nghĩa xã hội."],"answer":0,"explain":"Cách mạng Tháng Tám 1945 chấm dứt chế độ quân chủ, đưa nhân dân lên làm chủ đất nước, mở ra kỷ nguyên độc lập tự do; tuy nhiên không thể coi là đã làm tan rã hoàn toàn chủ nghĩa thực dân cũ trên toàn thế giới, vì hệ thống thuộc địa của các nước đế quốc khác vẫn còn tồn tại sau 1945."},{"id":577,"section":"ch1-2","q":"Cao trào cách mạng 1930-1931 đạt đỉnh cao ở đâu, với hình thức chính quyền kiểu mới nào?","options":["Ở Nghệ An, Hà Tĩnh, với sự ra đời của các Xô viết Nghệ - Tĩnh","Ở Nam Kỳ, với chính quyền tự trị theo mô hình cộng hòa","Ở Bắc Kỳ, với chính quyền quân sự lâm thời do binh lính lập","Ở Trung Kỳ, với chính quyền do các sĩ phu yêu nước lập ra"],"answer":0,"explain":"Cao trào 1930-1931 lên đến đỉnh cao ở hai tỉnh Nghệ An, Hà Tĩnh, nơi quần chúng đã lập nên các Xô viết - hình thức chính quyền cách mạng sơ khai của công nông."},{"id":578,"section":"ch1-2","q":"Chính quyền Xô viết Nghệ - Tĩnh đã thực hiện những chính sách tiến bộ nào?","options":["Chia lại ruộng công, giảm tô, xóa nợ cho nông dân, thực hiện các quyền tự do dân chủ","Duy trì nguyên vẹn chế độ sưu thuế, tô tức nặng nề của thực dân phong kiến đối với nông dân","Cấm hoàn toàn hoạt động của các tổ chức nông hội, công hội và các đoàn thể quần chúng","Thi hành chính sách đồng hóa văn hóa, buộc nhân dân theo phong tục và lối sống của người Pháp"],"answer":0,"explain":"Xô viết Nghệ - Tĩnh đã thi hành nhiều chính sách tiến bộ: chia lại ruộng đất công cho dân nghèo, bãi bỏ các thứ thuế vô lý, thực hiện quyền tự do dân chủ, mở lớp dạy chữ Quốc ngữ."},{"id":579,"section":"ch1-2","q":"Luận cương chính trị tháng 10/1930 do ai soạn thảo, được thông qua tại Hội nghị nào?","options":["Do Trần Phú soạn thảo, thông qua tại Hội nghị Trung ương lần thứ nhất (10/1930)","Do Nguyễn Ái Quốc soạn thảo, thông qua tại Hội nghị hợp nhất các tổ chức cộng sản","Do Lê Hồng Phong soạn thảo, thông qua tại Đại hội đại biểu lần thứ I của Đảng (1935)","Do Hà Huy Tập soạn thảo, thông qua tại Đại hội VII Quốc tế Cộng sản (1935)"],"answer":0,"explain":"Luận cương chính trị tháng 10/1930 do đồng chí Trần Phú - Tổng Bí thư đầu tiên của Đảng - soạn thảo, được thông qua tại Hội nghị Ban Chấp hành Trung ương lần thứ nhất họp tại Hương Cảng (10/1930)."},{"id":580,"section":"ch1-2","q":"Luận cương chính trị tháng 10/1930 xác định lực lượng cách mạng chủ yếu, có vai trò quyết định nhất là giai cấp nào?","options":["Công nhân và nông dân, trong đó giai cấp công nhân giữ vai trò lãnh đạo","Giai cấp tư sản dân tộc, giữ vai trò chủ yếu và quyết định nhất của cách mạng","Tầng lớp tiểu tư sản và trí thức, giữ vai trò chủ yếu và quyết định nhất của cách mạng","Giai cấp địa chủ yêu nước, giữ vai trò chủ yếu và quyết định nhất của cách mạng"],"answer":0,"explain":"Luận cương chính trị 10/1930 xác định động lực chủ yếu của cách mạng tư sản dân quyền là giai cấp công nhân và giai cấp nông dân, trong đó giai cấp công nhân là động lực chính, có sứ mệnh lãnh đạo cách mạng."},{"id":581,"section":"ch1-2","q":"Thực dân Pháp đã đàn áp cao trào cách mạng 1930-1931 bằng biện pháp nào?","options":["Khủng bố trắng tàn khốc, bắt bớ, tù đày, sát hại nhiều đảng viên và quần chúng","Nhượng bộ, trao trả một phần quyền tự trị và quyền tự do báo chí cho Việt Nam","Đối thoại hòa bình, thực hiện cải cách ruộng đất theo yêu cầu của nông dân Nghệ - Tĩnh","Rút toàn bộ quân đội khỏi Đông Dương và trao quyền cai trị cho triều đình Huế"],"answer":0,"explain":"Thực dân Pháp thẳng tay khủng bố, đàn áp đẫm máu phong trào 1930-1931, nhiều cơ sở Đảng bị phá vỡ, hàng vạn cán bộ, đảng viên, quần chúng bị bắt, tù đày, sát hại."},{"id":582,"section":"ch1-2","q":"Đại hội đại biểu toàn quốc lần thứ I của Đảng (3/1935) xác định ba nhiệm vụ chủ yếu trước mắt của Đảng là gì?","options":["Củng cố, phát triển Đảng; tranh thủ quần chúng rộng rãi; chống chiến tranh đế quốc","Tổng khởi nghĩa vũ trang giành chính quyền ngay lập tức trên phạm vi cả nước","Đàm phán hòa bình với thực dân Pháp để giành độc lập từng phần cho Đông Dương","Chỉ tập trung duy nhất vào công tác đối ngoại và liên lạc với Quốc tế Cộng sản"],"answer":0,"explain":"Đại hội I (3/1935) đề ra ba nhiệm vụ chủ yếu trước mắt: củng cố và phát triển Đảng, tranh thủ quần chúng rộng rãi, chống chiến tranh đế quốc, nhằm khôi phục và phát triển phong trào cách mạng sau thời kỳ bị khủng bố."},{"id":583,"section":"ch1-2","q":"Trong giai đoạn 1932-1935, nhiệm vụ trọng tâm của những người cộng sản Việt Nam là gì?","options":["Khôi phục hệ thống tổ chức Đảng và phong trào cách mạng sau khủng bố trắng","Chuẩn bị tổng khởi nghĩa vũ trang giành chính quyền trên phạm vi toàn quốc","Xây dựng Mặt trận Việt Minh để tập hợp mọi lực lượng yêu nước chống Nhật","Tổ chức Tổng tuyển cử bầu Quốc hội và thành lập chính phủ liên hiệp"],"answer":0,"explain":"Sau khi bị khủng bố nặng nề (1931-1932), nhiệm vụ trọng tâm 1932-1935 là kiên trì đấu tranh, khôi phục các tổ chức đảng, đoàn thể quần chúng, khôi phục phong trào cách mạng."},{"id":584,"section":"ch1-2","q":"Chương trình hành động của Đảng Cộng sản Đông Dương (6/1932) đề ra những yêu sách cụ thể nào về quyền lợi của công nhân, nông dân?","options":["Ngày làm 8 giờ, tăng lương, giảm sưu thuế cho nông dân, chống khủng bố trắng","Quốc hữu hóa toàn bộ ruộng đất trên phạm vi cả nước ngay lập tức, xóa bỏ địa chủ","Xóa bỏ hoàn toàn hình thức lao động làm công ăn lương trong nhà máy, hầm mỏ","Chỉ đề cập vấn đề đối ngoại, không đề cập quyền lợi kinh tế của dân trong nước"],"answer":0,"explain":"Chương trình hành động (6/1932) đề ra những yêu sách thiết thực trước mắt như đấu tranh đòi ngày làm 8 giờ, tăng tiền lương, giảm sưu thuế cho nông dân, chống khủng bố trắng, nhằm tập hợp, động viên quần chúng tiếp tục đấu tranh trong hoàn cảnh khó khăn."},{"id":585,"section":"ch1-2","q":"Ý nghĩa lịch sử to lớn nhất của cao trào cách mạng 1930-1931 mà đỉnh cao là Xô viết Nghệ - Tĩnh là gì?","options":["Khẳng định đường lối đúng của Đảng và là cuộc tập dượt đầu tiên cho Cách mạng Tháng Tám","Giành được độc lập hoàn toàn cho dân tộc và lập nên nhà nước công nông trên cả nước","Buộc thực dân Pháp phải trao trả quyền tự trị và ban hành hiến pháp cho Việt Nam","Chấm dứt hoàn toàn chế độ phong kiến và xóa bỏ ách thống trị của thực dân Pháp"],"answer":0,"explain":"Quốc tế Cộng sản đánh giá cao trào 1930-1931 là cuộc tổng diễn tập đầu tiên của cách mạng Việt Nam, khẳng định đường lối đúng đắn của Đảng và quyền lãnh đạo của giai cấp công nhân đối với cách mạng Việt Nam."},{"id":586,"section":"ch1-2","q":"Sau Đại hội lần thứ I (3/1935), tình hình thế giới thay đổi như thế nào tác động trực tiếp đến chủ trương của Đảng trong giai đoạn tiếp theo (1936-1939)?","options":["Phát xít xuất hiện, đe dọa hòa bình; Quốc tế Cộng sản chủ trương lập mặt trận chống phát xít","Chiến tranh thế giới thứ hai đã kết thúc, Liên Xô và Mỹ chia nhau ảnh hưởng ở châu Âu, châu Á","Liên Xô sụp đổ, phong trào cộng sản quốc tế suy yếu, Quốc tế Cộng sản tuyên bố tự giải thể","Mỹ trở thành cường quốc duy nhất chi phối thế giới, các nước thuộc địa giành độc lập hàng loạt"],"answer":0,"explain":"Từ giữa những năm 1930, chủ nghĩa phát xít xuất hiện và ráo riết chuẩn bị chiến tranh; Đại hội VII Quốc tế Cộng sản (1935) chủ trương thành lập Mặt trận nhân dân rộng rãi chống phát xít, chống chiến tranh, tác động trực tiếp đến chủ trương của Đảng trong giai đoạn 1936-1939."},{"id":587,"section":"ch1-2","q":"Hội nghị Ban Chấp hành Trung ương Đảng (7/1936) đã xác định nhiệm vụ trực tiếp, trước mắt của cách mạng Đông Dương trong giai đoạn 1936-1939 là gì?","options":["Chống phản động thuộc địa, chống phát xít, chống chiến tranh, đòi dân sinh, dân chủ, hòa bình","Đấu tranh vũ trang lật đổ ngay chính quyền thực dân Pháp, thiết lập chính quyền Xô viết","Đấu tranh giành ruộng đất triệt để cho nông dân, thực hiện cách mạng thổ địa trên cả nước","Đấu tranh đòi thành lập nước Việt Nam Dân chủ Cộng hòa, đánh đuổi hoàn toàn Nhật - Pháp"],"answer":0,"explain":"Hội nghị Trung ương tháng 7/1936 xác định nhiệm vụ trực tiếp, trước mắt là chống chế độ phản động thuộc địa, chống phát xít, chống nguy cơ chiến tranh, đòi các quyền tự do, dân chủ, cơm áo, hòa bình."},{"id":588,"section":"ch1-2","q":"Hình thức tổ chức mặt trận được Đảng chủ trương thành lập trong giai đoạn 1936-1939 có tên gọi là gì?","options":["Mặt trận Dân chủ Đông Dương (1938)","Mặt trận Việt Minh (5/1941)","Mặt trận Liên Việt (3/1951)","Mặt trận Tổ quốc Việt Nam (1955)"],"answer":0,"explain":"Đảng chủ trương thành lập Mặt trận Thống nhất nhân dân phản đế Đông Dương (1936), đến tháng 3/1938 đổi tên thành Mặt trận Dân chủ Đông Dương, tập hợp rộng rãi các lực lượng yêu nước, dân chủ."},{"id":589,"section":"ch1-2","q":"Hình thức và phương pháp đấu tranh chủ yếu của phong trào cách mạng 1936-1939 là gì?","options":["Kết hợp các hình thức công khai và bí mật, hợp pháp và bất hợp pháp","Chỉ đấu tranh vũ trang bí mật trong rừng núi và vùng căn cứ địa","Chỉ đấu tranh nghị trường đơn thuần trong khuôn khổ luật pháp thuộc địa","Chỉ tổng bãi công toàn quốc kéo dài, không kết hợp hình thức nào khác"],"answer":0,"explain":"Trong giai đoạn 1936-1939, Đảng chủ trương kết hợp linh hoạt các hình thức đấu tranh công khai và bí mật, hợp pháp và bất hợp pháp để tập hợp lực lượng quần chúng rộng rãi."},{"id":590,"section":"ch1-2","q":"Phong trào Đông Dương Đại hội (1936) là phong trào gì?","options":["Phong trào thu thập \"dân nguyện\" của quần chúng để gửi yêu sách dân chủ tới phái đoàn Pháp","Đại hội thành lập Đảng Cộng sản Đông Dương với sự tham dự của đại biểu các tổ chức cộng sản","Cuộc tổng khởi nghĩa vũ trang giành chính quyền ở các tỉnh Nam Kỳ, Trung Kỳ và Bắc Kỳ","Hội nghị hợp nhất các tổ chức cộng sản ở Đông Dương do Nguyễn Ái Quốc chủ trì tại Hương Cảng"],"answer":0,"explain":"Phong trào Đông Dương Đại hội (giữa 1936) vận động nhân dân họp bàn, thu thập dân nguyện gửi tới phái đoàn điều tra của Chính phủ Mặt trận Nhân dân Pháp, đòi các quyền dân sinh, dân chủ."},{"id":591,"section":"ch1-2","q":"Báo chí công khai của Đảng trong thời kỳ vận động dân chủ 1936-1939 có vai trò gì?","options":["Là vũ khí tuyên truyền sắc bén, truyền bá chủ nghĩa Mác - Lênin và đường lối của Đảng","Chỉ phục vụ mục đích giải trí đơn thuần, không truyền bá tư tưởng chính trị nào","Chỉ đăng tải tin tức thể thao và quảng cáo thương mại, tránh bàn chuyện chính trị","Bị thực dân Pháp khuyến khích và tài trợ để tuyên truyền cho chính sách khai thác thuộc địa"],"answer":0,"explain":"Thời kỳ 1936-1939, Đảng tận dụng điều kiện tương đối thuận lợi để ra nhiều tờ báo công khai (Tin Tức, Dân Chúng, Le Travail...) làm vũ khí tuyên truyền, giáo dục quần chúng, vạch trần âm mưu của kẻ thù."},{"id":592,"section":"ch1-2","q":"Cuộc vận động dân chủ 1936-1939 để lại ý nghĩa quan trọng nào đối với cách mạng Việt Nam?","options":["Là cuộc diễn tập lần thứ hai chuẩn bị cho thắng lợi của Cách mạng Tháng Tám 1945","Giành được độc lập dân tộc hoàn toàn và lật đổ chế độ thực dân phong kiến trên cả nước","Xóa bỏ hoàn toàn chế độ thực dân phong kiến và lập chính quyền công nông","Thành lập được chính quyền Xô viết trên cả nước và đuổi hết quân Pháp"],"answer":0,"explain":"Cùng với cao trào 1930-1931, cuộc vận động dân chủ 1936-1939 được xem là cuộc diễn tập thứ hai, giúp Đảng tích lũy kinh nghiệm về xây dựng mặt trận, tổ chức quần chúng, chuẩn bị lực lượng cho Cách mạng Tháng Tám 1945."},{"id":593,"section":"ch1-2","q":"Qua phong trào 1936-1939, Đảng đã tích lũy được kinh nghiệm quý báu nào?","options":["Kinh nghiệm xây dựng mặt trận thống nhất, kết hợp đấu tranh hợp pháp và bất hợp pháp","Kinh nghiệm tổ chức tổng khởi nghĩa vũ trang giành chính quyền trên phạm vi toàn quốc","Kinh nghiệm đàm phán ngoại giao với các cường quốc để giành độc lập dân tộc","Kinh nghiệm xây dựng nhà nước pháp quyền xã hội chủ nghĩa trên phạm vi cả nước ta"],"answer":0,"explain":"Qua thực tiễn lãnh đạo phong trào 1936-1939, Đảng tích lũy kinh nghiệm quý về xây dựng mặt trận dân tộc thống nhất, tổ chức và lãnh đạo quần chúng đấu tranh công khai kết hợp bí mật."},{"id":594,"section":"ch1-2","q":"Chính phủ Mặt trận Nhân dân Pháp lên cầm quyền năm 1936 đã tạo điều kiện thuận lợi nào cho phong trào cách mạng ở Đông Dương?","options":["Nới lỏng một số chính sách, cho phép một số quyền tự do dân chủ tối thiểu ở thuộc địa","Trao trả độc lập hoàn toàn cho các nước thuộc địa của Pháp ở châu Á, châu Phi, châu Mỹ","Xóa bỏ hoàn toàn bộ máy cai trị thực dân ở Đông Dương và rút quân về nước","Cho phép thành lập chính đảng đối lập nắm quyền cai trị ở các nước thuộc địa"],"answer":0,"explain":"Chính phủ Mặt trận Nhân dân Pháp (1936) thi hành một số chính sách tiến bộ, nới lỏng kiểm soát ở thuộc địa, tạo điều kiện thuận lợi để Đảng và quần chúng ở Đông Dương đấu tranh công khai đòi các quyền dân sinh, dân chủ."},{"id":595,"section":"ch1-2","q":"Đến năm 1939, khi Chiến tranh thế giới thứ hai bùng nổ, tình hình chính trị ở Đông Dương thay đổi ra sao, tác động thế nào tới phong trào dân chủ?","options":["Pháp thi hành chính sách thời chiến phản động, đàn áp cách mạng, chấm dứt thời kỳ đấu tranh công khai","Pháp tiếp tục nới lỏng và mở rộng quyền tự do dân chủ, cho phép báo chí hoạt động công khai rộng rãi","Nhật Bản rút hoàn toàn khỏi Đông Dương, Pháp khôi phục chế độ cai trị dân chủ thời bình","Pháp trao trả độc lập ngay cho Việt Nam để tập trung lực lượng chống phát xít Đức"],"answer":0,"explain":"Khi Chiến tranh thế giới thứ hai bùng nổ (9/1939), thực dân Pháp ở Đông Dương thi hành chính sách thời chiến phản động, thẳng tay đàn áp phong trào cách mạng, chấm dứt thời kỳ đấu tranh công khai, hợp pháp 1936-1939."},{"id":596,"section":"ch1-2","q":"Trong giai đoạn 1936-1939, khẩu hiệu đấu tranh nào sau đây phù hợp với chủ trương của Đảng?","options":["\"Tự do, dân chủ, cơm áo, hòa bình\"","\"Đánh đuổi Nhật - Pháp, giành độc lập\"","\"Người cày có ruộng\" ngay lập tức","\"Độc lập tuyệt đối, chống cải lương\""],"answer":0,"explain":"Trong bối cảnh cần tập hợp lực lượng rộng rãi chống phát xít và phản động thuộc địa, Đảng chủ trương các khẩu hiệu đấu tranh đòi tự do, dân chủ, cơm áo, hòa bình, phù hợp với tính chất của giai đoạn cách mạng dân chủ này."},{"id":597,"section":"ch1-2","q":"So với cao trào 1930-1931, phong trào 1936-1939 có điểm khác biệt căn bản nào về mục tiêu đấu tranh?","options":["Không đặt vấn đề đánh đổ ngay đế quốc, phong kiến, mà tập trung đòi quyền dân sinh, dân chủ","Đặt mục tiêu đánh đổ chính quyền thực dân Pháp bằng khởi nghĩa vũ trang ngay lập tức trên cả nước","Chủ trương thành lập nhà nước công nông binh theo mô hình Xô viết trên toàn quốc","Chủ trương ly khai hoàn toàn khỏi hệ thống thuộc địa và xây dựng chế độ cộng hòa"],"answer":0,"explain":"Do điều kiện lịch sử khác nhau, phong trào 1936-1939 không đặt nhiệm vụ đánh đổ trực tiếp đế quốc và phong kiến giành độc lập ngay như 1930-1931, mà tập trung vào mục tiêu trước mắt là đòi quyền dân sinh, dân chủ, hòa bình."},{"id":598,"section":"ch1-2","q":"Ai là Tổng Bí thư của Đảng trong phần lớn thời kỳ vận động dân chủ 1936-1939?","options":["Hà Huy Tập, sau đó là Nguyễn Văn Cừ","Trần Phú, sau đó là Lê Hồng Phong","Lê Hồng Phong, sau đó là Trường Chinh","Nguyễn Ái Quốc, sau đó là Trần Phú"],"answer":0,"explain":"Trong giai đoạn 1936-1939, các đồng chí Hà Huy Tập và sau đó Nguyễn Văn Cừ lần lượt giữ cương vị Tổng Bí thư của Đảng, trực tiếp lãnh đạo phong trào vận động dân chủ."},{"id":599,"section":"ch1-2","q":"Tác phẩm \"Tự chỉ trích\" (1939) của Tổng Bí thư Nguyễn Văn Cừ có ý nghĩa gì đối với công tác xây dựng Đảng?","options":["Phê bình các biểu hiện \"tả\" khuynh, \"hữu\" khuynh, góp phần thống nhất tư tưởng trong Đảng","Đề xuất giải thể Đảng Cộng sản Đông Dương để thành lập một đảng mới rộng rãi hơn trong quần chúng","Chủ trương từ bỏ đấu tranh giai cấp để tập trung vào hoạt động cải lương hợp pháp","Chủ trương hợp tác lâu dài, không điều kiện với thực dân Pháp để giành tự do dân chủ"],"answer":0,"explain":"Tác phẩm \"Tự chỉ trích\" của Nguyễn Văn Cừ (1939) thẳng thắn phê bình các biểu hiện lệch lạc trong Đảng, góp phần thống nhất tư tưởng, giữ vững nguyên tắc, tăng cường sự đoàn kết, vững mạnh của Đảng trước bước ngoặt mới."},{"id":600,"section":"ch1-2","q":"Hội nghị Ban Chấp hành Trung ương Đảng (11/1939) đánh dấu bước chuyển hướng chỉ đạo chiến lược cách mạng như thế nào?","options":["Đặt nhiệm vụ giải phóng dân tộc lên hàng đầu, tạm gác cách mạng ruộng đất, chuyển sang chuẩn bị khởi nghĩa vũ trang","Tiếp tục duy trì nguyên vẹn đường lối đấu tranh công khai, hợp pháp như giai đoạn 1936-1939 ở Đông Dương, không thay đổi","Chủ trương liên minh chặt chẽ, lâu dài với thực dân Pháp để cùng nhau chống phát xít Nhật ở Đông Dương","Giải tán các tổ chức quần chúng, chuyển sang hoạt động cá nhân đơn lẻ trong nhân dân để tránh đàn áp"],"answer":0,"explain":"Hội nghị Trung ương (11/1939) đánh dấu bước chuyển hướng chỉ đạo chiến lược quan trọng: đặt nhiệm vụ giải phóng dân tộc lên hàng đầu, tạm gác khẩu hiệu cách mạng ruộng đất, chuyển từ đấu tranh đòi dân sinh dân chủ sang chuẩn bị lực lượng cho khởi nghĩa vũ trang giành chính quyền."},{"id":601,"section":"ch1-2","q":"Sau khi Chiến tranh thế giới thứ hai bùng nổ, Đảng chủ trương chuyển hình thức tổ chức quần chúng từ công khai sang hình thức nào?","options":["Bí mật, để bảo tồn lực lượng và chuẩn bị đấu tranh lâu dài","Vẫn giữ nguyên hình thức công khai để tiếp tục vận động quần chúng","Giải tán toàn bộ các đoàn thể để tránh bị thực dân Pháp đàn áp","Chuyển hoàn toàn sang đấu tranh nghị trường trong khuôn khổ luật pháp"],"answer":0,"explain":"Trước chính sách khủng bố của thực dân Pháp thời chiến, Đảng chủ trương rút vào hoạt động bí mật, chuyển các đoàn thể quần chúng sang hình thức bí mật, trá hình để bảo tồn lực lượng, chuẩn bị cho giai đoạn đấu tranh mới."},{"id":602,"section":"ch1-2","q":"Đảng Cộng sản Đông Dương xác định kẻ thù chính trước mắt sau Hội nghị Trung ương (11/1939) là ai?","options":["Đế quốc Pháp và bọn phong kiến tay sai phản bội dân tộc","Chỉ riêng phát xít Nhật cùng bọn tay sai thân Nhật ở Đông Dương","Chỉ riêng giai cấp địa chủ phong kiến trong nước và bọn cường hào","Các nước Đồng minh chống phát xít đang đóng quân ở Đông Dương"],"answer":0,"explain":"Hội nghị Trung ương (11/1939) xác định kẻ thù chính, trước mắt của cách mạng Đông Dương lúc này là đế quốc Pháp và bọn phong kiến tay sai, phản bội quyền lợi dân tộc."},{"id":603,"section":"ch1-2","q":"Chủ trương thành lập Mặt trận Dân tộc Thống nhất phản đế Đông Dương được đề ra tại Hội nghị nào?","options":["Hội nghị Ban Chấp hành Trung ương Đảng (11/1939)","Hội nghị Ban Chấp hành Trung ương Đảng (5/1941)","Đại hội đại biểu lần thứ I của Đảng (3/1935)","Hội nghị thành lập Đảng tại Hương Cảng (2/1930)"],"answer":0,"explain":"Hội nghị Trung ương (11/1939) chủ trương thành lập Mặt trận Dân tộc Thống nhất phản đế Đông Dương, thay cho Mặt trận Dân chủ Đông Dương trước đó, nhằm tập hợp mọi lực lượng chống đế quốc, giải phóng dân tộc."},{"id":604,"section":"ch1-2","q":"Từ thực tiễn lãnh đạo giai đoạn 1930-1939, Đảng đã khẳng định bài học kinh nghiệm quan trọng nào về phương pháp cách mạng?","options":["Phải nắm vững, vận dụng linh hoạt các hình thức đấu tranh phù hợp với từng hoàn cảnh lịch sử","Chỉ có đấu tranh vũ trang là phương pháp đúng đắn trong mọi hoàn cảnh lịch sử cụ thể","Đấu tranh nghị trường luôn là hình thức cao nhất, hiệu quả nhất trong mọi giai đoạn cách mạng","Không cần xây dựng mặt trận dân tộc thống nhất trong bất kỳ giai đoạn cách mạng nào"],"answer":0,"explain":"Qua thực tiễn hai cao trào 1930-1931 và 1936-1939, Đảng rút ra bài học quan trọng về sự cần thiết phải nắm vững, vận dụng linh hoạt, sáng tạo các hình thức và phương pháp đấu tranh phù hợp với đặc điểm của từng thời kỳ lịch sử."},{"id":605,"section":"ch1-2","q":"Giai đoạn 1936-1939 gắn liền với sự phát triển của tổ chức quần chúng nào theo hướng công khai, hợp pháp?","options":["Các hội ái hữu, nghiệp đoàn, hội truyền bá chữ Quốc ngữ","Chỉ có các đội tự vệ vũ trang bí mật trong các vùng căn cứ","Chỉ có tổ chức Việt Nam Quốc dân Đảng ở các tỉnh miền Bắc","Chỉ có các hội kín theo mô hình phong kiến ở vùng nông thôn"],"answer":0,"explain":"Trong điều kiện tương đối thuận lợi 1936-1939, Đảng chú trọng xây dựng, phát triển các tổ chức quần chúng công khai, hợp pháp như hội ái hữu, nghiệp đoàn, hội truyền bá chữ Quốc ngữ để tập hợp, giáo dục quần chúng."},{"id":606,"section":"ch1-2","q":"Nhận định nào sau đây phản ánh đúng vai trò của phong trào 1936-1939 đối với việc chuẩn bị lực lượng cho Cách mạng Tháng Tám 1945?","options":["Giúp Đảng xây dựng đội quân chính trị đông đảo, rèn luyện đội ngũ cán bộ, đảng viên","Trực tiếp giành được chính quyền cách mạng trên phạm vi cả nước, lập nhà nước công nông","Thành lập được lực lượng vũ trang ba thứ quân hoàn chỉnh, sẵn sàng tổng khởi nghĩa","Xóa bỏ hoàn toàn ảnh hưởng của thực dân Pháp, phát xít Nhật đối với Đông Dương"],"answer":0,"explain":"Phong trào 1936-1939 giúp Đảng xây dựng được lực lượng chính trị quần chúng rộng lớn, rèn luyện đội ngũ cán bộ, đảng viên trưởng thành qua thực tiễn đấu tranh, tạo tiền đề quan trọng để tiến tới Cách mạng Tháng Tám 1945."},{"id":607,"section":"ch1-2","q":"Hội nghị Ban Chấp hành Trung ương Đảng lần thứ 8 (5/1941) hoàn chỉnh chủ trương chuyển hướng chỉ đạo chiến lược được đề ra từ Hội nghị Trung ương (11/1939) như thế nào?","options":["Khẳng định dứt khoát nhiệm vụ giải phóng dân tộc là bức thiết nhất, đặt lên hàng đầu","Chuyển trọng tâm sang thực hiện triệt để khẩu hiệu cách mạng ruộng đất ở nông thôn","Chủ trương hợp nhất ba nước Đông Dương thành một quốc gia duy nhất ngay lập tức","Quyết định giải tán Đảng Cộng sản Đông Dương để thành lập ba đảng riêng biệt"],"answer":0,"explain":"Hội nghị Trung ương 8 (5/1941) do Nguyễn Ái Quốc chủ trì đã hoàn chỉnh chủ trương chuyển hướng chỉ đạo chiến lược, khẳng định dứt khoát giải phóng dân tộc là nhiệm vụ bức thiết nhất, trên hết, trước hết của cách mạng Đông Dương lúc này."},{"id":608,"section":"ch1-2","q":"Hội nghị Trung ương 8 (5/1941) chủ trương giải quyết vấn đề dân tộc trong khuôn khổ nào?","options":["Trong khuôn khổ từng nước Đông Dương, lập mặt trận riêng ở Việt Nam, Lào, Campuchia","Chỉ trong khuôn khổ chung toàn Đông Dương, lập một mặt trận duy nhất cho ba nước","Giao cho Quốc tế Cộng sản quyết định trực tiếp và thống nhất cho cả ba dân tộc","Không đặt vấn đề dân tộc làm trọng tâm mà tập trung vào vấn đề giai cấp, ruộng đất"],"answer":0,"explain":"Khác với các nghị quyết trước đó đặt vấn đề trong phạm vi Đông Dương chung, Hội nghị Trung ương 8 chủ trương giải quyết vấn đề dân tộc trong khuôn khổ từng nước, thành lập ở Việt Nam Mặt trận Việt Minh, ở Lào và Campuchia các mặt trận riêng phù hợp đặc điểm mỗi dân tộc."},{"id":609,"section":"ch1-2","q":"Sau Hội nghị Trung ương 8, công tác xây dựng lực lượng chính trị được Đảng chú trọng triển khai thông qua tổ chức nào?","options":["Các đoàn thể cứu quốc trong Mặt trận Việt Minh","Hệ thống chính quyền của thực dân Pháp ở các tỉnh","Các tổ chức tôn giáo hoạt động hợp pháp trong nước","Lực lượng quân đội chính quy của Nhà nước cách mạng"],"answer":0,"explain":"Sau Hội nghị Trung ương 8, Đảng chú trọng xây dựng lực lượng chính trị quần chúng thông qua hệ thống các đoàn thể cứu quốc (Công nhân cứu quốc, Nông dân cứu quốc, Phụ nữ cứu quốc, Thanh niên cứu quốc...) trong Mặt trận Việt Minh."},{"id":610,"section":"ch1-2","q":"Chỉ thị của Ban Thường vụ Trung ương Đảng (12/3/1945) nhận định thời cơ tổng khởi nghĩa sẽ xuất hiện khi nào?","options":["Khi quân Đồng minh vào Đông Dương đánh Nhật, hoặc khi Nhật đầu hàng Đồng minh","Ngay khi Nhật đảo chính Pháp ngày 9/3/1945, quân Nhật chiếm toàn bộ Đông Dương","Chỉ khi có sự đồng ý trực tiếp của thực dân Pháp và chính phủ Mỹ","Chỉ khi Đảng nhận được viện trợ vũ khí đầy đủ từ lực lượng nước ngoài và Liên Xô"],"answer":0,"explain":"Chỉ thị \"Nhật - Pháp bắn nhau và hành động của chúng ta\" (12/3/1945) dự báo hai thời cơ tổng khởi nghĩa có thể xuất hiện: khi quân Đồng minh vào Đông Dương đánh Nhật, hoặc khi Nhật Bản mất nước (bị Đồng minh đánh bại) và quân Nhật ở Đông Dương hoang mang, mất tinh thần."},{"id":611,"section":"ch1-2","q":"Cao trào kháng Nhật cứu nước (từ tháng 3/1945) diễn ra dưới nhiều hình thức phong phú, tiêu biểu là hình thức nào ở các tỉnh trung du, thượng du Bắc Kỳ?","options":["Khởi nghĩa từng phần, lập chiến khu và khu giải phóng","Chỉ đấu tranh nghị trường để đòi các cải cách dân chủ","Chỉ tổ chức bãi khóa của học sinh, sinh viên các trường","Chỉ đấu tranh ngoại giao với quân đội Nhật để đòi tự do"],"answer":0,"explain":"Trong cao trào kháng Nhật cứu nước, ở nhiều tỉnh trung du, thượng du Bắc Kỳ đã nổ ra khởi nghĩa từng phần, thành lập chính quyền cách mạng ở nhiều nơi, tiến tới xây dựng các chiến khu và khu giải phóng, tiêu biểu là Khu giải phóng Việt Bắc."},{"id":612,"section":"ch1-2","q":"Trong Cách mạng Tháng Tám năm 1945, Đảng đã vận dụng thành công bài học nào về việc chớp thời cơ cách mạng?","options":["Phát động khởi nghĩa đúng thời cơ \"ngàn năm có một\", khi Nhật đã đầu hàng, Đồng minh chưa vào","Chờ đợi quân Đồng minh vào Đông Dương giải phóng rồi mới tiến hành khởi nghĩa giành chính quyền","Tiến hành khởi nghĩa ngay sau khi Nhật đảo chính Pháp tháng 3/1945 để giành chủ động","Trì hoãn khởi nghĩa để chờ viện trợ quốc tế đầy đủ rồi mới phát động tổng khởi nghĩa toàn quốc"],"answer":0,"explain":"Đảng và Chủ tịch Hồ Chí Minh đã chớp đúng thời cơ \"ngàn năm có một\" - khi phát xít Nhật đầu hàng Đồng minh nhưng quân Đồng minh chưa kịp vào Đông Dương, chính quyền tay sai thân Nhật hoang mang tột độ - để phát động Tổng khởi nghĩa Tháng Tám giành thắng lợi nhanh chóng, ít đổ máu."},{"id":613,"section":"ch1-2","q":"Ý nghĩa quốc tế của thắng lợi Cách mạng Tháng Tám năm 1945 là gì?","options":["Cổ vũ mạnh mẽ phong trào giải phóng dân tộc ở các nước thuộc địa và phụ thuộc","Chấm dứt hoàn toàn Chiến tranh thế giới thứ hai trên phạm vi toàn thế giới","Giúp Liên Xô giành thắng lợi hoàn toàn trước phát xít Đức ở mặt trận châu Âu","Xóa bỏ hoàn toàn hệ thống thuộc địa của chủ nghĩa đế quốc trên thế giới"],"answer":0,"explain":"Cách mạng Tháng Tám thành công, lần đầu tiên một dân tộc thuộc địa tự giải phóng khỏi ách đế quốc, phong kiến, lập nên nhà nước dân chủ nhân dân, có ý nghĩa quốc tế to lớn, cổ vũ mạnh mẽ phong trào giải phóng dân tộc trên thế giới, nhất là ở châu Á, châu Phi."},{"id":614,"section":"ch1-2","q":"Trong thời kỳ chuẩn bị khởi nghĩa (1941-1945), Chủ tịch Hồ Chí Minh đã sáng lập tờ báo nào của Mặt trận Việt Minh để tuyên truyền, giác ngộ quần chúng?","options":["Báo Việt Nam Độc lập","Báo Thanh Niên (1925)","Báo Nhân Dân (1951)","Báo Người cùng khổ (1922)"],"answer":0,"explain":"Báo Việt Nam Độc lập do Chủ tịch Hồ Chí Minh sáng lập (8/1941) tại Cao Bằng là cơ quan tuyên truyền của Mặt trận Việt Minh, góp phần quan trọng giác ngộ, tập hợp quần chúng chuẩn bị cho tổng khởi nghĩa."},{"id":615,"section":"ch1-2","q":"Ngay sau khi giành chính quyền tại Hà Nội, Ủy ban Khởi nghĩa đã tổ chức mít tinh lớn ra mắt Việt Minh tại đâu?","options":["Quảng trường Nhà hát Lớn Hà Nội (19/8/1945)","Quảng trường Ba Đình, Hà Nội (2/9/1945)","Cửa Ngọ Môn, Kinh thành Huế (30/8/1945)","Đình Tân Trào, Tuyên Quang (16/8/1945)"],"answer":0,"explain":"Ngày 19/8/1945, cuộc mít tinh lớn tại Quảng trường Nhà hát Lớn Hà Nội đã biến thành cuộc biểu tình vũ trang tiến chiếm các công sở, đánh dấu thắng lợi của khởi nghĩa giành chính quyền ở Hà Nội."},{"id":616,"section":"ch1-2","q":"Sự kiện Bảo Đại tuyên bố thoái vị (30/8/1945) có ý nghĩa như thế nào?","options":["Đánh dấu sự sụp đổ của chế độ phong kiến tồn tại hàng nghìn năm ở nước ta","Đánh dấu thực dân Pháp chính thức công nhận nền độc lập của nước Việt Nam","Đánh dấu phát xít Nhật chính thức đầu hàng Đồng minh ở Đông Dương","Đánh dấu sự ra đời của Mặt trận Việt Minh tại căn cứ địa Cao Bằng"],"answer":0,"explain":"Việc vua Bảo Đại tuyên bố thoái vị, trao ấn kiếm cho đại diện Chính phủ lâm thời tại Ngọ Môn (Huế, 30/8/1945) đánh dấu sự sụp đổ hoàn toàn của chế độ quân chủ phong kiến tồn tại hàng nghìn năm trên đất nước ta."},{"id":617,"section":"ch1-2","q":"Trong 15 năm lãnh đạo cách mạng (1930-1945), một trong những bài học kinh nghiệm quan trọng của Đảng là gì về công tác xây dựng lực lượng?","options":["Xây dựng liên minh công - nông làm nòng cốt, tập hợp mọi lực lượng yêu nước vào mặt trận","Chỉ dựa vào lực lượng vũ trang chính quy, không cần xây dựng lực lượng chính trị quần chúng","Chỉ dựa vào sự viện trợ của lực lượng bên ngoài, không cần dựa vào sức mạnh của nhân dân","Không cần thiết phải xây dựng căn cứ địa cách mạng và lực lượng vũ trang của nhân dân"],"answer":0,"explain":"Một trong những bài học quan trọng của thời kỳ 1930-1945 là phải xây dựng khối liên minh công nông vững chắc làm nòng cốt của khối đại đoàn kết dân tộc, đồng thời khéo léo tập hợp mọi lực lượng yêu nước, cách mạng vào mặt trận dân tộc thống nhất."},{"id":618,"section":"ch1-2","q":"Ngay sau khi Cách mạng Tháng Tám thành công, Chủ tịch Hồ Chí Minh đã soạn thảo và đọc bản Tuyên ngôn độc lập, trong đó trích dẫn những bản tuyên ngôn nổi tiếng nào của Mỹ và Pháp để làm cơ sở lý lẽ?","options":["Tuyên ngôn Độc lập 1776 của Mỹ và Tuyên ngôn Nhân quyền và Dân quyền 1791 của Pháp","Hiến chương Đại Tây Dương (1941) và Hiến chương Liên hợp quốc (1945) của phe Đồng minh","Tuyên ngôn của Đảng Cộng sản (1848) và Cương lĩnh của Quốc tế Cộng sản (1928)","Hiệp ước Vécxây (1919) và Hiệp ước Oasinhtơn (1922) của các cường quốc thắng trận"],"answer":0,"explain":"Trong Tuyên ngôn độc lập, Chủ tịch Hồ Chí Minh đã trích dẫn những lời bất hủ trong Tuyên ngôn Độc lập năm 1776 của nước Mỹ và Tuyên ngôn Nhân quyền và Dân quyền năm 1791 của Cách mạng Pháp để khẳng định quyền độc lập, tự do thiêng liêng của dân tộc Việt Nam."},{"id":748,"section":"ch1-2","q":"Chương trình hành động của Đảng Cộng sản Đông Dương (15/6/1932) vạch ra nhiệm vụ đấu tranh trước mắt là","options":["giải phóng dân tộc, đánh đổ ách thống trị của đế quốc.","giải phóng giai cấp, xóa bỏ chế độ tư hữu trong xã hội.","khôi phục hệ thống tổ chức của Đảng và phong trào cách mạng.","đòi quyền dân chủ, dân sinh, chống phát xít, đòi độc lập cho dân tộc."],"answer":2,"explain":"Chương trình hành động của Đảng Cộng sản Đông Dương (15/6/1932) do Ban Chỉ huy ở ngoài công bố, đặt ra nhiệm vụ trước mắt là khôi phục hệ thống tổ chức Đảng và phong trào cách mạng sau tổn thất nặng nề do thực dân Pháp khủng bố trong 1930-1931."},{"id":749,"section":"ch1-2","q":"Hội nghị Trung ương (5/1941) xác định nội dung nào sau đây là nhiệm vụ trung tâm của Đảng và nhân dân trong lúc này?","options":["Chuẩn bị khởi nghĩa vũ trang giành chính quyền.","Chuẩn bị nguồn lực kinh tế cho cuộc kháng chiến.","Chuẩn bị cán bộ xây dựng nhà nước mới.","Thực hiện cách mạng ruộng đất trong cả nước."],"answer":0,"explain":"Hội nghị Trung ương (5/1941) xác định chuẩn bị khởi nghĩa vũ trang là nhiệm vụ trung tâm của Đảng và nhân dân trong giai đoạn hiện tại."},{"id":750,"section":"ch1-2","q":"Năm 1943, Đảng công bố Đề cương về văn hoá Việt Nam, trong đó chủ trương xây dựng nền văn hoá mới với nguyên tắc","options":["dân tộc, khoa học, đại chúng.","dân tộc, tiến bộ, quần chúng.","dân tộc, nhân văn, dân chủ.","dân tộc, dân chủ, tiến bộ."],"answer":0,"explain":"Đề cương về văn hoá Việt Nam (1943) do Trường Chinh soạn thảo xác định ba nguyên tắc xây dựng nền văn hoá mới là dân tộc hoá, khoa học hoá, đại chúng hoá."},{"id":751,"section":"ch1-2","q":"Tổ chức nào ra đời vào 30/6/1944 với tôn chỉ “Đấu tranh cho độc lập dân tộc, tự do dân chủ, dân sinh hạnh phúc” và hoạt động tích cực trong sinh viên, trí thức, tiểu tư sản lớp trên, có đóng góp tích cực cho sự nghiệp cách mạng Việt Nam?","options":["Đảng Dân chủ Việt Nam.","Đảng Xã hội Việt Nam.","Mặt trận Việt Minh.","Mặt trận Liên Việt."],"answer":0,"explain":"Đảng Dân chủ Việt Nam thành lập ngày 30/6/1944, với tôn chỉ đấu tranh cho độc lập dân tộc, tự do dân chủ, dân sinh hạnh phúc, hoạt động chủ yếu trong tầng lớp trí thức, tư sản dân tộc, tiểu tư sản lớp trên."},{"id":752,"section":"ch1-2","q":"Câu nói: “Sau hai mươi năm ngai vàng bệ ngọc đã biết bao ngậm đắng nuốt cay, từ nay... lấy làm vui được làm dân tự do của một nước độc lập” trong Tuyên cáo thoái vị ngày 30/8/1945 là của vua","options":["Bảo Đại.","Thành Thái.","Khải Định.","Duy Tân."],"answer":0,"explain":"Câu nói trong Tuyên cáo thoái vị ngày 30/8/1945, \"Sau hai mươi năm ngai vàng bệ ngọc...\", là của vua Bảo Đại, vị hoàng đế cuối cùng của triều Nguyễn, người đã trị vì khoảng 20 năm và tuyên bố thoái vị trước phong trào cách mạng."},{"id":131,"section":"ch2-1","q":"Sau Cách mạng Tháng Tám, tình thế đất nước được ví như thế nào?","options":["\"Ngàn cân treo sợi tóc\"","\"Nước lửa không dung\"","\"Trứng chọi đá\"","\"Nồi da xáo thịt\""],"answer":0,"explain":"Nền độc lập và chính quyền cách mạng non trẻ đứng trước tình thế \"ngàn cân treo sợi tóc\", phải đối phó cùng lúc với thù trong, giặc ngoài."},{"id":132,"section":"ch2-1","q":"Chính phủ lâm thời họp phiên đầu tiên (3/9/1945) xác định nhiệm vụ cấp bách nào?","options":["Diệt giặc đói, diệt giặc dốt, diệt giặc ngoại xâm","Xây dựng ngay quân đội chính quy hiện đại để chống Pháp","Ký hiệp định với thực dân Pháp để hòa hoãn lâu dài","Gia nhập Liên hợp quốc để được các nước công nhận"],"answer":0,"explain":"Ngày 3/9/1945, Chính phủ lâm thời họp phiên đầu tiên, xác định ngay nhiệm vụ lớn trước mắt: diệt giặc đói, diệt giặc dốt và diệt giặc ngoại xâm."},{"id":133,"section":"ch2-1","q":"Chỉ thị \"Kháng chiến kiến quốc\" được ban hành vào ngày nào?","options":["Ngày 25/11/1945","Ngày 3/9/1945","Ngày 6/1/1946","Ngày 19/12/1946"],"answer":0,"explain":"Ngày 25/11/1945, Ban Chấp hành Trung ương Đảng ra Chỉ thị Kháng chiến kiến quốc, xác định kẻ thù chính là thực dân Pháp xâm lược."},{"id":134,"section":"ch2-1","q":"Thực dân Pháp nổ súng gây hấn, đánh chiếm Sài Gòn - Chợ Lớn, mở đầu cuộc xâm lược lần thứ hai vào đêm nào?","options":["Đêm 22 rạng 23/9/1945","Đêm 19 rạng 20/12/1946","Đêm 5 rạng 6/3/1946","Đêm 18 rạng 19/8/1945"],"answer":0,"explain":"Đêm 22 rạng ngày 23/9/1945, quân đội Pháp nổ súng gây hấn, đánh chiếm Sài Gòn - Chợ Lớn, mở đầu cuộc chiến tranh xâm lược Việt Nam lần thứ hai."},{"id":135,"section":"ch2-1","q":"Cuộc Tổng tuyển cử bầu Quốc hội đầu tiên của nước Việt Nam Dân chủ Cộng hòa diễn ra vào ngày nào?","options":["Ngày 6/1/1946","Ngày 2/9/1945","Ngày 9/11/1946","Ngày 19/12/1946"],"answer":0,"explain":"Ngày 6/1/1946, nhân dân cả nước tham gia cuộc bầu cử Quốc hội đầu tiên, với hơn 89% cử tri đi bỏ phiếu."},{"id":136,"section":"ch2-1","q":"Bản Hiến pháp đầu tiên của nước Việt Nam Dân chủ Cộng hòa được Quốc hội thông qua vào ngày nào?","options":["Ngày 9/11/1946","Ngày 6/1/1946","Ngày 2/3/1946","Ngày 19/12/1946"],"answer":0,"explain":"Tại kỳ họp thứ 2, ngày 9/11/1946, Quốc hội đã thông qua bản Hiến pháp đầu tiên của Nhà nước Việt Nam Dân chủ Cộng hòa (Hiến pháp năm 1946)."},{"id":137,"section":"ch2-1","q":"Hiệp định Sơ bộ được ký kết vào ngày nào, giữa Việt Nam và Pháp?","options":["Ngày 6/3/1946","Ngày 14/9/1946","Ngày 19/12/1946","Ngày 28/2/1946"],"answer":0,"explain":"Ngày 6/3/1946, Chủ tịch Hồ Chí Minh thay mặt Chính phủ Việt Nam Dân chủ Cộng hòa ký với đại diện Pháp J.Xanhtơny bản Hiệp định Sơ bộ."},{"id":138,"section":"ch2-1","q":"Hiệp định Sơ bộ 6/3/1946 quy định điều gì về việc quân đội Pháp ra miền Bắc thay thế quân Tưởng?","options":["Việt Nam đồng ý để 15.000 quân Pháp ra miền Bắc thay quân Tưởng, rút dần trong 5 năm","Pháp phải rút toàn bộ quân đội khỏi Việt Nam ngay lập tức, không kèm theo điều kiện gì","Việt Nam công nhận Pháp là chính quốc bảo hộ và để Pháp đóng quân vô thời hạn ở miền Bắc","Quân Tưởng ở lại miền Bắc vô thời hạn để bảo vệ chính quyền cách mạng"],"answer":0,"explain":"Hiệp định Sơ bộ quy định Việt Nam đồng ý để 15.000 quân đội Pháp ra miền Bắc thay thế gần 20 vạn quân Tưởng, sẽ rút dần trong thời hạn 5 năm."},{"id":139,"section":"ch2-1","q":"Tạm ước được Chủ tịch Hồ Chí Minh ký với đại diện Pháp Marius Moutet vào ngày nào, tại đâu?","options":["Ngày 14/9/1946, tại Paris (Pháp)","Ngày 6/3/1946, tại Hà Nội","Ngày 19/12/1946, tại Hà Đông","Ngày 9/11/1946, tại Hà Nội"],"answer":0,"explain":"Ngày 14/9/1946, tại Paris, Chủ tịch Hồ Chí Minh ký với Marius Moutet - đại diện Chính phủ Pháp - bản Tạm ước 14/9."},{"id":140,"section":"ch2-1","q":"Hội nghị trù bị Việt - Pháp họp tại đâu, từ ngày nào đến ngày nào trong năm 1946?","options":["Tại Đà Lạt, từ 19/4 đến 11/5/1946","Tại Fontainebleau, từ 6/7 đến 10/9/1946","Tại Hà Nội, từ 6/3 đến 9/3/1946","Tại Paris, từ 14/9 đến 20/9/1946"],"answer":0,"explain":"Từ ngày 19/4 đến 11/5/1946, đại diện Chính phủ Việt Nam và Pháp gặp nhau tại Hội nghị trù bị ở Đà Lạt, chuẩn bị cho Hội nghị chính thức tại Fontainebleau."},{"id":141,"section":"ch2-1","q":"Toàn quốc kháng chiến bùng nổ vào thời điểm nào?","options":["20 giờ ngày 19/12/1946","22 giờ đêm 22/9/1945","5 giờ sáng ngày 23/9/1945","0 giờ ngày 6/3/1946"],"answer":0,"explain":"Mệnh lệnh của Chính phủ, bắt đầu từ 20 giờ ngày 19/12/1946, quân và dân Hà Nội cùng cả nước đồng loạt nổ súng, cuộc kháng chiến toàn quốc bùng nổ."},{"id":142,"section":"ch2-1","q":"Chỉ thị \"Toàn dân kháng chiến\" của Trung ương Đảng được ban hành vào ngày nào?","options":["Ngày 12/12/1946","Ngày 19/12/1946","Ngày 25/11/1945","Ngày 6/3/1946"],"answer":0,"explain":"Ngày 12/12/1946, Trung ương Đảng ra Chỉ thị Toàn dân kháng chiến."},{"id":143,"section":"ch2-1","q":"Chủ tịch Hồ Chí Minh ra Lời kêu gọi toàn quốc kháng chiến vào ngày nào?","options":["Ngày 19/12/1946","Ngày 12/12/1946","Ngày 6/3/1946","Ngày 2/9/1945"],"answer":0,"explain":"Ngày 19/12/1946, Chủ tịch Hồ Chí Minh ra Lời kêu gọi toàn quốc kháng chiến."},{"id":144,"section":"ch2-1","q":"Trong Lời kêu gọi toàn quốc kháng chiến, Hồ Chí Minh khẳng định quyết tâm như thế nào?","options":["\"Thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ\"","\"Không có gì quý hơn độc lập, tự do; nước Việt Nam là một, dân tộc Việt Nam là một\"","\"Đoàn kết, đoàn kết, đại đoàn kết; thành công, thành công, đại thành công\"","\"Dĩ bất biến, ứng vạn biến, kiên trì hòa hoãn để giữ gìn hòa bình lâu dài\""],"answer":0,"explain":"Lời kêu gọi khẳng định: \"Chúng ta thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ\"."},{"id":145,"section":"ch2-1","q":"Đường lối kháng chiến chống thực dân Pháp của Đảng gồm những nội dung cơ bản nào?","options":["Toàn dân, toàn diện, trường kỳ và dựa vào sức mình là chính","Chớp nhoáng, tốc chiến tốc thắng, dựa vào viện trợ nước ngoài","Phòng ngự cố định, đánh lớn, dựa vào lực lượng quân chính quy","Đấu tranh chính trị là chủ yếu, không tiến hành đấu tranh vũ trang"],"answer":0,"explain":"Đường lối kháng chiến của Đảng: dựa trên sức mạnh toàn dân, tiến hành kháng chiến toàn dân, toàn diện, lâu dài (trường kỳ) và dựa vào sức mình là chính."},{"id":146,"section":"ch2-1","q":"Trung đoàn Thủ đô rút khỏi Hà Nội, lên chiến khu an toàn vào ngày nào, sau bao nhiêu ngày đêm chiến đấu?","options":["Ngày 17/2/1947, sau 60 ngày đêm chiến đấu","Ngày 2/1/1947, sau 15 ngày đêm chiến đấu","Ngày 7/10/1947, sau 30 ngày đêm chiến đấu","Ngày 20/2/1948, sau 90 ngày đêm chiến đấu"],"answer":0,"explain":"Cuộc chiến đấu ở Hà Nội diễn ra suốt 60 ngày đêm; đến 17/2/1947, Trung đoàn Thủ đô chủ động rút khỏi thành phố, lên chiến khu an toàn."},{"id":147,"section":"ch2-1","q":"Chiến dịch Việt Bắc Thu Đông diễn ra vào cuối năm nào?","options":["Cuối năm 1947","Cuối năm 1946","Cuối năm 1950","Cuối năm 1954"],"answer":0,"explain":"Thu đông 1947, Pháp huy động khoảng 15.000 quân tấn công lên Việt Bắc; sau 75 ngày đêm chiến đấu, quân dân ta đánh bại cuộc tấn công này (thắng lợi kết thúc ngày 21/12/1947)."},{"id":148,"section":"ch2-1","q":"Chủ tịch Hồ Chí Minh ký Sắc lệnh phong quân hàm Đại tướng cho Võ Nguyên Giáp vào thời gian nào?","options":["Đầu năm 1948","Cuối năm 1947","Đầu năm 1950","Cuối năm 1946"],"answer":0,"explain":"Đầu năm 1948, Chủ tịch Hồ Chí Minh ký Sắc lệnh phong quân hàm Đại tướng cho đồng chí Võ Nguyên Giáp cùng Trung tướng Nguyễn Bình và 9 thiếu tướng."},{"id":149,"section":"ch2-1","q":"Nước Cộng hòa Nhân dân Trung Hoa ra đời vào ngày nào, có ý nghĩa gì với kháng chiến Việt Nam?","options":["Ngày 1/10/1949, tạo chuyển biến có lợi cho cách mạng Việt Nam","Ngày 2/9/1945, không tác động đến cục diện kháng chiến Việt Nam","Ngày 19/12/1946, cùng thời điểm toàn quốc kháng chiến bùng nổ","Ngày 7/5/1954, cùng thời điểm chiến thắng Điện Biên Phủ lịch sử"],"answer":0,"explain":"Ngày 1/10/1949, nước Cộng hòa Nhân dân Trung Hoa ra đời, tạo chuyển biến tích cực, có lợi cho các lực lượng cách mạng và cuộc kháng chiến của Việt Nam."},{"id":150,"section":"ch2-1","q":"Chủ tịch Hồ Chí Minh phát động phong trào thi đua ái quốc theo Lời kêu gọi ngày nào?","options":["Ngày 11/6/1948","Ngày 19/12/1946","Ngày 12/12/1946","Ngày 25/11/1945"],"answer":0,"explain":"Nhiều cuộc vận động thi đua ái quốc được tổ chức sâu rộng theo Lời kêu gọi Thi đua ái quốc của Chủ tịch Hồ Chí Minh ngày 11/6/1948."},{"id":151,"section":"ch2-1","q":"Đại hội đại biểu toàn quốc lần thứ II của Đảng họp vào thời gian nào, ở đâu?","options":["Tháng 2/1951, tại Tuyên Quang","Tháng 9/1960, tại Hà Nội","Tháng 3/1935, tại Ma Cao","Tháng 12/1976, tại Hà Nội"],"answer":0,"explain":"Đại hội đại biểu toàn quốc lần thứ II của Đảng họp tháng 2/1951, tại Chiêm Hóa (Tuyên Quang)."},{"id":152,"section":"ch2-1","q":"Đại hội II (2/1951) quyết định đưa Đảng ra hoạt động công khai với tên gọi mới là gì?","options":["Đảng Lao động Việt Nam","Đảng Cộng sản Đông Dương","Đảng Cộng sản Việt Nam","Đảng Nhân dân Cách mạng Việt Nam"],"answer":0,"explain":"Đại hội II quyết định đưa Đảng ra hoạt động công khai, lấy tên là Đảng Lao động Việt Nam."},{"id":153,"section":"ch2-1","q":"Chiến dịch Biên giới diễn ra vào thời gian nào, có ý nghĩa gì?","options":["Năm 1950, khai thông biên giới Việt - Trung, giành quyền chủ động chiến lược","Năm 1947, bảo vệ căn cứ địa Việt Bắc, đánh bại cuộc tấn công của Pháp","Năm 1954, kết thúc kháng chiến chống Pháp, buộc Pháp ký Hiệp định Giơnevơ","Năm 1952, mở đầu cuộc kháng chiến toàn quốc chống thực dân Pháp"],"answer":0,"explain":"Chiến dịch Biên giới (1950) giành thắng lợi, khai thông biên giới Việt - Trung, ta giành được quyền chủ động chiến lược trên chiến trường chính Bắc Bộ."},{"id":154,"section":"ch2-1","q":"Chiến dịch Điện Biên Phủ kết thúc thắng lợi vào ngày nào?","options":["Ngày 7/5/1954","Ngày 21/7/1954","Ngày 19/12/1946","Ngày 2/1948"],"answer":0,"explain":"Chiến dịch Điện Biên Phủ kết thúc thắng lợi vào ngày 7/5/1954, đưa đến việc ký kết Hiệp định Giơnevơ."},{"id":155,"section":"ch2-1","q":"Hiệp định Giơnevơ về Đông Dương được ký kết vào ngày nào?","options":["Ngày 21/7/1954","Ngày 7/5/1954","Ngày 20/7/1954","Ngày 27/1/1973"],"answer":0,"explain":"Hiệp nghị Giơnevơ về Đông Dương được ký kết ngày 21/7/1954, chấm dứt chiến tranh, lập lại hòa bình ở Đông Dương."},{"id":156,"section":"ch2-1","q":"Sau Hiệp định Giơnevơ, đế quốc Mỹ tiến hành hành động gì ở miền Nam Việt Nam?","options":["Áp đặt chủ nghĩa thực dân mới, tiến hành chiến tranh xâm lược 1954-1975","Rút toàn bộ quân khỏi Đông Dương, tôn trọng Hiệp định Giơnevơ","Chỉ viện trợ kinh tế cho miền Nam, không can thiệp quân sự trực tiếp","Công nhận, ủng hộ Chính phủ Việt Nam Dân chủ Cộng hòa và tổng tuyển cử"],"answer":0,"explain":"Đế quốc Mỹ áp đặt chủ nghĩa thực dân mới ở miền Nam Việt Nam và tiến hành cuộc chiến tranh xâm lược Việt Nam từ năm 1954 đến năm 1975."},{"id":157,"section":"ch2-1","q":"Chỉ thị \"Hòa để tiến\" của Thường vụ Trung ương Đảng được ban hành vào ngày nào?","options":["Ngày 9/3/1946","Ngày 6/3/1946","Ngày 3/3/1946","Ngày 19/12/1946"],"answer":0,"explain":"Ngay sau khi ký Hiệp định Sơ bộ, ngày 9/3/1946, Thường vụ Trung ương Đảng ra bản Chỉ thị Hòa để tiến."},{"id":158,"section":"ch2-1","q":"Chỉ thị \"Tình hình và chủ trương\" (3/3/1946) của Đảng chủ trương gì đối với thực dân Pháp?","options":["Tạm thời \"dàn hòa với Pháp\" để tránh phải đối phó cùng lúc nhiều kẻ thù","Kiên quyết đánh Pháp ngay lập tức, tuyệt đối không đàm phán thỏa hiệp","Nhờ Liên Xô can thiệp quân sự trực tiếp để buộc Pháp phải rút quân","Từ chối mọi đàm phán với Pháp, dồn lực đánh quân Tưởng trước tiên"],"answer":0,"explain":"Chỉ thị Tình hình và chủ trương (3/3/1946) chủ trương tạm thời \"dàn hòa với Pháp\", nhân nhượng về lợi ích kinh tế nhưng đòi Pháp thừa nhận quyền dân tộc tự quyết của Việt Nam."},{"id":159,"section":"ch2-1","q":"Cuộc đột nhập bắt giữ nhóm phản động âm mưu đảo chính, phá vụ án số 7 phố Ôn Như Hầu diễn ra vào ngày nào?","options":["Rạng sáng 12/7/1946","Ngày 6/3/1946","Ngày 19/12/1946","Ngày 14/9/1946"],"answer":0,"explain":"Rạng sáng ngày 12/7/1946, lực lượng công an đột nhập bất ngờ vào trụ sở của bọn Đại Việt, Quốc dân Đảng ở số 7 phố Ôn Như Hầu (Hà Nội), phá vụ án phố Ôn Như Hầu, đập tan âm mưu đảo chính."},{"id":160,"section":"ch2-1","q":"Đến tháng 12/1946, số lượng đảng viên của Đảng tăng lên khoảng bao nhiêu?","options":["Hơn 20.000 người","Hơn 70.000 người","Hơn 5.000 người","Hơn 1.597 người"],"answer":0,"explain":"Đến tháng 12/1946, Đảng đã có sự phát triển thêm về chất lượng, số lượng đảng viên tăng lên tới hơn 20.000 người."},{"id":161,"section":"ch2-1","q":"Đến cuối năm 1947, tổng số đảng viên toàn Đảng tăng lên khoảng bao nhiêu?","options":["Hơn 70.000 người","Hơn 20.000 người","Hơn 50.000 người","Hơn 1.000.000 người"],"answer":0,"explain":"Cuối năm 1947, tổng số đảng viên toàn Đảng tăng lên hơn 70.000 người."},{"id":162,"section":"ch2-1","q":"Trong hai năm 1948-1949, công tác xây dựng Đảng kết nạp thêm khoảng bao nhiêu đảng viên mới?","options":["Hơn 50.000 đảng viên mới","Hơn 20.000 đảng viên mới","Hơn 70.000 đảng viên mới","Hơn 5.000 đảng viên mới"],"answer":0,"explain":"Công tác xây dựng Đảng được đẩy mạnh, phát triển nhanh trong 2 năm 1948-1949, kết nạp được hơn 50.000 đảng viên mới."},{"id":163,"section":"ch2-1","q":"Chủ tịch Hồ Chí Minh ký ban hành Sắc lệnh về nghĩa vụ quân sự vào thời gian nào?","options":["Tháng 11/1949","Tháng 2/1950","Tháng 1/1948","Tháng 6/1948"],"answer":0,"explain":"Tháng 11/1949, Chủ tịch Hồ Chí Minh ký ban hành Sắc lệnh về nghĩa vụ quân sự."},{"id":164,"section":"ch2-1","q":"Đầu năm 1950, Chủ tịch Hồ Chí Minh đi thăm những nước nào để tranh thủ sự ủng hộ quốc tế?","options":["Trung Quốc và Liên Xô","Pháp và Vương quốc Anh","Hoa Kỳ và Nhật Bản","Thái Lan và Campuchia"],"answer":0,"explain":"Đầu năm 1950, Chủ tịch Hồ Chí Minh đi thăm Trung Quốc, Liên Xô để tranh thủ sự ủng hộ, giúp đỡ quốc tế cho cuộc kháng chiến."},{"id":165,"section":"ch2-1","q":"Nước nào công nhận và đặt quan hệ ngoại giao với Việt Nam Dân chủ Cộng hòa đầu tiên (18/1/1950)?","options":["Trung Quốc","Liên Xô","Triều Tiên","Tiệp Khắc"],"answer":0,"explain":"Ngày 18/1/1950, Chính phủ Trung Quốc công nhận và đặt quan hệ ngoại giao với Việt Nam Dân chủ Cộng hòa, sau đó Liên Xô (30/1/1950) và các nước dân chủ nhân dân Đông Âu."},{"id":166,"section":"ch2-1","q":"Tổ điệp báo A13 đã lập chiến công nổi tiếng nào vào tháng 9/1950?","options":["Đánh đắm Thông báo hạm Amyot D'Inville của Pháp","Đánh chiếm cứ điểm Đông Khê trên đường số 4 của Pháp","Giải phóng hoàn toàn thị xã Điện Biên Phủ khỏi quân Pháp","Phá vụ án phố Ôn Như Hầu ở Hà Nội của bọn Đại Việt"],"answer":0,"explain":"Chiến công của Tổ điệp báo A13, đánh đắm Thông báo hạm Amyot D'Inville của Pháp ngoài khơi vùng biển Sầm Sơn, Thanh Hóa (9/1950)."},{"id":167,"section":"ch2-1","q":"Cuối năm 1946, tổng số bộ đội chính quy của Việt Nam là bao nhiêu?","options":["Hơn 8 vạn người","Hơn 23 vạn người","Hơn 12 vạn người","Hơn 3 vạn người"],"answer":0,"explain":"Cuối năm 1946, Việt Nam có hơn 8 vạn bộ đội chính quy, lực lượng công an được tổ chức đến cấp huyện."},{"id":168,"section":"ch2-1","q":"Đến năm 1950, lực lượng bộ đội chủ lực, bộ đội địa phương, dân quân du kích phát triển tăng lên bao nhiêu người, trong đó bao nhiêu là dân quân tự vệ và du kích?","options":["23 vạn bộ đội; dân quân tự vệ và du kích lên đến 3 triệu người","10 vạn bộ đội; dân quân tự vệ và du kích lên đến 1 triệu người","50 vạn bộ đội; dân quân tự vệ và du kích lên đến 5 triệu người","5 vạn bộ đội; dân quân tự vệ và du kích lên đến 500 nghìn người"],"answer":0,"explain":"Lực lượng ba thứ quân phát triển nhanh chóng, số lượng bộ đội tăng lên 23 vạn người, trong đó có 40.000 đảng viên; dân quân tự vệ và du kích lên đến 3 triệu người."},{"id":169,"section":"ch2-1","q":"Chỉ thị \"Phải phá tan cuộc tấn công mùa đông của giặc Pháp\" được Thường vụ Trung ương Đảng ban hành vào ngày nào?","options":["Ngày 15/10/1947","Ngày 21/12/1947","Ngày 6/4/1947","Ngày 17/2/1947"],"answer":0,"explain":"Ngày 15/10/1947, Ban Thường vụ Trung ương Đảng ra Chỉ thị Phải phá tan cuộc tấn công mùa đông của giặc Pháp."},{"id":170,"section":"ch2-1","q":"Hội nghị cán bộ Trung ương (6/4/1947) đã bàn về vấn đề gì?","options":["Mở rộng Mặt trận dân tộc thống nhất, củng cố chính quyền, đẩy mạnh chiến tranh du kích","Thành lập nước Việt Nam Dân chủ Cộng hòa, ban hành Hiến pháp mới của Nhà nước","Ký Hiệp định Sơ bộ với Pháp, nhân nhượng để kéo dài thời gian hòa hoãn với Pháp","Chuẩn bị Đại hội II của Đảng, đổi tên Đảng và ra hoạt động công khai trong cả nước"],"answer":0,"explain":"Ngày 6/4/1947, Ban Chấp hành Trung ương Đảng triệu tập Hội nghị cán bộ Trung ương, nhấn mạnh mở rộng Mặt trận dân tộc thống nhất chống Pháp, đẩy mạnh chiến tranh du kích."},{"id":171,"section":"ch2-1","q":"Sau vụ Pháp gây hấn ngày 2/9/1945 ở Sài Gòn - Chợ Lớn, tinh thần chiến đấu của nhân dân Nam Bộ được thể hiện qua khẩu hiệu nào?","options":["\"Thà chết tự do còn hơn sống nô lệ\"","\"Người cày có ruộng, giảm tô giảm tức\"","\"Tất cả cho tiền tuyến, tất cả để thắng\"","\"Đoàn kết, đoàn kết, đại đoàn kết\""],"answer":0,"explain":"Nhân dân các tỉnh Nam Bộ nêu cao tinh thần \"Thà chết tự do còn hơn sống nô lệ\", nhất loạt đứng lên chống trả hành động xâm lược của thực dân Pháp."},{"id":172,"section":"ch2-1","q":"Đảng Cộng sản Đông Dương ra \"Thông cáo Đảng Cộng sản Đông Dương tự ý tự giải tán\" vào ngày nào, thực chất là gì?","options":["Ngày 11/11/1945, thực chất Đảng rút vào bí mật, để lại Hội nghiên cứu chủ nghĩa Mác ở Đông Dương","Ngày 11/11/1945, thực chất Đảng thật sự tan rã, giải thể hoàn toàn mọi tổ chức đảng trong cả nước","Ngày 2/9/1945, thực chất Đảng đổi tên thành Đảng Lao động Việt Nam và ra hoạt động công khai","Ngày 6/3/1946, thực chất Đảng sáp nhập vào Việt Minh, trở thành một bộ phận của Mặt trận"],"answer":0,"explain":"Ngày 11/11/1945, Đảng ra Thông cáo tự ý tự giải tán, thực chất là rút vào hoạt động bí mật, để lại một bộ phận hoạt động công khai với danh nghĩa \"Hội nghiên cứu chủ nghĩa Mác ở Đông Dương\"."},{"id":173,"section":"ch2-1","q":"Hiệp ước Hoa - Pháp (Hiệp ước Trùng Khánh) được ký kết vào ngày nào?","options":["Ngày 28/2/1946","Ngày 6/3/1946","Ngày 14/9/1946","Ngày 19/12/1946"],"answer":0,"explain":"Đầu năm 1946, Pháp và Trung Hoa dân quốc ký bản Hiệp ước Trùng Khánh (Hiệp ước Hoa-Pháp), ngày 28/2/1946, trong đó Pháp đưa quân ra Bắc thay Tưởng."},{"id":174,"section":"ch2-1","q":"Chủ tịch Hồ Chí Minh cùng phái đoàn Chính phủ Việt Nam thăm chính thức nước Pháp trong khoảng thời gian nào?","options":["Từ 31/5/1946, chuyến thăm kéo dài hơn 4 tháng","Từ 6/3/1946, chuyến thăm chỉ kéo dài khoảng 3 ngày","Từ 19/4/1946, chuyến thăm kéo dài khoảng 3 tuần","Từ 14/9/1946, chuyến thăm kéo dài đúng 6 ngày"],"answer":0,"explain":"Ngày 31/5/1946, Chủ tịch Hồ Chí Minh cùng phái đoàn Chính phủ Việt Nam thăm chính thức nước Cộng hòa Pháp, chuyến thăm kéo dài hơn 4 tháng."},{"id":175,"section":"ch2-1","q":"Cuối tháng 11/1946, thực dân Pháp mở cuộc tấn công vũ trang đánh chiếm những đâu?","options":["Hải Phòng, Lạng Sơn","Cao Bằng, Thái Nguyên","Sài Gòn, Chợ Lớn","Đà Nẵng, Quy Nhơn"],"answer":0,"explain":"Cuối tháng 11/1946, thực dân Pháp mở cuộc tấn công vũ trang đánh chiếm Hải Phòng, Lạng Sơn."},{"id":176,"section":"ch2-1","q":"Cuộc kháng chiến chống Pháp giành thắng lợi hoàn toàn với sự kiện nào?","options":["Chiến thắng Điện Biên Phủ (7/5/1954) và Hiệp định Giơnevơ (21/7/1954)","Chiến dịch Biên giới (1950) và Đại hội đại biểu lần II (1951)","Chiến dịch Việt Bắc (1947) và tác phẩm Kháng chiến nhất định thắng lợi","Toàn quốc kháng chiến (19/12/1946) và Hiệp định Sơ bộ (6/3/1946)"],"answer":0,"explain":"Cuộc kháng chiến chống thực dân Pháp kết thúc thắng lợi với chiến thắng lịch sử Điện Biên Phủ (7/5/1954) và việc ký kết Hiệp định Giơnevơ (21/7/1954)."},{"id":177,"section":"ch2-1","q":"Đường lối kháng chiến toàn diện của Đảng đánh địch trên những mặt trận nào?","options":["Quân sự, chính trị, kinh tế, văn hóa, tư tưởng, ngoại giao","Chỉ trên mặt trận quân sự, không đánh địch ở lĩnh vực khác","Chỉ về chính trị và ngoại giao, tránh xung đột quân sự","Chỉ về kinh tế và văn hóa, không đánh địch về quân sự"],"answer":0,"explain":"Kháng chiến toàn diện là đánh địch trên mọi lĩnh vực không chỉ bằng quân sự mà cả về chính trị, kinh tế, văn hóa, tư tưởng, ngoại giao."},{"id":178,"section":"ch2-1","q":"Tác phẩm \"Kháng chiến nhất định thắng lợi\" là của ai, xuất bản năm nào?","options":["Của Trường Chinh, xuất bản năm 1947","Của Hồ Chí Minh, xuất bản năm 1945","Của Võ Nguyên Giáp, xuất bản năm 1954","Của Lê Duẩn, xuất bản năm 1960"],"answer":0,"explain":"Tác phẩm Kháng chiến nhất định thắng lợi của đồng chí Tổng Bí thư Trường Chinh, xuất bản tháng 8/1947, là văn kiện quan trọng về đường lối kháng chiến."},{"id":179,"section":"ch2-1","q":"Trong kháng chiến chống Pháp, khẩu hiệu \"Vườn không, nhà trống\" nhằm mục đích gì?","options":["Tiêu thổ kháng chiến, cản bước tiến và hạn chế tiềm lực của địch","Kêu gọi nhân dân di dân sang nước khác để lánh nạn chiến tranh","Xây dựng thành phố hiện đại, quy hoạch lại nhà cửa của dân","Phát triển nông nghiệp tự cung tự cấp, khuyến khích dân trồng trọt"],"answer":0,"explain":"Nhân dân thực hiện tiêu thổ kháng chiến với khẩu hiệu \"Vườn không, nhà trống\", \"Phá hoại để kháng chiến\" nhằm ngăn cản bước tiến, hạn chế tiềm năng kinh tế của địch."},{"id":180,"section":"ch2-1","q":"Từ 1945 đến 1947, đường lối kháng chiến chống Pháp của Đảng được hình thành, bổ sung qua các văn kiện quan trọng nào?","options":["Chỉ thị Kháng chiến kiến quốc, Toàn dân kháng chiến, Lời kêu gọi toàn quốc kháng chiến, Kháng chiến nhất định thắng lợi","Cương lĩnh chính trị đầu tiên, Chính cương vắn tắt, Sách lược vắn tắt, Chương trình tóm tắt của Đảng Cộng sản Việt Nam (1930)","Luận cương chính trị 10/1930, Nghị quyết Hội nghị Trung ương 8 (1941), Đề cương về văn hóa Việt Nam (1943), Chỉ thị Nhật - Pháp bắn nhau (1945)","Nghị quyết Đại hội II, Chính cương Đảng Lao động Việt Nam, Báo cáo Bàn về cách mạng Việt Nam (1951), Điều lệ Đảng Lao động Việt Nam"],"answer":0,"explain":"Đường lối kháng chiến được hình thành, bổ sung qua các văn kiện: Chỉ thị Kháng chiến kiến quốc (25/11/1945), Chỉ thị Toàn dân kháng chiến (12/12/1946), Lời kêu gọi toàn quốc kháng chiến (19/12/1946), tác phẩm Kháng chiến nhất định thắng lợi (8/1947)."},{"id":181,"section":"ch2-1","q":"Đến năm 1945, tỷ lệ dân số Việt Nam bị mù chữ, thất học là bao nhiêu?","options":["95% dân số thất học, mù chữ","50% dân số thất học, mù chữ","20% dân số thất học, mù chữ","10% dân số thất học, mù chữ"],"answer":0,"explain":"Hậu quả chế độ cũ để lại rất nặng nề: 95% dân số thất học, mù chữ."},{"id":182,"section":"ch2-1","q":"Đến cuối năm 1946, cả nước có hơn bao nhiêu người dân biết đọc, biết viết chữ quốc ngữ nhờ phong trào \"Bình dân học vụ\"?","options":["Hơn 2,5 triệu người","Hơn 500 nghìn người","Hơn 5 triệu người","Hơn 1 triệu người"],"answer":0,"explain":"Nhờ phong trào Bình dân học vụ, đến cuối năm 1946, cả nước đã có hơn 2,5 triệu người dân biết đọc, biết viết chữ quốc ngữ."},{"id":183,"section":"ch2-1","q":"Cuộc bầu cử Quốc hội khóa I (6/1/1946) bầu ra bao nhiêu đại biểu Quốc hội?","options":["333 đại biểu","400 đại biểu","250 đại biểu","500 đại biểu"],"answer":0,"explain":"Bầu cử thành công đã bầu ra 333 đại biểu Quốc hội đầu tiên của Nhà nước Việt Nam Dân chủ Cộng hòa."},{"id":184,"section":"ch2-1","q":"Ai được bầu làm Trưởng ban soạn thảo Hiến pháp năm 1946?","options":["Hồ Chí Minh","Trường Chinh","Tôn Đức Thắng","Nguyễn Văn Tố"],"answer":0,"explain":"Ban soạn thảo bản Hiến pháp mới được thành lập do Hồ Chí Minh làm Trưởng ban."},{"id":185,"section":"ch2-1","q":"Hội Liên hiệp quốc dân Việt Nam (Liên Việt) được thành lập nhằm mục đích gì, do ai làm Hội trưởng?","options":["Mở rộng Mặt trận dân tộc thống nhất, do Huỳnh Thúc Kháng làm Hội trưởng","Thống nhất các lực lượng vũ trang, do Võ Nguyên Giáp làm Hội trưởng","Chuẩn bị đàm phán với Pháp ở Đà Lạt, do Phạm Văn Đồng làm Hội trưởng","Xây dựng nền kinh tế mới thời bình, do Tôn Đức Thắng làm Hội trưởng"],"answer":0,"explain":"Mặt trận dân tộc thống nhất tiếp tục được mở rộng: Hội Liên hiệp quốc dân Việt Nam (Liên Việt) được thành lập do Huỳnh Thúc Kháng làm Hội trưởng, Tôn Đức Thắng làm Hội phó."},{"id":186,"section":"ch2-1","q":"Hội nghị nào (18-19/12/1946) đã quyết định phát động toàn quốc kháng chiến, nối tiếp Chỉ thị Toàn dân kháng chiến (12/12/1946)?","options":["Hội nghị mở rộng của Ban Thường vụ Trung ương Đảng tại làng Vạn Phúc (Hà Đông)","Hội nghị Trung ương lần thứ 8 do Chủ tịch Hồ Chí Minh chủ trì tại Pác Bó (Cao Bằng)","Đại hội đại biểu toàn quốc lần thứ II của Đảng do Tổng Bí thư Trường Chinh chủ trì","Phiên họp của Chính phủ lâm thời ngay sau cuộc Tổng tuyển cử bầu Quốc hội khóa I"],"answer":0,"explain":"Ngày 18/12/1946, Hội nghị Ban Thường vụ Trung ương Đảng (mở rộng) họp tại làng Vạn Phúc, Hà Đông, quyết định phát động toàn quốc kháng chiến."},{"id":187,"section":"ch2-1","q":"Trong những năm đầu kháng chiến, chính sách đối ngoại của Đảng với Tưởng và Pháp lần lượt là gì?","options":["Hòa với Tưởng để đánh Pháp ở Nam Bộ, sau đó hòa với Pháp để đuổi Tưởng","Đánh cả Tưởng và Pháp cùng lúc, kiên quyết không nhân nhượng ai","Chỉ tập trung đánh Tưởng ở miền Bắc, tạm thời bỏ qua Pháp ở Nam Bộ","Nhờ Mỹ giúp đỡ chống cả hai, sau đó liên minh quân sự với Mỹ"],"answer":0,"explain":"Đảng thực hiện sách lược mềm dẻo: trước tiên hòa hoãn với quân Tưởng ở miền Bắc để tập trung đánh Pháp ở Nam Bộ, sau đó hòa với Pháp (Hiệp định Sơ bộ) để đẩy nhanh quân Tưởng rút về nước."},{"id":188,"section":"ch2-1","q":"Từ năm 1948, tình hình quốc tế có chuyển biến có lợi cho kháng chiến Việt Nam, đặc biệt sau sự kiện nào?","options":["Nước Cộng hòa Nhân dân Trung Hoa ra đời (1/10/1949)","Chiến tranh thế giới thứ hai kết thúc (2/9/1945)","Hội nghị quốc tế Giơnevơ về Đông Dương (1954)","Cách mạng Tháng Mười Nga thành công (7/11/1917)"],"answer":0,"explain":"Từ năm 1948, tình hình quốc tế có những chuyển biến có lợi, đặc biệt ngày 1/10/1949, nước Cộng hòa Nhân dân Trung Hoa ra đời."},{"id":189,"section":"ch2-1","q":"Chiến dịch Điện Biên Phủ được xem là chiến thắng đưa đến kết quả ngoại giao gì?","options":["Ký Hiệp định Giơnevơ chấm dứt chiến tranh, lập lại hòa bình ở Đông Dương","Ký Hiệp định Paris chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam","Việt Nam được kết nạp vào Liên hợp quốc, trở thành thành viên chính thức","Thành lập nước Cộng hòa xã hội chủ nghĩa Việt Nam, thống nhất hai miền"],"answer":0,"explain":"Chiến thắng Điện Biên Phủ (7/5/1954) là cơ sở quyết định để ký kết Hiệp định Giơnevơ về chấm dứt chiến tranh, lập lại hòa bình ở Đông Dương (21/7/1954)."},{"id":190,"section":"ch2-1","q":"Theo Hiệp định Giơnevơ, Việt Nam bị chia cắt tạm thời ở vĩ tuyến nào?","options":["Vĩ tuyến 17","Vĩ tuyến 16","Vĩ tuyến 20","Vĩ tuyến 13"],"answer":0,"explain":"Theo Hiệp định Giơnevơ, Việt Nam tạm thời bị chia cắt thành hai miền ở vĩ tuyến 17 (sông Bến Hải), chờ tổng tuyển cử thống nhất đất nước."},{"id":191,"section":"ch2-1","q":"Trong kháng chiến chống Pháp, phong trào \"Tuần lễ vàng\" và quỹ \"Độc lập\" nhằm mục đích gì?","options":["Huy động tài chính, vàng bạc ủng hộ chính quyền cách mạng non trẻ","Xây dựng hệ thống trường học mới cho nhân dân ở các vùng nông thôn","Tổ chức cuộc bầu cử Quốc hội đầu tiên của nước Việt Nam mới","Tuyên truyền, vận động nhân dân tham gia chống giặc dốt, xóa mù chữ"],"answer":0,"explain":"Chính phủ và Chủ tịch Hồ Chí Minh phát động phong trào Tuần lễ vàng, quỹ Độc lập, quỹ Đảm phụ quốc phòng nhằm huy động tài chính ủng hộ chính quyền cách mạng non trẻ."},{"id":192,"section":"ch2-1","q":"Cuộc kháng chiến chống thực dân Pháp của nhân dân Việt Nam kéo dài trong bao nhiêu năm (1945/1946-1954)?","options":["Khoảng 9 năm","Khoảng 5 năm","Khoảng 15 năm","Khoảng 20 năm"],"answer":0,"explain":"Cuộc kháng chiến chống thực dân Pháp kéo dài từ toàn quốc kháng chiến (19/12/1946) đến chiến thắng Điện Biên Phủ (7/5/1954), khoảng 9 năm."},{"id":193,"section":"ch2-1","q":"Chính sách giảm tô được Chính phủ Việt Nam Dân chủ Cộng hòa thực hiện với mức giảm bao nhiêu?","options":["Giảm tô 25%","Giảm tô 50%","Giảm tô 10%","Giảm tô 75%"],"answer":0,"explain":"Chính phủ thực hiện chính sách giảm tô 25% cho nông dân, góp phần ổn định đời sống nhân dân trong những năm đầu kháng chiến."},{"id":194,"section":"ch2-1","q":"Trường Đại học Văn khoa Hà Nội được thành lập trong bối cảnh nào?","options":["Trong công cuộc diệt giặc dốt, xây dựng nền giáo dục mới sau Cách mạng","Sau chiến thắng Điện Biên Phủ, khi đất nước bước vào khôi phục kinh tế","Trong thời kỳ Đổi mới, khi Đảng chủ trương mở cửa hội nhập (sau 1986)","Sau khi ký Hiệp định Paris 1973, khi miền Bắc khôi phục kinh tế"],"answer":0,"explain":"Trong công cuộc diệt giặc dốt và xây dựng đời sống văn hóa mới, Trường Đại học Văn khoa Hà Nội được thành lập cùng việc mở lại các trường học từ tiểu học trở lên."},{"id":195,"section":"ch2-1","q":"Việt Nam thiết lập quan hệ ngoại giao với những nước dân chủ nhân dân Đông Âu và Triều Tiên vào thời gian nào?","options":["Đầu năm 1950","Năm 1945","Năm 1954","Năm 1930"],"answer":0,"explain":"Đầu năm 1950, sau khi Trung Quốc và Liên Xô công nhận, các nước dân chủ nhân dân Đông Âu và Triều Tiên (2/1950) cũng lần lượt công nhận và đặt quan hệ ngoại giao với Việt Nam Dân chủ Cộng hòa."},{"id":196,"section":"ch2-1","q":"Trong giai đoạn 1945-1946, Đảng chủ trương xử lý quan hệ với các đảng phái đối lập (Việt Quốc, Việt Cách) như thế nào trong Quốc hội và Chính phủ?","options":["Nhân nhượng, bổ sung ghế Quốc hội và ghế bộ trưởng cho họ để mở rộng đoàn kết","Kiên quyết loại bỏ hoàn toàn họ khỏi chính quyền để bảo vệ thành quả cách mạng","Dùng vũ lực trấn áp ngay lập tức, giải tán toàn bộ tổ chức đảng phái của họ","Không nhân nhượng, từ chối mọi yêu cầu của họ về ghế trong Quốc hội"],"answer":0,"explain":"Sau bầu cử, Hồ Chí Minh đồng ý mở rộng thành phần đại biểu Quốc hội (thêm 70 ghế không qua bầu cử) và cải tổ Chính phủ liên hiệp với sự tham gia của một số nhân sĩ, kể cả một số ghế bộ trưởng cho Việt Quốc, Việt Cách."},{"id":197,"section":"ch2-1","q":"Từ cuối 1946, Trung ương Đảng, Chính phủ, Quốc hội đã tổ chức việc gì để chuẩn bị kháng chiến lâu dài?","options":["Di chuyển cơ quan lãnh đạo ra khỏi thành phố, xây dựng chiến khu, ATK","Chuyển toàn bộ cơ quan lãnh đạo sang Trung Quốc để lánh nạn lâu dài","Giải thể bộ máy nhà nước Trung ương, trao toàn quyền cho địa phương","Ký hòa ước đầu hàng thực dân Pháp, giữ nguyên các cơ quan ở Hà Nội"],"answer":0,"explain":"Trung ương khẩn trương tiến hành cuộc tổng di chuyển các cơ quan lãnh đạo của Đảng, Chính phủ, Quốc hội... ra khỏi thành phố, thị xã; củng cố, xây dựng các chiến khu, ATK (an toàn khu)."},{"id":198,"section":"ch2-1","q":"Đến năm 1954, lực lượng công an nhân dân Việt Nam đã lập được chiến công nổi bật nào?","options":["Tổ điệp báo A13 đánh đắm Thông báo hạm Amyot D'Inville của Pháp","Bắt sống tướng Đờ Cát và toàn bộ Bộ chỉ huy tại Điện Biên Phủ","Bảo vệ an toàn Hội nghị thành lập Đảng tại Hương Cảng năm 1930","Giải phóng Sài Gòn, bắt sống toàn bộ chính quyền Sài Gòn năm 1975"],"answer":0,"explain":"Công an nhân dân đã lập nên nhiều chiến công lớn có tiếng vang cả nước, điển hình là chiến công của Tổ điệp báo A13, đánh đắm Thông báo hạm Amyot D'Inville của Pháp (9/1950)."},{"id":199,"section":"ch2-1","q":"Đại tướng Võ Nguyên Giáp là tác giả cuốn hồi ký nào viết về giai đoạn 1945-1946?","options":["Chiến đấu trong vòng vây","Đường tới Điện Biên Phủ","Điện Biên Phủ - điểm hẹn lịch sử","Chiến thắng mùa xuân năm 1975"],"answer":0,"explain":"Tác phẩm Chiến đấu trong vòng vây của Đại tướng Võ Nguyên Giáp phản ánh bối cảnh khó khăn sau Cách mạng Tháng Tám."},{"id":200,"section":"ch2-1","q":"Nội dung cơ bản của đường lối kháng chiến chống thực dân Pháp được đúc kết là gì?","options":["Kháng chiến toàn dân, toàn diện, lâu dài, dựa vào sức mình là chính","Chủ yếu dựa vào viện trợ và sự giúp đỡ của các nước xã hội chủ nghĩa","Chủ yếu là đấu tranh ngoại giao, hạn chế đấu tranh vũ trang quy mô lớn","Kết hợp đấu tranh nghị trường với đấu tranh kinh tế, không dùng vũ trang"],"answer":0,"explain":"Nội dung cơ bản của đường lối là: dựa trên sức mạnh toàn dân, tiến hành kháng chiến toàn dân, toàn diện, lâu dài và dựa vào sức mình là chính."},{"id":619,"section":"ch2-1","q":"Ngay sau Cách mạng Tháng Tám, nước Việt Nam Dân chủ Cộng hòa non trẻ phải đối mặt với tình thế \"ngàn cân treo sợi tóc\" do những khó khăn nào?","options":["Giặc ngoại xâm, giặc đói, giặc dốt cùng lúc đe dọa, ngân khố trống rỗng","Chỉ gặp khó khăn về ngân sách tài chính, các mặt khác đều thuận lợi","Chỉ có nguy cơ từ quân đội Tưởng Giới Thạch ở miền Bắc, còn lại ổn định","Chỉ có nguy cơ nạn đói do thiên tai gây ra, chính quyền đã vững vàng"],"answer":0,"explain":"Chính quyền cách mạng non trẻ đứng trước tình thế \"ngàn cân treo sợi tóc\" với thù trong giặc ngoài, nạn đói, nạn dốt hoành hành, ngân khố quốc gia gần như trống rỗng, chính quyền cách mạng chưa được củng cố."},{"id":620,"section":"ch2-1","q":"Chủ tịch Hồ Chí Minh phát động phong trào \"Tuần lễ vàng\", \"hũ gạo cứu đói\" nhằm mục đích gì?","options":["Huy động sức dân giải quyết nạn đói và khó khăn tài chính của chính quyền","Chuẩn bị vật chất cho cuộc kháng chiến chống Mỹ cứu nước sau năm 1965","Xây dựng quỹ dự trữ ngoại tệ để nhập khẩu máy móc từ nước ngoài","Xây dựng cơ sở vật chất cho công nghiệp hóa, hiện đại hóa đất nước"],"answer":0,"explain":"Phong trào \"Tuần lễ vàng\", \"hũ gạo cứu đói\", \"tăng gia sản xuất\" do Chủ tịch Hồ Chí Minh phát động nhằm huy động sức mạnh của toàn dân giải quyết nạn đói, góp phần giải quyết khó khăn về tài chính cho chính quyền cách mạng non trẻ."},{"id":621,"section":"ch2-1","q":"Để đối phó với quân Tưởng Giới Thạch và tay sai ở miền Bắc (1945-1946), Đảng và Chủ tịch Hồ Chí Minh chủ trương sách lược gì?","options":["Hòa hoãn, nhân nhượng có nguyên tắc, tránh cùng lúc đối phó với nhiều kẻ thù","Kiên quyết dùng vũ lực, đánh đuổi ngay quân Tưởng và tay sai ra khỏi miền Bắc","Nhượng bộ hoàn toàn mọi yêu sách của quân Tưởng và tay sai để giữ hòa bình","Liên minh quân sự chặt chẽ với thực dân Pháp để cùng chống lại quân Tưởng"],"answer":0,"explain":"Trước tình thế cùng lúc phải đối phó nhiều kẻ thù, Đảng và Chủ tịch Hồ Chí Minh chủ trương sách lược hòa hoãn, nhân nhượng có nguyên tắc với quân Tưởng ở miền Bắc để tập trung lực lượng kháng chiến chống thực dân Pháp ở Nam Bộ."},{"id":622,"section":"ch2-1","q":"Hiệp định Sơ bộ (6/3/1946) được ký kết giữa Chính phủ Việt Nam Dân chủ Cộng hòa với Pháp nhằm mục đích trước mắt nào?","options":["Đẩy nhanh quân Tưởng về nước, tránh đối phó cùng lúc nhiều kẻ thù, tranh thủ thời gian hòa hoãn","Chính thức công nhận nền độc lập hoàn toàn của Việt Nam và buộc Pháp rút hết quân khỏi Đông Dương","Chấm dứt hoàn toàn quan hệ ngoại giao với Pháp và chuẩn bị tổng tiến công ngay","Nhượng toàn bộ Nam Bộ cho thực dân Pháp quản lý để đổi lấy sự công nhận quốc tế"],"answer":0,"explain":"Việc ký Hiệp định Sơ bộ (6/3/1946), tạm hòa với Pháp, nhằm mục đích trước mắt là đẩy nhanh quân Tưởng về nước, tránh đối phó cùng lúc nhiều kẻ thù, tranh thủ thời gian hòa hoãn để củng cố lực lượng, chuẩn bị cho cuộc kháng chiến lâu dài."},{"id":623,"section":"ch2-1","q":"Tạm ước 14/9/1946 do Chủ tịch Hồ Chí Minh ký với Pháp có ý nghĩa gì?","options":["Kéo dài thời gian hòa hoãn, tranh thủ thêm thời gian hòa bình để chuẩn bị lực lượng kháng chiến","Chấm dứt hoàn toàn nguy cơ chiến tranh với Pháp, mở ra thời kỳ hòa bình lâu dài","Chính thức trao trả độc lập hoàn toàn cho Việt Nam, buộc Pháp rút quân khỏi Nam Bộ ngay lập tức","Khẳng định Việt Nam gia nhập Liên hiệp Pháp với tư cách quốc gia tự do hoàn toàn"],"answer":0,"explain":"Tạm ước 14/9/1946 tiếp tục là một bước nhân nhượng nhằm kéo dài thời gian hòa bình, tranh thủ thêm thời gian hòa hoãn quý báu để củng cố chính quyền, chuẩn bị lực lượng cho cuộc kháng chiến toàn quốc không thể tránh khỏi."},{"id":624,"section":"ch2-1","q":"Ý nghĩa của cuộc Tổng tuyển cử ngày 6/1/1946 đối với chính quyền cách mạng là gì?","options":["Hợp thức hóa pháp lý nhà nước Việt Nam Dân chủ Cộng hòa, khẳng định quyền làm chủ của nhân dân","Chỉ nhằm mục đích tuyên truyền đối ngoại, chưa có giá trị pháp lý đối với chính quyền cách mạng","Là bước chuẩn bị cho việc trao trả chính quyền lại cho Pháp theo thỏa thuận quốc tế","Chỉ có ý nghĩa với riêng khu vực Bắc Bộ, không tác động đến phạm vi cả nước"],"answer":0,"explain":"Cuộc Tổng tuyển cử bầu Quốc hội đầu tiên (6/1/1946) có ý nghĩa to lớn, hợp thức hóa về mặt pháp lý nhà nước Việt Nam Dân chủ Cộng hòa, khẳng định quyền làm chủ đất nước của nhân dân, đập tan âm mưu chia rẽ, lật đổ của các thế lực phản động."},{"id":625,"section":"ch2-1","q":"Bên cạnh Sắc lệnh về Tổng tuyển cử, ngay trong những tháng đầu sau Cách mạng Tháng Tám, Chính phủ lâm thời đã ban hành sắc lệnh nào liên quan tới quyền tự do tín ngưỡng, tôn giáo của nhân dân?","options":["Sắc lệnh bảo đảm quyền tự do tín ngưỡng và thờ cúng của nhân dân","Sắc lệnh quốc hữu hóa toàn bộ tài sản của các tổ chức tôn giáo","Sắc lệnh cấm mọi hoạt động tôn giáo trên phạm vi cả nước","Sắc lệnh sáp nhập các tổ chức tôn giáo vào bộ máy nhà nước"],"answer":0,"explain":"Chính phủ lâm thời đã sớm ban hành các sắc lệnh bảo đảm quyền tự do tín ngưỡng, thờ cúng của nhân dân, thể hiện chính sách đại đoàn kết toàn dân tộc không phân biệt tôn giáo của chính quyền cách mạng ngay từ những ngày đầu."},{"id":626,"section":"ch2-1","q":"Chủ trương \"diệt giặc dốt\" của Chính phủ được thực hiện thông qua việc thành lập cơ quan nào?","options":["Nha Bình dân học vụ","Viện Đại học Đông Dương","Viện Hàn lâm Khoa học","Trường Đại học Quốc gia"],"answer":0,"explain":"Nha Bình dân học vụ được thành lập (9/1945) nhằm tổ chức phong trào xóa nạn mù chữ rộng khắp trong cả nước, thực hiện chủ trương \"diệt giặc dốt\" của Chủ tịch Hồ Chí Minh."},{"id":627,"section":"ch2-1","q":"Chỉ thị \"Kháng chiến kiến quốc\" (25/11/1945) xác định nhiệm vụ chiến lược của cách mạng Việt Nam lúc này là gì?","options":["Củng cố chính quyền, chống thực dân Pháp xâm lược, bài trừ nội phản, cải thiện đời sống nhân dân","Ưu tiên tuyệt đối cho cách mạng ruộng đất triệt để, xóa bỏ ngay chế độ sở hữu của địa chủ","Tập trung toàn lực xây dựng chủ nghĩa xã hội ngay lập tức, quốc hữu hóa toàn bộ nền kinh tế quốc gia","Ưu tiên đàm phán, nhượng bộ hoàn toàn với thực dân Pháp để đổi lấy hòa bình lâu dài"],"answer":0,"explain":"Chỉ thị \"Kháng chiến kiến quốc\" (25/11/1945) xác định khẩu hiệu chung là \"Dân tộc trên hết, Tổ quốc trên hết\", nhiệm vụ chủ yếu là củng cố chính quyền, chống thực dân Pháp xâm lược, bài trừ nội phản, cải thiện đời sống nhân dân."},{"id":628,"section":"ch2-1","q":"Trong Quốc hội khóa I (1946), chính quyền cách mạng đã nhân nhượng dành một số ghế không qua bầu cử cho các đảng phái nào để tăng cường đoàn kết dân tộc, tránh xung đột?","options":["Việt Nam Quốc dân Đảng (Việt Quốc) và Việt Nam Cách mạng Đồng minh Hội (Việt Cách)","Đảng Dân chủ Việt Nam và Đảng Xã hội Việt Nam cùng các đảng phái trung lập khác","Đảng Cộng sản Đông Dương và Mặt trận Việt Minh cùng các đoàn thể cứu quốc","Các đảng phái thân Nhật còn sót lại sau Cách mạng Tháng Tám và tay sai Pháp"],"answer":0,"explain":"Để tăng cường khối đoàn kết dân tộc, tránh xung đột trong bối cảnh phức tạp, ta đã nhân nhượng dành 70 ghế không qua bầu cử trong Quốc hội khóa I cho Việt Nam Quốc dân Đảng (Việt Quốc) và Việt Nam Cách mạng Đồng minh Hội (Việt Cách)."},{"id":629,"section":"ch2-1","q":"Sự kiện thực dân Pháp nổ súng đánh chiếm Sài Gòn, mở đầu cuộc chiến tranh xâm lược trở lại Việt Nam diễn ra vào thời gian nào?","options":["Đêm 22 rạng sáng 23/9/1945","Đêm 19 rạng sáng 20/12/1946","Rạng sáng ngày 6/3/1946","Rạng sáng ngày 20/11/1946"],"answer":0,"explain":"Đêm 22 rạng sáng ngày 23/9/1945, được sự giúp đỡ của quân Anh, thực dân Pháp nổ súng đánh chiếm Sài Gòn, mở đầu cuộc chiến tranh xâm lược Việt Nam lần thứ hai."},{"id":630,"section":"ch2-1","q":"Đảng Cộng sản Đông Dương tuyên bố \"tự giải tán\" (11/1945) trên thực tế nhằm mục đích gì?","options":["Rút vào hoạt động bí mật để tránh sự công kích, chống phá của kẻ thù, tiếp tục lãnh đạo cách mạng","Chấm dứt vĩnh viễn vai trò lãnh đạo cách mạng của những người cộng sản ở Đông Dương","Nhường quyền lãnh đạo cách mạng cho Quốc dân Đảng và các đảng phái khác để tránh xung đột","Giải tán toàn bộ hệ thống tổ chức cơ sở đảng trên cả nước, xóa bỏ mọi liên hệ với đảng viên các cấp"],"answer":0,"explain":"Việc tuyên bố \"tự giải tán\" (thực chất là rút vào hoạt động bí mật, chỉ để lại một bộ phận hoạt động công khai dưới danh nghĩa Hội nghiên cứu chủ nghĩa Mác ở Đông Dương) là một sách lược khôn khéo nhằm tránh mũi nhọn chống phá của kẻ thù, bảo tồn lực lượng để tiếp tục lãnh đạo cách mạng."},{"id":631,"section":"ch2-1","q":"Trong thời kỳ 1945-1946, Chính phủ đã ban hành sắc lệnh nào để từng bước xóa bỏ những tàn tích bất công về ruộng đất?","options":["Sắc lệnh giảm tô 25%, tạm cấp ruộng đất công và ruộng đất vắng chủ cho nông dân nghèo","Sắc lệnh quốc hữu hóa toàn bộ ruộng đất trên cả nước, xóa bỏ mọi hình thức tư hữu","Sắc lệnh trả lại toàn bộ ruộng đất cho địa chủ phong kiến, bãi bỏ chính sách giảm tô","Sắc lệnh tịch thu ruộng đất của nông dân để lập nông trường tập thể trên cả nước"],"answer":0,"explain":"Chính phủ đã ban hành các sắc lệnh giảm tô 25%, tạm cấp ruộng đất công, ruộng đất vắng chủ cho nông dân nghèo, bước đầu đem lại quyền lợi thiết thực, củng cố khối liên minh công nông và niềm tin của nhân dân vào chính quyền cách mạng."},{"id":632,"section":"ch2-1","q":"Bài học kinh nghiệm rút ra từ việc xử lý mối quan hệ với các thế lực ngoại xâm trong giai đoạn 1945-1946 là gì?","options":["Phải phân biệt kẻ thù chính, lợi dụng mâu thuẫn trong hàng ngũ địch, sách lược mềm dẻo, linh hoạt","Phải kiên quyết đối đầu cùng lúc với mọi thế lực thù địch, không nhân nhượng bất kỳ ai","Phải dựa hoàn toàn vào sự giúp đỡ, chỉ đạo từ bên ngoài để bảo vệ chính quyền cách mạng non trẻ","Không cần sách lược ngoại giao linh hoạt, chỉ cần dựa vào sức mạnh quân sự để đối phó"],"answer":0,"explain":"Một bài học lớn của giai đoạn 1945-1946 là nghệ thuật phân biệt kẻ thù chính - phụ trong từng thời điểm, biết lợi dụng mâu thuẫn trong hàng ngũ kẻ thù, thực hiện sách lược mềm dẻo, linh hoạt theo tinh thần \"dĩ bất biến, ứng vạn biến\" của Chủ tịch Hồ Chí Minh để bảo vệ thành quả cách mạng."},{"id":633,"section":"ch2-1","q":"Lời kêu gọi toàn quốc kháng chiến của Chủ tịch Hồ Chí Minh (12/1946) khẳng định tinh thần, ý chí gì của dân tộc Việt Nam?","options":["Thà hy sinh tất cả chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ","Sẵn sàng nhượng bộ mọi yêu sách của Pháp để duy trì hòa bình, tránh đổ máu","Chỉ kêu gọi đấu tranh ngoại giao, không phát động kháng chiến vũ trang toàn dân trên cả nước","Kêu gọi nhân dân sơ tán về vùng tự do, không tham gia kháng chiến chống Pháp"],"answer":0,"explain":"Lời kêu gọi toàn quốc kháng chiến khẳng định ý chí sắt đá của dân tộc: \"Chúng ta thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ\", kêu gọi toàn dân đứng lên kháng chiến bằng mọi vũ khí có trong tay."},{"id":634,"section":"ch2-1","q":"Tác phẩm \"Kháng chiến nhất định thắng lợi\" (1947) của Trường Chinh phân tích so sánh tương quan lực lượng giữa ta và địch theo nguyên lý nào?","options":["Ta có chính nghĩa, được nhân dân ủng hộ, đánh lâu dài sẽ chuyển hóa tương quan lực lượng có lợi cho ta","Ta có ưu thế tuyệt đối về vũ khí, trang bị ngay từ đầu nên giành thắng lợi nhanh chóng","Địch yếu hơn ta về mọi mặt ngay từ khi bắt đầu nên ta có thể đánh nhanh, thắng nhanh","Tương quan lực lượng không thay đổi theo thời gian nên ta phải dựa hoàn toàn vào viện trợ từ bên ngoài"],"answer":0,"explain":"Tác phẩm phân tích: tuy địch mạnh hơn về vũ khí, trang bị ban đầu, nhưng ta có chính nghĩa, được toàn dân ủng hộ; qua quá trình kháng chiến lâu dài, tự lực cánh sinh, tương quan lực lượng sẽ dần chuyển hóa có lợi cho ta, dẫn tới thắng lợi cuối cùng."},{"id":635,"section":"ch2-1","q":"Chiến thắng Việt Bắc Thu - Đông năm 1947 có ý nghĩa như thế nào đối với cuộc kháng chiến?","options":["Làm phá sản chiến lược \"đánh nhanh, thắng nhanh\" của Pháp, bảo vệ vững chắc căn cứ địa kháng chiến","Buộc thực dân Pháp phải rút hoàn toàn quân khỏi Đông Dương, kết thúc chiến tranh ngay sau thất bại này","Kết thúc thắng lợi hoàn toàn cuộc kháng chiến chống Pháp, giải phóng toàn bộ miền Bắc và miền Trung","Mở đầu cho việc Pháp phải ký ngay Hiệp định Giơnevơ, chấm dứt chiến tranh ở Đông Dương trong năm đó"],"answer":0,"explain":"Chiến thắng Việt Bắc Thu - Đông 1947 đã đánh bại âm mưu \"đánh nhanh, thắng nhanh\" của thực dân Pháp, buộc chúng phải chuyển sang đánh lâu dài, bảo vệ vững chắc cơ quan đầu não và căn cứ địa kháng chiến."},{"id":636,"section":"ch2-1","q":"Đại hội đại biểu toàn quốc lần thứ II của Đảng (2/1951) có quyết định quan trọng nào?","options":["Đưa Đảng ra hoạt động công khai, lấy tên Đảng Lao động Việt Nam, thông qua Chính cương và Điều lệ","Quyết định đổi tên nước thành Cộng hòa xã hội chủ nghĩa Việt Nam, ban hành Hiến pháp mới cho cả nước","Quyết định giải thể Mặt trận Việt Minh, chuyển sang đấu tranh nghị trường hợp pháp","Quyết định phát động Tổng khởi nghĩa giành chính quyền toàn quốc, lập chính phủ mới"],"answer":0,"explain":"Đại hội đại biểu toàn quốc lần thứ II (2/1951) họp tại Chiêm Hóa (Tuyên Quang) quyết định đưa Đảng ra hoạt động công khai với tên gọi Đảng Lao động Việt Nam, thông qua Chính cương của Đảng, phân tích tính chất xã hội và xác định nhiệm vụ cách mạng."},{"id":637,"section":"ch2-1","q":"Chiến dịch Biên giới Thu - Đông năm 1950 có ý nghĩa như thế nào?","options":["Ta giành quyền chủ động chiến lược ở chiến trường chính Bắc Bộ, khai thông biên giới Việt - Trung","Là chiến dịch phòng ngự đầu tiên và duy nhất của quân ta trong kháng chiến chống Pháp","Kết thúc hoàn toàn cuộc kháng chiến chống thực dân Pháp, buộc Pháp rút quân khỏi miền Bắc Việt Nam","Buộc Pháp phải ký ngay Hiệp định đình chiến với Việt Nam, công nhận độc lập hoàn toàn"],"answer":0,"explain":"Chiến thắng Biên giới Thu - Đông 1950 giúp quân ta giành quyền chủ động chiến lược trên chiến trường chính Bắc Bộ, khai thông biên giới Việt - Trung, phá vỡ thế bao vây, cô lập của địch đối với căn cứ địa Việt Bắc."},{"id":638,"section":"ch2-1","q":"Từ năm 1950, các nước nào đã chính thức thiết lập quan hệ ngoại giao, công nhận nước Việt Nam Dân chủ Cộng hòa?","options":["Trung Quốc, Liên Xô và các nước dân chủ nhân dân khác","Mỹ, Anh và các nước phương Tây thuộc khối Đồng minh","Chỉ có Liên Xô công nhận, các nước còn lại chưa công nhận","Các nước thuộc khối Liên hiệp Pháp và các thuộc địa ở châu Phi"],"answer":0,"explain":"Đầu năm 1950, Trung Quốc, Liên Xô và lần lượt các nước xã hội chủ nghĩa khác chính thức công nhận, đặt quan hệ ngoại giao với nước Việt Nam Dân chủ Cộng hòa, phá vỡ thế bị bao vây, cô lập về ngoại giao."},{"id":639,"section":"ch2-1","q":"Trong những năm đầu toàn quốc kháng chiến, phương châm tác chiến của lực lượng vũ trang ta là gì?","options":["Đánh lâu dài, vừa kháng chiến vừa kiến quốc, kết hợp chiến tranh du kích với chiến tranh chính quy","Chỉ tiến hành chiến tranh du kích quy mô nhỏ, không xây dựng bộ đội chủ lực chính quy hiện đại","Chỉ tập trung phòng ngự cố định tại các đô thị lớn, không đánh du kích ở nông thôn","Đánh nhanh, thắng nhanh trong thời gian ngắn, tập trung quyết chiến chiến lược ngay từ đầu"],"answer":0,"explain":"Phương châm chỉ đạo kháng chiến là đánh lâu dài, vừa kháng chiến vừa kiến quốc, từng bước xây dựng lực lượng, kết hợp chiến tranh du kích rộng khắp với xây dựng bộ đội chủ lực, tiến lên đánh chính quy quy mô lớn."},{"id":640,"section":"ch2-1","q":"Chính cương Đảng Lao động Việt Nam (thông qua tại Đại hội II, 1951) xác định tính chất xã hội Việt Nam lúc bấy giờ là gì?","options":["Xã hội dân chủ nhân dân, một phần thuộc địa và nửa phong kiến","Xã hội tư bản chủ nghĩa phát triển, do giai cấp tư sản lãnh đạo","Xã hội xã hội chủ nghĩa đã hoàn thành, không còn giai cấp bóc lột","Xã hội phong kiến thuần túy, chưa chịu ảnh hưởng của chủ nghĩa thực dân"],"answer":0,"explain":"Chính cương Đảng Lao động Việt Nam (1951) xác định xã hội Việt Nam lúc này có ba tính chất: dân chủ nhân dân, một phần thuộc địa và nửa phong kiến, ba tính chất đó đang đấu tranh lẫn nhau, nhưng mâu thuẫn chủ yếu là mâu thuẫn giữa tính chất dân chủ nhân dân và tính chất thuộc địa."},{"id":641,"section":"ch2-1","q":"Trong kháng chiến chống Pháp, Đảng chủ trương xây dựng nền kinh tế kháng chiến theo hướng nào?","options":["Vừa kháng chiến vừa xây dựng, tự cấp tự túc, phát triển sản xuất nông nghiệp và thủ công nghiệp","Phát triển công nghiệp nặng quy mô lớn để xuất khẩu, tập trung ở các đô thị lớn","Hoàn toàn phụ thuộc vào viện trợ nước ngoài, không tự tổ chức sản xuất trong nước","Ưu tiên tuyệt đối phát triển thương mại quốc tế, mở rộng giao thương với các nước tư bản phương Tây"],"answer":0,"explain":"Trong điều kiện chiến tranh, Đảng chủ trương xây dựng nền kinh tế kháng chiến tự cấp tự túc, đẩy mạnh sản xuất nông nghiệp, tiểu thủ công nghiệp tại các vùng tự do và căn cứ địa, bảo đảm hậu cần phục vụ kháng chiến, cải thiện đời sống nhân dân."},{"id":642,"section":"ch2-1","q":"Đại hội thống nhất Mặt trận Việt Minh và Hội Liên Việt (3/1951) thành lập tổ chức mặt trận mới có tên gọi gì?","options":["Mặt trận Liên hiệp Quốc dân Việt Nam (Mặt trận Liên Việt)","Mặt trận Tổ quốc Việt Nam (gọi tắt là Mặt trận Tổ quốc)","Mặt trận Dân tộc Giải phóng Việt Nam (Mặt trận Giải phóng)","Mặt trận Dân chủ Đông Dương (gọi tắt là Mặt trận Dân chủ)"],"answer":0,"explain":"Tháng 3/1951, Đại hội thống nhất Việt Minh - Liên Việt đã hợp nhất hai tổ chức thành Mặt trận Liên hiệp Quốc dân Việt Nam (gọi tắt là Mặt trận Liên Việt), tăng cường khối đại đoàn kết toàn dân phục vụ kháng chiến."},{"id":643,"section":"ch2-1","q":"Từ thực tiễn lãnh đạo kháng chiến giai đoạn 1946-1950, Đảng rút ra kinh nghiệm quan trọng nào về xây dựng lực lượng vũ trang?","options":["Xây dựng ba thứ quân: chủ lực, địa phương, dân quân du kích, gắn với thế trận chiến tranh nhân dân","Chỉ cần tập trung xây dựng một lực lượng quân đội chính quy duy nhất, hiện đại hóa nhanh chóng ngay từ đầu","Không cần xây dựng lực lượng vũ trang địa phương, dân quân du kích ở cơ sở và nông thôn","Chỉ dựa vào lực lượng vũ trang do nước ngoài huấn luyện, trang bị và trực tiếp chỉ huy"],"answer":0,"explain":"Qua thực tiễn 1946-1950, Đảng khẳng định kinh nghiệm xây dựng lực lượng vũ trang ba thứ quân: bộ đội chủ lực, bộ đội địa phương và dân quân du kích, kết hợp chặt chẽ tạo nên thế trận chiến tranh nhân dân rộng khắp, toàn dân đánh giặc."},{"id":644,"section":"ch2-1","q":"Kế hoạch Nava (1953) của thực dân Pháp - can thiệp Mỹ nhằm mục đích gì?","options":["Xoay chuyển cục diện, trong 18 tháng giành thắng lợi quân sự quyết định để kết thúc chiến tranh","Rút toàn bộ quân đội Pháp khỏi Đông Dương ngay lập tức, nhường lại cho quân đội Mỹ","Thiết lập chính quyền Quốc gia Việt Nam độc lập hoàn toàn khỏi sự chi phối của Pháp","Đàm phán hòa bình vô điều kiện với Việt Nam để chấm dứt chiến tranh trong thời gian ngắn nhất"],"answer":0,"explain":"Kế hoạch Nava là nỗ lực quân sự cao nhất của Pháp có sự giúp sức của Mỹ, nhằm trong 18 tháng xoay chuyển cục diện, giành thắng lợi quân sự quyết định để \"kết thúc chiến tranh trong danh dự\"."},{"id":645,"section":"ch2-1","q":"Trước kế hoạch Nava, Bộ Chính trị Trung ương Đảng (9/1953) đề ra phương hướng chiến lược Đông - Xuân 1953-1954 là gì?","options":["Tập trung lực lượng tiến công vào những hướng chiến lược quan trọng, buộc địch phân tán đối phó","Tập trung toàn bộ lực lượng phòng thủ tại đồng bằng Bắc Bộ, tránh giao chiến với địch","Chủ trương hòa hoãn, tạm ngừng mọi hoạt động quân sự để chờ đàm phán hòa bình với phía Pháp","Chuyển hướng toàn bộ chiến trường vào miền Nam, bỏ lại căn cứ địa Việt Bắc và Tây Bắc"],"answer":0,"explain":"Bộ Chính trị (9/1953) đề ra phương hướng chiến lược: tập trung lực lượng mở các cuộc tiến công vào những hướng quan trọng về chiến lược mà địch tương đối yếu, buộc chúng phải phân tán lực lượng, tạo điều kiện tiêu diệt sinh lực địch, làm phá sản kế hoạch Nava."},{"id":646,"section":"ch2-1","q":"Tập đoàn cứ điểm Điện Biên Phủ được thực dân Pháp xây dựng nhằm mục đích gì?","options":["Thành \"pháo đài bất khả xâm phạm\", nhử chủ lực ta vào quyết chiến chiến lược để tiêu diệt","Làm căn cứ hậu cần phục vụ dân sinh cho vùng Tây Bắc, hỗ trợ đồng bào các dân tộc","Làm nơi tổ chức đàm phán hòa bình giữa Pháp với phái đoàn Việt Nam Dân chủ Cộng hòa","Làm trung tâm hành chính mới của Pháp ở Đông Dương, thay thế vị trí của thủ đô Hà Nội"],"answer":0,"explain":"Điện Biên Phủ được Pháp xây dựng thành tập đoàn cứ điểm mạnh nhất Đông Dương, coi là \"pháo đài bất khả xâm phạm\", nhằm thu hút và tiêu diệt bộ đội chủ lực của ta trong một trận quyết chiến chiến lược."},{"id":647,"section":"ch2-1","q":"Chiến dịch Điện Biên Phủ diễn ra trong khoảng thời gian nào?","options":["Từ 13/3 đến 7/5/1954","Từ 19/12/1946 đến 2/1947","Từ 16/9 đến 22/10/1950","Từ 20/11/1953 đến 13/3/1954"],"answer":0,"explain":"Chiến dịch lịch sử Điện Biên Phủ diễn ra từ ngày 13/3 đến ngày 7/5/1954, kết thúc bằng thắng lợi hoàn toàn của quân đội và nhân dân Việt Nam."},{"id":648,"section":"ch2-1","q":"Đại tướng Võ Nguyên Giáp - Tổng Tư lệnh chiến dịch Điện Biên Phủ - đã quyết định thay đổi phương châm tác chiến từ \"đánh nhanh, thắng nhanh\" sang phương châm nào ngay trước giờ nổ súng?","options":["\"Đánh chắc, tiến chắc\"","\"Đánh nhanh, rút nhanh\"","\"Vây thành, diệt viện\"","\"Đánh du kích trường kỳ\""],"answer":0,"explain":"Trước tình hình thực tế của địch tại Điện Biên Phủ, Đại tướng Võ Nguyên Giáp đã quyết định thay đổi phương châm tác chiến từ \"đánh nhanh, thắng nhanh\" sang \"đánh chắc, tiến chắc\", đây được coi là một quyết định lịch sử, góp phần quyết định vào thắng lợi cuối cùng."},{"id":649,"section":"ch2-1","q":"Ý nghĩa lịch sử của chiến thắng Điện Biên Phủ (7/5/1954) là gì?","options":["Đập tan kế hoạch Nava, giáng đòn quyết định vào ý chí xâm lược của Pháp, tạo cơ sở cho Giơnevơ","Kết thúc hoàn toàn mọi cuộc chiến tranh trên bán đảo Đông Dương, lập lại hòa bình vĩnh viễn","Trực tiếp giải phóng hoàn toàn miền Nam Việt Nam, thống nhất đất nước về mặt Nhà nước và lãnh thổ","Buộc Mỹ phải rút quân hoàn toàn khỏi khu vực Đông Nam Á, kết thúc sự can thiệp của Mỹ ở châu Á"],"answer":0,"explain":"Chiến thắng Điện Biên Phủ đã đập tan hoàn toàn kế hoạch Nava, giáng đòn quyết định vào ý chí xâm lược của thực dân Pháp, trực tiếp đưa đến việc ký kết Hiệp định Giơnevơ, chấm dứt chiến tranh, lập lại hòa bình ở Đông Dương."},{"id":650,"section":"ch2-1","q":"Phái đoàn Chính phủ Việt Nam Dân chủ Cộng hòa tham dự và ký Hiệp định Giơnevơ (1954) do ai làm Trưởng đoàn?","options":["Phạm Văn Đồng","Hồ Chí Minh","Võ Nguyên Giáp","Trường Chinh"],"answer":0,"explain":"Phái đoàn Chính phủ Việt Nam Dân chủ Cộng hòa tham dự Hội nghị và ký kết Hiệp định Giơnevơ (1954) do đồng chí Phạm Văn Đồng, Phó Thủ tướng kiêm Bộ trưởng Ngoại giao, làm Trưởng đoàn."},{"id":651,"section":"ch2-1","q":"Theo Hiệp định Giơnevơ 1954, Việt Nam tạm thời bị chia cắt thành hai miền lấy ranh giới quân sự tạm thời ở đâu?","options":["Vĩ tuyến 17 (sông Bến Hải, Quảng Trị)","Vĩ tuyến 16 (dọc sông Hàn, Đà Nẵng)","Vĩ tuyến 13 (dọc sông Ba, Phú Yên)","Vĩ tuyến 20 (dọc sông Mã, Thanh Hóa)"],"answer":0,"explain":"Theo Hiệp định Giơnevơ, Việt Nam tạm thời bị chia làm hai miền lấy vĩ tuyến 17 (dọc theo sông Bến Hải, tỉnh Quảng Trị) làm giới tuyến quân sự tạm thời, chờ tổng tuyển cử thống nhất đất nước sau hai năm."},{"id":652,"section":"ch2-1","q":"Hiệp định Giơnevơ 1954 quy định thời hạn tổ chức tổng tuyển cử tự do thống nhất Việt Nam là khi nào?","options":["Sau hai năm, vào tháng 7/1956","Ngay sau khi ký hiệp định","Sau mười năm, vào năm 1964","Không quy định thời hạn cụ thể"],"answer":0,"explain":"Hiệp định Giơnevơ quy định việc chia cắt hai miền chỉ là tạm thời, sau hai năm (tháng 7/1956) sẽ tổ chức tổng tuyển cử tự do trong cả nước để thống nhất Việt Nam."},{"id":653,"section":"ch2-1","q":"Trong hai cuộc kháng chiến, chính sách hậu phương của Đảng có vai trò như thế nào đối với thắng lợi Điện Biên Phủ?","options":["Huy động sức người, sức của to lớn từ hậu phương như dân công hỏa tuyến, lương thực, vũ khí","Không có vai trò đáng kể vì chiến dịch chủ yếu dựa vào viện trợ trực tiếp từ nước ngoài","Chỉ có vai trò về mặt tuyên truyền, cổ vũ tinh thần mà không đóng góp vật chất","Chỉ huy động lực lượng tại chỗ ở khu vực Tây Bắc, không huy động từ vùng khác"],"answer":0,"explain":"Thắng lợi Điện Biên Phủ gắn liền với sự huy động to lớn sức người, sức của từ hậu phương: hàng vạn dân công hỏa tuyến, phương tiện thô sơ vận chuyển lương thực, vũ khí vượt qua địa hình hiểm trở, bảo đảm hậu cần cho chiến dịch quy mô lớn, xa hậu phương."},{"id":654,"section":"ch2-1","q":"Chiến thắng Điện Biên Phủ được đánh giá là sự kiện có tầm vóc như thế nào trên thế giới?","options":["Chấn động địa cầu, cổ vũ mạnh mẽ phong trào giải phóng dân tộc ở các nước thuộc địa","Chỉ có ý nghĩa cục bộ trong phạm vi Đông Dương, ít ảnh hưởng ra bên ngoài","Không có tác động gì đáng kể tới phong trào đấu tranh của các dân tộc thuộc địa","Chỉ được biết đến trong phạm vi các nước xã hội chủ nghĩa và các nước láng giềng"],"answer":0,"explain":"Chiến thắng Điện Biên Phủ \"lừng lẫy năm châu, chấn động địa cầu\" là chiến thắng của một dân tộc thuộc địa nhỏ bé trước một cường quốc thực dân, cổ vũ mạnh mẽ phong trào đấu tranh giải phóng dân tộc trên toàn thế giới, nhất là ở châu Á, châu Phi, Mỹ Latinh."},{"id":655,"section":"ch2-1","q":"Trong Đông - Xuân 1953-1954, cùng với mặt trận Điện Biên Phủ, quân dân ta còn phối hợp mở nhiều chiến dịch khác ở đâu?","options":["Trung Lào, Hạ Lào, Tây Nguyên, Thượng Lào, buộc địch phân tán lực lượng ở nhiều hướng","Chỉ mở chiến dịch duy nhất tại đồng bằng Bắc Bộ, không phối hợp với chiến trường khác","Chỉ tập trung toàn bộ lực lượng tại chiến trường Nam Bộ, bỏ trống các hướng còn lại","Chỉ phối hợp với lực lượng quân sự nước ngoài đóng ở xa khu vực Đông Dương"],"answer":0,"explain":"Phối hợp với mặt trận chính Điện Biên Phủ, quân dân ta mở các chiến dịch tiến công ở Trung Lào, Hạ Lào, Tây Nguyên, Thượng Lào, buộc thực dân Pháp phải phân tán lực lượng cơ động chiến lược trên nhiều hướng, tạo điều kiện thuận lợi cho chiến trường chính."},{"id":656,"section":"ch2-1","q":"Đường lối kháng chiến \"toàn dân, toàn diện\" được thể hiện rõ nét trong giai đoạn 1951-1954 qua việc kết hợp đấu tranh trên những mặt trận nào?","options":["Quân sự, chính trị, kinh tế, văn hóa và ngoại giao","Chỉ đơn thuần trên mặt trận quân sự, bỏ qua mặt trận khác","Chỉ tập trung vào mặt trận ngoại giao ở các diễn đàn quốc tế","Chỉ tiến hành trên mặt trận kinh tế, không có đấu tranh quân sự"],"answer":0,"explain":"Trong giai đoạn đẩy mạnh kháng chiến 1951-1954, Đảng lãnh đạo kết hợp chặt chẽ đấu tranh trên các mặt trận quân sự, chính trị, kinh tế, văn hóa, ngoại giao, tạo nên sức mạnh tổng hợp đưa cuộc kháng chiến đến thắng lợi."},{"id":657,"section":"ch2-1","q":"Chính sách ruộng đất trong giai đoạn kháng chiến chống Pháp được đẩy mạnh qua việc ban hành Luật Cải cách ruộng đất vào năm nào?","options":["Năm 1953","Năm 1945","Năm 1954","Năm 1960"],"answer":0,"explain":"Năm 1953, Quốc hội thông qua Luật Cải cách ruộng đất, nhằm thực hiện triệt để khẩu hiệu \"người cày có ruộng\", xóa bỏ chế độ chiếm hữu ruộng đất của địa chủ phong kiến, củng cố khối liên minh công nông."},{"id":658,"section":"ch2-1","q":"Bài học kinh nghiệm nổi bật về nghệ thuật quân sự được rút ra từ chiến dịch Điện Biên Phủ là gì?","options":["Kết hợp quân sự với ngoại giao, biết tạo và nắm thời cơ, vận dụng sáng tạo phương châm tác chiến","Chỉ dựa hoàn toàn vào ưu thế vũ khí, trang bị kỹ thuật hiện đại hơn đối phương trên chiến trường","Chỉ áp dụng chiến thuật phòng ngự bị động, tránh tiến công vào các cứ điểm kiên cố của địch","Không cần chuẩn bị hậu cần, chỉ cần dựa vào tinh thần chiến đấu và quyết tâm của bộ đội"],"answer":0,"explain":"Chiến dịch Điện Biên Phủ để lại bài học lớn về nghệ thuật quân sự: kết hợp chặt chẽ đấu tranh quân sự với đấu tranh ngoại giao (tại Giơnevơ), biết tạo và nắm thời cơ, linh hoạt thay đổi phương châm tác chiến phù hợp thực tế chiến trường để giành thắng lợi quyết định."},{"id":659,"section":"ch2-1","q":"Sau thắng lợi Điện Biên Phủ và Hiệp định Giơnevơ, quân đội và cán bộ ta ở miền Nam thực hiện chủ trương gì theo quy định của Hiệp định?","options":["Tập kết chuyển quân ra miền Bắc, để lại một bộ phận cán bộ bám trụ chuẩn bị đấu tranh","Toàn bộ giải giáp vũ khí, chuyển sang làm nhiệm vụ dân sự tại chỗ ở các địa phương miền Nam","Ở lại nguyên vị trí, không có sự thay đổi bố trí lực lượng, tiếp tục chiến đấu như cũ","Chuyển toàn bộ lực lượng sang chiến đấu giúp cách mạng Lào và Campuchia, bỏ lại miền Nam"],"answer":0,"explain":"Theo quy định của Hiệp định Giơnevơ về tập kết chuyển quân, lực lượng vũ trang cách mạng ở miền Nam tập kết chuyển ra miền Bắc trong thời hạn quy định, đồng thời Đảng chủ trương để lại một bộ phận cán bộ, đảng viên bám trụ, chuẩn bị cho cuộc đấu tranh trong giai đoạn cách mạng mới."},{"id":660,"section":"ch2-1","q":"Nguyên nhân sâu xa dẫn tới thắng lợi của cuộc kháng chiến chống thực dân Pháp (1945-1954) là gì?","options":["Sự lãnh đạo đúng đắn, sáng tạo của Đảng với đường lối kháng chiến toàn dân, toàn diện, trường kỳ","Chỉ đơn thuần nhờ vào viện trợ quân sự to lớn của các nước xã hội chủ nghĩa và bạn bè quốc tế","Chỉ do thực dân Pháp tự nguyện rút lui vì gặp khó khăn kinh tế nặng nề ở chính quốc","Chỉ nhờ vào yếu tố địa hình rừng núi hiểm trở và điều kiện khí hậu khắc nghiệt của Việt Nam"],"answer":0,"explain":"Nguyên nhân quyết định thắng lợi của cuộc kháng chiến chống Pháp là sự lãnh đạo đúng đắn, sáng tạo của Đảng và Chủ tịch Hồ Chí Minh với đường lối kháng chiến toàn dân, toàn diện, trường kỳ, tự lực cánh sinh, kết hợp sức mạnh dân tộc với sức mạnh thời đại."},{"id":661,"section":"ch2-1","q":"Tác phẩm nào của Tổng Bí thư Trường Chinh đã hệ thống hóa đường lối kháng chiến toàn dân, toàn diện, trường kỳ, tự lực cánh sinh?","options":["\"Kháng chiến nhất định thắng lợi\" (1947)","\"Đường Kách mệnh\" của Nguyễn Ái Quốc (1927)","\"Sửa đổi lối làm việc\" của Hồ Chí Minh (1947)","\"Bản án chế độ thực dân Pháp\" (1925)"],"answer":0,"explain":"Tác phẩm \"Kháng chiến nhất định thắng lợi\" (1947) của đồng chí Trường Chinh đã trình bày, hệ thống hóa một cách toàn diện đường lối kháng chiến toàn dân, toàn diện, trường kỳ, tự lực cánh sinh của Đảng."},{"id":662,"section":"ch2-1","q":"Trong giai đoạn 1951-1954, công tác chỉnh Đảng, chỉnh quân được tiến hành nhằm mục đích gì?","options":["Nhằm nâng cao bản lĩnh chính trị, năng lực lãnh đạo của đảng viên và sức chiến đấu của quân đội","Nhằm giảm bớt quy mô của Đảng và quân đội để tinh gọn bộ máy trong điều kiện kháng chiến khó khăn","Nhằm chuyển hướng kháng chiến sang đấu tranh ôn hòa, bất bạo động với thực dân Pháp","Nhằm chuyển giao quyền chỉ huy quân đội cho các cố vấn quân sự nước ngoài ở Việt Nam"],"answer":0,"explain":"Các đợt chỉnh Đảng, chỉnh quân (1952-1953) nhằm nâng cao bản lĩnh chính trị, năng lực lãnh đạo, tính tiên phong gương mẫu của cán bộ, đảng viên, đồng thời nâng cao sức chiến đấu, kỷ luật của quân đội, đáp ứng yêu cầu ngày càng cao của cuộc kháng chiến."},{"id":663,"section":"ch2-1","q":"Hội nghị Giơnevơ về Đông Dương (1954) có sự tham gia của các bên nào?","options":["Việt Nam Dân chủ Cộng hòa, Pháp, Liên Xô, Trung Quốc, Anh, Mỹ và chính quyền Bảo Đại","Chỉ có Việt Nam Dân chủ Cộng hòa, Pháp và Mỹ, không có nước nào khác tham dự","Chỉ có các nước lớn, không có đại diện của Việt Nam Dân chủ Cộng hòa","Chỉ có Liên Xô, Trung Quốc và Việt Nam Dân chủ Cộng hòa cùng các nước láng giềng"],"answer":0,"explain":"Hội nghị Giơnevơ về Đông Dương (1954) có sự tham gia của nhiều bên: Việt Nam Dân chủ Cộng hòa, Pháp, Liên Xô, Trung Quốc, Anh, Mỹ và chính quyền Quốc gia Việt Nam (Bảo Đại), là hội nghị quốc tế đa phương quan trọng chấm dứt chiến tranh Đông Dương."},{"id":753,"section":"ch2-1","q":"Ngày 23/9/1945, thực dân Pháp nổ súng mở đầu cuộc chiến tranh xâm lược Việt Nam lần thứ hai ở","options":["Hà Nội - Hà Đông.","Thừa Thiên Huế.","Đà Nẵng - Hội An.","Sài Gòn - Chợ Lớn."],"answer":3,"explain":"Đêm 22 rạng ngày 23/9/1945, được sự yểm trợ của quân Anh, thực dân Pháp nổ súng đánh chiếm trụ sở Ủy ban Nhân dân Nam Bộ và các công sở của ta tại Sài Gòn - Chợ Lớn, mở đầu cuộc chiến tranh xâm lược Việt Nam lần thứ hai."},{"id":754,"section":"ch2-1","q":"Theo thoả thuận tại Hội nghị Potsdam (7/1945), quân đội nước nào vào miền Bắc Việt Nam để giải giáp vũ khí quân phát xít Nhật?","options":["Liên Xô (Hồng quân).","Anh (quân Đồng minh).","Pháp (quân viễn chinh).","Trung Hoa dân quốc."],"answer":3,"explain":"Theo thỏa thuận tại Hội nghị Potsdam (7/1945) giữa các nước Đồng minh, quân đội Trung Hoa Dân quốc (từ vĩ tuyến 16 ra Bắc) vào miền Bắc Việt Nam với danh nghĩa giải giáp quân đội Nhật, nhưng thực chất mang theo âm mưu \"diệt Cộng, cầm Hồ\", giúp các thế lực tay sai chống phá cách mạng."},{"id":755,"section":"ch2-1","q":"Theo thỏa thuận tại Hội nghị Potsdam (7/1945), quân đội nước nào vào miền Nam Việt Nam để giải giáp vũ khí quân phát xít Nhật?","options":["Liên Xô (Hồng quân).","Anh (quân Đồng minh).","Pháp (quân viễn chinh).","Trung Hoa dân quốc."],"answer":1,"explain":"Theo thỏa thuận tại Hội nghị Potsdam (7/1945), quân đội Anh (đại diện quân Đồng minh) vào miền Nam Việt Nam (từ vĩ tuyến 16 vào Nam) với danh nghĩa giải giáp quân đội Nhật, nhưng trên thực tế đã dọn đường, tạo điều kiện cho thực dân Pháp trở lại xâm lược Nam Bộ."},{"id":756,"section":"ch2-1","q":"Ngày 3/9/1945, Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa họp phiên đầu tiên do ai chủ trì?","options":["Trường Chinh.","Phạm Văn Đồng.","Huỳnh Thúc Kháng.","Hồ Chí Minh."],"answer":3,"explain":"Ngày 3/9/1945, Chủ tịch Hồ Chí Minh, với tư cách người đứng đầu Chính phủ lâm thời, đã chủ trì phiên họp đầu tiên của Chính phủ, xác định ngay những nhiệm vụ cấp bách cần giải quyết trước tình thế \"ngàn cân treo sợi tóc\"."},{"id":757,"section":"ch2-1","q":"Hai nhiệm vụ chiến lược mới của cách mạng Việt Nam sau Cách mạng Tháng Tám 1945 là gì?","options":["Giải phóng dân tộc và thực hiện cách mạng ruộng đất triệt để.","Kháng chiến chống thực dân Pháp xâm lược và kiến quốc.","Xây dựng chủ nghĩa xã hội ở miền Bắc và giải phóng miền Nam.","Xây dựng chủ nghĩa xã hội và bảo vệ Tổ quốc xã hội chủ nghĩa."],"answer":1,"explain":"Sau Cách mạng Tháng Tám 1945, cách mạng Việt Nam bước vào thời kỳ mới với hai nhiệm vụ chiến lược song hành là kháng chiến (chống thực dân Pháp xâm lược) và kiến quốc (xây dựng, bảo vệ chính quyền cách mạng non trẻ), được Đảng cụ thể hóa trong Chỉ thị Kháng chiến kiến quốc (25/11/1945)."},{"id":758,"section":"ch2-1","q":"Trong Chỉ thị Kháng chiến kiến quốc (25/11/1945), Đảng xác định mục tiêu chính của cách mạng Đông Dương lúc này là","options":["hoàn thành nhiệm vụ dân tộc giải phóng.","thực hiện khẩu hiệu người cày có ruộng.","hoàn thành cách mạng dân chủ nhân dân.","hoàn thành cách mạng xã hội chủ nghĩa."],"answer":0,"explain":"Chỉ thị Kháng chiến kiến quốc (25/11/1945) khẳng định tính chất của cuộc cách mạng Đông Dương lúc này vẫn là cách mạng dân tộc giải phóng, do đó mục tiêu chính vẫn là hoàn thành nhiệm vụ giải phóng dân tộc, chưa đặt vấn đề cách mạng ruộng đất triệt để hay cách mạng xã hội chủ nghĩa."},{"id":759,"section":"ch2-1","q":"Trong Chỉ thị Kháng chiến kiến quốc (25/11/1945), đối với Pháp, Đảng chủ trương thực hiện khẩu hiệu","options":["“Độc lập về kinh tế, nhân nhượng về chính trị”.","“Độc lập về chính trị, nhân nhượng về kinh tế”.","“Độc lập về đối nội, nhân nhượng về đối ngoại”.","“Độc lập về quân sự, nhân nhượng về ngoại giao”."],"answer":1,"explain":"Trong Chỉ thị Kháng chiến kiến quốc (25/11/1945), đối với thực dân Pháp, Đảng chủ trương thực hiện khẩu hiệu \"Độc lập về chính trị, nhân nhượng về kinh tế\", nhằm hạn chế xung đột trực diện trong điều kiện thực lực cách mạng còn non yếu."},{"id":760,"section":"ch2-1","q":"Quốc hội khóa I của nước Việt Nam Dân chủ Cộng hoà đã bầu Ban Thường trực Quốc hội do ai làm chủ tịch?","options":["Hồ Chí Minh.","Huỳnh Thúc Kháng.","Nguyễn Lương Bằng.","Nguyễn Văn Tố."],"answer":3,"explain":"Quốc hội khóa I đã bầu Ban Thường trực Quốc hội do cụ Nguyễn Văn Tố làm Chủ tịch, đảm nhiệm vai trò cơ quan thường trực, thay mặt Quốc hội hoạt động giữa hai kỳ họp."},{"id":761,"section":"ch2-1","q":"Tháng 2/1946, thay mặt Chính phủ, Bác Hồ đã tặng danh hiệu vẻ vang “Thành đồng Tổ quốc” cho","options":["đồng bào miền Nam.","đồng bào miền Trung.","đồng bào Tây Nguyên.","đồng bào miền Bắc."],"answer":0,"explain":"Tháng 2/1946, thay mặt Chính phủ, Chủ tịch Hồ Chí Minh đã tặng đồng bào miền Nam danh hiệu vẻ vang \"Thành đồng Tổ quốc\", ca ngợi tinh thần kiên cường, đi đầu chống thực dân Pháp xâm lược ngay từ những ngày đầu (23/9/1945)."},{"id":762,"section":"ch2-1","q":"Chọn từ điền vào chỗ trống phù hợp với nội dung Hiệp định Sơ bộ (6/3/1946): “Chính phủ Pháp công nhận Việt Nam là một quốc gia …, có chính phủ, nghị viện, tài chính và quân đội riêng nằm trong Liên bang Đông Dương thuộc khối Liên hiệp Pháp”.","options":["độc lập","tự do","tự trị","trung lập"],"answer":1,"explain":"Điều 1 Hiệp định Sơ bộ (6/3/1946) quy định: Chính phủ Pháp công nhận Việt Nam là một quốc gia \"tự do\", có chính phủ, nghị viện, tài chính và quân đội riêng, nằm trong Liên bang Đông Dương và trong khối Liên hiệp Pháp."},{"id":763,"section":"ch2-1","q":"Nội dung nào dưới đây không phải ý nghĩa của chủ trương, biện pháp, sách lược đúng đắn của Đảng, Chính phủ và Chủ tịch Hồ Chí Minh trong cuộc đấu tranh chống giặc ngoài, thù trong những năm (1945 - 1946)?","options":["Ngăn chặn bước tiến của quân Pháp ở Nam Bộ, vạch trần và làm thất bại âm mưu chống phá của các kẻ thù.","Củng cố, giữ vững và bảo vệ chính quyền cách mạng từ Trung ương đến cơ sở cùng thành quả Cách mạng Tháng Tám 1945.","Tạo thêm thời gian hòa hoãn, tranh thủ xây dựng thực lực, chuẩn bị sẵn sàng cho cuộc kháng chiến lâu dài.","Mở ra thời kì sụp đổ có hệ thống của chủ nghĩa thực dân mới trên phạm vi toàn thế giới ngay sau đó."],"answer":3,"explain":"Chủ trương, sách lược đấu tranh chống giặc ngoài, thù trong (1945-1946) có ý nghĩa ngăn chặn bước tiến của Pháp ở Nam Bộ, bảo vệ chính quyền cách mạng và tạo thời gian hòa hoãn để chuẩn bị kháng chiến lâu dài; tuy nhiên, nhận định \"mở ra thời kỳ sụp đổ có hệ thống của chủ nghĩa thực dân mới trên toàn thế giới\" là phóng đại, không phản ánh đúng phạm vi tác động thực tế của sách lược ngoại giao này."},{"id":764,"section":"ch2-1","q":"Nội dung nào dưới đây không phải hành động của đại diện Pháp tại Hà Nội ngày 18/12/1946?","options":["Tuyên bố cắt đứt mọi liên hệ với chính phủ Việt Nam Dân chủ Cộng hòa.","Đưa tối hậu thư đòi phía Việt Nam phải giải giáp, giải tán lực lượng tự vệ chiến đấu ở Hà Nội.","Đòi độc quyền thực thi nhiệm vụ kiểm soát, gìn giữ an ninh, trật tự của thành phố Hà Nội.","Quyết định đàm phán chính thức với đại diện Chính phủ Việt Nam Dân chủ Cộng hoà."],"answer":3,"explain":"Ngày 18/12/1946, đại diện Pháp tại Hà Nội tuyên bố cắt đứt liên hệ với Chính phủ Việt Nam Dân chủ Cộng hòa, đưa tối hậu thư đòi ta giải giáp lực lượng tự vệ chiến đấu và đòi độc quyền kiểm soát an ninh, trật tự thành phố - hoàn toàn không có việc \"quyết định đàm phán chính thức\" với phía Việt Nam như phương án nêu."},{"id":765,"section":"ch2-1","q":"Đường lối kháng chiến chống thực dân Pháp của Đảng (1946 - 1950) xác định mục tiêu của cuộc kháng chiến là","options":["đánh đổ thực dân Pháp xâm lược, giành độc lập, tự do và thống nhất Tổ quốc.","đánh đuổi thực dân Pháp xâm lược, giành độc lập rồi đi lên chủ nghĩa xã hội.","đánh đuổi thực dân Pháp xâm lược và phong kiến làm cách mạng ruộng đất.","đánh đuổi thực dân, phong kiến và can thiệp Mỹ, làm cho Việt Nam độc lập."],"answer":0,"explain":"Đường lối kháng chiến chống thực dân Pháp của Đảng (1946-1950), được thể hiện qua Chỉ thị Toàn dân kháng chiến, Lời kêu gọi toàn quốc kháng chiến và tác phẩm Kháng chiến nhất định thắng lợi, xác định mục tiêu của cuộc kháng chiến là đánh đổ thực dân Pháp xâm lược, giành độc lập, tự do và thống nhất hoàn toàn cho Tổ quốc."},{"id":766,"section":"ch2-1","q":"“Mỗi người dân là một chiến sĩ, mỗi làng xã là một pháo đài, mỗi đường phố là một mặt trận” thuộc nội dung nào dưới đây của đường lối kháng chiến chống thực dân Pháp (1946 - 1950)?","options":["Kháng chiến toàn dân.","Kháng chiến toàn diện.","Kháng chiến lâu dài.","Kháng chiến dựa vào sức mình."],"answer":0,"explain":"Phương châm \"Mỗi người dân là một chiến sĩ, mỗi làng xã là một pháo đài, mỗi đường phố là một mặt trận\" thể hiện nội dung kháng chiến toàn dân, huy động mọi tầng lớp nhân dân, không phân biệt già trẻ, gái trai, giai cấp, tôn giáo cùng đứng lên đánh giặc."},{"id":767,"section":"ch2-1","q":"Nội dung nào dưới đây không phải cách hiểu đúng về phương châm “tự lực cánh sinh” trong đường lối kháng chiến chống thực dân Pháp của Đảng (1946 - 1950)?","options":["Chỉ dựa vào sức mình, khước từ mọi sự giúp đỡ về vật chất và tinh thần từ bên ngoài.","Phát huy nguồn sức mạnh vật chất, tinh thần trong nhân dân ta làm chỗ dựa chủ yếu.","Tranh thủ có hiệu quả sự ủng hộ, giúp đỡ vật chất và tinh thần của quốc tế khi có điều kiện.","Lấy độc lập, tự chủ về đường lối là yếu tố quan trọng hàng đầu của cuộc kháng chiến."],"answer":0,"explain":"Phương châm \"tự lực cánh sinh\" trong đường lối kháng chiến của Đảng nghĩa là phát huy cao độ nguồn sức mạnh vật chất, tinh thần của toàn dân làm chỗ dựa chủ yếu, giữ vững độc lập, tự chủ về đường lối, đồng thời tranh thủ có hiệu quả sự ủng hộ, giúp đỡ của quốc tế khi có điều kiện; do đó, hiểu \"tự lực cánh sinh\" là hoàn toàn không nhận sự giúp đỡ từ bên ngoài là không đúng."},{"id":768,"section":"ch2-1","q":"Đại hội đại biểu toàn quốc lần thứ II (2/1951) đã quyết định","options":["thành lập Mặt trận Dân chủ Đông Dương để đoàn kết ba nước.","thành lập Liên bang Đông Dương gồm ba nước Việt - Miên - Lào.","thành lập Mặt trận kháng chiến chung ở ba nước Đông Dương.","tách Đảng Cộng sản Đông Dương, mỗi nước một đảng riêng."],"answer":3,"explain":"Do yêu cầu phát triển cách mạng riêng của mỗi nước Đông Dương, Đại hội II (2/1951) chủ trương tách Đảng Cộng sản Đông Dương để thành lập ở Việt Nam, Lào, Campuchia mỗi nước một đảng cách mạng riêng, có cương lĩnh phù hợp với đặc điểm của từng dân tộc; ở Việt Nam, Đảng ra hoạt động công khai với tên Đảng Lao động Việt Nam."},{"id":769,"section":"ch2-1","q":"Chính cương Đảng Lao động Việt Nam trình bày tại Đại hội đại biểu toàn quốc lần thứ II (2/1951) do ai dự thảo?","options":["Lê Duẩn.","Trường Chinh.","Phạm Văn Đồng.","Hồ Chí Minh."],"answer":1,"explain":"Chính cương Đảng Lao động Việt Nam trình bày tại Đại hội II (2/1951) do đồng chí Trường Chinh, Tổng Bí thư của Đảng, trực tiếp dự thảo và trình bày trước Đại hội, hệ thống hóa đường lối cách mạng dân tộc dân chủ nhân dân trong giai đoạn kháng chiến."},{"id":770,"section":"ch2-1","q":"Trong Chính cương Đảng Lao động Việt Nam (2/1951), Đảng xác định tính chất của xã hội Việt Nam lúc này là","options":["dân chủ nhân dân, một phần thuộc địa và nửa phong kiến.","dân chủ nhân dân, thuộc địa hoàn toàn và nửa phong kiến.","thuộc địa và nửa phong kiến, chưa có yếu tố dân chủ nhân dân.","nửa thuộc địa, nửa phong kiến, chưa có chính quyền dân chủ."],"answer":0,"explain":"Chính cương Đảng Lao động Việt Nam (2/1951) xác định xã hội Việt Nam lúc này có ba tính chất: dân chủ nhân dân, một phần thuộc địa và nửa phong kiến; trong đó mâu thuẫn chủ yếu là giữa tính chất dân chủ nhân dân với tính chất thuộc địa."},{"id":771,"section":"ch2-1","q":"Trong Chính cương Đảng Lao động Việt Nam (2/1951), Đảng xác định đối tượng đấu tranh của cách mạng Việt Nam lúc này là","options":["đế quốc xâm lược Pháp, can thiệp Mỹ và phong kiến phản động.","phát xít Nhật xâm lược, can thiệp Anh và địa chủ phản động.","chủ nghĩa phát xít và bọn tay sai phản cách mạng.","bọn phản động thuộc địa và bè lũ tay sai của chúng."],"answer":0,"explain":"Chính cương xác định đối tượng đấu tranh của cách mạng Việt Nam gồm đối tượng chính là chủ nghĩa đế quốc xâm lược, cụ thể là thực dân Pháp và bọn can thiệp Mỹ, và đối tượng phụ là phong kiến phản động."},{"id":772,"section":"ch2-1","q":"Nội dung nào dưới đây không phải là nhiệm vụ được xác định trong Chính cương Đảng Lao động Việt Nam (2/1951)?","options":["Đánh đuổi đế quốc xâm lược, giành độc lập và thống nhất cho dân tộc.","Xóa bỏ di tích phong kiến, nửa phong kiến, làm cho người cày có ruộng.","Gây cơ sở vật chất ban đầu cho việc tiến lên chủ nghĩa xã hội.","Đẩy mạnh xây dựng chủ nghĩa xã hội ở miền Bắc sau khi hòa bình lập lại."],"answer":3,"explain":"Ba nhiệm vụ cơ bản của cách mạng theo Chính cương (2/1951) là đánh đuổi đế quốc xâm lược giành độc lập, thống nhất; xóa bỏ di tích phong kiến, nửa phong kiến, thực hiện người cày có ruộng; và gây cơ sở cho chủ nghĩa xã hội. Nhiệm vụ \"đẩy mạnh xây dựng chủ nghĩa xã hội ở miền Bắc\" chỉ xuất hiện sau năm 1954, khi miền Bắc được giải phóng, nên không thuộc Chính cương 1951."},{"id":773,"section":"ch2-1","q":"Trong Chính cương Đảng Lao động Việt Nam (2/1951), Đảng khẳng định nền tảng của khối đại đoàn kết toàn dân là giai cấp, tầng lớp nào dưới đây?","options":["Công nhân, nông dân và binh lính cách mạng.","Công nhân, nông dân và tư sản dân tộc.","Công nhân, nông dân và lao động trí óc.","Công nhân, nông dân và địa chủ yêu nước."],"answer":2,"explain":"Chính cương Đảng Lao động Việt Nam (2/1951) khẳng định nền tảng của khối đại đoàn kết toàn dân là liên minh giữa giai cấp công nhân, giai cấp nông dân và lao động trí óc, do giai cấp công nhân lãnh đạo."},{"id":774,"section":"ch2-1","q":"Trong Chính cương Đảng Lao động Việt Nam (2/1951), Đảng xác định giai cấp, tầng lớp nào dưới đây đóng vai trò là lực lượng lãnh đạo cách mạng?","options":["Công nhân.","Nông dân.","Tiểu tư sản.","Tư sản dân tộc."],"answer":0,"explain":"Theo Chính cương (2/1951), giai cấp công nhân là lực lượng lãnh đạo cách mạng Việt Nam thông qua vai trò lãnh đạo của Đảng, còn công nhân, nông dân và lao động trí óc là lực lượng nòng cốt, nền tảng của cách mạng."},{"id":775,"section":"ch2-1","q":"Đại hội nào của Đảng được coi là “Đại hội kháng chiến kiến quốc”?","options":["Đại hội I (3/1935).","Đại hội II (2/1951).","Đại hội III (9/1960).","Đại hội IV (12/1976)."],"answer":1,"explain":"Đại hội đại biểu toàn quốc lần thứ II (2/1951), diễn ra khi cuộc kháng chiến chống Pháp chuyển sang giai đoạn quyết liệt, được coi là \"Đại hội kháng chiến kiến quốc\", đề ra đường lối đẩy mạnh kháng chiến đến thắng lợi gắn với xây dựng chế độ dân chủ nhân dân."},{"id":776,"section":"ch2-1","q":"Từ đầu năm 1951, Đảng chủ trương mở các chiến dịch tiến công quân sự có quy mô tương đối lớn đánh vào các vùng chiếm đóng của địch ở khu vực","options":["Tây Nguyên và Nam Trung Bộ.","Trung du và đồng bằng Bắc Bộ.","Trung du miền núi phía Bắc.","Tây Nam Bộ và Đông Nam Bộ."],"answer":1,"explain":"Từ đầu năm 1951, sau Đại hội II, Đảng chủ trương mở các chiến dịch tiến công quy mô tương đối lớn vào các vùng địch chiếm ở Trung du và đồng bằng Bắc Bộ (Chiến dịch Trung Du, Đường số 18, Hà Nam Ninh...) nhằm tiêu diệt sinh lực địch và mở rộng vùng giải phóng."},{"id":777,"section":"ch2-1","q":"Tại Hội nghị Trung ương Đảng lần thứ 3 (4/1952), Đảng đã đề ra quyết sách lớn về","options":["chỉnh Đảng, chỉnh quân.","cải cách ruộng đất.","triệt để giảm tô, giảm tức.","mở Chiến dịch Điện Biên Phủ."],"answer":0,"explain":"Hội nghị lần thứ 3 Ban Chấp hành Trung ương Đảng (khóa II, 4/1952) đề ra chủ trương lớn về công tác chỉnh Đảng, chỉnh quân, nhằm nâng cao bản lĩnh chính trị, năng lực lãnh đạo của cán bộ, đảng viên và sức chiến đấu của quân đội, đáp ứng yêu cầu ngày càng cao của cuộc kháng chiến."},{"id":778,"section":"ch2-1","q":"Ngày 6/12/1953, Bộ Chính trị quyết định mở chiến dịch nào dưới đây?","options":["Chiến dịch Biên giới.","Chiến dịch Điện Biên Phủ.","Chiến dịch Huế - Đà Nẵng.","Chiến dịch Hồ Chí Minh."],"answer":1,"explain":"Ngày 6/12/1953, Bộ Chính trị Trung ương Đảng họp và quyết định mở Chiến dịch Điện Biên Phủ, chọn Điện Biên Phủ làm điểm quyết chiến chiến lược với thực dân Pháp trong Đông - Xuân 1953-1954."},{"id":779,"section":"ch2-1","q":"Nội dung nào dưới đây không phải là quyết sách của Đảng, Quốc hội và Chủ tịch Hồ Chí Minh nhằm phát huy sức mạnh của hậu phương, chi viện tiền tuyến, nhất là lực lượng nông dân tham gia Chiến dịch Điện Biên Phủ?","options":["Phát động giảm tô, giảm tức và tiến hành cải cách ruộng đất.","Thành lập Ủy ban chi viện tiền tuyến, huy động sức người sức của.","Thành lập Hội đồng cung cấp mặt trận Trung ương và địa phương.","Phát động \"Tuần lễ vàng\" quyên góp vàng ủng hộ kháng chiến."],"answer":3,"explain":"Trong các quyết sách chi viện tiền tuyến cho Chiến dịch Điện Biên Phủ, Đảng, Quốc hội và Chủ tịch Hồ Chí Minh đã phát động giảm tô, giảm tức và cải cách ruộng đất, thành lập Ủy ban chi viện tiền tuyến, thành lập Hội đồng cung cấp mặt trận. \"Tuần lễ vàng\" là phong trào quyên góp vàng, tiền ủng hộ chính quyền cách mạng non trẻ ngay sau Cách mạng Tháng Tám (9/1945), không liên quan đến việc chi viện cho Điện Biên Phủ (1954)."},{"id":780,"section":"ch2-1","q":"Chiến dịch nào dưới đây được Chủ tịch Hồ Chí Minh xác định “rất quan trọng, không những về mặt quân sự mà cả về mặt chính trị, không những trong nước, mà đối với quốc tế”?","options":["Việt Bắc (thu đông 1947)","Biên giới (thu đông 1950)","Điện Biên Phủ (1954)","Mậu Thân (Tết 1968)"],"answer":2,"explain":"Chủ tịch Hồ Chí Minh đánh giá Chiến dịch Điện Biên Phủ là chiến dịch \"rất quan trọng, không những về mặt quân sự mà cả về mặt chính trị, không những trong nước mà đối với quốc tế\", thể hiện tầm vóc và ý nghĩa đặc biệt to lớn của trận quyết chiến chiến lược này."},{"id":201,"section":"ch2-2","q":"Sau Hiệp định Giơnevơ (1954), cách mạng Việt Nam thực hiện đồng thời hai nhiệm vụ chiến lược nào?","options":["Xây dựng chủ nghĩa xã hội ở miền Bắc và giải phóng miền Nam","Chỉ tập trung xây dựng chủ nghĩa xã hội ở miền Bắc, tạm gác miền Nam","Chỉ tập trung đấu tranh giải phóng miền Nam, tạm gác xây dựng miền Bắc","Xây dựng quân đội hiện đại và phát triển kinh tế đối ngoại"],"answer":0,"explain":"Sau 1954, Đảng lãnh đạo nhân dân thực hiện đồng thời hai nhiệm vụ chiến lược: xây dựng CNXH ở miền Bắc và đấu tranh giải phóng miền Nam, thống nhất đất nước."},{"id":202,"section":"ch2-2","q":"Đại hội đại biểu toàn quốc lần thứ III của Đảng họp vào thời gian nào, ở đâu?","options":["Tháng 9/1960, tại Hà Nội","Tháng 2/1951, tại Tuyên Quang","Tháng 12/1976, tại Hà Nội","Tháng 3/1982, tại Hà Nội"],"answer":0,"explain":"Đại hội đại biểu toàn quốc lần thứ III của Đảng họp tháng 9/1960 tại Thủ đô Hà Nội."},{"id":203,"section":"ch2-2","q":"Đại hội III (9/1960) xác định cách mạng miền Nam có vai trò gì đối với sự nghiệp giải phóng dân tộc?","options":["Vai trò quyết định trực tiếp đối với việc giải phóng miền Nam","Vai trò quyết định nhất đối với toàn bộ cách mạng cả nước","Vai trò thứ yếu, phụ thuộc hoàn toàn vào cách mạng miền Bắc","Không có vai trò đáng kể trong sự nghiệp giải phóng dân tộc"],"answer":0,"explain":"Đại hội III xác định cách mạng xã hội chủ nghĩa ở miền Bắc có vai trò quyết định nhất, còn cách mạng miền Nam có vai trò quyết định trực tiếp đối với sự nghiệp giải phóng miền Nam."},{"id":204,"section":"ch2-2","q":"Nghị quyết Hội nghị Trung ương lần thứ 15 (khóa II) của Đảng, ban hành tháng 1/1959, có nội dung quan trọng gì?","options":["Xác định con đường cơ bản của cách mạng miền Nam là khởi nghĩa giành chính quyền","Chủ trương chỉ đấu tranh chính trị hòa bình đơn thuần, tuyệt đối không dùng vũ trang","Chủ trương hòa hợp, hiệp thương với chính quyền Ngô Đình Diệm để thống nhất đất nước","Chủ trương mở tổng tiến công quân sự toàn diện trên khắp miền Nam ngay lập tức"],"answer":0,"explain":"Nghị quyết Trung ương 15 (1/1959) xác định con đường cách mạng miền Nam là khởi nghĩa giành chính quyền về tay nhân dân bằng con đường đấu tranh chính trị là chủ yếu, kết hợp đấu tranh vũ trang."},{"id":205,"section":"ch2-2","q":"Phong trào Đồng khởi bùng nổ mạnh mẽ nhất ở tỉnh nào, vào thời gian nào?","options":["Bến Tre, cuối năm 1959 đầu năm 1960","Quảng Trị, trong Tổng tiến công năm 1968","Tây Ninh, trong những năm 1964 - 1965","Long An, trong cao điểm của năm 1972"],"answer":0,"explain":"Phong trào Đồng khởi bùng nổ mạnh mẽ nhất ở Bến Tre, lan rộng khắp Nam Bộ, Tây Nguyên và một số nơi ở Trung Trung Bộ (1959-1960)."},{"id":206,"section":"ch2-2","q":"Mặt trận Dân tộc Giải phóng miền Nam Việt Nam được thành lập vào ngày nào?","options":["Ngày 20/12/1960","Ngày 6/6/1969","Ngày 19/5/1965","Ngày 30/4/1975"],"answer":0,"explain":"Ngày 20/12/1960, Mặt trận Dân tộc Giải phóng miền Nam Việt Nam ra đời, làm nòng cốt cho cuộc đấu tranh của nhân dân miền Nam. (Ngày 6/6/1969 là ngày thành lập Chính phủ Cách mạng lâm thời Cộng hòa miền Nam Việt Nam — một mốc khác, dễ nhầm lẫn.)"},{"id":207,"section":"ch2-2","q":"Sau thất bại của chiến lược \"Chiến tranh đơn phương\", Mỹ chuyển sang chiến lược chiến tranh nào ở miền Nam (1961-1965)?","options":["Chiến tranh đặc biệt","Chiến tranh cục bộ","Việt Nam hóa chiến tranh","Đông Dương hóa chiến tranh"],"answer":0,"explain":"Từ năm 1961, Mỹ - ngụy tiến hành chiến lược \"Chiến tranh đặc biệt\", dùng quân đội tay sai do cố vấn Mỹ chỉ huy, với vũ khí, phương tiện chiến tranh của Mỹ."},{"id":208,"section":"ch2-2","q":"Chiến lược \"Chiến tranh cục bộ\" của Mỹ ở miền Nam Việt Nam được triển khai trong giai đoạn nào?","options":["1965-1968","1961-1965","1969-1973","1954-1960"],"answer":0,"explain":"Từ năm 1965, Mỹ chuyển sang chiến lược \"Chiến tranh cục bộ\", trực tiếp đưa quân viễn chinh Mỹ vào tham chiến ở miền Nam."},{"id":209,"section":"ch2-2","q":"Chiến lược \"Việt Nam hóa chiến tranh\" được Mỹ thực hiện trong giai đoạn nào?","options":["1969-1973","1965-1968","1954-1960","1961-1965"],"answer":0,"explain":"Từ năm 1969, Mỹ thực hiện chiến lược \"Việt Nam hóa chiến tranh\", rút dần quân Mỹ, tăng cường vũ trang và huấn luyện cho quân đội Sài Gòn."},{"id":210,"section":"ch2-2","q":"Cuộc Tổng tiến công và nổi dậy Tết Mậu Thân diễn ra vào năm nào?","options":["Năm 1968","Năm 1965","Năm 1972","Năm 1975"],"answer":0,"explain":"Cuộc Tổng tiến công và nổi dậy Tết Mậu Thân năm 1968 giáng đòn bất ngờ vào ý chí xâm lược của Mỹ, buộc Mỹ phải xuống thang chiến tranh."},{"id":211,"section":"ch2-2","q":"Trận \"Điện Biên Phủ trên không\" diễn ra vào thời gian nào, ở đâu?","options":["Tháng 12/1972, tại Hà Nội và Hải Phòng","Tháng 5/1954, tại Điện Biên Phủ và Hà Nội","Tháng 1/1968, tại Sài Gòn và Huế","Tháng 3/1975, tại Tây Nguyên và Đà Nẵng"],"answer":0,"explain":"Trận \"Điện Biên Phủ trên không\" tháng 12/1972 đánh bại cuộc tập kích chiến lược bằng máy bay B-52 của Mỹ vào Hà Nội, Hải Phòng."},{"id":212,"section":"ch2-2","q":"Hiệp định Paris về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam được ký kết vào ngày nào?","options":["Ngày 27/1/1973","Ngày 21/7/1954","Ngày 30/4/1975","Ngày 29/12/1972"],"answer":0,"explain":"Ngày 27/1/1973, Hiệp định Paris về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam được ký kết, Mỹ phải rút hết quân khỏi miền Nam."},{"id":213,"section":"ch2-2","q":"Cuộc Tổng tiến công và nổi dậy mùa Xuân 1975 mở đầu bằng chiến dịch nào?","options":["Chiến dịch Tây Nguyên","Chiến dịch Huế - Đà Nẵng","Chiến dịch Hồ Chí Minh","Chiến dịch Đường 9 - Nam Lào"],"answer":0,"explain":"Cuộc Tổng tiến công và nổi dậy mùa Xuân 1975 mở đầu bằng chiến dịch Tây Nguyên (3/1975), tiếp đó là chiến dịch Huế - Đà Nẵng, và kết thúc bằng chiến dịch Hồ Chí Minh lịch sử."},{"id":214,"section":"ch2-2","q":"Chiến dịch Hồ Chí Minh giải phóng hoàn toàn miền Nam, thống nhất đất nước vào ngày nào?","options":["Ngày 30/4/1975","Ngày 27/1/1973","Ngày 20/12/1960","Ngày 2/9/1975"],"answer":0,"explain":"Ngày 30/4/1975, chiến dịch Hồ Chí Minh toàn thắng, giải phóng hoàn toàn miền Nam, thống nhất đất nước."},{"id":215,"section":"ch2-2","q":"Sau Hiệp định Giơnevơ 1954, miền Bắc bước vào thời kỳ nào?","options":["Thời kỳ quá độ lên chủ nghĩa xã hội","Thời kỳ chuyển sang chế độ tư bản chủ nghĩa","Thời kỳ thuộc địa kiểu mới của đế quốc","Thời kỳ Pháp thuộc tiếp tục kéo dài"],"answer":0,"explain":"Sau Hiệp định Giơnevơ (1954), miền Bắc hoàn toàn giải phóng, bước vào thời kỳ quá độ lên chủ nghĩa xã hội."},{"id":216,"section":"ch2-2","q":"Kế hoạch 5 năm lần thứ nhất của miền Bắc được thực hiện trong giai đoạn nào?","options":["1961-1965","1954-1960","1965-1968","1969-1975"],"answer":0,"explain":"Kế hoạch 5 năm lần thứ nhất (1961-1965) được thực hiện nhằm bước đầu xây dựng cơ sở vật chất - kỹ thuật của chủ nghĩa xã hội ở miền Bắc."},{"id":217,"section":"ch2-2","q":"Cải cách ruộng đất ở miền Bắc được thực hiện trong giai đoạn nào?","options":["1954-1957","1945-1946","1930-1931","1965-1968"],"answer":0,"explain":"Cải cách ruộng đất được thực hiện ở miền Bắc trong những năm 1954-1957 nhằm thực hiện khẩu hiệu người cày có ruộng."},{"id":218,"section":"ch2-2","q":"Mỹ tiến hành hai lần chiến tranh phá hoại miền Bắc bằng không quân, hải quân vào những giai đoạn nào?","options":["Lần thứ nhất (1965-1968) và lần thứ hai (1972)","Chỉ có một lần duy nhất, kéo dài từ 1965 đến 1972","Lần thứ nhất (1954-1955) và lần thứ hai (1975)","Ba lần liên tục trong giai đoạn từ 1960 đến 1975"],"answer":0,"explain":"Mỹ tiến hành hai lần chiến tranh phá hoại miền Bắc bằng không quân và hải quân: lần thứ nhất (1965-1968) và lần thứ hai (tập trung cao điểm 12/1972)."},{"id":219,"section":"ch2-2","q":"Tổng thống Mỹ nào đã leo thang đưa quân viễn chinh Mỹ trực tiếp tham chiến ở miền Nam Việt Nam (khởi đầu chiến lược Chiến tranh cục bộ)?","options":["Lyndon B. Johnson","John F. Kennedy","Richard Nixon","Dwight Eisenhower"],"answer":0,"explain":"Dưới thời Tổng thống Lyndon B. Johnson, Mỹ leo thang chiến tranh, đưa quân viễn chinh Mỹ trực tiếp tham chiến, thực hiện chiến lược Chiến tranh cục bộ (1965)."},{"id":220,"section":"ch2-2","q":"Chiến dịch nào của quân giải phóng miền Nam đánh dấu bước ngoặt, mở đầu cho cuộc Tổng tiến công mùa Xuân 1975 với thắng lợi tại Buôn Ma Thuột?","options":["Chiến dịch Tây Nguyên","Chiến dịch Huế - Đà Nẵng","Chiến dịch Hồ Chí Minh","Chiến dịch Đường 9 - Khe Sanh"],"answer":0,"explain":"Chiến dịch Tây Nguyên mở màn bằng trận đánh then chốt Buôn Ma Thuột (3/1975), tạo bước ngoặt cho cuộc Tổng tiến công và nổi dậy mùa Xuân 1975."},{"id":221,"section":"ch2-2","q":"Sau Hiệp định Paris (1973), Mỹ vẫn tiếp tục thực hiện âm mưu gì ở miền Nam Việt Nam?","options":["Tiếp tục viện trợ, hậu thuẫn chính quyền Sài Gòn phá hoại hiệp định","Rút toàn bộ viện trợ và ngừng hậu thuẫn chính quyền Sài Gòn","Công nhận hoàn toàn chính quyền cách mạng lâm thời miền Nam","Rút hết quân và chấm dứt mọi sự can thiệp vào miền Nam Việt Nam"],"answer":0,"explain":"Sau Hiệp định Paris, Mỹ vẫn tiếp tục viện trợ quân sự, kinh tế, hậu thuẫn chính quyền Sài Gòn phá hoại hiệp định, âm mưu chia cắt lâu dài đất nước."},{"id":222,"section":"ch2-2","q":"Cuộc Tổng tiến công và nổi dậy Xuân 1975 hoàn thành trong khoảng thời gian bao lâu?","options":["Gần 2 tháng (từ 3/1975 đến 4/1975)","Khoảng 1 năm (từ 4/1974 đến 4/1975)","Khoảng 10 năm (từ 1965 đến 1975)","Khoảng 6 tháng (từ 11/1974 đến 4/1975)"],"answer":0,"explain":"Cuộc Tổng tiến công và nổi dậy Xuân 1975 diễn ra trong gần 2 tháng, từ chiến dịch Tây Nguyên (tháng 3) đến toàn thắng của chiến dịch Hồ Chí Minh (30/4/1975)."},{"id":223,"section":"ch2-2","q":"Ý nghĩa lịch sử to lớn nhất của Đại thắng mùa Xuân 1975 là gì?","options":["Kết thúc 21 năm chống Mỹ, 30 năm chiến tranh giải phóng, thống nhất đất nước","Chỉ có ý nghĩa quân sự, không tác động đến phong trào cách mạng thế giới","Mới giải phóng một phần lãnh thổ miền Nam, còn chia cắt hai miền đất nước","Mở đầu cho thời kỳ Đổi mới toàn diện đất nước theo kinh tế thị trường"],"answer":0,"explain":"Đại thắng mùa Xuân 1975 kết thúc 21 năm kháng chiến chống Mỹ, cứu nước và 30 năm chiến tranh giải phóng dân tộc, bảo vệ Tổ quốc, thống nhất đất nước."},{"id":224,"section":"ch2-2","q":"Trong giai đoạn 1954-1975, đường lối chung của cách mạng Việt Nam thể hiện sự kết hợp giữa hai nhiệm vụ chiến lược nào?","options":["Cách mạng xã hội chủ nghĩa và cách mạng dân tộc dân chủ nhân dân","Cách mạng ruộng đất và cách mạng công nghiệp hóa tư bản chủ nghĩa","Cách mạng văn hóa tư tưởng và cách mạng khoa học kỹ thuật","Cách mạng chính trị tư sản và cách mạng tôn giáo cải cách"],"answer":0,"explain":"Đường lối chung là tiến hành đồng thời cách mạng xã hội chủ nghĩa ở miền Bắc và cách mạng dân tộc dân chủ nhân dân ở miền Nam, tiến tới thống nhất nước nhà."},{"id":225,"section":"ch2-2","q":"Trận \"Điện Biên Phủ trên không\" (12/1972) có ý nghĩa gì đối với việc ký Hiệp định Paris?","options":["Buộc Mỹ phải ký Hiệp định Paris (27/1/1973) chấm dứt chiến tranh","Không có liên hệ gì đến việc ký kết Hiệp định Paris (27/1/1973)","Khiến Việt Nam phải nhượng bộ nhiều hơn trong đàm phán Paris","Làm trì hoãn việc ký Hiệp định Paris thêm 5 năm so với dự kiến"],"answer":0,"explain":"Thắng lợi của trận Điện Biên Phủ trên không đập tan uy thế không quân chiến lược Mỹ, buộc Mỹ phải ký Hiệp định Paris (27/1/1973) chấm dứt chiến tranh."},{"id":226,"section":"ch2-2","q":"Ai là Bí thư thứ nhất Ban Chấp hành Trung ương Đảng Lao động Việt Nam trong phần lớn giai đoạn kháng chiến chống Mỹ?","options":["Lê Duẩn","Hồ Chí Minh","Trường Chinh","Nguyễn Văn Linh"],"answer":0,"explain":"Đồng chí Lê Duẩn giữ cương vị Bí thư thứ nhất Ban Chấp hành Trung ương Đảng trong phần lớn thời kỳ kháng chiến chống Mỹ, cứu nước."},{"id":227,"section":"ch2-2","q":"Đường Hồ Chí Minh (đường mòn Hồ Chí Minh) có vai trò gì trong kháng chiến chống Mỹ?","options":["Tuyến chi viện chiến lược của miền Bắc cho miền Nam","Tuyến đường sắt xuyên Việt nối liền Hà Nội với Sài Gòn","Tuyến đường biên giới Việt - Trung dùng để buôn bán qua lại","Tuyến đường ngoại giao nối liền Việt Nam với Liên Xô"],"answer":0,"explain":"Đường Hồ Chí Minh (trên bộ và trên biển) là tuyến chi viện chiến lược quan trọng, đưa sức người, vũ khí, hậu cần từ miền Bắc vào chi viện cho chiến trường miền Nam."},{"id":228,"section":"ch2-2","q":"Đại hội III của Đảng (1960) đề ra đường lối gì nhằm xây dựng miền Bắc?","options":["Đường lối xây dựng chủ nghĩa xã hội, ưu tiên công nghiệp nặng","Đường lối cải cách, mở cửa hoàn toàn nền kinh tế thị trường","Đường lối tư nhân hóa toàn bộ nền kinh tế miền Bắc ngay từ đầu","Đường lối kinh tế thị trường tự do, bỏ quản lý của Nhà nước"],"answer":0,"explain":"Đại hội III đề ra đường lối xây dựng CNXH ở miền Bắc, chủ trương ưu tiên phát triển công nghiệp nặng một cách hợp lý, đồng thời phát triển nông nghiệp và công nghiệp nhẹ."},{"id":229,"section":"ch2-2","q":"Khẩu hiệu nào dưới đây thể hiện nghĩa vụ hậu phương lớn của miền Bắc đối với tiền tuyến lớn miền Nam?","options":["Thóc không thiếu một cân, quân không thiếu một người","Người cày có ruộng, thực hiện giảm tô giảm tức ở nông thôn","Diệt giặc đói, diệt giặc dốt, diệt giặc ngoại xâm","Toàn dân kháng chiến, toàn diện kháng chiến, trường kỳ"],"answer":0,"explain":"Miền Bắc thực hiện nghĩa vụ hậu phương lớn với khẩu hiệu \"Thóc không thiếu một cân, quân không thiếu một người\" và \"Tất cả cho tiền tuyến, tất cả để chiến thắng\". Các khẩu hiệu còn lại thuộc lĩnh vực cải cách ruộng đất, các giai đoạn đầu cách mạng và kháng chiến chống Pháp."},{"id":230,"section":"ch2-2","q":"Chính phủ Cách mạng lâm thời Cộng hòa miền Nam Việt Nam được thành lập vào thời gian nào?","options":["Tháng 6/1969","Tháng 12/1960","Tháng 1/1973","Tháng 4/1975"],"answer":0,"explain":"Tháng 6/1969, Chính phủ Cách mạng lâm thời Cộng hòa miền Nam Việt Nam được thành lập, đại diện cho nhân dân miền Nam trên trường quốc tế và tại Hội nghị Paris."},{"id":231,"section":"ch2-2","q":"Sự kiện Vịnh Bắc Bộ (8/1964) được Mỹ dựng lên nhằm mục đích gì?","options":["Lấy cớ leo thang chiến tranh phá hoại miền Bắc bằng không quân, hải quân","Mở đường cho đàm phán hòa bình với Việt Nam Dân chủ Cộng hòa tại Paris","Làm cớ để rút quân khỏi miền Nam Việt Nam và chấm dứt can thiệp","Mở đường cho việc ký kết hiệp định thương mại với Việt Nam Dân chủ Cộng hòa"],"answer":0,"explain":"Mỹ dựng lên \"sự kiện Vịnh Bắc Bộ\" (8/1964) làm cớ leo thang chiến tranh, mở đầu cuộc chiến tranh phá hoại miền Bắc bằng không quân và hải quân."},{"id":232,"section":"ch2-2","q":"Nghị quyết Hội nghị Trung ương lần thứ 21 (1973) của Đảng xác định phương pháp cách mạng miền Nam sau Hiệp định Paris là gì?","options":["Con đường cách mạng bạo lực, giữ vững chiến lược tiến công","Chỉ đấu tranh chính trị, ngừng hẳn đấu tranh vũ trang","Thương lượng hòa bình lâu dài với chính quyền Sài Gòn","Chờ đợi sự can thiệp của quốc tế để chấm dứt chiến tranh"],"answer":0,"explain":"Hội nghị Trung ương 21 (1973) khẳng định con đường cách mạng của miền Nam vẫn là con đường cách mạng bạo lực, kiên định giữ vững chiến lược tiến công."},{"id":233,"section":"ch2-2","q":"Cuộc Tổng tiến công và nổi dậy Xuân 1975 kết thúc thắng lợi khi Dinh Độc Lập bị đánh chiếm vào lúc nào ngày 30/4/1975?","options":["11 giờ 30 phút trưa","6 giờ 15 phút sáng","18 giờ 30 phút chiều","23 giờ 30 phút đêm"],"answer":0,"explain":"Đến 11 giờ 30 phút trưa ngày 30/4/1975, xe tăng quân giải phóng tiến vào Dinh Độc Lập, Tổng thống ngụy quyền Dương Văn Minh tuyên bố đầu hàng không điều kiện."},{"id":234,"section":"ch2-2","q":"Một trong những bài học kinh nghiệm lớn của Đảng trong lãnh đạo kháng chiến chống Mỹ, cứu nước là gì?","options":["Giương cao ngọn cờ độc lập dân tộc gắn liền với chủ nghĩa xã hội","Chỉ dựa hoàn toàn vào viện trợ của các nước xã hội chủ nghĩa","Từ bỏ đấu tranh vũ trang, chỉ dựa vào đấu tranh ngoại giao","Ưu tiên phát triển kinh tế trước, hoãn nhiệm vụ giải phóng miền Nam"],"answer":0,"explain":"Bài học kinh nghiệm quan trọng là giương cao ngọn cờ độc lập dân tộc và chủ nghĩa xã hội, kết hợp sức mạnh dân tộc với sức mạnh thời đại để giành thắng lợi."},{"id":235,"section":"ch2-2","q":"Cuộc kháng chiến chống Mỹ, cứu nước của nhân dân Việt Nam kéo dài trong bao nhiêu năm?","options":["21 năm (1954-1975)","9 năm (1945-1954)","30 năm (1945-1975)","15 năm (1960-1975)"],"answer":0,"explain":"Cuộc kháng chiến chống Mỹ, cứu nước kéo dài 21 năm, từ 1954 đến toàn thắng ngày 30/4/1975."},{"id":236,"section":"ch2-2","q":"Trong chiến lược \"Chiến tranh đặc biệt\", quân đội chủ yếu do ai chỉ huy, trang bị vũ khí của nước nào?","options":["Quân đội Sài Gòn do cố vấn Mỹ chỉ huy, dùng vũ khí của Mỹ","Quân viễn chinh Mỹ trực tiếp chỉ huy, dùng vũ khí của Mỹ","Quân đội Pháp do tướng Pháp chỉ huy, dùng vũ khí của Pháp","Quân đội Nhật Bản do sĩ quan Nhật chỉ huy, dùng vũ khí Nhật"],"answer":0,"explain":"Trong \"Chiến tranh đặc biệt\", Mỹ sử dụng quân đội Sài Gòn làm công cụ, do cố vấn Mỹ chỉ huy, được trang bị vũ khí, phương tiện chiến tranh hiện đại của Mỹ."},{"id":237,"section":"ch2-2","q":"Chiến thắng Ấp Bắc (Mỹ Tho, 1/1963) có ý nghĩa gì đối với cuộc kháng chiến chống \"Chiến tranh đặc biệt\"?","options":["Chứng minh có thể đánh bại chiến thuật \"trực thăng vận\", \"thiết xa vận\"","Đánh dấu sự sụp đổ hoàn toàn của chính quyền Sài Gòn ở miền Nam Việt Nam","Mở đầu cuộc Tổng tiến công và nổi dậy Tết Mậu Thân năm 1968 ở Sài Gòn","Kết thúc chiến tranh chống Mỹ, buộc Mỹ ký Hiệp định Paris năm 1973"],"answer":0,"explain":"Chiến thắng Ấp Bắc (đầu 1963) chứng minh quân dân miền Nam có thể đánh bại các chiến thuật cơ động mới của Mỹ - ngụy, mở ra phong trào \"Thi đua Ấp Bắc, giết giặc lập công\"."},{"id":238,"section":"ch2-2","q":"Chiến thắng Vạn Tường (Quảng Ngãi, 8/1965) có ý nghĩa gì?","options":["Là trận đầu đánh thắng quân viễn chinh Mỹ trong chiến lược Chiến tranh cục bộ","Là trận đánh cuối cùng của cuộc kháng chiến chống Mỹ, cứu nước ở Quảng Ngãi","Là trận đánh mở đầu chiến dịch Hồ Chí Minh giải phóng Sài Gòn năm 1975","Đánh dấu Mỹ rút hoàn toàn quân đội khỏi Việt Nam theo Hiệp định Paris"],"answer":0,"explain":"Chiến thắng Vạn Tường (8/1965) là trận đầu quân dân miền Nam đánh thắng trực tiếp quân viễn chinh Mỹ, mở đầu cho phong trào \"tìm Mỹ mà đánh, lùng ngụy mà diệt\"."},{"id":239,"section":"ch2-2","q":"Đế quốc Mỹ tuyên bố ngừng ném bom miền Bắc và chấp nhận đàm phán với Việt Nam Dân chủ Cộng hòa tại Hội nghị Paris bắt đầu vào năm nào?","options":["Năm 1968","Năm 1965","Năm 1972","Năm 1973"],"answer":0,"explain":"Sau đòn bất ngờ của cuộc Tổng tiến công Mậu Thân 1968, Mỹ buộc phải tuyên bố ngừng ném bom miền Bắc và chấp nhận đàm phán tại Hội nghị Paris (khai mạc 1968)."},{"id":240,"section":"ch2-2","q":"Cuộc tiến công chiến lược năm 1972 (Xuân - Hè 1972) của quân giải phóng mở màn ở đâu?","options":["Mặt trận Quảng Trị","Mặt trận Tây Nguyên","Mặt trận Sài Gòn","Mặt trận miền Tây Nam Bộ"],"answer":0,"explain":"Cuộc tiến công chiến lược năm 1972 mở màn ở mặt trận Quảng Trị, gây tổn thất nặng nề cho quân đội Sài Gòn, buộc Mỹ phải xuống thang hơn nữa."},{"id":241,"section":"ch2-2","q":"Chiến dịch Hồ Chí Minh được Bộ Chính trị quyết định mở, mang tên Chủ tịch Hồ Chí Minh, diễn ra trong khoảng thời gian nào?","options":["Từ 26/4 đến 30/4/1975","Từ 10/3 đến 30/4/1975","Từ 1/4 đến 15/4/1975","Từ 12/1972 đến 1/1973"],"answer":0,"explain":"Chiến dịch Hồ Chí Minh (đợt cuối của cuộc Tổng tiến công Xuân 1975) diễn ra từ 26/4 đến 30/4/1975, đánh thẳng vào sào huyệt cuối cùng của địch tại Sài Gòn."},{"id":242,"section":"ch2-2","q":"Cách gọi \"hậu phương lớn\" và \"tiền tuyến lớn\" trong kháng chiến chống Mỹ dùng để chỉ điều gì?","options":["Miền Bắc là hậu phương lớn, miền Nam là tiền tuyến lớn","Miền Nam là hậu phương lớn, miền Bắc là tiền tuyến lớn","Cả hai miền đều là hậu phương lớn của cách mạng cả nước","Cả hai miền đều là tiền tuyến lớn của cách mạng cả nước"],"answer":0,"explain":"Miền Bắc được xác định là hậu phương lớn, chi viện sức người sức của cho miền Nam - tiền tuyến lớn của cả nước."},{"id":243,"section":"ch2-2","q":"Ai là Chủ tịch Ủy ban Trung ương Mặt trận Dân tộc Giải phóng miền Nam Việt Nam?","options":["Luật sư Nguyễn Hữu Thọ","Kiến trúc sư Huỳnh Tấn Phát","Bà Nguyễn Thị Bình","Thượng tướng Trần Văn Trà"],"answer":0,"explain":"Luật sư Nguyễn Hữu Thọ là Chủ tịch Ủy ban Trung ương Mặt trận Dân tộc Giải phóng miền Nam Việt Nam."},{"id":244,"section":"ch2-2","q":"Trong Hiệp định Paris (1973), Mỹ cam kết điều gì liên quan đến chủ quyền và toàn vẹn lãnh thổ Việt Nam?","options":["Tôn trọng độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ","Duy trì quân đội và căn cứ quân sự Mỹ tại miền Nam vô thời hạn","Công nhận sự chia cắt vĩnh viễn hai miền Nam - Bắc Việt Nam","Thiết lập chính quyền quân sự do Mỹ điều hành tại miền Nam"],"answer":0,"explain":"Hiệp định Paris quy định Mỹ và các nước cam kết tôn trọng độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ của Việt Nam."},{"id":245,"section":"ch2-2","q":"Kết quả của kế hoạch 5 năm lần thứ nhất (1961-1965) ở miền Bắc là gì?","options":["Bước đầu xây dựng cơ sở vật chất - kỹ thuật của chủ nghĩa xã hội","Hoàn thành công nghiệp hóa, hiện đại hóa toàn diện nền kinh tế","Chuyển hoàn toàn sang nền kinh tế thị trường tự do ở miền Bắc","Xóa bỏ hoàn toàn mọi thành phần kinh tế tư nhân và cá thể"],"answer":0,"explain":"Kế hoạch 5 năm lần thứ nhất (1961-1965) đạt được những thành tựu bước đầu quan trọng trong xây dựng cơ sở vật chất - kỹ thuật của CNXH ở miền Bắc."},{"id":246,"section":"ch2-2","q":"Mỹ đã sử dụng loại vũ khí hóa học nào trong chiến tranh xâm lược Việt Nam, gây hậu quả lâu dài?","options":["Chất độc da cam/dioxin","Bom hạt nhân chiến thuật","Vũ khí sinh học diện rộng","Bom điện từ công suất lớn"],"answer":0,"explain":"Mỹ rải chất độc da cam/dioxin trên diện rộng ở miền Nam Việt Nam, gây hậu quả nặng nề, lâu dài cho môi trường và sức khỏe con người."},{"id":247,"section":"ch2-2","q":"Trước khi tiến hành Tổng tiến công và nổi dậy mùa Xuân 1975, Bộ Chính trị đã đề ra kế hoạch chiến lược giải phóng miền Nam trong thời gian nào?","options":["Giải phóng trong hai năm 1975-1976, có thời cơ thì làm ngay năm 1975","Giải phóng trong 10 năm, từ 1975 đến 1985, theo từng giai đoạn nhỏ","Giải phóng ngay trong năm 1973, ngay sau khi ký Hiệp định Paris","Không xác định thời gian cụ thể, chờ thời cơ quốc tế thuận lợi"],"answer":0,"explain":"Bộ Chính trị đề ra kế hoạch giải phóng hoàn toàn miền Nam trong hai năm 1975-1976, đồng thời nhấn mạnh nếu thời cơ đến vào đầu hoặc cuối 1975 thì lập tức giải phóng trong năm 1975."},{"id":248,"section":"ch2-2","q":"Đường Trường Sơn (đường Hồ Chí Minh trên bộ) bắt đầu được xây dựng, khai thông từ năm nào?","options":["Năm 1959","Năm 1954","Năm 1965","Năm 1968"],"answer":0,"explain":"Tuyến đường Trường Sơn (đường Hồ Chí Minh) được bắt đầu xây dựng, khai thông từ năm 1959 để chi viện cho chiến trường miền Nam."},{"id":249,"section":"ch2-2","q":"Trong giai đoạn kháng chiến chống Mỹ, Đảng ta xác định kẻ thù trực tiếp và nguy hiểm nhất của cách mạng miền Nam là ai?","options":["Đế quốc Mỹ và chính quyền tay sai Sài Gòn","Thực dân Pháp và bọn tay sai phong kiến","Phong kiến địa chủ và tư sản mại bản","Quân đội Trung Hoa dân quốc và tay sai"],"answer":0,"explain":"Kẻ thù trực tiếp, nguy hiểm nhất của cách mạng miền Nam giai đoạn này được xác định là đế quốc Mỹ và chính quyền tay sai Sài Gòn."},{"id":250,"section":"ch2-2","q":"Chiến dịch Đường 9 - Nam Lào (1971) nhằm đánh bại âm mưu gì của địch?","options":["Cắt đứt tuyến chi viện chiến lược của ta","Tấn công ra miền Bắc Việt Nam bằng đường bộ","Phá vỡ vùng giải phóng ở đồng bằng sông Cửu Long","Phong tỏa cảng Hải Phòng và vùng biển miền Bắc"],"answer":0,"explain":"Chiến dịch phản công Đường 9 - Nam Lào (1971) đánh bại cuộc hành quân Lam Sơn 719 của địch nhằm cắt đứt tuyến chi viện chiến lược đường Hồ Chí Minh."},{"id":251,"section":"ch2-2","q":"Đại hội III của Đảng (1960) đã bầu ai làm Bí thư thứ nhất Ban Chấp hành Trung ương Đảng?","options":["Lê Duẩn (Ủy viên Bộ Chính trị)","Hồ Chí Minh (Chủ tịch Đảng)","Trường Chinh (Ủy viên Bộ Chính trị)","Phạm Văn Đồng (Thủ tướng Chính phủ)"],"answer":0,"explain":"Đại hội III bầu đồng chí Lê Duẩn làm Bí thư thứ nhất Ban Chấp hành Trung ương Đảng (Hồ Chí Minh tiếp tục là Chủ tịch Đảng)."},{"id":252,"section":"ch2-2","q":"Phong trào \"tìm Mỹ mà đánh, lùng ngụy mà diệt\" xuất hiện gắn với giai đoạn chiến lược nào của Mỹ?","options":["Chiến tranh cục bộ (1965-1968)","Chiến tranh đặc biệt (1961-1965)","Việt Nam hóa chiến tranh (1969-1973)","Chiến tranh đơn phương (1954-1960)"],"answer":0,"explain":"Khi Mỹ đưa quân viễn chinh trực tiếp tham chiến (Chiến tranh cục bộ), quân dân miền Nam phát động phong trào \"tìm Mỹ mà đánh, lùng ngụy mà diệt\"."},{"id":253,"section":"ch2-2","q":"Ngày 2/9/1969, sự kiện lịch sử quan trọng nào diễn ra?","options":["Chủ tịch Hồ Chí Minh qua đời tại Hà Nội","Ký kết Hiệp định Paris chấm dứt chiến tranh","Thành lập Mặt trận Giải phóng miền Nam","Giải phóng hoàn toàn miền Nam Việt Nam"],"answer":0,"explain":"Ngày 2/9/1969, Chủ tịch Hồ Chí Minh qua đời, để lại bản Di chúc thiêng liêng cho toàn Đảng, toàn dân, toàn quân."},{"id":254,"section":"ch2-2","q":"Trong Di chúc, Chủ tịch Hồ Chí Minh căn dặn điều gì về việc thống nhất đất nước?","options":["Tin tưởng kháng chiến chống Mỹ thắng lợi, Bắc Nam sum họp một nhà","Chủ trương duy trì tình trạng chia cắt hai miền trong thời gian dài","Kêu gọi ngừng kháng chiến để đàm phán hòa bình vô điều kiện với Mỹ","Chỉ căn dặn về xây dựng Đảng, không nhắc đến thống nhất đất nước"],"answer":0,"explain":"Trong Di chúc, Hồ Chí Minh khẳng định niềm tin cuộc kháng chiến chống Mỹ, cứu nước nhất định thắng lợi, Tổ quốc nhất định thống nhất, đồng bào Nam Bắc nhất định sum họp một nhà."},{"id":255,"section":"ch2-2","q":"Sau Đại thắng mùa Xuân 1975, đất nước Việt Nam bước vào giai đoạn cách mạng mới với nhiệm vụ trọng tâm là gì?","options":["Thống nhất đất nước về mặt nhà nước, đưa cả nước đi lên chủ nghĩa xã hội","Chia tách đất nước thành hai quốc gia độc lập ở hai miền Nam - Bắc","Duy trì chế độ quân quản lâu dài ở miền Nam, hoãn thống nhất đất nước","Chuyển ngay sang nền kinh tế thị trường tự do trên phạm vi cả nước"],"answer":0,"explain":"Sau Đại thắng mùa Xuân 1975, nhiệm vụ trọng tâm là hoàn thành thống nhất đất nước về mặt nhà nước và đưa cả nước quá độ lên chủ nghĩa xã hội."},{"id":256,"section":"ch2-2","q":"Trong kháng chiến chống Mỹ, phong trào thi đua nào ở miền Bắc gắn với khẩu hiệu \"Mỗi người làm việc bằng hai vì miền Nam ruột thịt\"?","options":["Thi đua lao động sản xuất và chiến đấu ở miền Bắc","Phong trào Đồng khởi (1959-1960) ở các tỉnh miền Nam","Phong trào \"Ấp Bắc, giết giặc lập công\" ở miền Nam","Phong trào \"tìm Mỹ mà đánh\" ở chiến trường miền Nam"],"answer":0,"explain":"Ở miền Bắc, phong trào thi đua lao động sản xuất với khẩu hiệu \"Mỗi người làm việc bằng hai vì miền Nam ruột thịt\" được phát động rộng khắp."},{"id":257,"section":"ch2-2","q":"Trận chiến 81 ngày đêm bảo vệ Thành cổ Quảng Trị diễn ra vào năm nào?","options":["Năm 1972","Năm 1968","Năm 1965","Năm 1975"],"answer":0,"explain":"Trận chiến đấu 81 ngày đêm bảo vệ Thành cổ Quảng Trị diễn ra trong mùa hè năm 1972, thể hiện tinh thần chiến đấu kiên cường của quân dân ta."},{"id":258,"section":"ch2-2","q":"Trước khi mở chiến dịch Hồ Chí Minh, quân giải phóng đã giành thắng lợi quyết định nào ở miền Trung?","options":["Chiến dịch Huế - Đà Nẵng (3/1975)","Chiến dịch Điện Biên Phủ (1954)","Chiến dịch Mậu Thân (1968)","Chiến dịch Đường 9 Nam Lào (1971)"],"answer":0,"explain":"Sau chiến dịch Tây Nguyên, quân giải phóng tiếp tục giành thắng lợi ở chiến dịch Huế - Đà Nẵng (tháng 3/1975), tạo đà cho chiến dịch Hồ Chí Minh."},{"id":259,"section":"ch2-2","q":"Ý nghĩa quốc tế của cuộc kháng chiến chống Mỹ, cứu nước của nhân dân Việt Nam là gì?","options":["Cổ vũ phong trào giải phóng dân tộc thế giới, làm suy yếu chủ nghĩa đế quốc","Không có ý nghĩa gì đối với phong trào cách mạng và hòa bình thế giới","Chỉ có ý nghĩa trong phạm vi ba nước Đông Dương, không lan rộng ra ngoài","Làm chậm lại phong trào giải phóng dân tộc ở châu Phi và châu Mỹ Latinh"],"answer":0,"explain":"Thắng lợi của cuộc kháng chiến chống Mỹ có ý nghĩa quốc tế to lớn, góp phần cổ vũ mạnh mẽ phong trào giải phóng dân tộc, làm suy yếu chủ nghĩa đế quốc."},{"id":260,"section":"ch2-2","q":"Trước năm 1965, chiến lược của Mỹ ở miền Nam (1954-1960) được gọi là gì?","options":["Chiến tranh đơn phương","Chiến tranh đặc biệt","Chiến tranh cục bộ","Việt Nam hóa chiến tranh"],"answer":0,"explain":"Giai đoạn 1954-1960, Mỹ - Diệm thực hiện chính sách được gọi là \"chiến tranh đơn phương\", dùng quân đội tay sai đàn áp phong trào cách mạng miền Nam."},{"id":261,"section":"ch2-2","q":"Nghị quyết Hội nghị Trung ương lần thứ 11 và 12 (1965) của Đảng đề ra chủ trương gì khi Mỹ leo thang Chiến tranh cục bộ?","options":["Quyết tâm đánh Mỹ và thắng Mỹ trên cả hai miền Nam - Bắc","Chủ trương chấp nhận đàm phán hòa bình ngay lập tức với Mỹ","Chủ trương rút lui về phòng ngự chiến lược ở vùng rừng núi","Chủ trương chuyển hướng sang đấu tranh ngoại giao đơn thuần"],"answer":0,"explain":"Trước sự leo thang của Mỹ, các Nghị quyết Trung ương (1965) khẳng định quyết tâm đánh Mỹ và thắng Mỹ trên cả hai miền Nam - Bắc."},{"id":262,"section":"ch2-2","q":"Trong kháng chiến chống Mỹ, hình thức đấu tranh nào được xem là \"ba mũi giáp công\"?","options":["Đấu tranh quân sự, chính trị và binh vận","Đấu tranh kinh tế, văn hóa và ngoại giao","Đấu tranh công khai, bí mật và vũ trang","Đấu tranh trong nước, ngoài nước và quốc tế"],"answer":0,"explain":"Phương châm đấu tranh \"ba mũi giáp công\" của cách mạng miền Nam gồm đấu tranh quân sự, đấu tranh chính trị và công tác binh vận (địch vận)."},{"id":263,"section":"ch2-2","q":"Sau khi ký Hiệp định Paris, Chính phủ Cách mạng lâm thời Cộng hòa miền Nam Việt Nam kiểm soát vùng nào?","options":["Nhiều vùng giải phóng rộng lớn ở nông thôn miền Nam","Toàn bộ lãnh thổ miền Nam Việt Nam, kể cả Sài Gòn","Chỉ khu vực biên giới Việt - Lào và vùng núi phía Tây","Không kiểm soát được vùng lãnh thổ nào ở miền Nam"],"answer":0,"explain":"Sau Hiệp định Paris, Chính phủ Cách mạng lâm thời Cộng hòa miền Nam Việt Nam kiểm soát nhiều vùng giải phóng rộng lớn ở nông thôn miền Nam."},{"id":264,"section":"ch2-2","q":"Chiến thắng Phước Long (đầu năm 1975) có ý nghĩa gì đối với quyết định của Bộ Chính trị?","options":["Là \"trận trinh sát chiến lược\", củng cố quyết tâm giải phóng miền Nam năm 1975","Là thất bại lớn của quân giải phóng, buộc Bộ Chính trị hoãn kế hoạch giải phóng","Là chiến thắng cuối cùng, kết thúc chiến tranh ngay lập tức trên cả nước","Không có ý nghĩa chiến lược, chỉ là trận đánh nhỏ ở vùng rừng núi biên giới"],"answer":0,"explain":"Chiến thắng Phước Long (đầu 1975) được xem như \"trận trinh sát chiến lược\", cho thấy khả năng suy yếu của quân đội Sài Gòn, củng cố quyết tâm của Bộ Chính trị giải phóng miền Nam trong năm 1975."},{"id":265,"section":"ch2-2","q":"Trong 21 năm kháng chiến chống Mỹ, Đảng Lao động Việt Nam đã triệu tập bao nhiêu kỳ Đại hội đại biểu toàn quốc?","options":["Một kỳ Đại hội (Đại hội lần thứ III, 1960)","Hai kỳ Đại hội (Đại hội lần thứ II và III)","Ba kỳ Đại hội (Đại hội lần thứ III, IV, V)","Không tổ chức kỳ Đại hội nào trong 21 năm"],"answer":0,"explain":"Trong giai đoạn 1954-1975, Đảng chỉ tổ chức một kỳ Đại hội đại biểu toàn quốc là Đại hội III (1960); Đại hội IV được tổ chức sau khi thống nhất đất nước (1976)."},{"id":266,"section":"ch2-2","q":"Cuộc kháng chiến chống Mỹ, cứu nước thắng lợi đã đưa cả nước bước vào thời kỳ nào?","options":["Thời kỳ cả nước độc lập, thống nhất, cùng đi lên chủ nghĩa xã hội","Thời kỳ đất nước tiếp tục bị chia cắt thành hai miền Nam - Bắc","Thời kỳ nội chiến giữa các phe phái chính trị trong nước","Thời kỳ Mỹ tiếp tục kiểm soát chính quyền ở miền Nam Việt Nam"],"answer":0,"explain":"Thắng lợi của cuộc kháng chiến chống Mỹ đưa cả nước độc lập, thống nhất, cùng đi lên chủ nghĩa xã hội."},{"id":267,"section":"ch2-2","q":"Miền Bắc đã bắn rơi bao nhiêu máy bay B-52 của Mỹ trong 12 ngày đêm cuối tháng 12/1972 (theo con số phổ biến trong lịch sử)?","options":["34 máy bay B-52","5 máy bay B-52","100 máy bay B-52","0 máy bay B-52"],"answer":0,"explain":"Trong 12 ngày đêm cuối 1972, quân dân miền Bắc đã bắn rơi nhiều máy bay Mỹ trong đó có 34 máy bay B-52, làm nên chiến thắng \"Điện Biên Phủ trên không\"."},{"id":268,"section":"ch2-2","q":"Đường lối kháng chiến chống Mỹ, cứu nước của Đảng đã kết hợp chặt chẽ giữa các mặt trận đấu tranh nào?","options":["Đấu tranh quân sự, chính trị và ngoại giao","Chỉ đấu tranh quân sự trên chiến trường","Chỉ đấu tranh ngoại giao tại bàn đàm phán","Đấu tranh kinh tế và văn hóa là chủ yếu"],"answer":0,"explain":"Đường lối kháng chiến chống Mỹ kết hợp chặt chẽ đấu tranh quân sự, đấu tranh chính trị và đấu tranh ngoại giao, tạo thành sức mạnh tổng hợp."},{"id":269,"section":"ch2-2","q":"Trước năm 1975, thủ đô của chính quyền Việt Nam Cộng hòa (chế độ Sài Gòn) đặt tại đâu?","options":["Sài Gòn","Huế","Đà Nẵng","Cần Thơ"],"answer":0,"explain":"Chính quyền Việt Nam Cộng hòa (chế độ Sài Gòn, do Mỹ dựng lên và hậu thuẫn) đặt thủ đô tại Sài Gòn cho đến ngày giải phóng 30/4/1975."},{"id":270,"section":"ch2-2","q":"Sự kiện nào đánh dấu việc quân đội Mỹ hoàn toàn rút khỏi miền Nam Việt Nam theo Hiệp định Paris?","options":["Mỹ rút quân viễn chinh và chư hầu khỏi miền Nam trong 60 ngày sau 27/1/1973","Mỹ rút hết quân viễn chinh ngay sau cuộc Tổng tiến công Tết Mậu Thân 1968","Mỹ rút hết quân sau chiến thắng Điện Biên Phủ trên không tháng 12/1972","Mỹ không rút quân mà duy trì lực lượng chiến đấu tại miền Nam đến 4/1975"],"answer":0,"explain":"Theo Hiệp định Paris (27/1/1973), Mỹ phải rút hết quân viễn chinh và quân các nước chư hầu khỏi miền Nam Việt Nam trong vòng 60 ngày."},{"id":664,"section":"ch2-2","q":"Sau Hiệp định Giơnevơ 1954, đế quốc Mỹ đã thực hiện âm mưu gì đối với miền Nam Việt Nam?","options":["Hất cẳng Pháp, dựng chính quyền Ngô Đình Diệm, biến miền Nam thành thuộc địa kiểu mới","Tôn trọng và thực hiện nghiêm chỉnh mọi điều khoản của Hiệp định Giơnevơ về Việt Nam","Rút hoàn toàn khỏi Đông Nam Á, trao trả quyền tự quyết cho nhân dân miền Nam","Ủng hộ tổ chức tổng tuyển cử thống nhất Việt Nam vào năm 1956 theo Hiệp định"],"answer":0,"explain":"Ngay sau Hiệp định Giơnevơ, Mỹ từng bước thay chân Pháp, dựng lên chính quyền tay sai Ngô Đình Diệm ở miền Nam, biến miền Nam Việt Nam thành thuộc địa kiểu mới, căn cứ quân sự nhằm ngăn chặn chủ nghĩa cộng sản ở Đông Nam Á."},{"id":665,"section":"ch2-2","q":"Hội nghị Trung ương lần thứ 15 (1/1959) có ý nghĩa như thế nào đối với cách mạng miền Nam?","options":["Xác định con đường cơ bản của cách mạng miền Nam là khởi nghĩa giành chính quyền","Chủ trương tiếp tục đấu tranh hòa bình đơn thuần, không kết hợp với đấu tranh vũ trang","Chủ trương chuyển toàn bộ trọng tâm của cách mạng cả nước ra miền Bắc để xây dựng","Chủ trương chờ sự can thiệp trực tiếp của quốc tế rồi mới tiến hành khởi nghĩa"],"answer":0,"explain":"Nghị quyết Hội nghị Trung ương 15 (1/1959) có ý nghĩa lịch sử quan trọng, xác định con đường phát triển cơ bản của cách mạng miền Nam là khởi nghĩa giành chính quyền về tay nhân dân bằng con đường đấu tranh chính trị là chủ yếu, kết hợp với đấu tranh vũ trang, mở đường cho phong trào Đồng khởi."},{"id":666,"section":"ch2-2","q":"Trước khi phong trào Đồng khởi bùng nổ, chính quyền Ngô Đình Diệm đã ban hành đạo luật phát xít nào để đàn áp khốc liệt phong trào cách mạng miền Nam?","options":["Luật 10/59, đặt cộng sản ra ngoài vòng pháp luật","Luật Cải cách điền địa, chia lại ruộng đất cho nông dân","Luật trưng cầu dân ý nhằm phế truất Bảo Đại","Luật ân xá cho tù chính trị trên toàn miền Nam"],"answer":0,"explain":"Luật 10/59 do chính quyền Ngô Đình Diệm ban hành đặt những người cộng sản và người yêu nước ra ngoài vòng pháp luật, cho phép xử tử hình không cần xét xử, gây ra làn sóng khủng bố tàn khốc, đẩy phong trào cách mạng miền Nam tới chỗ phải vùng lên đấu tranh vũ trang tự vệ, dẫn tới Đồng khởi."},{"id":667,"section":"ch2-2","q":"Chương trình hành động của Mặt trận Dân tộc Giải phóng miền Nam Việt Nam (công bố sau khi thành lập) nêu mục tiêu trước mắt là gì?","options":["Đoàn kết toàn dân, đánh đổ Mỹ - Diệm, thành lập chính quyền liên hợp dân tộc dân chủ","Sáp nhập ngay miền Nam vào miền Bắc, lập nhà nước xã hội chủ nghĩa thống nhất","Chỉ đấu tranh đòi cải thiện đời sống kinh tế, không đề cập vấn đề chính quyền","Hợp tác toàn diện, không điều kiện với chính quyền Sài Gòn và Mỹ để xây dựng đất nước"],"answer":0,"explain":"Chương trình hành động của Mặt trận Dân tộc Giải phóng miền Nam Việt Nam xác định mục tiêu đoàn kết toàn dân, kiên quyết đấu tranh đánh đổ ách thống trị của đế quốc Mỹ và tập đoàn tay sai, thành lập chính quyền liên hợp dân tộc dân chủ, tiến tới hòa bình thống nhất Tổ quốc."},{"id":668,"section":"ch2-2","q":"Đại hội đại biểu toàn quốc lần thứ III của Đảng (9/1960) xác định miền Bắc có vai trò gì đối với cách mạng cả nước?","options":["Miền Bắc là hậu phương lớn, có vai trò quyết định nhất đối với cả nước","Miền Bắc chỉ có vai trò thứ yếu, không quan trọng đối với cách mạng cả nước","Miền Bắc không có vai trò gì trong việc chi viện cho cách mạng miền Nam","Miền Bắc chỉ tập trung phát triển kinh tế, không liên quan quân sự"],"answer":0,"explain":"Đại hội III (9/1960) xác định cách mạng xã hội chủ nghĩa ở miền Bắc có vai trò quyết định nhất đối với sự phát triển của toàn bộ cách mạng Việt Nam, miền Bắc là hậu phương lớn, chi viện sức người, sức của cho tiền tuyến lớn miền Nam."},{"id":669,"section":"ch2-2","q":"Đại hội III của Đảng (9/1960) chỉ rõ nhiệm vụ của cách mạng miền Nam về mặt tính chất là gì?","options":["Cách mạng dân tộc dân chủ nhân dân, đánh đổ ách thống trị của Mỹ và tay sai","Cách mạng xã hội chủ nghĩa hoàn chỉnh, giống như ở miền Bắc lúc bấy giờ","Cách mạng cải lương, chỉ đòi cải cách trong khuôn khổ chính quyền Sài Gòn","Cách mạng dân chủ tư sản kiểu phương Tây, không có sự lãnh đạo của Đảng"],"answer":0,"explain":"Đại hội III (9/1960) xác định cách mạng miền Nam là cách mạng dân tộc dân chủ nhân dân, có nhiệm vụ đánh đổ ách thống trị của đế quốc Mỹ và tập đoàn tay sai, thực hiện độc lập dân tộc và người cày có ruộng, hoàn thành cách mạng dân tộc dân chủ nhân dân ở miền Nam."},{"id":670,"section":"ch2-2","q":"Miền Bắc bước vào thực hiện kế hoạch 5 năm lần thứ nhất (1961-1965) với mục tiêu tổng quát nào?","options":["Bước đầu xây dựng cơ sở vật chất - kỹ thuật của chủ nghĩa xã hội","Chỉ tập trung duy nhất vào phát triển nông nghiệp lúa nước","Tập trung toàn bộ nguồn lực cho chiến tranh, không phát triển kinh tế","Chuyển hoàn toàn sang nền kinh tế thị trường tự do theo mô hình tư bản"],"answer":0,"explain":"Kế hoạch 5 năm lần thứ nhất (1961-1965) đặt mục tiêu bước đầu xây dựng cơ sở vật chất - kỹ thuật của chủ nghĩa xã hội, thực hiện một bước công nghiệp hóa xã hội chủ nghĩa, cải thiện đời sống nhân dân miền Bắc."},{"id":671,"section":"ch2-2","q":"Chiến lược \"Chiến tranh đặc biệt\" (1961-1965) của đế quốc Mỹ ở miền Nam có đặc điểm cơ bản nào?","options":["Dùng quân đội Sài Gòn là chủ yếu, dựa vào cố vấn và vũ khí, trang bị của Mỹ","Sử dụng trực tiếp quân viễn chinh Mỹ làm lực lượng chủ yếu trên chiến trường","Chỉ tiến hành chiến tranh bằng không quân, không có lực lượng bộ binh mặt đất","Chỉ tiến hành đấu tranh ngoại giao và kinh tế, không dùng biện pháp quân sự"],"answer":0,"explain":"\"Chiến tranh đặc biệt\" là hình thức chiến tranh xâm lược thực dân kiểu mới, được tiến hành bằng quân đội tay sai Sài Gòn là chủ yếu, dưới sự chỉ huy của hệ thống cố vấn quân sự Mỹ, dựa vào vũ khí, trang bị, phương tiện chiến tranh của Mỹ."},{"id":672,"section":"ch2-2","q":"Chiến thuật \"trực thăng vận\", \"thiết xa vận\" mà quân đội Sài Gòn sử dụng trong \"Chiến tranh đặc biệt\" nhằm mục đích chủ yếu gì?","options":["Cơ động nhanh để càn quét, tiêu diệt lực lượng cách mạng, lập ấp chiến lược","Vận chuyển lương thực, hàng hóa dân sự phục vụ đời sống nhân dân nông thôn","Xây dựng hệ thống giao thông phục vụ phát triển kinh tế ở nông thôn miền Nam","Chỉ phục vụ mục đích trinh sát, không có chức năng tác chiến trực tiếp"],"answer":0,"explain":"Chiến thuật \"trực thăng vận\" (dùng máy bay lên thẳng) và \"thiết xa vận\" (dùng xe bọc thép) là chiến thuật cơ động nhanh của quân đội Sài Gòn dưới sự cố vấn Mỹ, nhằm bất ngờ càn quét, bao vây tiêu diệt lực lượng cách mạng, hỗ trợ chương trình bình định gom dân vào \"ấp chiến lược\"."},{"id":673,"section":"ch2-2","q":"Trong công cuộc xây dựng chủ nghĩa xã hội ở miền Bắc giai đoạn 1954-1965, phong trào thi đua nào gắn liền với lao động sản xuất, xây dựng chủ nghĩa xã hội được phát động rộng khắp?","options":["Phong trào \"Gió Đại Phong\", \"Sóng Duyên Hải\", \"Cờ Ba nhất\"","Phong trào Đông Du do Phan Bội Châu khởi xướng đầu thế kỷ XX","Phong trào Xô viết Nghệ - Tĩnh trong những năm 1930-1931","Phong trào Đồng khởi ở miền Nam trong những năm 1959-1960"],"answer":0,"explain":"Trong xây dựng chủ nghĩa xã hội ở miền Bắc, nhiều phong trào thi đua yêu nước được phát động gắn với các điển hình tiên tiến trong nông nghiệp, công nghiệp, quân đội như \"Gió Đại Phong\" (nông nghiệp), \"Sóng Duyên Hải\" (công nghiệp), \"Cờ Ba nhất\" (quân đội)."},{"id":674,"section":"ch2-2","q":"Cải cách ruộng đất ở miền Bắc (1953-1956) bên cạnh những thành tựu căn bản đã bộc lộ hạn chế, sai lầm nghiêm trọng nào?","options":["Đấu tố tràn lan, quy sai thành phần; Đảng nhận khuyết điểm và sửa sai","Không đạt được bất kỳ kết quả tích cực nào đối với nông dân miền Bắc","Chỉ mang lại lợi ích cho riêng giai cấp địa chủ ở nông thôn miền Bắc","Không có tác động gì tới đời sống và sản xuất của nông dân miền Bắc"],"answer":0,"explain":"Bên cạnh thành tựu căn bản là xóa bỏ chế độ chiếm hữu ruộng đất phong kiến, đem lại ruộng đất cho nông dân, cải cách ruộng đất đã mắc những sai lầm nghiêm trọng (đấu tố tràn lan, quy sai thành phần); Đảng đã thẳng thắn nhận khuyết điểm và tiến hành sửa sai (1956-1957)."},{"id":675,"section":"ch2-2","q":"Bài học kinh nghiệm rút ra từ những sai lầm trong cải cách ruộng đất ở miền Bắc là gì?","options":["Quán triệt quan điểm quần chúng, tôn trọng thực tiễn, đề cao pháp chế, dám sửa sai","Không nên tiến hành bất kỳ cuộc cải cách ruộng đất nào nữa trong bất cứ hoàn cảnh nào","Chỉ nên dựa hoàn toàn vào kinh nghiệm của nước ngoài mà không xét thực tiễn trong nước","Nên xóa bỏ hoàn toàn vai trò lãnh đạo của Đảng đối với công tác ruộng đất ở nông thôn"],"answer":0,"explain":"Qua sai lầm trong cải cách ruộng đất, Đảng rút ra bài học sâu sắc về việc phải quán triệt quan điểm quần chúng, tôn trọng thực tiễn khách quan, đề cao pháp chế, và tinh thần thẳng thắn tự phê bình, sửa chữa kịp thời sai lầm, khuyết điểm."},{"id":676,"section":"ch2-2","q":"Từ năm 1965, đế quốc Mỹ chuyển sang thực hiện chiến lược chiến tranh nào ở miền Nam?","options":["\"Chiến tranh cục bộ\", đưa quân viễn chinh Mỹ trực tiếp vào tham chiến","\"Chiến tranh đặc biệt\", tiếp tục duy trì nguyên vẹn như trước năm 1965","\"Việt Nam hóa chiến tranh\", dùng quân đội Sài Gòn là chủ yếu ngay từ 1965","Chấm dứt hoàn toàn can thiệp quân sự, rút hết quân khỏi miền Nam"],"answer":0,"explain":"Trước nguy cơ phá sản của \"Chiến tranh đặc biệt\", từ giữa năm 1965 Mỹ chuyển sang chiến lược \"Chiến tranh cục bộ\", ồ ạt đưa quân viễn chinh Mỹ và quân các nước đồng minh vào trực tiếp tham chiến ở miền Nam."},{"id":677,"section":"ch2-2","q":"Chiến thắng Vạn Tường (Quảng Ngãi, 8/1965) có ý nghĩa gì đối với cuộc kháng chiến chống \"Chiến tranh cục bộ\"?","options":["Chứng minh có thể đánh thắng quân viễn chinh Mỹ, mở đầu cao trào \"tìm Mỹ mà đánh\"","Là trận đánh quy mô nhỏ, không có ý nghĩa chiến lược đối với cuộc kháng chiến","Đánh dấu sự sụp đổ hoàn toàn của chiến lược Chiến tranh cục bộ và buộc Mỹ rút quân","Chỉ có ý nghĩa phòng ngự cục bộ tại địa phương, không có tính chất tiến công"],"answer":0,"explain":"Chiến thắng Vạn Tường được coi là \"Ấp Bắc\" đối với quân viễn chinh Mỹ, chứng minh quân dân ta có khả năng đánh thắng quân Mỹ dù chúng có ưu thế tuyệt đối về vũ khí, hỏa lực, mở ra cao trào \"tìm Mỹ mà đánh, lùng ngụy mà diệt\" trên khắp miền Nam."},{"id":678,"section":"ch2-2","q":"Từ năm 1965, Mỹ đồng thời tiến hành cuộc chiến tranh phá hoại bằng không quân, hải quân đối với miền Bắc nhằm mục đích gì?","options":["Phá hoại tiềm lực kinh tế, quốc phòng và ngăn chặn chi viện cho miền Nam","Chỉ nhằm mục đích thị uy quân sự, không có ý định phá hoại thực sự nào","Nhằm hỗ trợ miền Bắc khôi phục và phát triển kinh tế sau chiến tranh","Nhằm buộc Việt Nam Dân chủ Cộng hòa phải tuyên chiến trước với Mỹ"],"answer":0,"explain":"Mỹ tiến hành chiến tranh phá hoại miền Bắc bằng không quân, hải quân (từ 1965) nhằm phá hoại tiềm lực kinh tế, quốc phòng, ngăn chặn nguồn chi viện của hậu phương lớn miền Bắc cho tiền tuyến lớn miền Nam, đồng thời làm lung lay ý chí chống Mỹ của nhân dân ta."},{"id":679,"section":"ch2-2","q":"Khẩu hiệu \"Tất cả để đánh thắng giặc Mỹ xâm lược\" gắn liền với phong trào thi đua nào của quân dân miền Bắc trong thời kỳ chống chiến tranh phá hoại?","options":["Phong trào \"Ba sẵn sàng\" và \"Ba đảm đang\"","Phong trào Đông Du của Phan Bội Châu","Phong trào Cần Vương chống Pháp cuối thế kỷ XIX","Phong trào Xô viết Nghệ Tĩnh những năm 1930-1931"],"answer":0,"explain":"Trong thời kỳ vừa sản xuất vừa chiến đấu chống chiến tranh phá hoại, phong trào \"Ba sẵn sàng\" của thanh niên và \"Ba đảm đang\" của phụ nữ miền Bắc được phát động rộng khắp, góp phần quan trọng chi viện cho tiền tuyến."},{"id":680,"section":"ch2-2","q":"Cuộc Tổng tiến công và nổi dậy Tết Mậu Thân năm 1968 có ý nghĩa chiến lược như thế nào?","options":["Làm lung lay ý chí xâm lược của Mỹ, buộc Mỹ xuống thang và ngồi vào đàm phán","Giành thắng lợi quân sự quyết định, kết thúc hoàn toàn cuộc kháng chiến chống Mỹ","Chỉ có ý nghĩa quân sự cục bộ tại một vài đô thị lớn, không tác động chính trị","Không có tác động gì đến chính sách của chính phủ Mỹ đối với cuộc chiến tranh"],"answer":0,"explain":"Cuộc Tổng tiến công và nổi dậy Tết Mậu Thân 1968 dù còn những hạn chế nhưng đã giáng đòn bất ngờ, làm lung lay ý chí xâm lược của đế quốc Mỹ, buộc Mỹ phải tuyên bố xuống thang chiến tranh, chấp nhận ngồi vào bàn đàm phán tại Hội nghị Pari."},{"id":681,"section":"ch2-2","q":"Hội nghị Pari về Việt Nam chính thức khai mạc vào thời gian nào?","options":["13/5/1968","27/1/1973","30/4/1975","2/9/1969"],"answer":0,"explain":"Hội nghị Pari về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam chính thức khai mạc ngày 13/5/1968 giữa hai bên (Việt Nam Dân chủ Cộng hòa và Mỹ), sau mở rộng thành bốn bên."},{"id":682,"section":"ch2-2","q":"Từ năm 1969, sau thất bại của \"Chiến tranh cục bộ\", Mỹ chuyển sang thực hiện chiến lược nào?","options":["\"Việt Nam hóa chiến tranh\", dùng quân Sài Gòn là chủ yếu, có Mỹ yểm trợ","Chấm dứt hoàn toàn chiến tranh, rút quân vô điều kiện khỏi miền Nam","Tiếp tục duy trì nguyên vẹn \"Chiến tranh cục bộ\" như giai đoạn trước","Mở rộng chiến tranh ra toàn bộ Đông Nam Á bằng quân đội Mỹ là chủ yếu"],"answer":0,"explain":"Từ năm 1969, thất bại trong \"Chiến tranh cục bộ\", Mỹ chuyển sang chiến lược \"Việt Nam hóa chiến tranh\" (nằm trong học thuyết Nixon), tăng cường xây dựng và trang bị cho quân đội Sài Gòn làm lực lượng chủ yếu, có sự hỗ trợ hỏa lực, không quân của Mỹ, đồng thời từng bước rút quân Mỹ về nước."},{"id":683,"section":"ch2-2","q":"Chủ tịch Hồ Chí Minh qua đời vào thời gian nào, để lại di sản tinh thần to lớn nào cho toàn Đảng, toàn dân?","options":["Ngày 2/9/1969, để lại bản Di chúc thiêng liêng cho toàn Đảng, toàn dân","Ngày 7/5/1954, sau chiến thắng Điện Biên Phủ, để lại bản Tuyên ngôn độc lập","Ngày 30/4/1975, cùng ngày miền Nam giải phóng, để lại bản Di chúc cho toàn dân","Năm 1960, trước ngày thành lập Mặt trận Dân tộc Giải phóng, để lại bản Di chúc"],"answer":0,"explain":"Chủ tịch Hồ Chí Minh qua đời ngày 2/9/1969, để lại bản Di chúc thiêng liêng, căn dặn toàn Đảng, toàn dân về công tác xây dựng Đảng, chăm lo đời sống nhân dân, tăng cường đoàn kết quốc tế và quyết tâm hoàn thành sự nghiệp thống nhất đất nước."},{"id":684,"section":"ch2-2","q":"Cuộc tiến công chiến lược năm 1972 (Xuân - Hè 1972) của quân dân ta có ý nghĩa như thế nào đối với \"Việt Nam hóa chiến tranh\"?","options":["Giáng đòn nặng vào \"Việt Nam hóa chiến tranh\", buộc Mỹ phải \"Mỹ hóa\" trở lại","Không có ảnh hưởng đáng kể tới cục diện chiến trường và đàm phán Pari","Đánh dấu sự sụp đổ hoàn toàn của chính quyền Sài Gòn ngay trong năm 1972","Buộc Mỹ phải ký ngay Hiệp định Pari mà không cần thêm cuộc đàm phán nào"],"answer":0,"explain":"Cuộc tiến công chiến lược năm 1972 giáng đòn mạnh mẽ vào chiến lược \"Việt Nam hóa chiến tranh\", làm phá sản về cơ bản chiến lược này, buộc Mỹ phải thừa nhận thất bại, quay lại dùng không quân, hải quân đánh phá miền Bắc và đẩy nhanh việc ký kết Hiệp định Pari."},{"id":685,"section":"ch2-2","q":"Chiến thắng \"Điện Biên Phủ trên không\" (12 ngày đêm cuối tháng 12/1972) diễn ra chủ yếu ở đâu, có ý nghĩa gì?","options":["Ở Hà Nội, Hải Phòng, đánh bại cuộc tập kích chiến lược bằng B-52 của Mỹ","Ở Điện Biên Phủ (Lai Châu), lặp lại chiến thắng quân sự năm 1954 trước Pháp","Ở Sài Gòn, đánh dấu giải phóng hoàn toàn miền Nam, kết thúc chiến tranh","Ở biên giới Việt - Trung, chống lại cuộc chiến tranh xâm lược biên giới"],"answer":0,"explain":"Trận \"Điện Biên Phủ trên không\" (18-29/12/1972) diễn ra chủ yếu tại Hà Nội, Hải Phòng, quân dân miền Bắc đã đánh bại cuộc tập kích chiến lược bằng máy bay B-52 của Mỹ, buộc Mỹ phải ký Hiệp định Pari về Việt Nam."},{"id":686,"section":"ch2-2","q":"Đoàn đại biểu Chính phủ Cách mạng lâm thời Cộng hòa miền Nam Việt Nam tham gia đàm phán và ký Hiệp định Pari (1973) với tư cách gì?","options":["Một trong bốn bên chính thức ký Hiệp định, đại diện cho cách mạng miền Nam","Chỉ tham dự với tư cách quan sát viên, không có quyền ký kết Hiệp định","Không được mời tham gia đàm phán, chỉ nhận kết quả sau khi Hiệp định ký","Chỉ đàm phán riêng, tách biệt hoàn toàn với đoàn Việt Nam Dân chủ Cộng hòa"],"answer":0,"explain":"Hội nghị Pari về Việt Nam được mở rộng thành đàm phán bốn bên, trong đó Chính phủ Cách mạng lâm thời Cộng hòa miền Nam Việt Nam là một bên chính thức tham gia đàm phán và ký kết Hiệp định Pari (1973), đại diện cho cách mạng miền Nam."},{"id":687,"section":"ch2-2","q":"Ý nghĩa lịch sử quan trọng nhất của Hiệp định Pari (1973) là gì?","options":["Thắng lợi \"đánh cho Mỹ cút\", mở đường tiến tới giải phóng hoàn toàn miền Nam","Đã kết thúc hoàn toàn chiến tranh và thống nhất đất nước ngay sau khi ký kết","Buộc chính quyền Sài Gòn phải giải thể ngay sau khi Hiệp định được ký kết","Không có ý nghĩa thực tiễn, chỉ mang tính hình thức ngoại giao đơn thuần"],"answer":0,"explain":"Hiệp định Pari đánh dấu thắng lợi lịch sử: \"đánh cho Mỹ cút\", buộc quân đội Mỹ và đồng minh phải rút khỏi miền Nam, tạo ra sự thay đổi căn bản trong so sánh lực lượng có lợi cho cách mạng, mở đường tiến tới giải phóng hoàn toàn miền Nam."},{"id":688,"section":"ch2-2","q":"Sau khi Hiệp định Pari được ký kết, đường Trường Sơn (đường Hồ Chí Minh) có vai trò như thế nào đối với cách mạng miền Nam?","options":["Là tuyến chi viện chiến lược huyết mạch, được mở rộng để đưa người, vũ khí vào Nam","Bị dừng hoạt động hoàn toàn theo yêu cầu của Hiệp định Pari về Việt Nam","Chỉ còn vai trò tượng trưng, không còn giá trị chi viện thực tế cho chiến trường","Chuyển hoàn toàn thành tuyến đường giao thông dân sự thông thường ở miền Nam"],"answer":0,"explain":"Sau Hiệp định Pari, tuyến đường Trường Sơn - đường Hồ Chí Minh tiếp tục được mở rộng, hiện đại hóa, trở thành tuyến chi viện chiến lược huyết mạch, đưa lực lượng, vũ khí, phương tiện vào miền Nam, chuẩn bị cho cuộc Tổng tiến công và nổi dậy mùa Xuân 1975."},{"id":689,"section":"ch2-2","q":"Sau khi Hiệp định Pari được ký kết (1/1973), chính quyền Sài Gòn được sự hậu thuẫn của Mỹ đã có hành động gì vi phạm nghiêm trọng Hiệp định?","options":["Mở các cuộc hành quân \"tràn ngập lãnh thổ\", lấn chiếm vùng giải phóng","Nghiêm chỉnh thực hiện ngừng bắn, rút quân theo đúng các cam kết đã ký","Chủ động đề nghị tổ chức tổng tuyển cử thống nhất đất nước ngay lập tức","Giải tán bộ máy chính quyền, giao quyền lực cho Chính phủ Cách mạng lâm thời"],"answer":0,"explain":"Vi phạm nghiêm trọng Hiệp định Pari, được Mỹ tiếp tục viện trợ, chính quyền Sài Gòn liên tục mở các cuộc hành quân \"tràn ngập lãnh thổ\", lấn chiếm vùng giải phóng, phá hoại việc thi hành Hiệp định, buộc quân dân ta phải kiên quyết đấu tranh đánh trả để bảo vệ vùng giải phóng."},{"id":690,"section":"ch2-2","q":"Hội nghị Bộ Chính trị (cuối 1974 - đầu 1975) đã đề ra quyết tâm chiến lược gì đối với việc giải phóng hoàn toàn miền Nam?","options":["Giải phóng miền Nam trong 1975-1976, nếu có thời cơ thì làm ngay năm 1975","Kéo dài cuộc kháng chiến thêm ít nhất mười năm nữa mới giành thắng lợi","Chỉ đặt mục tiêu giữ vững vùng giải phóng, chưa tính đến tổng tiến công","Chờ quân đội Mỹ can thiệp trực tiếp trở lại rồi mới quyết định hành động"],"answer":0,"explain":"Hội nghị Bộ Chính trị (cuối 1974, đầu 1975) đề ra kế hoạch giải phóng hoàn toàn miền Nam trong hai năm 1975-1976, đồng thời nhấn mạnh quyết tâm chiến lược: nếu thời cơ đến vào đầu hoặc cuối năm 1975 thì lập tức giải phóng miền Nam ngay trong năm 1975."},{"id":691,"section":"ch2-2","q":"Chiến dịch Tây Nguyên (3/1975) mở màn bằng trận đánh then chốt tại đâu?","options":["Thị xã Buôn Ma Thuột (Đắk Lắk)","Thành phố Huế (Thừa Thiên)","Thành phố Đà Nẵng (Quảng Nam)","Thị xã Xuân Lộc (Long Khánh)"],"answer":0,"explain":"Chiến dịch Tây Nguyên mở màn bằng trận đánh then chốt, bất ngờ tiến công và giải phóng thị xã Buôn Ma Thuột (10/3/1975), làm rung chuyển toàn bộ hệ thống phòng thủ của địch ở Tây Nguyên."},{"id":692,"section":"ch2-2","q":"Sau thắng lợi chiến dịch Tây Nguyên, Bộ Chính trị đã có quyết định chiến lược táo bạo, kịp thời nào?","options":["Giải phóng miền Nam ngay trong năm 1975, trước mùa mưa, thần tốc, táo bạo","Tạm dừng tiến công để củng cố lực lượng, chờ sang năm 1976 mới hành động","Chỉ giải phóng khu vực Tây Nguyên, không mở rộng tiến công ra nơi khác","Chuyển hướng sang đấu tranh ngoại giao thay vì tiến công quân sự nữa"],"answer":0,"explain":"Trước thắng lợi to lớn, mau lẹ ngoài dự kiến ở Tây Nguyên, Bộ Chính trị kịp thời bổ sung quyết tâm chiến lược: giải phóng miền Nam ngay trong năm 1975, trước mùa mưa, với phương châm thần tốc, táo bạo, bất ngờ, chắc thắng."},{"id":693,"section":"ch2-2","q":"Chiến dịch Huế - Đà Nẵng (3/1975) đã giải phóng hoàn toàn hai thành phố lớn của miền Trung vào những ngày nào?","options":["Huế (26/3/1975) và Đà Nẵng (29/3/1975)","Huế và Đà Nẵng cùng được giải phóng ngày 30/4/1975","Huế (10/3/1975) và Đà Nẵng (30/3/1975)","Chỉ giải phóng Đà Nẵng, chưa giải phóng được Huế"],"answer":0,"explain":"Trong chiến dịch Huế - Đà Nẵng, thành phố Huế được giải phóng ngày 26/3/1975, tiếp đó thành phố Đà Nẵng được giải phóng ngày 29/3/1975, làm tan rã nhanh chóng tuyến phòng thủ của địch ở Quân khu I."},{"id":694,"section":"ch2-2","q":"Chiến dịch cuối cùng mang tên Chiến dịch Hồ Chí Minh nhằm giải phóng Sài Gòn - Gia Định diễn ra trong khoảng thời gian nào?","options":["Từ 26/4 đến 30/4/1975","Từ 13/3 đến 7/5/1954","Từ 30/3 đến 29/4/1975","Từ 10/3 đến 26/3/1975"],"answer":0,"explain":"Chiến dịch Hồ Chí Minh lịch sử diễn ra từ ngày 26/4 đến ngày 30/4/1975, là chiến dịch quyết chiến chiến lược cuối cùng, giải phóng hoàn toàn Sài Gòn - Gia Định, kết thúc cuộc kháng chiến chống Mỹ, cứu nước."},{"id":695,"section":"ch2-2","q":"Xe tăng quân giải phóng tiến vào Dinh Độc Lập, bắt sống nội các chính quyền Sài Gòn vào thời điểm nào, đánh dấu sự kiện gì?","options":["Trưa 30/4/1975, đánh dấu miền Nam hoàn toàn giải phóng","Sáng 7/5/1954, đánh dấu kết thúc chiến dịch Điện Biên Phủ","Ngày 2/9/1945, đánh dấu thành lập nước Việt Nam Dân chủ Cộng hòa","Ngày 27/1/1973, đánh dấu ký kết Hiệp định Pari"],"answer":0,"explain":"Trưa ngày 30/4/1975, xe tăng quân giải phóng tiến thẳng vào Dinh Độc Lập, Tổng thống chính quyền Sài Gòn Dương Văn Minh tuyên bố đầu hàng không điều kiện, đánh dấu miền Nam hoàn toàn giải phóng, đất nước thống nhất."},{"id":696,"section":"ch2-2","q":"Cuộc Tổng tiến công và nổi dậy mùa Xuân năm 1975 diễn ra qua ba chiến dịch lớn nào, theo đúng trình tự thời gian?","options":["Chiến dịch Tây Nguyên, Chiến dịch Huế - Đà Nẵng, Chiến dịch Hồ Chí Minh","Chiến dịch Hồ Chí Minh, Chiến dịch Huế - Đà Nẵng, Chiến dịch Tây Nguyên","Chiến dịch Điện Biên Phủ, Chiến dịch Biên giới, Chiến dịch Hồ Chí Minh","Chiến dịch Huế - Đà Nẵng, Chiến dịch Tây Nguyên, Chiến dịch Hồ Chí Minh"],"answer":0,"explain":"Cuộc Tổng tiến công và nổi dậy mùa Xuân 1975 diễn ra qua ba chiến dịch lớn nối tiếp nhau theo trình tự: Chiến dịch Tây Nguyên (mở màn, 3/1975), Chiến dịch Huế - Đà Nẵng, và Chiến dịch Hồ Chí Minh (kết thúc, cuối 4/1975)."},{"id":697,"section":"ch2-2","q":"Nguyên nhân quyết định thắng lợi của cuộc kháng chiến chống Mỹ, cứu nước là gì?","options":["Sự lãnh đạo đúng đắn của Đảng với đường lối độc lập, tự chủ, sáng tạo","Chỉ đơn thuần nhờ viện trợ quân sự, kinh tế của các nước xã hội chủ nghĩa","Chỉ do nội bộ chính quyền Sài Gòn suy yếu và tự sụp đổ hoàn toàn","Chỉ nhờ yếu tố địa hình, khí hậu thuận lợi cho chiến tranh du kích"],"answer":0,"explain":"Nhân tố quyết định hàng đầu làm nên thắng lợi của cuộc kháng chiến chống Mỹ là sự lãnh đạo đúng đắn, sáng suốt của Đảng Cộng sản Việt Nam, với đường lối chính trị, quân sự độc lập, tự chủ, đúng đắn, sáng tạo, biết kết hợp sức mạnh dân tộc với sức mạnh thời đại."},{"id":698,"section":"ch2-2","q":"Đại thắng mùa Xuân năm 1975 đã hoàn thành trọn vẹn mục tiêu nào mà toàn Đảng, toàn dân, toàn quân ta theo đuổi suốt 21 năm kháng chiến chống Mỹ?","options":["Độc lập dân tộc và thống nhất Tổ quốc, cả nước đi lên chủ nghĩa xã hội","Chỉ giành được độc lập cho miền Nam, chưa thống nhất với miền Bắc","Chỉ thống nhất về mặt lãnh thổ, chưa thống nhất về thể chế nhà nước","Thiết lập một nhà nước liên bang gồm hai miền Nam - Bắc riêng biệt"],"answer":0,"explain":"Đại thắng mùa Xuân 1975 đã hoàn thành trọn vẹn mục tiêu độc lập dân tộc và thống nhất Tổ quốc mà toàn Đảng, toàn dân, toàn quân ta theo đuổi suốt 21 năm kháng chiến chống Mỹ, mở ra thời kỳ cả nước độc lập, thống nhất cùng đi lên chủ nghĩa xã hội."},{"id":699,"section":"ch2-2","q":"Trong 21 năm kháng chiến chống Mỹ (1954-1975), hậu phương lớn miền Bắc đã chi viện cho tiền tuyến lớn miền Nam qua tuyến đường vận tải chiến lược nào trên bộ và trên biển?","options":["Đường Trường Sơn trên bộ và đường Hồ Chí Minh trên biển","Chỉ có duy nhất tuyến đường sắt Bắc - Nam xuyên Việt","Chỉ có tuyến đường hàng không từ Hà Nội vào Sài Gòn","Chỉ dựa vào các tuyến đường bộ liên tỉnh có sẵn từ trước"],"answer":0,"explain":"Miền Bắc chi viện cho miền Nam qua hai tuyến đường chiến lược quan trọng: đường Trường Sơn (đường Hồ Chí Minh) trên bộ và đường Hồ Chí Minh trên biển, vận chuyển hàng triệu tấn vũ khí, lương thực và hàng vạn cán bộ, chiến sĩ vào chi viện cho chiến trường miền Nam."},{"id":700,"section":"ch2-2","q":"Bài học kinh nghiệm về sự kết hợp giữa đấu tranh quân sự, chính trị và ngoại giao trong kháng chiến chống Mỹ được thể hiện rõ nhất qua giai đoạn nào?","options":["Giai đoạn 1968-1973, \"vừa đánh vừa đàm\" cho đến Hiệp định Pari","Giai đoạn 1954-1959, trước khi có phong trào Đồng khởi ở miền Nam","Giai đoạn 1945-1946, trước khi toàn quốc kháng chiến bùng nổ","Chỉ thể hiện duy nhất trong Chiến dịch Hồ Chí Minh năm 1975"],"answer":0,"explain":"Từ sau Tết Mậu Thân 1968 đến khi ký Hiệp định Pari (1973), Đảng đã lãnh đạo kết hợp nhuần nhuyễn phương châm \"vừa đánh vừa đàm\", phối hợp chặt chẽ đấu tranh quân sự trên chiến trường với đấu tranh chính trị, ngoại giao tại bàn đàm phán, tạo sức ép buộc đối phương phải nhượng bộ."},{"id":701,"section":"ch2-2","q":"Quốc hội khóa VI, kỳ họp thứ nhất (1976) đã quyết định những vấn đề trọng đại nào sau đại thắng mùa Xuân 1975?","options":["Thống nhất nhà nước, đổi quốc hiệu thành Cộng hòa xã hội chủ nghĩa Việt Nam","Quyết định tiếp tục duy trì hai nhà nước riêng biệt ở hai miền Nam - Bắc","Quyết định trưng cầu dân ý về mô hình nhà nước liên bang của cả nước","Quyết định giữ nguyên quốc hiệu Việt Nam Dân chủ Cộng hòa cho cả nước"],"answer":0,"explain":"Quốc hội khóa VI, kỳ họp thứ nhất (1976) đã hoàn thành việc thống nhất đất nước về mặt nhà nước, quyết định đổi tên nước thành Cộng hòa xã hội chủ nghĩa Việt Nam, chọn Hà Nội là thủ đô của nước Việt Nam thống nhất."},{"id":702,"section":"ch2-2","q":"Chủ tịch Cuba Fidel Castro từng có chuyến thăm đặc biệt tới vùng giải phóng Quảng Trị (1973) thể hiện điều gì về ý nghĩa quốc tế của cuộc kháng chiến chống Mỹ?","options":["Sự đoàn kết, ủng hộ mạnh mẽ của bạn bè quốc tế với kháng chiến Việt Nam","Sự can thiệp quân sự trực tiếp của Cuba vào cuộc chiến tranh Việt Nam","Một hoạt động ngoại giao đơn thuần, không có ý nghĩa chính trị đáng kể","Chuyến thăm cá nhân, không đại diện cho quan điểm của nhà nước Cuba"],"answer":0,"explain":"Chuyến thăm vùng giải phóng Quảng Trị của Chủ tịch Fidel Castro (1973) là biểu tượng sinh động cho tình đoàn kết quốc tế, thể hiện sự ủng hộ mạnh mẽ của bạn bè thế giới, các lực lượng cách mạng và yêu chuộng hòa bình đối với cuộc kháng chiến chính nghĩa của nhân dân Việt Nam."},{"id":703,"section":"ch2-2","q":"Trong quá trình lãnh đạo cuộc kháng chiến chống Mỹ, Đảng đã vận dụng sáng tạo nguyên tắc nào của chủ nghĩa Mác - Lênin về chiến tranh cách mạng?","options":["Kết hợp xây dựng chủ nghĩa xã hội ở miền Bắc với đấu tranh giải phóng miền Nam, thực hiện đồng thời hai chiến lược cách mạng","Chỉ áp dụng một chiến lược cách mạng duy nhất là đấu tranh vũ trang trên phạm vi cả nước, không phân biệt đặc điểm hai miền","Từ bỏ vai trò của hậu phương miền Bắc, chỉ dựa vào lực lượng tại chỗ ở miền Nam để tiến hành chiến tranh cách mạng","Chỉ rập khuôn lý luận chiến tranh du kích của nước ngoài vào chiến trường, không có sáng tạo riêng của Đảng ta"],"answer":0,"explain":"Nét đặc sắc, sáng tạo trong đường lối của Đảng là thực hiện đồng thời hai nhiệm vụ chiến lược khác nhau ở hai miền: xây dựng chủ nghĩa xã hội ở miền Bắc và tiến hành cách mạng dân tộc dân chủ nhân dân, giải phóng miền Nam, thống nhất đất nước - đây là sáng tạo lý luận và thực tiễn độc đáo của cách mạng Việt Nam."},{"id":704,"section":"ch2-2","q":"Số lượng các chiến lược chiến tranh mà đế quốc Mỹ đã lần lượt tiến hành ở miền Nam Việt Nam (1954-1975) là bao nhiêu, gồm những chiến lược nào?","options":["Ba chiến lược: Chiến tranh đơn phương/đặc biệt, Chiến tranh cục bộ, Việt Nam hóa chiến tranh","Một chiến lược duy nhất là Chiến tranh cục bộ, được duy trì không thay đổi trong suốt 21 năm","Bốn chiến lược: Chiến tranh đặc biệt, Chiến tranh cục bộ, Chiến tranh tổng lực, Việt Nam hóa chiến tranh","Hai chiến lược: Chiến tranh đặc biệt và Việt Nam hóa chiến tranh, không có Chiến tranh cục bộ"],"answer":0,"explain":"Trong 21 năm, đế quốc Mỹ đã lần lượt thực hiện ba chiến lược chiến tranh xâm lược thực dân kiểu mới ở miền Nam: Chiến tranh đặc biệt (1961-1965, kế thừa giai đoạn chiến tranh đơn phương 1954-1960), Chiến tranh cục bộ (1965-1968), và Việt Nam hóa chiến tranh (1969-1975), tất cả đều lần lượt bị quân và dân ta đánh bại."},{"id":705,"section":"ch2-2","q":"Cuộc kháng chiến chống Mỹ, cứu nước (1954-1975) được Đảng ta xác định có tính chất gì nổi bật?","options":["Chiến tranh cách mạng, chính nghĩa, giải phóng dân tộc, đồng thời bảo vệ chủ nghĩa xã hội ở miền Bắc","Cuộc nội chiến thuần túy giữa hai miền Nam - Bắc, hoàn toàn không có yếu tố ngoại xâm","Cuộc chiến tranh ủy nhiệm giữa các cường quốc, hoàn toàn không mang ý nghĩa dân tộc của nhân dân ta","Cuộc xung đột chỉ mang tính chất tôn giáo, sắc tộc giữa các lực lượng ở miền Nam Việt Nam"],"answer":0,"explain":"Đảng ta luôn khẳng định cuộc kháng chiến chống Mỹ, cứu nước là cuộc chiến tranh cách mạng, chính nghĩa của dân tộc Việt Nam nhằm giải phóng miền Nam khỏi ách xâm lược của đế quốc Mỹ và tay sai, đồng thời bảo vệ công cuộc xây dựng chủ nghĩa xã hội ở miền Bắc."},{"id":706,"section":"ch2-2","q":"Ngay sau đại thắng mùa Xuân 1975, một trong những nhiệm vụ cấp bách hàng đầu mà Đảng lãnh đạo nhân dân thực hiện là gì?","options":["Khắc phục hậu quả chiến tranh, ổn định đời sống nhân dân, khôi phục sản xuất ở cả hai miền","Ngay lập tức tiến hành công nghiệp hóa nặng trên quy mô toàn quốc, bỏ qua khôi phục kinh tế","Giải thể toàn bộ bộ máy chính quyền cách mạng ở miền Nam để xây dựng lại từ đầu hệ thống mới","Chuyển trọng tâm hoàn toàn sang chi viện quốc tế cho phong trào cách mạng ở các nước khác"],"answer":0,"explain":"Sau đại thắng mùa Xuân 1975, nhiệm vụ cấp bách hàng đầu là khắc phục hậu quả nặng nề của 30 năm chiến tranh, ổn định đời sống nhân dân, khôi phục sản xuất nông nghiệp, công nghiệp ở cả hai miền, tạo tiền đề cho công cuộc thống nhất đất nước về mọi mặt."},{"id":707,"section":"ch2-2","q":"Chiến dịch Hồ Chí Minh được đặt tên theo tên của Chủ tịch Hồ Chí Minh nhằm thể hiện điều gì?","options":["Tri ân Người, khẳng định chiến dịch quyết chiến cuối cùng nhằm hoàn thành di nguyện thống nhất đất nước","Chỉ là một tên gọi mang tính hành chính, không hàm chứa ý nghĩa chính trị hay tinh thần đặc biệt nào","Do đích thân Chủ tịch Hồ Chí Minh trực tiếp ra mệnh lệnh và chỉ huy chiến dịch ngoài mặt trận","Nhằm phân biệt chiến dịch này với các chiến dịch quân sự khác trong cuộc kháng chiến chống Mỹ"],"answer":0,"explain":"Bộ Chính trị quyết định đặt tên chiến dịch giải phóng Sài Gòn là Chiến dịch Hồ Chí Minh nhằm thể hiện lòng tri ân sâu sắc, khẳng định chiến dịch quyết chiến chiến lược cuối cùng của cuộc kháng chiến chính là để hoàn thành tâm nguyện thống nhất đất nước mà Chủ tịch Hồ Chí Minh hằng mong ước trước lúc đi xa."},{"id":781,"section":"ch2-2","q":"Một trong những đặc điểm chưa từng có tiền lệ trong lịch sử Việt Nam sau Hiệp định Giơnevơ là","options":["đất nước bị chia làm hai miền, có chế độ xã hội khác nhau.","đất nước trải qua chiến tranh kéo dài nên bị thiệt hại rất nhiều.","đất nước hoàn toàn thống nhất, non sông thu về một mối.","cả nước cùng đi lên chủ nghĩa xã hội theo một con đường."],"answer":0,"explain":"Việc đất nước bị chia làm hai miền với hai chế độ chính trị - xã hội đối lập nhau sau Hiệp định Giơnevơ (1954) là một hoàn cảnh chưa từng có tiền lệ trong lịch sử dân tộc, đặt ra yêu cầu Đảng phải đồng thời lãnh đạo hai nhiệm vụ chiến lược khác nhau ở hai miền."},{"id":782,"section":"ch2-2","q":"Hội nghị Bộ Chính trị tháng 9/1954 đề ra nhiệm vụ chủ yếu trước mắt của miền Bắc là","options":["đẩy mạnh công nghiệp hoá, hiện đại hoá đất nước.","nhanh chóng xây dựng chủ nghĩa xã hội ở miền Bắc.","hàn gắn vết thương chiến tranh, phục hồi kinh tế.","đẩy mạnh sự nghiệp kháng chiến chống Mỹ, cứu nước."],"answer":2,"explain":"Hội nghị Bộ Chính trị (9/1954) xác định nhiệm vụ chủ yếu trước mắt của miền Bắc là hàn gắn vết thương chiến tranh, phục hồi kinh tế quốc dân, ổn định xã hội, ổn định đời sống nhân dân, làm cơ sở tiến lên xây dựng chủ nghĩa xã hội sau này."},{"id":783,"section":"ch2-2","q":"Nhận định nào sau đây được Đảng đưa ra tại Hội nghị lần thứ 7 (3/1955) và lần thứ 8 (8/1955) của Ban Chấp hành Trung ương Đảng (khóa II)?","options":["Mỹ và tay sai hất cẳng Pháp ở miền Nam, công khai lập nhà nước riêng chống phá Hiệp định Giơnevơ.","Cuộc chiến tranh Mỹ gây ra ở miền Nam vẫn là cuộc chiến tranh xâm lược thực dân mới, kéo dài nhiều năm.","Cơ hội thực hiện hoà bình, thống nhất đất nước chỉ còn một đến hai năm nữa, cần chuẩn bị tổng khởi nghĩa.","Chúng ta có điều kiện giải phóng hoàn toàn miền Nam sớm hơn dự kiến, cần chuyển ngay sang đấu tranh vũ trang."],"answer":0,"explain":"Tại các Hội nghị Trung ương lần thứ 7 (3/1955) và lần thứ 8 (8/1955, khóa II), Đảng nhận định đế quốc Mỹ và tay sai đã từng bước hất cẳng Pháp, công khai lập nhà nước riêng ở miền Nam chống phá việc thi hành Hiệp định Giơnevơ, ra sức đàn áp phong trào cách mạng, từ đó đề ra chủ trương đấu tranh phù hợp với tình hình mới."},{"id":784,"section":"ch2-2","q":"Trong chủ trương khôi phục và phát triển kinh tế miền Bắc những năm 1954 - 1957, Đảng chủ trương lấy khôi phục lĩnh vực nào dưới đây là trọng tâm?","options":["Công nghiệp.","Nông nghiệp.","Quân sự.","Dịch vụ."],"answer":1,"explain":"Trong khôi phục và phát triển kinh tế miền Bắc giai đoạn 1954-1957, Đảng xác định lấy khôi phục nông nghiệp làm trọng tâm, vì nông nghiệp là ngành kinh tế chủ yếu, liên quan trực tiếp đến đời sống của đại bộ phận nhân dân miền Bắc sau chiến tranh."},{"id":785,"section":"ch2-2","q":"Trong kế hoạch 3 năm phát triển kinh tế, văn hóa và cải tạo xã hội chủ nghĩa đối với thành phần kinh tế cá thể và tư bản tư doanh (1958 - 1960), Đảng chủ trương phát triển thành phần kinh tế","options":["kinh tế cá thể, tiểu chủ.","kinh tế tư bản tư doanh.","kinh tế quốc doanh và tập thể.","kinh tế cá thể và tập thể."],"answer":2,"explain":"Trong kế hoạch 3 năm (1958-1960), đi đôi với cải tạo thành phần kinh tế cá thể và tư bản tư doanh theo hướng công hữu hoá, Đảng chủ trương phát triển mạnh kinh tế quốc doanh và kinh tế tập thể, coi đây là hai thành phần kinh tế giữ vai trò chủ đạo của nền kinh tế xã hội chủ nghĩa đang hình thành ở miền Bắc."},{"id":786,"section":"ch2-2","q":"Nội dung nào dưới đây không phải là mục đích của Mỹ khi can thiệp vào miền Nam Việt Nam sau Hiệp định Giơnevơ?","options":["Biến miền Nam Việt Nam thành thuộc địa kiểu mới, lệ thuộc về chính trị và kinh tế vào Mỹ.","Biến miền Nam Việt Nam thành căn cứ quân sự để tiến công miền Bắc, chia cắt lâu dài đất nước.","Dựa vào miền Nam để ngăn chặn ảnh hưởng của chủ nghĩa xã hội xuống vùng Đông Nam Á.","Giúp chính quyền Ngô Đình Diệm xây dựng xã hội tự do, dân chủ, phồn vinh cho miền Nam."],"answer":3,"explain":"Mục đích thực chất của Mỹ khi can thiệp vào miền Nam sau Hiệp định Giơnevơ là biến miền Nam thành thuộc địa kiểu mới, căn cứ quân sự để ngăn chặn chủ nghĩa xã hội lan xuống Đông Nam Á. Lời tuyên bố \"xây dựng xã hội tự do, dân chủ, phồn vinh\" cho chính quyền Ngô Đình Diệm chỉ là luận điệu tuyên truyền che đậy bản chất thực dân mới, không phải mục đích thực sự."},{"id":787,"section":"ch2-2","q":"Lời tuyên bố “Biên giới Hoa Kỳ kéo dài đến vĩ tuyến 17” ngày 13/5/1957 là của ai?","options":["Cựu hoàng Bảo Đại.","Ngô Đình Diệm.","Dương Văn Minh.","Nguyễn Khánh."],"answer":1,"explain":"Trong chuyến thăm Hoa Kỳ (tháng 5/1957), Ngô Đình Diệm phát biểu trước Quốc hội Mỹ với lời tuyên bố \"Biên giới Hoa Kỳ kéo dài đến vĩ tuyến 17\", thể hiện rõ vai trò tay sai, lệ thuộc hoàn toàn vào Mỹ của chính quyền Sài Gòn."},{"id":788,"section":"ch2-2","q":"Trước thực tiễn cuộc đấu tranh cách mạng của nhân dân miền Nam, tháng 8/1956, đồng chí nào dưới đây đã dự thảo Đề cương đường lối cách mạng Việt Nam ở miền Nam?","options":["Trường Chinh.","Võ Nguyên Giáp.","Hồ Chí Minh.","Lê Duẩn."],"answer":3,"explain":"Trước thực tiễn phong trào đấu tranh cách mạng của nhân dân miền Nam, tháng 8/1956, đồng chí Lê Duẩn, khi đang hoạt động bí mật ở Nam Bộ, đã dự thảo bản \"Đề cương đường lối cách mạng Việt Nam ở miền Nam\", đặt cơ sở lý luận quan trọng cho việc hình thành đường lối cách mạng miền Nam sau này."},{"id":789,"section":"ch2-2","q":"Trong quá trình thực hiện kế hoạch 5 năm lần thứ nhất tại miền Bắc (1961 - 1965), phong trào nào dưới đây được Bác Hồ ra lời kêu gọi tại Hội nghị chính trị đặc biệt (3/1964)?","options":["Phong trào Ba nhất, thi đua yêu nước của các đơn vị trong quân đội.","Phong trào Xe chưa qua, nhà không tiếc của ngành giao thông vận tải.","Phong trào Mỗi người làm việc bằng hai vì đồng bào miền Nam ruột thịt.","Phong trào Nhằm thẳng quân thù mà bắn của lực lượng vũ trang."],"answer":2,"explain":"Tại Hội nghị chính trị đặc biệt (3/1964), Chủ tịch Hồ Chí Minh ra lời kêu gọi phát động phong trào thi đua \"Mỗi người làm việc bằng hai để đền đáp lại cho đồng bào miền Nam ruột thịt\", động viên nhân dân miền Bắc hăng hái lao động sản xuất, chi viện cho cuộc đấu tranh giải phóng miền Nam."},{"id":790,"section":"ch2-2","q":"Để lấy cớ leo thang chiến tranh phá hoại ra miền Bắc nước ta, Mỹ đã dựng lên sự kiện nào vào tháng 8/1964?","options":["Sự kiện Vịnh Bắc Bộ, vu cáo tàu Việt Nam tấn công tàu chiến Mỹ.","Vụ ném bom phá hoại bằng máy bay B.52 trong 12 ngày đêm ở Hà Nội.","Sự kiện Vịnh Con Lợn, cuộc đổ bộ của lực lượng chống Cuba năm 1961.","Vụ thảm sát Mỹ Lai (thảm sát Sơn Mỹ) ở Quảng Ngãi năm 1968."],"answer":0,"explain":"Tháng 8/1964, đế quốc Mỹ dựng lên \"sự kiện Vịnh Bắc Bộ\", vu cáo tàu hải quân Việt Nam Dân chủ Cộng hòa tấn công tàu chiến Mỹ, lấy đó làm cớ leo thang, mở đầu cuộc chiến tranh phá hoại miền Bắc bằng không quân và hải quân."},{"id":791,"section":"ch2-2","q":"Nội dung nào dưới đây không phải tinh thần của Đảng tại Hội nghị Bộ chính trị tháng 1/1961 và tháng 2/1962 nhằm chống chiến lược “Chiến tranh đặc biệt” của đế quốc Mỹ?","options":["Giữ vững thế tiến công chiến lược mà cách mạng miền Nam giành được từ Đồng khởi.","Đưa đấu tranh vũ trang phát triển lên song song với đấu tranh chính trị.","Tiến công địch đồng thời trên cả ba vùng chiến lược: rừng núi, đồng bằng, đô thị.","Đấu tranh quân sự có tác dụng trực tiếp và giữ vị trí ngày càng quan trọng."],"answer":3,"explain":"Tại Hội nghị Bộ Chính trị tháng 1/1961 và tháng 2/1962, Đảng chủ trương giữ vững và phát triển thế chiến lược tiến công đã giành được từ Đồng khởi, đẩy đấu tranh vũ trang phát triển song song với đấu tranh chính trị, tiến công địch trên cả ba vùng chiến lược. Trong giai đoạn này, chính đấu tranh chính trị (không phải đấu tranh quân sự) mới được xác định có tác dụng trực tiếp và giữ vị trí ngày càng quan trọng, nên phương án này không phản ánh đúng tinh thần chủ trương của Đảng."},{"id":792,"section":"ch2-2","q":"Vùng nào dưới đây không phải là một trong ba vùng chiến lược được Đảng xác định trong chủ trương tiến công địch nhằm chống “Chiến tranh đặc biệt”?","options":["Các vùng đô thị.","Nông thôn đồng bằng.","Nông thôn rừng núi.","Ven biển và hải đảo."],"answer":3,"explain":"Chủ trương tiến công địch nhằm chống \"Chiến tranh đặc biệt\" của Đảng xác định ba vùng chiến lược là: rừng núi, nông thôn đồng bằng và đô thị (thành thị); phương án \"ven biển và hải đảo\" không thuộc ba vùng chiến lược này."},{"id":793,"section":"ch2-2","q":"Các lực lượng vũ trang ở miền Nam được Đảng chủ trương thống nhất (15/2/1961) với tên gọi","options":["Mặt trận Dân tộc giải phóng miền Nam","Quân giải phóng miền Nam Việt Nam","Vệ quốc đoàn miền Nam Việt Nam","Lực lượng kháng chiến Nam Bộ"],"answer":1,"explain":"Ngày 15/2/1961, các lực lượng vũ trang cách mạng ở miền Nam được Đảng chủ trương thống nhất tổ chức thành Quân giải phóng miền Nam Việt Nam, một bộ phận của Quân đội nhân dân Việt Nam hoạt động trên chiến trường miền Nam."},{"id":794,"section":"ch2-2","q":"Đảng Lao động Việt Nam về cơ bản đã hoàn thiện đường lối kháng chiến chống Mỹ, cứu nước nhằm chống chiến lược “Chiến tranh cục bộ” của đế quốc Mỹ tại","options":["Hội nghị Bộ Chính trị (9/1954) và Hội nghị Trung ương lần thứ 7 (3/1955).","Đại hội đại biểu toàn quốc lần thứ III của Đảng, họp tháng 9/1960.","Hội nghị Trung ương lần thứ 11 (3/1965) và lần thứ 12 (12/1965).","Hội nghị Bộ Chính trị mở rộng (10/1974) và (1/1975)."],"answer":2,"explain":"Hội nghị Trung ương lần thứ 11 (3/1965) và lần thứ 12 (12/1965) Ban Chấp hành Trung ương Đảng (khóa III) đã phân tích tình hình, hoàn chỉnh đường lối kháng chiến chống Mỹ, cứu nước trên phạm vi cả nước, xác định quyết tâm đánh Mỹ và thắng Mỹ để đối phó với chiến lược \"Chiến tranh cục bộ\" mà Mỹ mới triển khai từ giữa năm 1965."},{"id":795,"section":"ch2-2","q":"Điền vào chỗ trống để hoàn thành lời kêu gọi của Chủ tịch Hồ Chí Minh ngày 17/7/1966. “Chiến tranh có thể kéo dài 5 năm, 10 năm, 20 năm hoặc lâu hơn nữa. Hà Nội, Hải Phòng và một số thành phố, xí nghiệp có thể bị tàn phá, song nhân dân Việt Nam quyết…. . Không có gì quý hơn độc lập, tự do!”.","options":["không sợ","không lùi bước","không nản chí","không đầu hàng"],"answer":0,"explain":"Trong lời kêu gọi ngày 17/7/1966 phát trên Đài Tiếng nói Việt Nam, Chủ tịch Hồ Chí Minh khẳng định dù chiến tranh có kéo dài và bị tàn phá đến đâu, nhân dân Việt Nam \"quyết không sợ\", thể hiện ý chí quyết chiến, quyết thắng, trở thành khẩu hiệu hành động của toàn Đảng, toàn quân, toàn dân trong kháng chiến chống Mỹ."},{"id":796,"section":"ch2-2","q":"Thực hiện những nghị quyết của Đảng và theo lời kêu gọi của Chủ tịch Hồ Chí Minh, quân và dân miền Bắc đã dấy lên cao trào chống Mỹ, hàng loạt phong trào thi đua diễn ra, phong trào “Ba sẵn sàng” của đối tượng nào sau đây?","options":["Thanh niên.","Phụ nữ.","Quân đội.","Công nhân."],"answer":0,"explain":"Phong trào \"Ba sẵn sàng\" là phong trào thi đua của thanh niên miền Bắc trong kháng chiến chống Mỹ (từ 1964), với nội dung sẵn sàng chiến đấu, sẵn sàng nhập ngũ và sẵn sàng đi bất cứ đâu, làm bất cứ việc gì Tổ quốc cần, song hành với phong trào \"Ba đảm đang\" của phụ nữ."},{"id":797,"section":"ch2-2","q":"Sự kiện nào sau đây không phải là chiến thắng của quân và dân ta trong quá trình chống chiến lược \"Chiến tranh cục bộ\" của Mỹ ở miền Nam?","options":["Núi Thành (5/1965).","Vạn Tường (8/1965).","Plâyme (11/1965).","Ấp Bắc (1/1963)."],"answer":3,"explain":"Trận Ấp Bắc (1/1963) là chiến thắng điển hình của quân dân ta trong thời kỳ đánh bại chiến lược \"Chiến tranh đặc biệt\" (trước năm 1965), còn Núi Thành (5/1965), Vạn Tường (8/1965) và Plâyme (11/1965) là những chiến thắng mở đầu cao trào \"tìm Mỹ mà đánh, lùng ngụy mà diệt\" trong giai đoạn chống \"Chiến tranh cục bộ\"."},{"id":798,"section":"ch2-2","q":"Một trong những hạn chế được Đảng đánh giá là sai lầm về chỉ đạo chiến lược trong sự kiện tiến công và nổi dậy xuân Mậu Thân năm 1968 là","options":["lựa chọn thời điểm mở đầu cuộc tiến công vào đêm giao thừa.","tiến công địch với trọng điểm là các đô thị lớn ở miền Nam.","tiếp tục mở các đợt tiến công vào đô thị khi đã mất yếu tố bất ngờ.","sử dụng lực lượng biệt động Sài Gòn làm mũi nhọn trong giai đoạn đầu."],"answer":2,"explain":"Một trong những hạn chế về chỉ đạo chiến lược trong Tổng tiến công Mậu Thân 1968 là sau đợt tiến công Tết (đợt 1) đã đạt hiệu quả bất ngờ, Đảng vẫn chủ trương tiếp tục mở các đợt 2, đợt 3 tấn công vào đô thị trong khi so sánh lực lượng không còn lợi cho ta và đã mất yếu tố bí mật, bất ngờ, khiến lực lượng ta chịu tổn thất nặng nề."},{"id":799,"section":"ch2-2","q":"Nội dung nào sau đây không phù hợp với chủ trương của Đảng tại Hội nghị lần thứ 18 Ban Chấp hành Trung ương Đảng (1/1970) và Hội nghị Bộ Chính trị (6/1970) nhằm chống chiến lược “Việt Nam hoá chiến tranh” của Mỹ?","options":["Kiên trì kháng chiến, lấy nông thôn làm hướng tiến công chính của cách mạng.","Tập trung ngăn chặn và đẩy lùi chương trình “bình định” của địch ở nông thôn.","Đẩy mạnh tác chiến của bộ đội chủ lực, phát triển chiến tranh nhân dân địa phương.","Thương lượng thoả thuận với chính quyền Việt Nam Cộng hoà để kết thúc chiến tranh."],"answer":3,"explain":"Chủ trương của Đảng tại Hội nghị lần thứ 18 Ban Chấp hành Trung ương (1/1970) và Hội nghị Bộ Chính trị (6/1970) là kiên trì đẩy mạnh kháng chiến, lấy nông thôn làm hướng tiến công chính, tập trung chống \"bình định\", kết hợp đẩy mạnh tác chiến của bộ đội chủ lực với phát triển chiến tranh nhân dân địa phương, chứ không chủ trương thoả thuận với chính quyền Việt Nam Cộng hoà để kết thúc chiến tranh."},{"id":800,"section":"ch2-2","q":"Đoạn trích: “Năm tháng sẽ trôi qua, nhưng thắng lợi của nhân dân ta trong sự nghiệp kháng chiến chống Mỹ, cứu nước mãi mãi được ghi vào lịch sử dân tộc ta như một trong những trang chói lọi nhất, một biểu tượng sáng ngời về sự toàn thắng của chủ nghĩa anh hùng cách mạng và trí tuệ con người, và đi vào lịch sử thế giới như một chiến công vĩ đại của thế kỉ XX, một sự kiện có tầm quan trọng quốc tế to lớn và có tính thời đại sâu sắc” được nêu ra tại sự kiện nào sau đây?","options":["Đại hội đại biểu toàn quốc lần thứ III của Đảng.","Đại hội đại biểu toàn quốc lần thứ IV của Đảng.","Đại hội đại biểu toàn quốc lần thứ V của Đảng.","Đại hội đại biểu toàn quốc lần thứ VI của Đảng."],"answer":1,"explain":"Đoạn văn trên được trích từ Báo cáo Chính trị của Ban Chấp hành Trung ương Đảng tại Đại hội đại biểu toàn quốc lần thứ IV (12/1976), đánh giá tầm vóc và ý nghĩa lịch sử vĩ đại của thắng lợi cuộc kháng chiến chống Mỹ, cứu nước đối với dân tộc và thời đại."},{"id":801,"section":"ch2-2","q":"Lực lượng tình báo của quân đội nhân dân Việt Nam đã đóng góp rất nhiều cho những chiến công trong cuộc kháng chiến chống Mỹ, cứu nước. Nhà tình báo nào của ta từng làm phóng viên tạp chí Time (Mỹ) và sau này được biết đến với biệt danh \"Điệp viên hoàn hảo\"?","options":["Đinh Thị Vân.","Phạm Xuân Ẩn.","Phạm Ngọc Thảo.","Vũ Ngọc Nhạ."],"answer":1,"explain":"Phạm Xuân Ẩn là một trong những nhà tình báo xuất sắc của Quân đội nhân dân Việt Nam trong kháng chiến chống Mỹ. Ông hoạt động công khai với vai trò phóng viên, sau là Trưởng văn phòng đại diện tạp chí Time tại Sài Gòn, thu thập được nhiều tin tức tình báo chiến lược quan trọng, sau này được nhà báo Mỹ Larry Berman gọi là \"Điệp viên hoàn hảo\" (Perfect Spy) qua cuốn sách cùng tên."},{"id":802,"section":"ch2-2","q":"Nhân vật nào sau đây hoạt động trong lực lượng tình báo của quân đội nhân dân Việt Nam, ông đã leo cao trong chính quyền Việt Nam Cộng hoà, có thể tác động trực tiếp đến chính quyền Sài Gòn, ông được mệnh danh là “Nhà tình báo cô độc” đã có đóng góp rất lớn cho sự nghiệp kháng chiến chống Mỹ, cứu nước của quân và dân ta?","options":["Hoàng Minh Đạo.","Phạm Xuân Ẩn.","Phạm Ngọc Thảo.","Vũ Ngọc Nhạ."],"answer":2,"explain":"Phạm Ngọc Thảo là nhà tình báo hoạt động đơn tuyến, len lỏi lên đến cấp Đại tá, Tỉnh trưởng trong chính quyền Việt Nam Cộng hoà, có thể tác động trực tiếp đến nội bộ chính quyền Sài Gòn, tham gia tổ chức, vận động các cuộc đảo chính làm suy yếu chính quyền địch từ bên trong, được biết đến với biệt danh \"Nhà tình báo cô độc\" do tính chất hoạt động đơn độc, ít gắn với một cụm/lưới tình báo có tổ chức như các nhà tình báo khác."},{"id":271,"section":"ch3-1","q":"Hội nghị lần thứ 24 Ban Chấp hành Trung ương Đảng (khóa III, 8/1975) đề ra nhiệm vụ gì?","options":["Hoàn thành thống nhất đất nước về nhà nước","Tiến hành công cuộc đổi mới toàn diện","Gia nhập ASEAN, mở rộng hợp tác khu vực","Ký Hiệp định Paris, chấm dứt chiến tranh"],"answer":0,"explain":"Hội nghị lần thứ 24 Ban Chấp hành Trung ương Đảng (8/1975) đề ra nhiệm vụ hoàn thành thống nhất đất nước về mặt nhà nước."},{"id":272,"section":"ch3-1","q":"Cuộc Tổng tuyển cử bầu Quốc hội chung của cả nước thống nhất diễn ra vào ngày nào?","options":["Ngày 25/4/1976","Ngày 30/4/1975","Ngày 2/7/1976","Ngày 20/9/1977"],"answer":0,"explain":"Ngày 25/4/1976, cuộc Tổng tuyển cử bầu Quốc hội chung của cả nước được tiến hành, đánh dấu bước hoàn thành thống nhất đất nước về mặt nhà nước."},{"id":273,"section":"ch3-1","q":"Quốc hội khóa VI, kỳ họp thứ nhất (7/1976) đã quyết định đổi tên nước ta thành gì?","options":["Cộng hòa xã hội chủ nghĩa Việt Nam","Việt Nam Dân chủ Cộng hòa thống nhất","Cộng hòa Dân chủ nhân dân Việt Nam","Liên bang Xã hội chủ nghĩa Việt Nam"],"answer":0,"explain":"Ngày 2/7/1976, Quốc hội khóa VI quyết định đổi tên nước thành Cộng hòa xã hội chủ nghĩa Việt Nam."},{"id":274,"section":"ch3-1","q":"Đại hội đại biểu toàn quốc lần thứ IV của Đảng họp vào thời gian nào, đổi tên Đảng ra sao?","options":["Tháng 12/1976, đổi Đảng Lao động Việt Nam thành Đảng Cộng sản Việt Nam","Tháng 3/1982, vẫn giữ nguyên tên gọi Đảng Lao động Việt Nam","Tháng 9/1960, đổi Đảng Lao động Việt Nam thành Đảng Cộng sản Đông Dương","Tháng 12/1986, đổi Đảng Lao động Việt Nam thành Đảng Nhân dân Cách mạng"],"answer":0,"explain":"Đại hội IV (12/1976) quyết định đổi tên Đảng Lao động Việt Nam thành Đảng Cộng sản Việt Nam."},{"id":275,"section":"ch3-1","q":"Đại hội đại biểu toàn quốc lần thứ V của Đảng họp vào thời gian nào?","options":["Tháng 3/1982","Tháng 12/1976","Tháng 12/1986","Tháng 6/1991"],"answer":0,"explain":"Đại hội đại biểu toàn quốc lần thứ V của Đảng họp tháng 3/1982 tại Hà Nội."},{"id":276,"section":"ch3-1","q":"Chiến tranh biên giới Tây Nam chống lại chế độ diệt chủng Khmer Đỏ diễn ra chủ yếu vào thời gian nào?","options":["Cuối những năm 1970, cao điểm 1978-1979","Đầu những năm 1960, cao điểm 1960-1961","Giữa những năm 1980, cao điểm 1985-1986","Giai đoạn 1954-1960, cao điểm 1957-1958"],"answer":0,"explain":"Cuối những năm 1970, quân dân Việt Nam phải tiến hành cuộc chiến tranh bảo vệ biên giới Tây Nam chống lại chế độ diệt chủng Khmer Đỏ (Campuchia), đỉnh điểm 1978-1979."},{"id":277,"section":"ch3-1","q":"Chiến tranh bảo vệ biên giới phía Bắc chống quân xâm lược nổ ra vào thời gian nào?","options":["Tháng 2/1979","Tháng 4/1975","Tháng 12/1978","Tháng 12/1986"],"answer":0,"explain":"Tháng 2/1979, chiến tranh bảo vệ biên giới phía Bắc nổ ra khi quân đội nước ngoài tiến công xâm lược trên toàn tuyến biên giới phía Bắc Việt Nam."},{"id":278,"section":"ch3-1","q":"Sau năm 1975, tình hình kinh tế - xã hội Việt Nam cuối những năm 1970, đầu những năm 1980 gặp phải khó khăn gì?","options":["Khủng hoảng kinh tế - xã hội, cơ chế tập trung quan liêu, bao cấp bộc lộ nhiều hạn chế","Phát triển vượt bậc, kinh tế tăng trưởng cao, không còn khó khăn nào đáng kể","Tăng trưởng kinh tế nhanh nhất khu vực Đông Nam Á, đời sống nhân dân khá giả","Chuyển đổi hoàn toàn sang kinh tế thị trường tự do, xóa bỏ vai trò quản lý nhà nước"],"answer":0,"explain":"Cuối những năm 1970, đầu 1980, đất nước lâm vào khủng hoảng kinh tế - xã hội nghiêm trọng; cơ chế quản lý tập trung quan liêu, bao cấp bộc lộ nhiều hạn chế, trì trệ."},{"id":279,"section":"ch3-1","q":"Chỉ thị số 100-CT/TW (khoán 100) được ban hành vào năm nào, có nội dung gì?","options":["Năm 1981, khoán sản phẩm đến nhóm và người lao động","Năm 1986, khoán toàn bộ ruộng đất cho từng hộ nông dân","Năm 1975, quốc hữu hóa toàn bộ ruộng đất trong cả nước","Năm 1960, tập thể hóa toàn bộ nông nghiệp ở miền Bắc"],"answer":0,"explain":"Chỉ thị số 100-CT/TW (1/1981) của Ban Bí thư về \"khoán sản phẩm đến nhóm và người lao động\" trong hợp tác xã nông nghiệp (còn gọi là Khoán 100)."},{"id":280,"section":"ch3-1","q":"Đại hội V (1982) của Đảng đã xác định chặng đường đầu tiên của thời kỳ quá độ ở nước ta có đặc điểm gì?","options":["Chặng đường đầu của thời kỳ quá độ lên chủ nghĩa xã hội, nhiều khó khăn","Đã hoàn thành xây dựng chủ nghĩa xã hội, chuyển sang chủ nghĩa cộng sản","Chuẩn bị chuyển sang giai đoạn tư bản chủ nghĩa, mở cửa kinh tế","Chưa xác định rõ giai đoạn phát triển, còn nhiều ý kiến khác nhau"],"answer":0,"explain":"Đại hội V xác định nước ta đang ở chặng đường đầu tiên của thời kỳ quá độ lên chủ nghĩa xã hội, với nhiều khó khăn, phức tạp cần khắc phục."},{"id":281,"section":"ch3-1","q":"Trước Đổi mới, mô hình kinh tế chủ yếu ở Việt Nam là gì?","options":["Kế hoạch hóa tập trung, quan liêu, bao cấp","Kinh tế thị trường tự do, không kế hoạch hóa","Kinh tế hỗn hợp nhiều thành phần, cạnh tranh tự do","Kinh tế mở cửa, hội nhập quốc tế sâu rộng"],"answer":0,"explain":"Trước thời kỳ Đổi mới, Việt Nam áp dụng mô hình kinh tế kế hoạch hóa tập trung, quan liêu, bao cấp, dẫn đến nhiều hạn chế, trì trệ."},{"id":282,"section":"ch3-1","q":"Hội nghị Trung ương 6 khóa IV (8/1979) có ý nghĩa gì trong quá trình tìm tòi đổi mới?","options":["Có những chủ trương “cởi trói”, tháo gỡ khó khăn cho sản xuất","Chính thức quyết định đường lối Đổi mới toàn diện của đất nước","Chủ trương duy trì nguyên trạng cơ chế quản lý tập trung cũ","Quyết định giải thể toàn bộ các hợp tác xã nông nghiệp ở miền Bắc"],"answer":0,"explain":"Hội nghị Trung ương 6 khóa IV (8/1979) đưa ra một số chủ trương \"cởi trói\", tháo gỡ khó khăn cho sản xuất, mở đầu cho quá trình tìm tòi đổi mới tư duy kinh tế."},{"id":283,"section":"ch3-1","q":"Từ thực tiễn khủng hoảng kinh tế - xã hội, Đảng đã trải qua quá trình gì để hình thành đường lối Đổi mới?","options":["Quá trình tìm tòi, thử nghiệm, đổi mới tư duy và khảo nghiệm thực tiễn trong 1979-1986","Quyết định ngay lập tức đường lối mới mà không qua bất kỳ thử nghiệm thực tiễn nào","Sao chép hoàn toàn mô hình cải cách của nước ngoài trong những năm 1979-1986","Giữ nguyên cơ chế cũ, không có tìm tòi hay thử nghiệm nào trong những năm 1979-1986"],"answer":0,"explain":"Đảng đã trải qua một quá trình tìm tòi, thử nghiệm, đổi mới tư duy lý luận, khảo nghiệm thực tiễn trong nhiều năm (1979-1986) để hình thành đường lối Đổi mới."},{"id":284,"section":"ch3-1","q":"Cuộc chiến tranh bảo vệ biên giới Tây Nam đã giúp nhân dân Campuchia thoát khỏi chế độ nào?","options":["Chế độ diệt chủng Pol Pot - Khmer Đỏ","Chế độ thực dân Pháp (1863-1953)","Chế độ quân chủ Norodom Sihanouk","Chế độ cộng hòa Khmer của Lon Nol"],"answer":0,"explain":"Cuộc chiến tranh bảo vệ biên giới Tây Nam giúp nhân dân Campuchia thoát khỏi họa diệt chủng của chế độ Pol Pot (Khmer Đỏ), thành lập nước Cộng hòa Nhân dân Campuchia (1979)."},{"id":285,"section":"ch3-1","q":"Sau khi thống nhất đất nước, cả nước bước vào thực hiện hai nhiệm vụ chiến lược nào?","options":["Xây dựng chủ nghĩa xã hội và bảo vệ Tổ quốc xã hội chủ nghĩa","Xây dựng chủ nghĩa tư bản và bảo vệ nền độc lập dân tộc ta","Phát triển kinh tế đối ngoại và mở rộng quan hệ quốc tế rộng rãi","Củng cố quân đội và phát triển mạnh công nghiệp quốc phòng"],"answer":0,"explain":"Sau thống nhất đất nước, cả nước cùng thực hiện hai nhiệm vụ chiến lược: xây dựng chủ nghĩa xã hội và bảo vệ vững chắc Tổ quốc Việt Nam xã hội chủ nghĩa."},{"id":286,"section":"ch3-1","q":"Kế hoạch 5 năm 1976-1980 của cả nước gặp phải khó khăn chủ yếu nào?","options":["Hậu quả chiến tranh nặng nề, quản lý kém, thiên tai, chiến tranh biên giới","Không gặp khó khăn nào, hoàn thành vượt mức tất cả các chỉ tiêu kế hoạch","Chỉ gặp khó khăn về đối ngoại, còn kinh tế phát triển ổn định và vững chắc","Được viện trợ quốc tế dồi dào nên kinh tế không gặp khó khăn đáng kể nào"],"answer":0,"explain":"Kế hoạch 5 năm 1976-1980 gặp nhiều khó khăn: hậu quả chiến tranh nặng nề, cơ chế quản lý kém hiệu quả, thiên tai liên tiếp, chiến tranh biên giới Tây Nam và phía Bắc."},{"id":287,"section":"ch3-1","q":"Đại hội IV của Đảng (1976) đề ra đường lối chung của cách mạng xã hội chủ nghĩa gồm nội dung cốt lõi nào?","options":["Nắm vững chuyên chính vô sản, phát huy quyền làm chủ tập thể, tiến hành ba cuộc cách mạng","Chuyển ngay sang kinh tế thị trường tự do, thu hẹp vai trò quản lý của nhà nước","Ưu tiên phát triển kinh tế tư nhân, khuyến khích tư bản nước ngoài đầu tư vào công nghiệp","Xóa bỏ vai trò lãnh đạo của Đảng, thực hiện chế độ đa nguyên đa đảng ở Việt Nam"],"answer":0,"explain":"Đại hội IV đề ra đường lối chung: nắm vững chuyên chính vô sản, phát huy quyền làm chủ tập thể của nhân dân lao động, tiến hành đồng thời ba cuộc cách mạng, trong đó cách mạng khoa học - kỹ thuật là then chốt."},{"id":288,"section":"ch3-1","q":"Trước khi có Chỉ thị 100 (khoán 100), mô hình sản xuất nông nghiệp chủ yếu ở miền Bắc là gì?","options":["Hợp tác xã nông nghiệp theo mô hình tập thể hóa","Kinh tế hộ gia đình sản xuất tự chủ hoàn toàn","Kinh tế trang trại tư nhân quy mô lớn ở miền Bắc","Doanh nghiệp nông nghiệp nhà nước hiện đại hóa"],"answer":0,"explain":"Trước khoán 100, mô hình sản xuất nông nghiệp chủ yếu là hợp tác xã theo cơ chế tập thể hóa, quản lý tập trung, hạn chế động lực sản xuất của người lao động."},{"id":289,"section":"ch3-1","q":"Kết quả bước đầu của khoán 100 (1981) đối với sản xuất nông nghiệp là gì?","options":["Khuyến khích người lao động, bước đầu tăng năng suất và sản lượng nông nghiệp","Không tạo ra tác động nào đáng kể đến năng suất và sản lượng nông nghiệp","Làm giảm mạnh sản lượng lương thực và đời sống người nông dân cả nước","Dẫn đến giải thể hoàn toàn các hợp tác xã nông nghiệp trên cả nước ngay lập tức"],"answer":0,"explain":"Khoán 100 bước đầu tạo động lực khuyến khích người lao động, góp phần tăng năng suất và sản lượng nông nghiệp trong những năm đầu 1980."},{"id":290,"section":"ch3-1","q":"Hội nghị Trung ương 8 khóa V (6/1985) có bước đột phá gì về tư duy kinh tế?","options":["Xóa bỏ cơ chế tập trung quan liêu, bao cấp, chuyển sang hạch toán kinh doanh","Chính thức quyết định đường lối Đổi mới toàn diện, mở cửa nền kinh tế","Chủ trương duy trì cơ chế bao cấp lâu dài, tăng cường kế hoạch hóa tập trung","Quyết định quốc hữu hóa toàn bộ nền kinh tế, xóa bỏ kinh tế tư nhân"],"answer":0,"explain":"Hội nghị Trung ương 8 khóa V (6/1985) chủ trương xóa bỏ cơ chế tập trung quan liêu, bao cấp, thực hiện cơ chế hạch toán kinh doanh xã hội chủ nghĩa, coi đây là bước đột phá quan trọng."},{"id":291,"section":"ch3-1","q":"Từ năm 1975 đến 1986 được xem là giai đoạn có tính chất gì trong lịch sử Đảng?","options":["Giai đoạn đi lên chủ nghĩa xã hội trong khó khăn, khủng hoảng, chuẩn bị tiền đề cho Đổi mới","Giai đoạn phát triển ổn định, kinh tế tăng trưởng cao, không có khủng hoảng nào","Giai đoạn kháng chiến chống ngoại xâm là chủ yếu, không có xây dựng kinh tế","Giai đoạn cơ bản hoàn thành công nghiệp hóa, hiện đại hóa, đưa nước ta thành nước công nghiệp"],"answer":0,"explain":"Giai đoạn 1975-1986 là giai đoạn cả nước đi lên CNXH trong hoàn cảnh khó khăn, khủng hoảng kinh tế - xã hội, đồng thời là giai đoạn tìm tòi, chuẩn bị tiền đề tư duy cho công cuộc Đổi mới sau này."},{"id":292,"section":"ch3-1","q":"Đảng đã tổng kết bài học kinh nghiệm quan trọng nào từ thực tiễn 1975-1986 để chuẩn bị cho Đổi mới?","options":["Phải xuất phát từ thực tế, tôn trọng quy luật khách quan","Phải trung thành tuyệt đối với mô hình cũ, không điều chỉnh","Không cần đổi mới tư duy kinh tế, cứ duy trì cơ chế hiện hành","Chủ yếu dựa vào viện trợ nước ngoài để phát triển kinh tế"],"answer":0,"explain":"Bài học quan trọng được rút ra là phải luôn xuất phát từ thực tế, tôn trọng và hành động theo quy luật khách quan, đây là cơ sở tư duy quan trọng dẫn tới đường lối Đổi mới."},{"id":293,"section":"ch3-1","q":"Việt Nam gia nhập tổ chức quốc tế nào vào năm 1977, thể hiện việc hội nhập ngoại giao sau thống nhất đất nước?","options":["Liên hợp quốc (LHQ/UN)","Tổ chức ASEAN (Đông Nam Á)","Tổ chức WTO (thương mại)","Khối SEV (Tương trợ Kinh tế)"],"answer":0,"explain":"Năm 1977, Việt Nam trở thành thành viên chính thức của Liên hợp quốc, đánh dấu bước phát triển quan trọng trong quan hệ đối ngoại sau khi thống nhất đất nước."},{"id":295,"section":"ch3-1","q":"Đại hội IV của Đảng (1976) đề ra mục tiêu tổng quát trong 5 năm 1976-1980 là gì?","options":["Xây dựng cơ sở vật chất - kỹ thuật của chủ nghĩa xã hội, cải thiện đời sống nhân dân","Hoàn thành toàn bộ công nghiệp hóa, hiện đại hóa, đưa nước ta thành nước công nghiệp","Chuyển đổi hoàn toàn sang kinh tế thị trường, xóa bỏ kế hoạch hóa tập trung","Ưu tiên phát triển kinh tế đối ngoại trước tiên, mở rộng quan hệ với các nước tư bản"],"answer":0,"explain":"Đại hội IV đề ra mục tiêu: xây dựng cơ sở vật chất - kỹ thuật của CNXH, hình thành bước đầu cơ cấu kinh tế mới, cải thiện đời sống vật chất, văn hóa của nhân dân."},{"id":296,"section":"ch3-1","q":"Cuộc cải cách giá - lương - tiền năm 1985 đã dẫn tới hậu quả gì cho nền kinh tế?","options":["Gây lạm phát phi mã, làm trầm trọng thêm khủng hoảng kinh tế - xã hội","Ổn định hoàn toàn nền kinh tế, kiềm chế thành công lạm phát và giá cả","Giải quyết dứt điểm mọi khó khăn, nâng cao rõ rệt đời sống người lao động","Không tạo ra tác động đáng kể nào đến giá cả và đời sống nhân dân"],"answer":0,"explain":"Cuộc tổng điều chỉnh giá - lương - tiền năm 1985 đã gây ra tình trạng lạm phát phi mã, làm trầm trọng thêm cuộc khủng hoảng kinh tế - xã hội của đất nước."},{"id":297,"section":"ch3-1","q":"Đại hội V (3/1982) xác định nông nghiệp có vị trí như thế nào trong nền kinh tế quốc dân giai đoạn này?","options":["Nông nghiệp được xác định là mặt trận hàng đầu","Công nghiệp nặng được xác định là mặt trận hàng đầu","Dịch vụ và du lịch được xác định là mặt trận hàng đầu","Công nghiệp quốc phòng được xác định là mặt trận hàng đầu"],"answer":0,"explain":"Khác với Đại hội IV, Đại hội V (1982) xác định nông nghiệp là mặt trận hàng đầu, kết hợp nông nghiệp, công nghiệp hàng tiêu dùng và công nghiệp nặng một cách hợp lý."},{"id":298,"section":"ch3-1","q":"Trong giai đoạn 1975-1986, Việt Nam vừa phải xây dựng đất nước vừa phải đối phó với những cuộc chiến tranh nào ở biên giới?","options":["Chiến tranh biên giới Tây Nam và biên giới phía Bắc","Chỉ có chiến tranh chống Mỹ tiếp diễn ở miền Nam","Chỉ có xung đột nội bộ giữa hai miền trong nước","Chiến tranh với Lào và chiến tranh với Thái Lan"],"answer":0,"explain":"Giai đoạn này, Việt Nam phải đồng thời xây dựng đất nước và tiến hành hai cuộc chiến tranh bảo vệ Tổ quốc ở biên giới Tây Nam (chống Khmer Đỏ) và biên giới phía Bắc."},{"id":299,"section":"ch3-1","q":"Sau chiến tranh biên giới Tây Nam, Việt Nam đã giúp thành lập chính quyền nào ở Campuchia (1979)?","options":["Nước Cộng hòa Nhân dân Campuchia","Vương quốc Campuchia của Sihanouk","Chính quyền Khmer Đỏ của Pol Pot","Chính quyền quân sự của Lon Nol"],"answer":0,"explain":"Sau khi lật đổ chế độ diệt chủng Pol Pot, nước Cộng hòa Nhân dân Campuchia được thành lập vào đầu năm 1979 với sự giúp đỡ của quân tình nguyện Việt Nam."},{"id":300,"section":"ch3-1","q":"Đại hội IV (1976) khẳng định đưa cả nước đi theo con đường nào?","options":["Quá độ lên chủ nghĩa xã hội, bỏ qua chế độ tư bản chủ nghĩa","Phát triển tư bản chủ nghĩa, dựa vào vốn và kỹ thuật phương Tây","Trung lập, không theo hệ tư tưởng nào, đứng ngoài các khối quân sự","Quân chủ lập hiến, duy trì chế độ chính trị cũ ở miền Nam"],"answer":0,"explain":"Đại hội IV khẳng định đưa cả nước quá độ lên chủ nghĩa xã hội, bỏ qua giai đoạn phát triển tư bản chủ nghĩa."},{"id":301,"section":"ch3-1","q":"Việc thống nhất đất nước về mặt nhà nước hoàn thành với sự kiện nào?","options":["Kỳ họp thứ nhất Quốc hội khóa VI (6-7/1976)","Thắng lợi Chiến dịch Hồ Chí Minh (30/4/1975)","Ký kết Hiệp định Paris về Việt Nam (1/1973)","Đại hội đại biểu toàn quốc lần thứ IV (12/1976)"],"answer":0,"explain":"Việc thống nhất đất nước về mặt nhà nước hoàn thành tại kỳ họp thứ nhất, Quốc hội khóa VI (họp từ 24/6 đến 3/7/1976), quyết định tên nước, quốc kỳ, quốc ca, thủ đô."},{"id":302,"section":"ch3-1","q":"Sau khi thống nhất, thủ đô của nước Cộng hòa xã hội chủ nghĩa Việt Nam được xác định là thành phố nào?","options":["Thành phố Hà Nội","Thành phố Hồ Chí Minh","Thành phố Huế","Thành phố Đà Nẵng"],"answer":0,"explain":"Quốc hội khóa VI quyết định thủ đô của nước Cộng hòa xã hội chủ nghĩa Việt Nam là Hà Nội."},{"id":303,"section":"ch3-1","q":"Thành phố Sài Gòn - Gia Định được đổi tên thành Thành phố Hồ Chí Minh vào thời gian nào?","options":["Tháng 7/1976 (kỳ họp Quốc hội khóa VI)","Ngày 30/4/1975 (ngày giải phóng miền Nam)","Năm 1986 (sau Đại hội VI của Đảng)","Năm 1954 (sau Hiệp định Giơnevơ)"],"answer":0,"explain":"Tại kỳ họp Quốc hội khóa VI (7/1976), thành phố Sài Gòn - Gia Định chính thức được đổi tên thành Thành phố Hồ Chí Minh."},{"id":304,"section":"ch3-1","q":"Trong công tác xây dựng Đảng giai đoạn 1975-1986, một trong những hạn chế lớn được chỉ ra là gì?","options":["Bệnh chủ quan, duy ý chí, giáo điều, bảo thủ trong chỉ đạo kinh tế","Không có hạn chế nào đáng kể trong công tác lãnh đạo kinh tế - xã hội","Quá cởi mở, buông lỏng quản lý kinh tế và tài chính của quốc gia","Chỉ tập trung quá mức vào phát triển kinh tế tư nhân và cá thể trong nước"],"answer":0,"explain":"Một hạn chế lớn giai đoạn này là bệnh chủ quan, duy ý chí, lối suy nghĩ và hành động giản đơn, nóng vội, giáo điều trong lãnh đạo phát triển kinh tế - xã hội."},{"id":305,"section":"ch3-1","q":"Kế hoạch 5 năm 1981-1985 được thực hiện trong bối cảnh đất nước ra sao?","options":["Còn nhiều khó khăn, khủng hoảng kinh tế - xã hội chưa khắc phục căn bản","Kinh tế đã ổn định vững chắc, không còn khó khăn lớn nào đáng kể","Đã hoàn thành công nghiệp hóa, đời sống nhân dân được nâng cao rõ rệt","Chuyển hẳn sang cơ chế thị trường tự do, bỏ hoàn toàn kế hoạch hóa"],"answer":0,"explain":"Kế hoạch 5 năm 1981-1985 được thực hiện trong bối cảnh đất nước còn nhiều khó khăn, khủng hoảng kinh tế - xã hội chưa được khắc phục căn bản, dù đã có một số cải tiến như khoán 100."},{"id":306,"section":"ch3-1","q":"Trước Đại hội VI (1986), tình hình tư tưởng trong Đảng và xã hội như thế nào trước yêu cầu đổi mới?","options":["Có sự trăn trở, đòi hỏi bức thiết phải đổi mới tư duy, nhất là kinh tế","Hoàn toàn đồng thuận duy trì mô hình cũ, không có bất kỳ tranh luận nào","Không có bất kỳ đòi hỏi đổi mới nào, mọi người đều hài lòng với thực tiễn","Chỉ có ý kiến phản đối đổi mới, không ai đề xuất điều chỉnh cơ chế cũ"],"answer":0,"explain":"Trước Đại hội VI, trong Đảng và xã hội có sự trăn trở sâu sắc, đòi hỏi bức thiết phải đổi mới tư duy, đặc biệt là tư duy kinh tế, để đưa đất nước ra khỏi khủng hoảng."},{"id":307,"section":"ch3-1","q":"Giai đoạn 1975-1986 được đánh giá là giai đoạn có ý nghĩa gì đối với công cuộc Đổi mới sau này?","options":["Là giai đoạn chuẩn bị tiền đề tư duy và thực tiễn cho đường lối Đổi mới","Là giai đoạn không liên quan gì đến công cuộc Đổi mới sau này của Đảng","Là giai đoạn phủ định hoàn toàn con đường đi lên chủ nghĩa xã hội","Là giai đoạn đã hoàn tất công cuộc Đổi mới và chuyển sang giai đoạn mới"],"answer":0,"explain":"Giai đoạn 1975-1986, qua thực tiễn khủng hoảng và những thử nghiệm như khoán 100, hạch toán kinh doanh xã hội chủ nghĩa, đã chuẩn bị những tiền đề tư duy và thực tiễn quan trọng cho đường lối Đổi mới."},{"id":308,"section":"ch3-1","q":"Đảng Cộng sản Việt Nam là tên gọi chính thức của Đảng được sử dụng liên tục từ Đại hội nào cho đến nay?","options":["Từ Đại hội IV (1976) đến nay","Từ Đại hội II (1951) đến nay","Từ Đại hội I (1935) đến nay","Từ Đại hội VI (1986) đến nay"],"answer":0,"explain":"Tên gọi \"Đảng Cộng sản Việt Nam\" được khôi phục tại Đại hội IV (12/1976) và được sử dụng liên tục cho đến nay."},{"id":309,"section":"ch3-1","q":"Cơ chế \"hạch toán kinh doanh xã hội chủ nghĩa\" được đề ra tại Hội nghị nào, nhằm thay thế cơ chế nào?","options":["Hội nghị Trung ương 8 khóa V (6/1985), thay cơ chế tập trung, bao cấp","Đại hội VI (12/1986), thay cho cơ chế thị trường nhiều thành phần","Hội nghị Trung ương 6 khóa IV (8/1979), thay thế chế độ khoán 100","Đại hội V (3/1982), thay cho chế độ hợp tác xã và tập đoàn sản xuất"],"answer":0,"explain":"Hội nghị Trung ương 8 khóa V (6/1985) chủ trương xóa bỏ cơ chế tập trung quan liêu, bao cấp, chuyển sang hạch toán kinh doanh xã hội chủ nghĩa."},{"id":310,"section":"ch3-1","q":"Nhìn chung, giai đoạn 1975-1986 để lại bài học sâu sắc nhất về điều gì trong lãnh đạo kinh tế của Đảng?","options":["Không chủ quan, nóng vội; phải xuất phát từ thực tiễn khi hoạch định đường lối","Chỉ cần noi theo mô hình các nước xã hội chủ nghĩa anh em một cách máy móc","Chỉ cần ưu tiên mục tiêu chính trị, không cần quan tâm đến đời sống nhân dân","Chỉ cần dựa vào sức mạnh quân sự và quốc phòng để thúc đẩy phát triển kinh tế"],"answer":0,"explain":"Bài học sâu sắc nhất là không được chủ quan, nóng vội, duy ý chí; phải luôn xuất phát từ thực tiễn khách quan, tôn trọng quy luật kinh tế khi hoạch định đường lối phát triển."},{"id":708,"section":"ch3-1","q":"Đại hội đại biểu toàn quốc lần thứ IV của Đảng (12/1976) đã đổi tên Đảng Lao động Việt Nam thành tên gọi nào, và tên gọi đó được giữ nguyên đến nay?","options":["Đảng Cộng sản Việt Nam","Đảng Nhân dân Việt Nam","Đảng Cộng sản Đông Dương","Đảng Dân chủ Việt Nam"],"answer":0,"explain":"Đại hội IV (12/1976) quyết định đổi tên Đảng Lao động Việt Nam thành Đảng Cộng sản Việt Nam, tên gọi được sử dụng chính thức, liên tục cho đến ngày nay."},{"id":709,"section":"ch3-1","q":"Trong 10 năm đầu sau thống nhất đất nước (1975-1985), mô hình quản lý kinh tế chủ yếu được duy trì ở nước ta là gì?","options":["Cơ chế kế hoạch hóa tập trung, quan liêu, bao cấp kéo dài","Cơ chế thị trường tự do, không có sự quản lý của Nhà nước","Cơ chế kinh tế nhiều thành phần vận hành theo thị trường","Cơ chế kinh tế mở cửa thu hút đầu tư nước ngoài rộng rãi"],"answer":0,"explain":"Trong giai đoạn 1975-1985, nền kinh tế nước ta vận hành theo cơ chế kế hoạch hóa tập trung, quan liêu, bao cấp, ngày càng bộc lộ nhiều hạn chế, dẫn tới khủng hoảng kinh tế - xã hội trầm trọng vào cuối những năm 1970, đầu những năm 1980."},{"id":710,"section":"ch3-1","q":"Hiện tượng \"xé rào\", \"bung ra\" trong sản xuất, kinh doanh ở một số địa phương (Long An, TP. Hồ Chí Minh...) cuối những năm 1970, đầu 1980 phản ánh điều gì?","options":["Yêu cầu bức thiết phải đổi mới cơ chế quản lý kinh tế đã lỗi thời, kìm hãm sản xuất","Sự chống đối có tổ chức đối với chủ trương, đường lối chung của Đảng ở các địa phương","Chính sách chính thức được Trung ương chủ động ban hành áp dụng thống nhất trên cả nước","Biểu hiện của tình trạng mất ổn định chính trị, xã hội nghiêm trọng ở các địa phương"],"answer":0,"explain":"Những hiện tượng \"xé rào\" bung ra làm ăn theo cơ chế mới ở một số địa phương phản ánh yêu cầu khách quan, bức thiết từ thực tiễn đòi hỏi phải đổi mới cơ chế quản lý kinh tế tập trung, quan liêu, bao cấp đã trở nên lỗi thời, kìm hãm sự phát triển của lực lượng sản xuất."},{"id":711,"section":"ch3-1","q":"Đại hội V của Đảng (3/1982) đã có sự điều chỉnh bước đầu nào về nhận thức đối với cơ cấu kinh tế?","options":["Coi nông nghiệp là mặt trận hàng đầu, ưu tiên nông nghiệp và công nghiệp hàng tiêu dùng","Tiếp tục ưu tiên tuyệt đối cho công nghiệp nặng như trước đây, coi nông nghiệp là thứ yếu","Chủ trương xóa bỏ hoàn toàn vai trò của kinh tế quốc doanh, chuyển sang kinh tế tư nhân","Chủ trương chuyển hẳn sang nền kinh tế thị trường tự do ngay lập tức, bỏ kế hoạch hóa"],"answer":0,"explain":"Đại hội V (3/1982) đã có bước điều chỉnh nhận thức quan trọng, xác định nông nghiệp là mặt trận hàng đầu, từng bước sắp xếp lại cơ cấu đầu tư, coi trọng phát triển công nghiệp hàng tiêu dùng bên cạnh công nghiệp nặng, tuy nhiên quá trình đổi mới tư duy vẫn chưa triệt để."},{"id":712,"section":"ch3-1","q":"Nguyên nhân chủ yếu dẫn đến cuộc khủng hoảng kinh tế - xã hội ở nước ta cuối những năm 1970, đầu những năm 1980 là gì?","options":["Duy trì quá lâu cơ chế quản lý tập trung, bao cấp, cùng hậu quả chiến tranh và bao vây, cấm vận","Chủ yếu do thiên tai, mất mùa liên tục nhiều năm cùng dịch bệnh lan rộng trên phạm vi cả nước","Chủ yếu do những sai lầm cá nhân của một số cán bộ lãnh đạo ở địa phương và cơ sở sản xuất","Chủ yếu do chưa nhận được đủ viện trợ từ các nước và các tổ chức tài chính quốc tế"],"answer":0,"explain":"Khủng hoảng kinh tế - xã hội cuối những năm 1970, đầu 1980 bắt nguồn từ nhiều nguyên nhân, trong đó chủ yếu là việc duy trì quá lâu cơ chế quản lý tập trung, quan liêu, bao cấp không còn phù hợp, kết hợp với hậu quả nặng nề của 30 năm chiến tranh và chính sách bao vây, cấm vận của các thế lực thù địch."},{"id":713,"section":"ch3-1","q":"Giai đoạn 1975-1986 có ý nghĩa như thế nào trong tiến trình lãnh đạo cách mạng của Đảng?","options":["Là giai đoạn Đảng tìm tòi, khảo nghiệm, tích lũy tiền đề lý luận và thực tiễn cho công cuộc Đổi mới toàn diện","Là giai đoạn hoàn toàn không có ý nghĩa gì, cần phủ định sạch trơn mọi thành tựu của Đảng và nhân dân","Là giai đoạn đất nước phát triển ổn định, không gặp bất kỳ khó khăn nào trong lãnh đạo và quản lý kinh tế","Là giai đoạn chỉ có ý nghĩa về mặt quân sự, quốc phòng, không liên quan đến kinh tế - xã hội của đất nước"],"answer":0,"explain":"Mặc dù trải qua nhiều khó khăn, khủng hoảng, giai đoạn 1975-1986 có ý nghĩa quan trọng là thời kỳ Đảng tìm tòi, khảo nghiệm, từng bước hình thành tư duy đổi mới, tích lũy những tiền đề cả về lý luận và thực tiễn, chuẩn bị cho công cuộc Đổi mới toàn diện đất nước được khởi xướng từ Đại hội VI (1986)."},{"id":311,"section":"ch3-2","q":"Đại hội đại biểu toàn quốc lần thứ VI của Đảng, khởi xướng đường lối Đổi mới toàn diện, họp vào thời gian nào?","options":["Tháng 12/1986","Tháng 3/1982","Tháng 6/1991","Tháng 12/1976"],"answer":0,"explain":"Đại hội đại biểu toàn quốc lần thứ VI của Đảng họp tháng 12/1986 tại Hà Nội, khởi xướng đường lối Đổi mới toàn diện đất nước."},{"id":312,"section":"ch3-2","q":"Đại hội VI (1986) chỉ ra nguyên nhân chủ yếu của những khuyết điểm, sai lầm trong thời gian qua là gì?","options":["Bệnh chủ quan, duy ý chí; lối suy nghĩ và hành động giản đơn, nóng vội","Do sự chống phá, bao vây, cấm vận của các thế lực thù địch bên ngoài","Do thiên tai, dịch bệnh liên tục xảy ra trên phạm vi cả nước nhiều năm","Do thiếu sự lãnh đạo tập trung, thống nhất của Đảng đối với kinh tế"],"answer":0,"explain":"Đại hội VI chỉ rõ nguyên nhân chủ yếu là bệnh chủ quan, duy ý chí, lối suy nghĩ và hành động giản đơn, nóng vội chạy theo nguyện vọng chủ quan."},{"id":313,"section":"ch3-2","q":"Đại hội VI đề ra quan điểm đổi mới toàn diện, trong đó nhấn mạnh trước hết phải đổi mới về lĩnh vực nào?","options":["Đổi mới tư duy, trước hết là tư duy kinh tế","Đổi mới tư duy, trước hết là tư duy quân sự","Đổi mới tư duy, trước hết là tư duy văn hóa","Đổi mới tư duy, trước hết là tư duy hành chính"],"answer":0,"explain":"Đại hội VI nhấn mạnh phải đổi mới tư duy, trước hết là tư duy kinh tế, coi đây là khâu đột phá của công cuộc đổi mới."},{"id":314,"section":"ch3-2","q":"Đại hội VI chủ trương phát triển nền kinh tế nhiều thành phần, vận hành theo cơ chế nào?","options":["Cơ chế thị trường có sự quản lý của Nhà nước","Cơ chế kế hoạch hóa tập trung như trước đây","Cơ chế thị trường tự do, Nhà nước không can thiệp","Cơ chế bao cấp toàn diện qua chế độ tem phiếu"],"answer":0,"explain":"Đại hội VI chủ trương xóa bỏ cơ chế tập trung quan liêu bao cấp, phát triển nền kinh tế hàng hóa nhiều thành phần vận hành theo cơ chế thị trường có sự quản lý của Nhà nước."},{"id":315,"section":"ch3-2","q":"Đại hội đại biểu toàn quốc lần thứ VII của Đảng họp vào thời gian nào, thông qua văn kiện quan trọng nào?","options":["Tháng 6/1991, thông qua Cương lĩnh xây dựng đất nước thời kỳ quá độ","Tháng 12/1986, thông qua đường lối Đổi mới toàn diện đất nước","Tháng 6/1996, thông qua chiến lược đẩy mạnh công nghiệp hóa","Tháng 1/2001, thông qua chiến lược phát triển kinh tế thị trường"],"answer":0,"explain":"Đại hội VII (6/1991) họp tại Hà Nội, thông qua Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (Cương lĩnh năm 1991)."},{"id":316,"section":"ch3-2","q":"Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên CNXH (1991) xác định xã hội XHCN Việt Nam xây dựng có mấy đặc trưng?","options":["6 đặc trưng","5 đặc trưng","8 đặc trưng","10 đặc trưng"],"answer":0,"explain":"Cương lĩnh năm 1991 xác định xã hội xã hội chủ nghĩa mà nhân dân ta xây dựng có 6 đặc trưng cơ bản (do dân làm chủ, có nền kinh tế phát triển cao, có nền văn hóa tiên tiến đậm đà bản sắc dân tộc...)."},{"id":317,"section":"ch3-2","q":"Đại hội đại biểu toàn quốc lần thứ VIII của Đảng họp vào năm nào, xác định nhiệm vụ trọng tâm gì?","options":["Năm 1996, đẩy mạnh công nghiệp hóa, hiện đại hóa đất nước","Năm 1991, xây dựng Cương lĩnh và ổn định kinh tế - xã hội","Năm 2001, phát triển kinh tế thị trường định hướng XHCN","Năm 2006, đẩy mạnh hội nhập quốc tế và gia nhập WTO"],"answer":0,"explain":"Đại hội VIII (1996) xác định nhiệm vụ trọng tâm là đẩy mạnh công nghiệp hóa, hiện đại hóa đất nước, đưa nước ta ra khỏi tình trạng kém phát triển."},{"id":318,"section":"ch3-2","q":"Đại hội VIII (1996) đánh giá đất nước đã ra khỏi tình trạng gì, chuyển sang thời kỳ nào?","options":["Ra khỏi khủng hoảng kinh tế - xã hội, chuyển sang thời kỳ đẩy mạnh CNH, HĐH","Vẫn còn trong khủng hoảng kinh tế - xã hội, tiếp tục thời kỳ khắc phục khó khăn","Đã hoàn thành công nghiệp hóa, hiện đại hóa, chuyển sang thời kỳ phát triển bền vững","Ra khỏi khủng hoảng, chuyển sang nền kinh tế kế hoạch hóa tập trung trở lại"],"answer":0,"explain":"Đại hội VIII đánh giá đất nước đã ra khỏi khủng hoảng kinh tế - xã hội, chuyển sang thời kỳ mới - đẩy mạnh công nghiệp hóa, hiện đại hóa."},{"id":319,"section":"ch3-2","q":"Đại hội đại biểu toàn quốc lần thứ IX của Đảng họp vào năm nào?","options":["Năm 2001","Năm 1996","Năm 2006","Năm 1991"],"answer":0,"explain":"Đại hội đại biểu toàn quốc lần thứ IX của Đảng họp năm 2001 tại Hà Nội."},{"id":320,"section":"ch3-2","q":"Đại hội IX (2001) khẳng định mô hình kinh tế tổng quát của Việt Nam trong thời kỳ quá độ là gì?","options":["Kinh tế thị trường định hướng xã hội chủ nghĩa","Kinh tế kế hoạch hóa tập trung, bao cấp toàn diện","Kinh tế thị trường tư bản chủ nghĩa thuần túy","Kinh tế tự cung tự cấp, khép kín, đóng cửa"],"answer":0,"explain":"Đại hội IX (2001) khẳng định: kinh tế thị trường định hướng xã hội chủ nghĩa là mô hình kinh tế tổng quát của nước ta trong thời kỳ quá độ lên chủ nghĩa xã hội."},{"id":321,"section":"ch3-2","q":"Đại hội IX (2001) khẳng định nền tảng tư tưởng của Đảng gồm chủ nghĩa Mác - Lênin và tư tưởng nào?","options":["Tư tưởng Hồ Chí Minh","Tư tưởng Tôn Trung Sơn","Chủ nghĩa Tam dân","Tư tưởng dân chủ tư sản"],"answer":0,"explain":"Đại hội IX khẳng định tư tưởng Hồ Chí Minh cùng chủ nghĩa Mác - Lênin là nền tảng tư tưởng, kim chỉ nam cho hành động của Đảng."},{"id":322,"section":"ch3-2","q":"Đại hội đại biểu toàn quốc lần thứ X của Đảng họp vào thời gian nào, tại đâu?","options":["Tháng 4/2006, tại Hà Nội","Tháng 4/2001, tại Hà Nội","Tháng 4/1996, tại Hà Nội","Tháng 1/2011, tại Hà Nội"],"answer":0,"explain":"Đại hội đại biểu toàn quốc lần thứ X của Đảng họp từ ngày 18 đến 25/4/2006 tại Hà Nội."},{"id":323,"section":"ch3-2","q":"Điểm mới nổi bật của Đại hội X là gì liên quan đến đảng viên làm kinh tế tư nhân?","options":["Cho phép đảng viên làm kinh tế tư nhân, kể cả tư bản tư nhân, tuân thủ Điều lệ và pháp luật","Cấm hoàn toàn đảng viên tham gia kinh tế tư nhân, kể cả làm thuê cho tư nhân trong nước","Chỉ cho phép đảng viên làm kinh tế tập thể và kinh tế nhà nước, không được làm kinh tế tư nhân","Chỉ cho phép đảng viên đã nghỉ hưu làm kinh tế tư nhân, với điều kiện được cấp trên đồng ý"],"answer":0,"explain":"Điểm mới nổi bật của Đại hội X là cho phép đảng viên làm kinh tế tư nhân, kể cả tư bản tư nhân, nhưng yêu cầu phải tuân thủ Điều lệ Đảng, nghị quyết của Đảng và pháp luật của Nhà nước."},{"id":324,"section":"ch3-2","q":"Việt Nam chính thức trở thành thành viên của Tổ chức Thương mại Thế giới (WTO) vào thời gian nào?","options":["Tháng 11/2006","Tháng 4/2006","Tháng 1/2001","Tháng 6/1996"],"answer":0,"explain":"Tháng 11/2006, Việt Nam chính thức trở thành thành viên của Tổ chức Thương mại Thế giới (WTO), đánh dấu bước hội nhập kinh tế quốc tế sâu rộng."},{"id":325,"section":"ch3-2","q":"Đại hội X đã tổng kết bao nhiêu năm đổi mới tính đến thời điểm Đại hội (2006)?","options":["20 năm đổi mới","15 năm đổi mới","30 năm đổi mới","10 năm đổi mới"],"answer":0,"explain":"Đại hội X (2006) tổng kết 20 năm đổi mới kể từ Đại hội VI (1986), đánh giá thành tựu, hạn chế và bài học kinh nghiệm."},{"id":326,"section":"ch3-2","q":"Nghị quyết Trung ương 4 khóa X (2/2007) về Chiến lược biển Việt Nam đặt mục tiêu đến năm 2020 kinh tế biển đóng góp bao nhiêu phần trăm GDP?","options":["Khoảng 53-55% GDP","Khoảng 20-25% GDP","Khoảng 70-80% GDP","Khoảng 10% GDP"],"answer":0,"explain":"Nghị quyết số 09-NQ/TW (2/2007) về Chiến lược biển Việt Nam đến năm 2020 đặt mục tiêu kinh tế biển đóng góp khoảng 53-55% GDP, 55-60% kim ngạch xuất khẩu cả nước."},{"id":327,"section":"ch3-2","q":"Đại hội đại biểu toàn quốc lần thứ XI của Đảng họp vào thời gian nào, thông qua văn kiện quan trọng nào?","options":["Tháng 1/2011, thông qua Cương lĩnh bổ sung, phát triển năm 2011","Tháng 4/2006, thông qua Nghị quyết về công nghiệp hóa, hiện đại hóa","Tháng 1/2016, thông qua chiến lược phát triển bền vững quốc gia","Tháng 6/1991, thông qua Cương lĩnh đầu tiên của thời kỳ quá độ"],"answer":0,"explain":"Đại hội đại biểu toàn quốc lần thứ XI của Đảng họp tháng 1/2011, thông qua Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (bổ sung, phát triển năm 2011)."},{"id":328,"section":"ch3-2","q":"Cương lĩnh bổ sung, phát triển năm 2011 (Đại hội XI) xác định con đường đi lên CNXH của Việt Nam là bỏ qua giai đoạn phát triển nào?","options":["Bỏ qua chế độ tư bản chủ nghĩa (không xác lập vị trí thống trị của quan hệ sản xuất tư bản)","Bỏ qua chế độ phong kiến (không xác lập vị trí thống trị của quan hệ sản xuất phong kiến)","Bỏ qua giai đoạn công nghiệp hóa (không cần tiến hành công nghiệp hóa, hiện đại hóa đất nước)","Bỏ qua giai đoạn hội nhập quốc tế (không cần mở cửa, hợp tác với các nước trên thế giới)"],"answer":0,"explain":"Cương lĩnh 2011 khẳng định con đường đi lên CNXH là bỏ qua chế độ tư bản chủ nghĩa, tức là bỏ qua việc xác lập vị trí thống trị của quan hệ sản xuất và kiến trúc thượng tầng tư bản chủ nghĩa, nhưng tiếp thu, kế thừa những thành tựu nhân loại đạt được dưới chế độ tư bản chủ nghĩa, đặc biệt về khoa học và công nghệ."},{"id":329,"section":"ch3-2","q":"Cương lĩnh 2011 xác định động lực chủ yếu để phát triển đất nước là gì?","options":["Đại đoàn kết toàn dân, trên cơ sở liên minh công - nông - trí do Đảng lãnh đạo","Chỉ dựa vào nguồn vốn đầu tư nước ngoài và viện trợ của các tổ chức quốc tế","Chỉ dựa vào nguồn tài nguyên thiên nhiên phong phú và khai thác khoáng sản","Chỉ dựa vào lực lượng vũ trang và sức mạnh của bộ máy cưỡng chế nhà nước"],"answer":0,"explain":"Cương lĩnh 2011 xác định động lực chủ yếu để phát triển đất nước là đại đoàn kết toàn dân trên cơ sở liên minh giữa công nhân với nông dân và trí thức do Đảng lãnh đạo."},{"id":330,"section":"ch3-2","q":"Đại hội đại biểu toàn quốc lần thứ XII của Đảng họp vào thời gian nào?","options":["Tháng 1/2016","Tháng 1/2011","Tháng 1/2021","Tháng 4/2006"],"answer":0,"explain":"Đại hội đại biểu toàn quốc lần thứ XII của Đảng họp tháng 1/2016 tại Hà Nội."},{"id":331,"section":"ch3-2","q":"Đại hội đại biểu toàn quốc lần thứ XIII của Đảng họp vào thời gian nào?","options":["Tháng 1/2021","Tháng 1/2016","Tháng 1/2011","Tháng 4/2006"],"answer":0,"explain":"Đại hội đại biểu toàn quốc lần thứ XIII của Đảng họp tháng 1/2021 tại Hà Nội."},{"id":332,"section":"ch3-2","q":"Đại hội XIII (2021) xác định mục tiêu phát triển đất nước đến năm 2030 (kỷ niệm 100 năm thành lập Đảng) là gì?","options":["Là nước đang phát triển, có công nghiệp hiện đại, thu nhập trung bình cao","Là nước phát triển, có công nghiệp hiện đại, thu nhập cao, hàng đầu châu Á","Là nước công nghiệp hóa hoàn toàn theo mô hình phương Tây, thu nhập cao","Là nước dẫn đầu khu vực Đông Nam Á về mọi mặt, thu nhập cao nhất khu vực"],"answer":0,"explain":"Đại hội XIII xác định mục tiêu đến năm 2030: là nước đang phát triển, có công nghiệp hiện đại, thu nhập trung bình cao."},{"id":334,"section":"ch3-2","q":"Ai được bầu làm Tổng Bí thư tại Đại hội XIII của Đảng (1/2021)?","options":["Nguyễn Phú Trọng","Nông Đức Mạnh","Tô Lâm","Nguyễn Tấn Dũng"],"answer":0,"explain":"Tại Đại hội XIII (1/2021), đồng chí Nguyễn Phú Trọng tiếp tục được bầu làm Tổng Bí thư Ban Chấp hành Trung ương Đảng."},{"id":335,"section":"ch3-2","q":"Tổng Bí thư Nguyễn Phú Trọng từ trần vào thời gian nào?","options":["Ngày 19/7/2024","Ngày 19/5/2023","Ngày 2/9/2024","Ngày 1/1/2025"],"answer":0,"explain":"Tổng Bí thư Nguyễn Phú Trọng từ trần ngày 19/7/2024."},{"id":336,"section":"ch3-2","q":"Ai được bầu làm Tổng Bí thư Ban Chấp hành Trung ương Đảng sau khi Tổng Bí thư Nguyễn Phú Trọng từ trần (8/2024)?","options":["Tô Lâm","Phạm Minh Chính","Vương Đình Huệ","Võ Văn Thưởng"],"answer":0,"explain":"Tháng 8/2024, đồng chí Tô Lâm được bầu làm Tổng Bí thư Ban Chấp hành Trung ương Đảng Cộng sản Việt Nam."},{"id":337,"section":"ch3-2","q":"Đại hội X (2006) bầu ai làm Tổng Bí thư của Đảng?","options":["Nông Đức Mạnh","Nguyễn Phú Trọng","Lê Khả Phiêu","Đỗ Mười"],"answer":0,"explain":"Đại hội X (2006) bầu lại đồng chí Nông Đức Mạnh làm Tổng Bí thư của Đảng."},{"id":338,"section":"ch3-2","q":"Đại hội X có 1.176 đại biểu, đại diện cho hơn bao nhiêu đảng viên trong cả nước?","options":["Hơn 3,1 triệu đảng viên","Hơn 1 triệu đảng viên","Hơn 5 triệu đảng viên","Hơn 500 nghìn đảng viên"],"answer":0,"explain":"Đại hội X có 1.176 đại biểu, thay mặt cho hơn 3,1 triệu đảng viên trong cả nước."},{"id":339,"section":"ch3-2","q":"Đại hội X xác định nhiệm vụ then chốt là gì để nâng tầm Đảng ngang với trọng trách của mình?","options":["Xây dựng, chỉnh đốn Đảng","Xây dựng quân đội hiện đại","Phát triển kinh tế tư nhân","Mở rộng hợp tác quốc tế"],"answer":0,"explain":"Đại hội X xác định nhiệm vụ then chốt là xây dựng, chỉnh đốn Đảng, coi đây là thành tố đầu tiên của chủ đề Đại hội."},{"id":340,"section":"ch3-2","q":"Đảng Cộng sản Việt Nam xác định bản chất của Đảng theo Đại hội X là gì?","options":["Đội tiên phong của giai cấp công nhân, đồng thời của nhân dân lao động và của dân tộc","Chỉ là đội tiên phong của giai cấp công nhân, không đại diện cho lợi ích dân tộc","Chỉ đại diện cho lợi ích của một giai cấp duy nhất trong xã hội Việt Nam hiện nay","Là tổ chức xã hội phi chính trị, hoạt động không mang tính lãnh đạo chính trị"],"answer":0,"explain":"Đại hội X làm sáng tỏ bản chất của Đảng: Đảng Cộng sản Việt Nam là đội tiên phong của giai cấp công nhân, đồng thời là đội tiên phong của nhân dân lao động và của dân tộc Việt Nam."},{"id":341,"section":"ch3-2","q":"Hội nghị Trung ương 7 khóa IX (3/2003) đã ban hành ba nghị quyết quan trọng về vấn đề gì?","options":["Đại đoàn kết dân tộc, công tác dân tộc, công tác tôn giáo","Cải cách hành chính, cải cách tư pháp, cải cách lập pháp","Công nghiệp hóa, hiện đại hóa, hội nhập kinh tế quốc tế","Xây dựng quân đội, công an, bảo vệ quốc phòng - an ninh"],"answer":0,"explain":"Hội nghị Trung ương 7 khóa IX (3/2003) ban hành ba nghị quyết quan trọng về phát huy sức mạnh đại đoàn kết toàn dân tộc, về công tác dân tộc, và về công tác tôn giáo."},{"id":342,"section":"ch3-2","q":"Chỉ thị số 23-CT/TW (27/3/2003) của Ban Bí thư có nội dung về vấn đề gì?","options":["Đẩy mạnh nghiên cứu, tuyên truyền, giáo dục tư tưởng Hồ Chí Minh","Tiếp tục thực hiện cải cách ruộng đất và phát triển kinh tế nông thôn","Chiến lược biển Việt Nam và phát triển kinh tế biển đến năm 2020","Phát triển kinh tế tư nhân, khuyến khích đầu tư tư nhân trong nước"],"answer":0,"explain":"Chỉ thị số 23-CT/TW (27/3/2003) của Ban Bí thư về đẩy mạnh nghiên cứu, tuyên truyền, giáo dục tư tưởng Hồ Chí Minh trong giai đoạn mới."},{"id":343,"section":"ch3-2","q":"Đến năm 2002, có khoảng bao nhiêu người Việt Nam đang sinh sống ở nước ngoài?","options":["Khoảng 2,7 triệu người, ở gần 90 nước và vùng lãnh thổ","Khoảng 1,5 triệu người, ở gần 50 nước và vùng lãnh thổ","Khoảng 10 triệu người, ở hơn 150 nước và vùng lãnh thổ","Khoảng 500 nghìn người, ở gần 30 nước và vùng lãnh thổ"],"answer":0,"explain":"Đến năm 2002, có khoảng 2,7 triệu người Việt Nam đang sinh sống ở gần 90 nước và vùng lãnh thổ trên thế giới."},{"id":344,"section":"ch3-2","q":"Nghị quyết số 36-NQ/TW (26/3/2004) của Bộ Chính trị đề cập đến vấn đề gì?","options":["Công tác đối với người Việt Nam ở nước ngoài","Chiến lược bảo vệ Tổ quốc trong tình hình mới","Chiến lược biển và phát triển kinh tế biển đến 2020","Đổi mới, sắp xếp lại doanh nghiệp nhà nước"],"answer":0,"explain":"Nghị quyết số 36-NQ/TW (26/3/2004) của Bộ Chính trị về công tác đối với người Việt Nam ở nước ngoài, coi đây là bộ phận không tách rời và nguồn lực quan trọng của cộng đồng dân tộc Việt Nam."},{"id":345,"section":"ch3-2","q":"Hội nghị Trung ương 8 khóa IX (7/2003) đã ban hành văn kiện quan trọng nào về quốc phòng - an ninh?","options":["Chiến lược bảo vệ Tổ quốc trong tình hình mới","Chiến lược phát triển biển Việt Nam đến năm 2020","Nghị quyết về công tác dân tộc trong tình hình mới","Nghị quyết về công tác tôn giáo trong tình hình mới"],"answer":0,"explain":"Hội nghị Trung ương 8 khóa IX (7/2003) ban hành Chiến lược bảo vệ Tổ quốc trong tình hình mới, xác định mục tiêu, nhiệm vụ cơ bản về bảo vệ Tổ quốc xã hội chủ nghĩa."},{"id":346,"section":"ch3-2","q":"Đại hội IX (2001) tiếp tục đẩy mạnh công cuộc đổi mới, được đánh giá là bước phát triển gì so với Cương lĩnh 1991?","options":["Bước trưởng thành về nhận thức, phát triển và cụ thể hóa Cương lĩnh 1991","Bước phủ định hoàn toàn Cương lĩnh 1991 và chuyển sang đường lối mới","Bước ngoặt tách rời, không có liên hệ gì với Cương lĩnh 1991","Chỉ là sự lặp lại nguyên văn Cương lĩnh 1991, không có điểm mới nào"],"answer":0,"explain":"Đại hội IX đánh dấu bước trưởng thành trong nhận thức về vận dụng sáng tạo chủ nghĩa Mác - Lênin, tư tưởng Hồ Chí Minh, phát triển và cụ thể hóa Cương lĩnh năm 1991 của Đảng trong những năm đầu thế kỷ XXI."},{"id":347,"section":"ch3-2","q":"Sau Đại hội IX, Hội nghị Trung ương 3 khóa IX (9/2001) ban hành Nghị quyết số 05-NQ/TW về vấn đề gì?","options":["Tiếp tục sắp xếp, đổi mới, nâng cao hiệu quả doanh nghiệp nhà nước","Tiếp tục đổi mới, phát triển và nâng cao hiệu quả kinh tế tập thể","Khuyến khích, tạo điều kiện phát triển kinh tế tư nhân trong nước","Chiến lược biển Việt Nam và phát triển kinh tế biển đến năm 2020"],"answer":0,"explain":"Hội nghị Trung ương 3 khóa IX ban hành Nghị quyết số 05-NQ/TW (24/9/2001) về tiếp tục sắp xếp, đổi mới, phát triển và nâng cao hiệu quả doanh nghiệp nhà nước."},{"id":348,"section":"ch3-2","q":"Luật Đất đai được ban hành năm 1987 và sửa đổi nhiều lần sau đó nhằm mục đích gì trong giai đoạn Đổi mới?","options":["Đổi mới chính sách, pháp luật đất đai phù hợp yêu cầu công nghiệp hóa, hiện đại hóa","Thu hồi toàn bộ đất đai của nông dân để giao cho các doanh nghiệp nhà nước quản lý","Duy trì nguyên trạng chính sách đất đai thời bao cấp, không cho phép giao đất cho hộ","Tư nhân hóa hoàn toàn quyền sở hữu đất đai, bãi bỏ sở hữu toàn dân về đất đai"],"answer":0,"explain":"Sau khi Luật Đất đai (1987) được ban hành, những đổi mới trong chính sách, pháp luật về đất đai tiếp tục được thực hiện, phù hợp yêu cầu công nghiệp hóa, hiện đại hóa đất nước."},{"id":349,"section":"ch3-2","q":"Kinh tế tư nhân ở Việt Nam qua 10 năm 1991-2001 đã có sự phát triển như thế nào?","options":["Phát triển rộng khắp cả nước, đóng góp quan trọng cho kinh tế, dù còn hạn chế","Bị thu hẹp hoàn toàn do chính sách hạn chế của Nhà nước và quản lý chặt chẽ","Không có sự phát triển đáng kể nào, chỉ tồn tại ở quy mô hộ gia đình nhỏ lẻ","Chỉ tồn tại ở khu vực thành thị lớn, hoàn toàn chưa có mặt ở nông thôn"],"answer":0,"explain":"Qua 10 năm 1991-2001, kinh tế tư nhân (gồm kinh tế cá thể, tiểu chủ và tư bản tư nhân) đã phát triển rộng khắp cả nước, đóng góp quan trọng vào phát triển kinh tế, dù còn nhiều hạn chế, yếu kém."},{"id":350,"section":"ch3-2","q":"Đảng và Nhà nước chủ trương thực hiện nhất quán và lâu dài mô hình kinh tế tổng quát nào trong thời kỳ quá độ?","options":["Nền kinh tế thị trường định hướng xã hội chủ nghĩa","Nền kinh tế kế hoạch hóa tập trung, bao cấp toàn diện","Nền kinh tế thị trường tư bản chủ nghĩa thuần túy","Nền kinh tế tự cung tự cấp, đóng cửa với bên ngoài"],"answer":0,"explain":"Đảng, Nhà nước chủ trương thực hiện nhất quán và lâu dài nền kinh tế thị trường định hướng xã hội chủ nghĩa, coi đây là mô hình kinh tế tổng quát của nước ta trong thời kỳ quá độ."},{"id":351,"section":"ch3-2","q":"Chiến lược Biển Việt Nam đến năm 2020 xác định quan điểm chỉ đạo của Đảng về biển như thế nào?","options":["Nước ta phải trở thành quốc gia mạnh về biển, làm giàu từ biển","Không coi trọng kinh tế biển, chỉ khai thác thủy sản ven bờ","Chỉ tập trung phát triển kinh tế nội địa, không đầu tư cho biển","Nhường quyền khai thác biển cho nước ngoài để thu hút vốn"],"answer":0,"explain":"Quan điểm chỉ đạo của Đảng: nước ta phải trở thành quốc gia mạnh về biển, làm giàu từ biển, trên cơ sở phát huy mọi tiềm năng từ biển, phát triển toàn diện các ngành, nghề biển."},{"id":352,"section":"ch3-2","q":"Đường lối đối ngoại thời kỳ Đổi mới của Việt Nam theo tinh thần độc lập, tự chủ được thể hiện qua phương châm nào?","options":["Sẵn sàng là bạn, là đối tác tin cậy của các nước trong cộng đồng quốc tế","Chỉ quan hệ với các nước xã hội chủ nghĩa, không mở rộng sang nước khác","Đóng cửa, không quan hệ với bất kỳ quốc gia nào để bảo vệ độc lập, tự chủ","Chỉ tập trung quan hệ với một siêu cường duy nhất để bảo đảm an ninh"],"answer":0,"explain":"Đường lối đối ngoại độc lập, tự do, rộng mở của Việt Nam được thể hiện qua phương châm: \"Việt Nam sẵn sàng là bạn, là đối tác tin cậy của các nước trong cộng đồng quốc tế, phấn đấu vì hòa bình, độc lập và phát triển\"."},{"id":353,"section":"ch3-2","q":"Đại hội VI đánh dấu bước ngoặt gì trong tư duy lý luận của Đảng về con đường đi lên chủ nghĩa xã hội?","options":["Đổi mới toàn diện, đồng bộ, không giáo điều, rập khuôn máy móc","Từ bỏ hoàn toàn mục tiêu xã hội chủ nghĩa, theo con đường tư bản","Quay trở lại mô hình kinh tế kế hoạch hóa tập trung cũ, bao cấp","Chỉ đổi mới về hình thức, không đổi mới về nội dung và tư duy"],"answer":0,"explain":"Đại hội VI đánh dấu bước ngoặt trong tư duy lý luận: đổi mới toàn diện, đồng bộ, không giáo điều, rập khuôn máy móc, mà xuất phát từ thực tiễn và quy luật khách quan."},{"id":354,"section":"ch3-2","q":"Đại hội đại biểu toàn quốc lần thứ VII (1991) đã tổng kết đánh giá về 5 năm thực hiện đường lối Đổi mới (1986-1991) như thế nào?","options":["Đổi mới bước đầu đạt thành tựu quan trọng, giúp đất nước thoát khủng hoảng một bước","Đổi mới thất bại hoàn toàn, cần quay lại mô hình kinh tế bao cấp trước năm 1986","Đổi mới không mang lại bất kỳ hiệu quả nào, đất nước vẫn khủng hoảng như trước","Đổi mới chỉ có hiệu quả ở lĩnh vực văn hóa, kinh tế - xã hội không thay đổi"],"answer":0,"explain":"Đại hội VII đánh giá công cuộc Đổi mới bước đầu đạt được những thành tựu quan trọng, đưa đất nước từng bước thoát khỏi khủng hoảng kinh tế - xã hội."},{"id":355,"section":"ch3-2","q":"Đại hội XII (2016) đánh giá đất nước đã trải qua bao nhiêu năm đổi mới tính đến thời điểm Đại hội?","options":["30 năm đổi mới (1986-2016)","20 năm đổi mới (1986-2006)","25 năm đổi mới (1986-2011)","35 năm đổi mới (1986-2021)"],"answer":0,"explain":"Đại hội XII (2016) tổng kết 30 năm đổi mới (1986-2016), đánh giá những thành tựu to lớn, có ý nghĩa lịch sử cùng những hạn chế, khuyết điểm cần khắc phục."},{"id":356,"section":"ch3-2","q":"Đại hội XIII (2021) tiếp tục khẳng định nền tảng tư tưởng của Đảng là gì?","options":["Chủ nghĩa Mác - Lênin và tư tưởng Hồ Chí Minh","Chỉ chủ nghĩa Mác - Lênin, không gồm tư tưởng khác","Chỉ tư tưởng Hồ Chí Minh, không gồm học thuyết khác","Chủ nghĩa dân tộc và tư tưởng Hồ Chí Minh"],"answer":0,"explain":"Đại hội XIII tiếp tục khẳng định chủ nghĩa Mác - Lênin và tư tưởng Hồ Chí Minh là nền tảng tư tưởng, kim chỉ nam cho hành động của Đảng và cách mạng Việt Nam."},{"id":357,"section":"ch3-2","q":"Đại hội XIII xác định khát vọng phát triển đất nước gắn với các mốc thời gian nào?","options":["Năm 2025 (50 năm thống nhất), 2030 (100 năm thành lập Đảng), 2045 (100 năm lập nước)","Chỉ có mốc năm 2030 (100 năm thành lập Đảng), không đề ra thêm bất kỳ mốc nào khác","Chỉ có mốc năm 2045 (100 năm thành lập nước), không đề ra thêm bất kỳ mốc nào khác","Năm 2035 (90 năm thành lập nước) và năm 2050 (105 năm thành lập nước), không có mốc nào khác"],"answer":0,"explain":"Đại hội XIII xác định khát vọng phát triển đất nước với các mốc: đến năm 2025 (kỷ niệm 50 năm giải phóng miền Nam, thống nhất đất nước), 2030 (kỷ niệm 100 năm thành lập Đảng) và 2045 (kỷ niệm 100 năm thành lập nước)."},{"id":358,"section":"ch3-2","q":"Trong quá trình đổi mới, Đảng xác định xây dựng nền văn hóa Việt Nam theo phương hướng nào?","options":["Tiên tiến, đậm đà bản sắc dân tộc, là mục tiêu và động lực của phát triển","Chỉ tiếp thu văn hóa nước ngoài, không cần giữ gìn bản sắc dân tộc","Đóng cửa hoàn toàn với văn hóa bên ngoài, chỉ giữ văn hóa truyền thống","Chỉ phát triển văn hóa vật chất, không chú trọng văn hóa tinh thần"],"answer":0,"explain":"Đảng chủ trương xây dựng nền văn hóa Việt Nam tiên tiến, đậm đà bản sắc dân tộc, vừa là mục tiêu vừa là động lực thúc đẩy phát triển kinh tế - xã hội."},{"id":359,"section":"ch3-2","q":"Trong tiến trình Đổi mới, Đảng xác định phát triển kinh tế phải gắn liền với vấn đề gì về xã hội?","options":["Gắn tăng trưởng kinh tế với tiến bộ và công bằng xã hội","Chỉ ưu tiên tăng trưởng kinh tế, không quan tâm công bằng xã hội","Chỉ ưu tiên công bằng xã hội, không quan tâm tăng trưởng","Tách biệt hoàn toàn mục tiêu kinh tế với mục tiêu xã hội"],"answer":0,"explain":"Đảng chủ trương gắn kết hài hòa giữa tăng trưởng kinh tế với tiến bộ và công bằng xã hội, phát triển văn hóa và bảo vệ môi trường trong từng bước, từng chính sách phát triển."},{"id":360,"section":"ch3-2","q":"Đại hội XI (2011) đề ra ba đột phá chiến lược nào để phát triển đất nước?","options":["Hoàn thiện thể chế kinh tế thị trường, phát triển nguồn nhân lực, xây dựng hạ tầng đồng bộ","Phát triển nông nghiệp công nghệ cao, công nghiệp nặng, các dịch vụ tài chính - ngân hàng","Phát triển quốc phòng, an ninh, đối ngoại và hội nhập quốc tế sâu rộng, toàn diện","Phát triển văn hóa, giáo dục, y tế và bảo vệ môi trường, ứng phó biến đổi khí hậu"],"answer":0,"explain":"Đại hội XI đề ra ba đột phá chiến lược: hoàn thiện thể chế kinh tế thị trường định hướng XHCN; phát triển nhanh nguồn nhân lực; xây dựng hệ thống kết cấu hạ tầng đồng bộ."},{"id":361,"section":"ch3-2","q":"Từ Đại hội VI đến nay, đường lối đối ngoại của Việt Nam theo hướng nào?","options":["Đa phương hóa, đa dạng hóa quan hệ quốc tế, chủ động, tích cực hội nhập quốc tế","Chỉ quan hệ song phương với một nước lớn duy nhất để bảo đảm sự ổn định lâu dài","Hạn chế tối đa quan hệ đối ngoại, ưu tiên khép kín nền kinh tế để giữ độc lập","Chỉ hội nhập về văn hóa - xã hội, không hội nhập kinh tế để tránh bị phụ thuộc"],"answer":0,"explain":"Đường lối đối ngoại thời kỳ Đổi mới theo hướng đa phương hóa, đa dạng hóa quan hệ quốc tế; chủ động, tích cực hội nhập quốc tế toàn diện, sâu rộng."},{"id":362,"section":"ch3-2","q":"Việt Nam gia nhập Hiệp hội các quốc gia Đông Nam Á (ASEAN) vào năm nào?","options":["Năm 1995","Năm 1986","Năm 2006","Năm 1991"],"answer":0,"explain":"Việt Nam chính thức gia nhập ASEAN vào tháng 7 năm 1995, đánh dấu bước hội nhập khu vực quan trọng trong thời kỳ Đổi mới."},{"id":363,"section":"ch3-2","q":"Chủ đề của Đại hội X (2006) là gì?","options":["\"Nâng cao năng lực lãnh đạo và sức chiến đấu của Đảng, phát huy sức mạnh toàn dân tộc, đẩy mạnh toàn diện công cuộc đổi mới, sớm đưa nước ta ra khỏi tình trạng kém phát triển\"","\"Tiếp tục đổi mới, phát huy sức mạnh toàn dân tộc, đẩy mạnh công nghiệp hóa, hiện đại hóa, xây dựng nền tảng để nước ta cơ bản trở thành nước công nghiệp theo hướng hiện đại\"","\"Phát huy dân chủ, giữ vững kỷ cương, tăng cường đoàn kết toàn dân tộc, đẩy mạnh toàn diện công cuộc đổi mới, hội nhập kinh tế quốc tế sâu rộng, bảo vệ vững chắc độc lập, chủ quyền\"","\"Xây dựng Đảng trong sạch, vững mạnh, nâng cao năng lực lãnh đạo, phát huy sức mạnh toàn dân tộc, xây dựng đất nước phồn vinh, hạnh phúc, vững bước đi lên chủ nghĩa xã hội\""],"answer":0,"explain":"Chủ đề Đại hội X: \"Nâng cao năng lực lãnh đạo và sức chiến đấu của Đảng, phát huy sức mạnh toàn dân tộc, đẩy mạnh toàn diện công cuộc đổi mới, sớm đưa nước ta ra khỏi tình trạng kém phát triển\"."},{"id":364,"section":"ch3-2","q":"Đại hội X đề cập việc bổ sung, diễn đạt lại đặc trưng xã hội chủ nghĩa của Việt Nam so với Cương lĩnh 1991, thêm hai đặc trưng nào?","options":["Dân giàu, nước mạnh, công bằng, dân chủ, văn minh; có Nhà nước pháp quyền xã hội chủ nghĩa","Độc lập dân tộc, tự do, hạnh phúc; có nền kinh tế quốc doanh giữ vai trò duy nhất, tuyệt đối","Công nghiệp hóa, hiện đại hóa hoàn toàn; có nền kinh tế tập trung bao cấp toàn diện","Kinh tế thị trường tự do hoàn toàn; có chế độ đa nguyên, đa đảng về chính trị"],"answer":0,"explain":"Đại hội X bổ sung hai đặc trưng mới: xã hội dân giàu, nước mạnh, công bằng, dân chủ, văn minh; và có Nhà nước pháp quyền xã hội chủ nghĩa của nhân dân, do nhân dân, vì nhân dân."},{"id":365,"section":"ch3-2","q":"Trong quá trình đổi mới, hệ thống chính trị nước ta được xác định vận hành theo cơ chế nào?","options":["Đảng lãnh đạo, Nhà nước quản lý, nhân dân làm chủ","Nhà nước lãnh đạo, Mặt trận quản lý, nhân dân tham gia","Nhân dân làm chủ, Nhà nước điều hành, không cần Đảng lãnh đạo","Quân đội lãnh đạo, Nhà nước quản lý, nhân dân thực hiện"],"answer":0,"explain":"Hệ thống chính trị Việt Nam được xác định vận hành theo cơ chế: Đảng lãnh đạo, Nhà nước quản lý, nhân dân làm chủ."},{"id":366,"section":"ch3-2","q":"Sau khi trở thành thành viên WTO (11/2006), Việt Nam có cơ hội và thách thức gì theo đánh giá của Đảng?","options":["Mở rộng thị trường xuất khẩu và thu hút đầu tư, nhưng cũng phải đối mặt với cạnh tranh gay gắt hơn","Chỉ có cơ hội về thị trường và đầu tư nước ngoài, hoàn toàn không phải đối mặt với bất kỳ thách thức nào","Chỉ có thách thức do cạnh tranh gay gắt, hoàn toàn không có cơ hội mở rộng thị trường","Không tạo ra tác động gì đáng kể đến thị trường xuất khẩu, đầu tư và mức độ cạnh tranh"],"answer":0,"explain":"Việc gia nhập WTO mở ra cơ hội lớn về mở rộng thị trường xuất khẩu, thu hút đầu tư nước ngoài, đồng thời đặt ra thách thức về cạnh tranh gay gắt hơn cho nền kinh tế trong nước."},{"id":367,"section":"ch3-2","q":"Nghị quyết Trung ương 5 khóa X (2007) đề ra chủ trương gì về công tác tư tưởng, lý luận, báo chí trước yêu cầu mới?","options":["Tăng cường công tác tư tưởng, lý luận và báo chí trước yêu cầu mới của thời kỳ hội nhập","Hạn chế hoạt động báo chí, truyền thông để giữ ổn định trước yêu cầu của thời kỳ hội nhập","Xóa bỏ công tác tư tưởng, lý luận vì không còn phù hợp với yêu cầu của thời kỳ hội nhập","Chỉ tập trung công tác kinh tế, không cần quan tâm đến tư tưởng, lý luận khi hội nhập"],"answer":0,"explain":"Nghị quyết Trung ương 5 khóa X (2007) đề ra chủ trương tiếp tục công tác tư tưởng, lý luận và báo chí trước yêu cầu mới của thời kỳ hội nhập, phát triển đất nước."},{"id":368,"section":"ch3-2","q":"Trong thời kỳ Đổi mới, chủ trương xây dựng, chỉnh đốn Đảng luôn gắn liền với công tác nào?","options":["Đấu tranh phòng, chống tham nhũng, tiêu cực, suy thoái về tư tưởng chính trị, đạo đức, lối sống","Chỉ tập trung phát triển kinh tế đơn thuần, không cần gắn với việc xây dựng, chỉnh đốn nội bộ Đảng","Chỉ tập trung công tác đối ngoại, không quan tâm đến việc xây dựng nội bộ Đảng","Giảm bớt vai trò lãnh đạo của Đảng đối với Nhà nước và các đoàn thể chính trị - xã hội"],"answer":0,"explain":"Xây dựng, chỉnh đốn Đảng trong thời kỳ đổi mới luôn gắn liền với công tác đấu tranh phòng, chống tham nhũng, tiêu cực, ngăn chặn, đẩy lùi sự suy thoái về tư tưởng chính trị, đạo đức, lối sống."},{"id":369,"section":"ch3-2","q":"Đại hội XII (2016) xác định nhiệm vụ trọng tâm hàng đầu là gì?","options":["Tăng cường xây dựng, chỉnh đốn Đảng; ngăn chặn, đẩy lùi sự suy thoái về tư tưởng chính trị, đạo đức","Chỉ tập trung phát triển kinh tế đối ngoại, thu hút vốn đầu tư trực tiếp nước ngoài quy mô rất lớn","Chỉ tập trung cải cách hành chính, tinh giản bộ máy nhà nước các cấp trong toàn hệ thống","Chỉ tập trung phát triển quốc phòng, tăng cường tiềm lực quân sự và an ninh quốc gia"],"answer":0,"explain":"Đại hội XII xác định nhiệm vụ trọng tâm hàng đầu là tăng cường xây dựng, chỉnh đốn Đảng; ngăn chặn, đẩy lùi sự suy thoái về tư tưởng chính trị, đạo đức, lối sống, những biểu hiện \"tự diễn biến\", \"tự chuyển hóa\" trong nội bộ."},{"id":370,"section":"ch3-2","q":"Nghị quyết Trung ương 4 khóa XI (2012) và khóa XII (2016) đều tập trung vào nội dung nào?","options":["Xây dựng, chỉnh đốn Đảng, ngăn chặn suy thoái về tư tưởng chính trị, đạo đức, lối sống của đảng viên","Phát triển kinh tế đối ngoại, mở rộng hội nhập và thu hút đầu tư nước ngoài vào các ngành chủ lực","Cải cách chế độ tiền lương, bảo hiểm xã hội và các chính sách an sinh đối với người lao động","Xây dựng chiến lược quốc phòng mới, hiện đại hóa quân đội và bảo vệ chủ quyền biển đảo"],"answer":0,"explain":"Nghị quyết Trung ương 4 khóa XI (2012) và khóa XII (2016) đều tập trung vào công tác xây dựng, chỉnh đốn Đảng, đấu tranh ngăn chặn sự suy thoái về tư tưởng chính trị, đạo đức, lối sống trong cán bộ, đảng viên."},{"id":371,"section":"ch3-2","q":"Việt Nam ký Hiệp định Thương mại song phương với Hoa Kỳ vào thời gian nào, mở ra bước ngoặt quan hệ hai nước?","options":["Năm 2000","Năm 1995","Năm 2006","Năm 1991"],"answer":0,"explain":"Năm 2000, Việt Nam và Hoa Kỳ ký Hiệp định Thương mại song phương (BTA), mở ra bước phát triển mới trong quan hệ kinh tế - thương mại giữa hai nước."},{"id":372,"section":"ch3-2","q":"Việt Nam và Hoa Kỳ bình thường hóa quan hệ ngoại giao vào năm nào?","options":["Năm 1995","Năm 1986","Năm 2000","Năm 2006"],"answer":0,"explain":"Năm 1995, Việt Nam và Hoa Kỳ chính thức bình thường hóa quan hệ ngoại giao, mở ra giai đoạn mới trong quan hệ hai nước sau chiến tranh."},{"id":373,"section":"ch3-2","q":"Trong thời kỳ Đổi mới, Đảng xác định công nghiệp hóa, hiện đại hóa đất nước phải gắn liền với phát triển nền kinh tế gì?","options":["Kinh tế tri thức, gắn với hội nhập kinh tế quốc tế","Kinh tế nông nghiệp thuần túy, khép kín trong nước","Kinh tế bao cấp truyền thống, dựa trên kế hoạch tập trung","Kinh tế tự cung tự cấp, đóng cửa với bên ngoài"],"answer":0,"explain":"Đảng chủ trương công nghiệp hóa, hiện đại hóa đất nước phải gắn với phát triển kinh tế tri thức, đồng thời chủ động, tích cực hội nhập kinh tế quốc tế."},{"id":374,"section":"ch3-2","q":"Sau hơn 20 năm đổi mới (tính đến khoảng 2008), nông nghiệp - nông dân - nông thôn Việt Nam đạt được thành tựu ra sao, còn tồn tại vấn đề gì?","options":["Đạt thành tựu khá toàn diện, to lớn, nhưng vẫn còn phát triển kém bền vững, thiếu quy hoạch","Đạt thành tựu tuyệt đối, đã giải quyết xong mọi vấn đề, không còn tồn tại hạn chế nào","Hầu như không đạt được thành tựu đáng kể nào, nông dân và nông thôn không thay đổi gì cả","Nông nghiệp bị suy thoái hoàn toàn, nông dân phải bỏ ruộng đồng ra thành thị hàng loạt"],"answer":0,"explain":"Sau hơn 20 năm đổi mới, nông nghiệp, nông dân, nông thôn đạt thành tựu khá toàn diện và to lớn, nhưng vẫn đứng trước nhiều thách thức, phát triển còn kém bền vững, thiếu quy hoạch."},{"id":375,"section":"ch3-2","q":"Hội nghị Trung ương 6 khóa X (2008) đã ban hành Nghị quyết số 21-NQ/TW về vấn đề gì?","options":["Tiếp tục hoàn thiện thể chế kinh tế thị trường định hướng xã hội chủ nghĩa","Chiến lược biển Việt Nam đến năm 2020, tầm nhìn đến năm 2030 của đất nước","Tăng cường công tác dân tộc trong tình hình mới ở vùng dân tộc thiểu số, miền núi","Công tác đối với người Việt Nam ở nước ngoài trong thời kỳ công nghiệp hóa"],"answer":0,"explain":"Hội nghị Trung ương 6 khóa X đã ban hành Nghị quyết số 21-NQ/TW (30/1/2008) về tiếp tục hoàn thiện thể chế kinh tế thị trường định hướng xã hội chủ nghĩa."},{"id":376,"section":"ch3-2","q":"Trong thời kỳ Đổi mới, Đảng nhấn mạnh phải kết hợp chặt chẽ giữa phát triển kinh tế với nhiệm vụ nào?","options":["Bảo đảm quốc phòng, an ninh và bảo vệ môi trường","Chỉ chú trọng phát triển kinh tế, bỏ qua quốc phòng an ninh","Chỉ chú trọng quốc phòng, hạn chế phát triển kinh tế","Tách biệt hoàn toàn kinh tế với môi trường"],"answer":0,"explain":"Đảng nhấn mạnh phải kết hợp chặt chẽ giữa phát triển kinh tế - xã hội với bảo đảm quốc phòng, an ninh, hợp tác quốc tế và bảo vệ môi trường."},{"id":377,"section":"ch3-2","q":"Những thành tựu to lớn có ý nghĩa lịch sử của gần 40 năm đổi mới (1986 đến nay) là minh chứng cho điều gì?","options":["Đường lối đổi mới của Đảng là đúng đắn, sáng tạo; con đường đi lên chủ nghĩa xã hội là phù hợp","Mô hình chủ nghĩa xã hội đã lỗi thời, cần thay thế bằng một con đường phát triển khác phù hợp hơn","Việt Nam nên từ bỏ con đường xã hội chủ nghĩa để chuyển sang mô hình tư bản chủ nghĩa","Thành tựu đổi mới chủ yếu nhờ yếu tố bên ngoài, không có ý nghĩa lịch sử đáng kể nào"],"answer":0,"explain":"Những thành tựu to lớn, có ý nghĩa lịch sử của công cuộc đổi mới là minh chứng thuyết phục cho tính đúng đắn, sáng tạo của đường lối đổi mới, khẳng định con đường đi lên chủ nghĩa xã hội ở nước ta là phù hợp với thực tiễn và xu thế phát triển của thời đại."},{"id":378,"section":"ch3-2","q":"Đại hội XIII đề ra định hướng phát triển đất nước giai đoạn 2021-2030 với bao nhiêu định hướng lớn?","options":["12 định hướng lớn","6 định hướng lớn","10 định hướng lớn","20 định hướng lớn"],"answer":0,"explain":"Đại hội XIII đề ra 12 định hướng phát triển đất nước giai đoạn 2021-2030 trên các lĩnh vực kinh tế, chính trị, văn hóa, xã hội, quốc phòng, an ninh, đối ngoại."},{"id":379,"section":"ch3-2","q":"Đảng xác định nhân tố quyết định thắng lợi của công cuộc đổi mới, xây dựng và bảo vệ Tổ quốc là gì?","options":["Sự lãnh đạo đúng đắn của Đảng Cộng sản Việt Nam","Nguồn viện trợ và hợp tác quốc tế của các nước lớn","Nguồn tài nguyên thiên nhiên phong phú của đất nước","Vị trí địa lý thuận lợi ở khu vực Đông Nam Á"],"answer":0,"explain":"Đảng khẳng định sự lãnh đạo đúng đắn của Đảng là nhân tố hàng đầu quyết định mọi thắng lợi của cách mạng Việt Nam, trong đó có công cuộc đổi mới."},{"id":380,"section":"ch3-2","q":"Trong giai đoạn hội nhập quốc tế, Việt Nam theo đuổi đường lối đối ngoại độc lập, tự chủ, đa phương hóa, đa dạng hóa và là thành viên có trách nhiệm của cộng đồng quốc tế, thể hiện qua việc tham gia tổ chức nào (bên cạnh ASEAN, WTO)?","options":["Liên hợp quốc, APEC và nhiều diễn đàn hợp tác đa phương khác","Chỉ tham gia duy nhất Liên hợp quốc, không tham gia diễn đàn nào khác","Không tham gia bất kỳ tổ chức quốc tế hay diễn đàn đa phương nào khác","Chỉ tham gia các tổ chức trong phạm vi ba nước Đông Dương"],"answer":0,"explain":"Việt Nam tích cực tham gia Liên hợp quốc, Diễn đàn Hợp tác kinh tế châu Á - Thái Bình Dương (APEC) và nhiều diễn đàn, tổ chức hợp tác đa phương khác, khẳng định vai trò, vị thế trên trường quốc tế."},{"id":381,"section":"ch3-2","q":"Sau gần 40 năm đổi mới, quy mô nền kinh tế Việt Nam đã có sự thay đổi như thế nào theo đánh giá chung của Đảng?","options":["Tăng trưởng liên tục, quy mô kinh tế mở rộng đáng kể, đời sống nhân dân cải thiện rõ rệt","Hầu như không thay đổi so với trước đổi mới, đời sống nhân dân không được cải thiện","Suy giảm liên tục qua các năm, quy mô kinh tế thu hẹp, đời sống nhân dân khó khăn hơn","Chỉ tăng trưởng trong 5 năm đầu rồi suy thoái, đời sống nhân dân không cải thiện"],"answer":0,"explain":"Sau gần 40 năm đổi mới, nền kinh tế Việt Nam đã tăng trưởng liên tục, quy mô được mở rộng đáng kể, đời sống vật chất và tinh thần của nhân dân được cải thiện rõ rệt so với trước đổi mới."},{"id":382,"section":"ch3-2","q":"Đảng xác định một trong những hạn chế cần khắc phục trong quá trình đổi mới là gì?","options":["Nguy cơ tụt hậu về kinh tế; suy thoái tư tưởng chính trị, đạo đức, lối sống của một bộ phận cán bộ","Không còn tồn tại bất kỳ hạn chế hay nguy cơ nào cần khắc phục trong suốt quá trình đổi mới","Chỉ có hạn chế trong lĩnh vực quốc phòng, an ninh và đối ngoại, các lĩnh vực khác đều hoàn hảo","Chỉ có hạn chế trong lĩnh vực văn hóa - giáo dục, các lĩnh vực khác không còn hạn chế nào"],"answer":0,"explain":"Đảng xác định các nguy cơ, hạn chế cần khắc phục gồm: nguy cơ tụt hậu về kinh tế, tình trạng suy thoái về tư tưởng chính trị, đạo đức, lối sống của một bộ phận cán bộ, đảng viên, tệ quan liêu, tham nhũng."},{"id":383,"section":"ch3-2","q":"Đại hội VI được đánh giá là Đại hội có ý nghĩa như thế nào trong lịch sử Đảng Cộng sản Việt Nam?","options":["Đại hội mở đầu công cuộc đổi mới toàn diện đất nước, có ý nghĩa lịch sử trọng đại","Đại hội không có ý nghĩa đặc biệt gì, chỉ tiếp tục đường lối của thời kỳ trước đó","Đại hội chỉ có ý nghĩa về mặt tổ chức, nhân sự, không đề ra đường lối mới nào","Đại hội đánh dấu sự kết thúc vai trò lãnh đạo của Đảng đối với toàn xã hội"],"answer":0,"explain":"Đại hội VI (12/1986) được đánh giá là Đại hội có ý nghĩa lịch sử trọng đại, mở đầu công cuộc đổi mới toàn diện đất nước."},{"id":384,"section":"ch3-2","q":"Việt Nam chính thức trở thành Ủy viên không thường trực Hội đồng Bảo an Liên hợp quốc lần đầu tiên vào nhiệm kỳ nào?","options":["Nhiệm kỳ 2008-2009","Nhiệm kỳ 1995-1996","Nhiệm kỳ 2006-2007","Nhiệm kỳ 2020-2021"],"answer":0,"explain":"Việt Nam lần đầu tiên được bầu làm Ủy viên không thường trực Hội đồng Bảo an Liên hợp quốc nhiệm kỳ 2008-2009, thể hiện vị thế và uy tín quốc tế ngày càng được nâng cao."},{"id":385,"section":"ch3-2","q":"Trong đường lối đổi mới, Đảng xác định giáo dục và đào tạo, khoa học và công nghệ có vai trò như thế nào?","options":["Là quốc sách hàng đầu, động lực quan trọng để phát triển đất nước","Chỉ là lĩnh vực thứ yếu so với kinh tế, không cần ưu tiên đầu tư","Không được ưu tiên đầu tư, chỉ phát triển khi kinh tế đã đạt mức cao","Chỉ quan trọng trong thời chiến, không quan trọng trong thời bình"],"answer":0,"explain":"Đảng xác định giáo dục và đào tạo, cùng với khoa học và công nghệ, là quốc sách hàng đầu, là động lực quan trọng để phát triển đất nước trong thời kỳ Đổi mới."},{"id":386,"section":"ch3-2","q":"Đại hội XIII đề ra quan điểm phát triển với nội dung nhấn mạnh nhân dân là gì?","options":["Nhân dân là trung tâm, là chủ thể của công cuộc đổi mới, xây dựng và bảo vệ Tổ quốc","Nhân dân chỉ là đối tượng thụ hưởng thụ động thành quả của công cuộc đổi mới","Nhân dân không có vai trò trong hoạch định chính sách, chỉ chấp hành chủ trương","Chỉ có cán bộ, đảng viên mới là chủ thể của công cuộc đổi mới, xây dựng đất nước"],"answer":0,"explain":"Đại hội XIII nhấn mạnh quan điểm: nhân dân là trung tâm, là chủ thể của công cuộc đổi mới, xây dựng và bảo vệ Tổ quốc; mọi chủ trương, chính sách phải xuất phát từ lợi ích, nguyện vọng chính đáng của nhân dân."},{"id":387,"section":"ch3-2","q":"Trong tiến trình đổi mới, một trong những bài học kinh nghiệm lớn được Đảng tổng kết là gì?","options":["Kết hợp chặt chẽ ngay từ đầu đổi mới kinh tế với đổi mới chính trị, lấy đổi mới kinh tế làm trọng tâm","Chỉ tập trung đổi mới chính trị, không cần đổi mới kinh tế vì cho rằng chính trị quyết định kinh tế","Chỉ đổi mới kinh tế, không cần đổi mới bất kỳ lĩnh vực nào khác, kể cả chính trị và văn hóa","Đổi mới văn hóa trước, sau đó mới lần lượt đổi mới kinh tế rồi đến đổi mới chính trị"],"answer":0,"explain":"Bài học kinh nghiệm lớn: kết hợp chặt chẽ ngay từ đầu đổi mới kinh tế với đổi mới chính trị, lấy đổi mới kinh tế làm trọng tâm, đồng thời từng bước đổi mới chính trị."},{"id":388,"section":"ch3-2","q":"Đảng khẳng định trong thời kỳ đổi mới phải nắm vững và xử lý tốt mối quan hệ giữa các yếu tố nào?","options":["Đổi mới, ổn định và phát triển","Chỉ giữa kinh tế và chính trị","Chỉ giữa trong nước và quốc tế","Chỉ giữa nhà nước và doanh nghiệp"],"answer":0,"explain":"Đảng khẳng định phải nắm vững và xử lý tốt mối quan hệ giữa đổi mới, ổn định và phát triển, coi ổn định là tiền đề, điều kiện cho đổi mới và phát triển."},{"id":389,"section":"ch3-2","q":"Đại hội XIII xác định một trong sáu nhiệm vụ trọng tâm là gì liên quan đến xây dựng Đảng?","options":["Tiếp tục đẩy mạnh xây dựng, chỉnh đốn Đảng toàn diện về chính trị, tư tưởng, đạo đức, tổ chức và cán bộ","Giảm nhẹ vai trò lãnh đạo của Đảng đối với Nhà nước, chuyển một phần quyền lực cho xã hội","Chỉ tập trung xây dựng Đảng về mặt tổ chức và cán bộ, không cần xây dựng về chính trị, tư tưởng, đạo đức","Chuyển giao vai trò lãnh đạo cho các tổ chức xã hội khác, Đảng chỉ giữ chức năng tư vấn"],"answer":0,"explain":"Một trong sáu nhiệm vụ trọng tâm của Đại hội XIII là tiếp tục đẩy mạnh xây dựng, chỉnh đốn Đảng toàn diện về chính trị, tư tưởng, đạo đức, tổ chức và cán bộ."},{"id":390,"section":"ch3-2","q":"Trong giai đoạn hiện nay, Đảng xác định cuộc Cách mạng công nghiệp lần thứ tư đặt ra yêu cầu gì đối với Việt Nam?","options":["Chủ động, tích cực tham gia để tận dụng thời cơ, vượt qua thách thức, thúc đẩy chuyển đổi số quốc gia","Đứng ngoài cuộc, không tham gia vì lo ngại các rủi ro về an ninh, việc làm và xã hội","Chỉ tiếp nhận thụ động công nghệ từ nước ngoài, không đầu tư nghiên cứu, phát triển công nghệ trong nước","Không có tác động gì đáng kể đến Việt Nam nên không cần điều chỉnh chiến lược phát triển"],"answer":0,"explain":"Đảng xác định phải chủ động, tích cực tham gia cuộc Cách mạng công nghiệp lần thứ tư để tận dụng thời cơ, vượt qua thách thức, thúc đẩy mạnh mẽ chuyển đổi số quốc gia."},{"id":391,"section":"ch3-2","q":"Trước những biến động phức tạp của tình hình thế giới, Đảng nhấn mạnh nguyên tắc đối ngoại nào cần kiên trì thực hiện?","options":["Bảo đảm cao nhất lợi ích quốc gia - dân tộc trên cơ sở các nguyên tắc cơ bản của luật pháp quốc tế","Từ bỏ hoàn toàn các nguyên tắc đối ngoại truyền thống để đi theo xu hướng của các nước lớn","Chỉ theo đuổi lợi ích của một quốc gia đối tác duy nhất, bất kể các quy định của luật pháp quốc tế","Không cần dựa trên luật pháp quốc tế mà ưu tiên các thỏa thuận song phương bất bình đẳng"],"answer":0,"explain":"Đảng nhấn mạnh nguyên tắc đối ngoại: bảo đảm cao nhất lợi ích quốc gia - dân tộc trên cơ sở các nguyên tắc cơ bản của Hiến chương Liên hợp quốc và luật pháp quốc tế, bình đẳng, hợp tác, cùng có lợi."},{"id":392,"section":"ch3-2","q":"Kể từ Đại hội VI đến Đại hội XIII, Đảng Cộng sản Việt Nam đã trải qua bao nhiêu kỳ Đại hội toàn quốc (tính cả Đại hội VI và XIII)?","options":["8 kỳ Đại hội (VI, VII, VIII, IX, X, XI, XII, XIII)","7 kỳ Đại hội (VII, VIII, IX, X, XI, XII, XIII)","9 kỳ Đại hội (V, VI, VII, VIII, IX, X, XI, XII, XIII)","6 kỳ Đại hội (VIII, IX, X, XI, XII, XIII)"],"answer":0,"explain":"Từ Đại hội VI (1986) đến Đại hội XIII (2021), Đảng đã trải qua 8 kỳ Đại hội đại biểu toàn quốc: VI, VII, VIII, IX, X, XI, XII, XIII."},{"id":393,"section":"ch3-2","q":"Việc kiên định mục tiêu độc lập dân tộc gắn liền với chủ nghĩa xã hội trong suốt tiến trình đổi mới thể hiện điều gì?","options":["Sự nhất quán, xuyên suốt trong đường lối của Đảng qua các thời kỳ lịch sử","Sự thay đổi hoàn toàn mục tiêu cách mạng của Đảng theo từng giai đoạn lịch sử","Sự mâu thuẫn, thiếu thống nhất trong đường lối của Đảng qua các thời kỳ","Chỉ là khẩu hiệu hình thức, không có nội dung thực chất trong thực tiễn"],"answer":0,"explain":"Việc kiên định mục tiêu độc lập dân tộc gắn liền với chủ nghĩa xã hội xuyên suốt các thời kỳ, kể cả trong thời kỳ đổi mới, thể hiện sự nhất quán trong đường lối chiến lược của Đảng."},{"id":394,"section":"ch3-2","q":"Trong công cuộc đổi mới, Đảng xác định phát triển kinh tế là nhiệm vụ trung tâm, còn xây dựng Đảng là nhiệm vụ như thế nào?","options":["Nhiệm vụ then chốt, bảo đảm sự lãnh đạo đúng đắn","Nhiệm vụ thứ yếu, không cần ưu tiên nguồn lực","Nhiệm vụ chỉ mang tính hình thức, tuyên truyền","Nhiệm vụ chỉ quan trọng trong thời kỳ chiến tranh"],"answer":0,"explain":"Đảng xác định: phát triển kinh tế là nhiệm vụ trung tâm, xây dựng Đảng là nhiệm vụ then chốt, xây dựng văn hóa là nền tảng tinh thần của xã hội."},{"id":395,"section":"ch3-2","q":"Đại hội XIII đánh giá đất nước ta chưa bao giờ có được điều gì như hiện nay?","options":["Cơ đồ, tiềm lực, vị thế và uy tín quốc tế như ngày nay","Tốc độ tăng trưởng kinh tế cao nhất thế giới như hiện nay","Quy mô dân số đông nhất khu vực Đông Nam Á như hiện nay","Diện tích lãnh thổ lớn nhất khu vực Đông Nam Á như hiện nay"],"answer":0,"explain":"Đại hội XIII khẳng định: \"Đất nước ta chưa bao giờ có được cơ đồ, tiềm lực, vị thế và uy tín quốc tế như ngày nay\", đây là nhận định quan trọng khẳng định thành tựu của công cuộc đổi mới."},{"id":396,"section":"ch3-2","q":"Mục tiêu tổng quát của Đảng trong giai đoạn hiện nay là gì?","options":["Xây dựng nước Việt Nam hòa bình, độc lập, dân chủ, giàu mạnh, phồn vinh, văn minh, hạnh phúc","Chỉ tập trung tăng trưởng GDP cao nhất khu vực, xem đó là mục tiêu duy nhất của đất nước","Chỉ tập trung phát triển quân sự, quốc phòng, xem đó là mục tiêu duy nhất của đất nước","Chỉ tập trung mở rộng lãnh thổ và ảnh hưởng, xem đó là mục tiêu duy nhất của đất nước"],"answer":0,"explain":"Mục tiêu tổng quát của Đảng là xây dựng nước Việt Nam hòa bình, độc lập, dân chủ, giàu mạnh, phồn vinh, văn minh, hạnh phúc, vững bước đi lên chủ nghĩa xã hội."},{"id":397,"section":"ch3-2","q":"Nhìn lại toàn bộ lịch sử Đảng Cộng sản Việt Nam từ 1930 đến nay, nhân tố nào được xem là quyết định mọi thắng lợi của cách mạng Việt Nam?","options":["Sự lãnh đạo đúng đắn, sáng tạo của Đảng Cộng sản Việt Nam","Chỉ nhờ điều kiện địa lý, tự nhiên thuận lợi của đất nước","Chỉ nhờ sự giúp đỡ về vật chất, kỹ thuật của các nước lớn","Chỉ nhờ tinh thần dân tộc mà không cần có vai trò của Đảng"],"answer":0,"explain":"Xuyên suốt lịch sử từ 1930 đến nay, sự lãnh đạo đúng đắn, sáng tạo của Đảng Cộng sản Việt Nam luôn được khẳng định là nhân tố hàng đầu quyết định mọi thắng lợi của cách mạng Việt Nam."},{"id":398,"section":"ch3-2","q":"Việc học tập, nghiên cứu Lịch sử Đảng Cộng sản Việt Nam có ý nghĩa gì đối với sinh viên hiện nay theo mục tiêu môn học?","options":["Củng cố niềm tin vào sự lãnh đạo của Đảng, nâng cao nhận thức, trách nhiệm của thế hệ trẻ với Tổ quốc","Chỉ nhằm mục đích ghi nhớ các mốc thời gian, sự kiện lịch sử để phục vụ thi cử, kiểm tra","Không có ý nghĩa thiết thực nào đối với sinh viên trong học tập, rèn luyện và nghề nghiệp","Chỉ dành cho những sinh viên có định hướng làm cán bộ Đảng hoặc làm việc trong các cơ quan nhà nước"],"answer":0,"explain":"Việc học tập, nghiên cứu Lịch sử Đảng giúp củng cố niềm tin vào sự lãnh đạo của Đảng, nâng cao nhận thức, ý thức trách nhiệm của thế hệ trẻ trong sự nghiệp xây dựng và bảo vệ Tổ quốc."},{"id":399,"section":"ch3-2","q":"Thành tựu của gần 40 năm đổi mới góp phần khẳng định điều gì về vai trò lãnh đạo của Đảng?","options":["Khẳng định vai trò lãnh đạo đúng đắn của Đảng là nhân tố quyết định mọi thắng lợi của cách mạng","Cho thấy vai trò lãnh đạo của Đảng ngày càng mờ nhạt, không còn là nhân tố quyết định như trước nữa","Chứng minh cần giảm bớt vai trò lãnh đạo của Đảng để kinh tế phát triển nhanh hơn nữa","Không liên quan gì đến vai trò lãnh đạo của Đảng mà chủ yếu nhờ các yếu tố bên ngoài"],"answer":0,"explain":"Thành tựu to lớn của công cuộc đổi mới góp phần khẳng định vai trò lãnh đạo đúng đắn, sáng suốt của Đảng Cộng sản Việt Nam - nhân tố quyết định mọi thắng lợi của cách mạng Việt Nam trong thời kỳ mới."},{"id":400,"section":"ch3-2","q":"Trải qua các thời kỳ lịch sử từ 1930 đến nay, Đảng Cộng sản Việt Nam luôn xác định mục tiêu, lý tưởng xuyên suốt là gì?","options":["Độc lập dân tộc gắn liền với chủ nghĩa xã hội, vì hạnh phúc của nhân dân","Chỉ theo đuổi mục tiêu phát triển kinh tế đơn thuần, không gắn với lý tưởng xã hội","Mục tiêu thay đổi hoàn toàn theo từng nhiệm kỳ Đại hội, không có tính nhất quán","Chỉ nhằm mục đích duy trì quyền lực chính trị lâu dài của một nhóm người"],"answer":0,"explain":"Xuyên suốt các thời kỳ lịch sử từ 1930 đến nay, Đảng Cộng sản Việt Nam luôn kiên định mục tiêu, lý tưởng độc lập dân tộc gắn liền với chủ nghĩa xã hội, vì mục tiêu dân giàu, nước mạnh, dân chủ, công bằng, văn minh, vì hạnh phúc của nhân dân."},{"id":714,"section":"ch3-2","q":"Đại hội đại biểu toàn quốc lần thứ VI của Đảng (12/1986) đã đề ra đường lối gì có ý nghĩa bước ngoặt đối với sự phát triển của đất nước?","options":["Đường lối đổi mới toàn diện đất nước, phát triển kinh tế hàng hóa nhiều thành phần","Đường lối tiếp tục duy trì nguyên vẹn cơ chế kế hoạch hóa tập trung bao cấp","Đường lối đóng cửa, tự lực cánh sinh tuyệt đối, không hội nhập kinh tế quốc tế","Đường lối ưu tiên tuyệt đối phát triển công nghiệp nặng như trước thời kỳ đổi mới"],"answer":0,"explain":"Đại hội VI (12/1986) đã đề ra đường lối đổi mới toàn diện đất nước, đánh dấu bước ngoặt quan trọng trong sự nghiệp xây dựng chủ nghĩa xã hội ở Việt Nam, mở đầu thời kỳ đổi mới."},{"id":715,"section":"ch3-2","q":"Đại hội VI (1986) đã thẳng thắn nhìn nhận và đánh giá như thế nào về những sai lầm, khuyết điểm trước đó?","options":["Nhìn thẳng vào sự thật, đánh giá đúng sự thật, nói rõ sự thật về những sai lầm, khuyết điểm","Né tránh, không đề cập đến bất kỳ hạn chế nào của giai đoạn trước đó trong báo cáo chính trị","Chỉ đổ lỗi hoàn toàn cho các yếu tố khách quan bên ngoài, không nhận khuyết điểm chủ quan","Chỉ tổng kết thành tích, không đề cập tới sai lầm, khuyết điểm trong lãnh đạo kinh tế"],"answer":0,"explain":"Với tinh thần nhìn thẳng vào sự thật, đánh giá đúng sự thật, nói rõ sự thật, Đại hội VI đã thẳng thắn chỉ ra những sai lầm, khuyết điểm nghiêm trọng và kéo dài trong lãnh đạo kinh tế - xã hội thời kỳ trước đổi mới, tạo cơ sở để hoạch định đường lối đổi mới đúng đắn."},{"id":716,"section":"ch3-2","q":"Đại hội VI (1986) xác định thành phần kinh tế nào giữ vai trò chủ đạo trong nền kinh tế nhiều thành phần thời kỳ đầu đổi mới?","options":["Kinh tế quốc doanh (kinh tế nhà nước)","Kinh tế cá thể, tiểu chủ (kinh tế hộ gia đình)","Kinh tế tư bản tư nhân (kinh tế tư doanh)","Kinh tế có vốn đầu tư nước ngoài (liên doanh)"],"answer":0,"explain":"Trong chủ trương phát triển nền kinh tế hàng hóa nhiều thành phần tại Đại hội VI, kinh tế quốc doanh (kinh tế nhà nước) được xác định giữ vai trò chủ đạo, cùng tồn tại và phát triển bình đẳng với các thành phần kinh tế khác theo pháp luật."},{"id":717,"section":"ch3-2","q":"Đại hội VI xác định thực hiện Ba chương trình kinh tế lớn nào để ổn định tình hình kinh tế - xã hội?","options":["Lương thực - thực phẩm, hàng tiêu dùng, hàng xuất khẩu","Công nghiệp nặng, quốc phòng - an ninh, giáo dục - đào tạo","Nông nghiệp, công nghiệp, dịch vụ tài chính - ngân hàng","Khoa học - công nghệ, giáo dục - đào tạo, y tế - dân số"],"answer":0,"explain":"Để giải quyết những vấn đề cấp bách, Đại hội VI xác định thực hiện Ba chương trình kinh tế lớn: chương trình lương thực - thực phẩm, chương trình hàng tiêu dùng và chương trình hàng xuất khẩu."},{"id":718,"section":"ch3-2","q":"Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội được thông qua tại Đại hội nào của Đảng?","options":["Đại hội VII (6/1991)","Đại hội VI (12/1986)","Đại hội VIII (1996)","Đại hội IX (2001)"],"answer":0,"explain":"Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (Cương lĩnh năm 1991) được thông qua tại Đại hội đại biểu toàn quốc lần thứ VII của Đảng (6/1991), xác định những đặc trưng cơ bản của xã hội xã hội chủ nghĩa mà nhân dân ta xây dựng."},{"id":719,"section":"ch3-2","q":"Cương lĩnh năm 1991 xác định chủ nghĩa Mác - Lênin và tư tưởng nào là nền tảng tư tưởng, kim chỉ nam cho hành động của Đảng?","options":["Tư tưởng Hồ Chí Minh về cách mạng Việt Nam","Tư tưởng của các nhà triết học phương Tây","Tư tưởng Nho giáo truyền thống Việt Nam","Tư tưởng của các đảng cộng sản anh em"],"answer":0,"explain":"Đây là lần đầu tiên trong văn kiện chính thức, Đại hội VII (1991) khẳng định Đảng lấy chủ nghĩa Mác - Lênin và tư tưởng Hồ Chí Minh làm nền tảng tư tưởng, kim chỉ nam cho hành động của Đảng."},{"id":720,"section":"ch3-2","q":"Chiến lược ổn định và phát triển kinh tế - xã hội đến năm 2000 được thông qua tại Đại hội VII (1991) đặt mục tiêu tổng quát nào?","options":["Ra khỏi khủng hoảng, ổn định kinh tế - xã hội, phấn đấu vượt qua tình trạng nước nghèo, kém phát triển","Hoàn thành công nghiệp hóa, hiện đại hóa, xây dựng xong cơ sở vật chất - kỹ thuật ngay trong thập niên 1990","Đưa Việt Nam trở thành nước công nghiệp phát triển vào năm 2000, ngang tầm các nước trong khu vực","Chuyển đổi hoàn toàn sang nền kinh tế tư bản chủ nghĩa, xóa bỏ thành phần kinh tế nhà nước"],"answer":0,"explain":"Chiến lược ổn định và phát triển kinh tế - xã hội đến năm 2000 (Đại hội VII) đặt mục tiêu tổng quát là ra khỏi khủng hoảng, ổn định tình hình kinh tế - xã hội, phấn đấu vượt qua tình trạng nước nghèo, kém phát triển, cải thiện đời sống nhân dân."},{"id":721,"section":"ch3-2","q":"Trước khi bình thường hóa hoàn toàn quan hệ ngoại giao với Hoa Kỳ (1995), Việt Nam đã đạt được bước tiến quan trọng nào trong quan hệ với nước này vào đầu năm 1994?","options":["Hoa Kỳ tuyên bố bãi bỏ lệnh cấm vận thương mại đối với Việt Nam","Hoa Kỳ ký kết hiệp định thương mại song phương chính thức với Việt Nam","Hai nước thiết lập quan hệ Đối tác chiến lược toàn diện","Việt Nam gia nhập Tổ chức Thương mại Thế giới với sự bảo trợ của Hoa Kỳ"],"answer":0,"explain":"Tháng 2/1994, Tổng thống Hoa Kỳ tuyên bố bãi bỏ lệnh cấm vận thương mại kéo dài nhiều năm đối với Việt Nam, là bước đi quan trọng mở đường cho việc bình thường hóa hoàn toàn quan hệ ngoại giao giữa hai nước vào năm 1995."},{"id":722,"section":"ch3-2","q":"Việc Việt Nam gia nhập ASEAN (1995) có ý nghĩa như thế nào đối với quá trình hội nhập khu vực và quốc tế của đất nước?","options":["Đánh dấu bước phát triển quan trọng trong phá thế bị bao vây, cô lập, mở rộng hợp tác khu vực, tạo tiền đề hội nhập sâu rộng hơn","Không có tác động đáng kể tới vị thế quốc tế của Việt Nam, chỉ là một thủ tục ngoại giao thông thường trong khu vực","Chỉ mang ý nghĩa hình thức, không có hợp tác thực chất trên các lĩnh vực kinh tế, văn hóa, an ninh với các nước trong khu vực","Đánh dấu Việt Nam từ bỏ đường lối đối ngoại độc lập, tự chủ để chuyển sang phụ thuộc vào các nước lớn trong khối"],"answer":0,"explain":"Việc gia nhập ASEAN (1995) có ý nghĩa quan trọng, đánh dấu bước phát triển trong quá trình phá thế bị bao vây, cô lập về đối ngoại, mở rộng quan hệ hợp tác nhiều mặt với các nước trong khu vực, tạo tiền đề thuận lợi cho quá trình hội nhập kinh tế quốc tế sâu rộng hơn của Việt Nam sau này."},{"id":723,"section":"ch3-2","q":"Đại hội VI (1986) đánh giá như thế nào về vai trò của khoán sản phẩm trong nông nghiệp (trên cơ sở Chỉ thị 100) đối với thực tiễn phát triển kinh tế?","options":["Là bước đột phá thực tiễn, góp phần cởi trói cho sản xuất nông nghiệp, là tiền đề cho đổi mới tư duy kinh tế","Không có ý nghĩa thực tiễn, chỉ mang tính thử nghiệm cục bộ, không tác động tới tư duy đổi mới kinh tế của Đảng","Bị đánh giá là sai lầm cần loại bỏ hoàn toàn vì đi ngược nguyên tắc tập thể hóa, làm suy giảm sản xuất","Chỉ áp dụng thành công ở một địa phương duy nhất, không có khả năng nhân rộng ra các vùng khác"],"answer":0,"explain":"Thực tiễn khoán sản phẩm trong nông nghiệp (bắt đầu từ Chỉ thị 100, sau đó là Nghị quyết 10 năm 1988 - \"khoán 10\") được đánh giá là bước đột phá quan trọng, góp phần giải phóng sức sản xuất nông nghiệp, là một trong những tiền đề thực tiễn quan trọng thúc đẩy quá trình đổi mới tư duy kinh tế của Đảng."},{"id":724,"section":"ch3-2","q":"Nghị quyết 10-NQ/TW của Bộ Chính trị (4/1988), còn gọi là \"khoán 10\", có nội dung cốt lõi gì?","options":["Xác lập hộ nông dân là đơn vị kinh tế tự chủ, giao đất cho hộ sử dụng ổn định lâu dài","Xóa bỏ hoàn toàn hình thức kinh tế hợp tác xã, giao toàn bộ tài sản cho tư nhân","Quốc hữu hóa toàn bộ ruộng đất nông nghiệp trên cả nước, thu hồi đất của hộ nông dân","Chỉ áp dụng thí điểm ở một số hợp tác xã miền núi, chưa đề cập quyền sử dụng đất"],"answer":0,"explain":"Nghị quyết 10 (\"khoán 10\", 4/1988) xác lập hộ nông dân là đơn vị kinh tế tự chủ, giao quyền sử dụng ruộng đất ổn định lâu dài cho hộ gia đình, tạo động lực to lớn thúc đẩy sản xuất nông nghiệp phát triển vượt bậc, đưa Việt Nam từ chỗ thiếu lương thực trở thành nước xuất khẩu gạo."},{"id":725,"section":"ch3-2","q":"Sự sụp đổ của mô hình chủ nghĩa xã hội ở Liên Xô và các nước Đông Âu (cuối những năm 1980, đầu 1990) đặt ra thách thức gì đối với công cuộc đổi mới ở Việt Nam?","options":["Đòi hỏi Đảng kiên định mục tiêu độc lập dân tộc gắn liền chủ nghĩa xã hội, vừa đổi mới, vừa giữ vững định hướng chính trị","Buộc Việt Nam phải từ bỏ hoàn toàn con đường đi lên chủ nghĩa xã hội và chuyển sang mô hình đa nguyên, đa đảng","Không có ảnh hưởng gì đến tình hình trong nước, nên Đảng không cần điều chỉnh bất kỳ chủ trương nào trong thời kỳ đổi mới","Buộc Việt Nam phải cắt đứt hoàn toàn quan hệ với các nước xã hội chủ nghĩa còn lại để tìm viện trợ phương Tây"],"answer":0,"explain":"Trước sự sụp đổ của mô hình chủ nghĩa xã hội ở Liên Xô, Đông Âu, Đảng ta khẳng định kiên định mục tiêu độc lập dân tộc gắn liền với chủ nghĩa xã hội, kiên trì đổi mới nhưng không đổi màu, giữ vững định hướng chính trị, ổn định để phát triển đất nước."},{"id":726,"section":"ch3-2","q":"Hội nghị Trung ương 6 khóa VI (3/1989) đã khẳng định nguyên tắc nào trong quá trình đổi mới?","options":["Đổi mới toàn diện, đồng bộ nhưng giữ vững định hướng xã hội chủ nghĩa, có bước đi phù hợp","Đổi mới kinh tế phải đi liền ngay lập tức với chế độ đa nguyên, đa đảng về chính trị và xã hội","Chỉ đổi mới kinh tế, giữ nguyên hoàn toàn hệ thống chính trị cũ, không điều chỉnh bất kỳ khâu nào","Chỉ đổi mới trên lĩnh vực đối ngoại và quốc phòng, không đổi mới kinh tế, chính trị trong nước"],"answer":0,"explain":"Hội nghị Trung ương 6 khóa VI (3/1989) khẳng định nguyên tắc: đổi mới phải toàn diện, đồng bộ trên các lĩnh vực nhưng phải giữ vững định hướng xã hội chủ nghĩa, có bước đi, cách làm phù hợp, kết hợp chặt chẽ đổi mới kinh tế với đổi mới từng bước về chính trị."},{"id":727,"section":"ch3-2","q":"Đại hội VII (1991) xác định quá trình đi lên chủ nghĩa xã hội ở Việt Nam là một quá trình như thế nào?","options":["Lâu dài, trải qua nhiều chặng đường, nhiều hình thức tổ chức kinh tế - xã hội có tính chất quá độ","Ngắn hạn, không cần nhiều chặng đường, có thể hoàn thành nhanh chóng trong vài kế hoạch 5 năm","Không cần trải qua thời kỳ quá độ nào, có thể chuyển thẳng lên chủ nghĩa cộng sản ngay lập tức","Chỉ cần sao chép nguyên mẫu mô hình của Liên Xô và các nước xã hội chủ nghĩa khác, không cần sáng tạo"],"answer":0,"explain":"Cương lĩnh 1991 (Đại hội VII) xác định đi lên chủ nghĩa xã hội ở nước ta là một quá trình lâu dài, trải qua nhiều chặng đường, phải sử dụng nhiều hình thức kinh tế trung gian, quá độ phù hợp với trình độ phát triển thực tế của lực lượng sản xuất."},{"id":728,"section":"ch3-2","q":"Bên cạnh Cương lĩnh xây dựng đất nước, Đại hội VII (1991) còn thông qua văn kiện chiến lược quan trọng nào?","options":["Chiến lược ổn định và phát triển kinh tế - xã hội đến năm 2000","Cương lĩnh chính trị đầu tiên của Đảng do Nguyễn Ái Quốc soạn thảo","Luận cương chính trị của Đảng do Trần Phú soạn thảo năm 1930","Nghị quyết về chỉnh đốn Đảng lần đầu tiên sau khi giành chính quyền"],"answer":0,"explain":"Cùng với Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội, Đại hội VII (1991) còn thông qua Chiến lược ổn định và phát triển kinh tế - xã hội đến năm 2000, cụ thể hóa các mục tiêu, giải pháp phát triển đất nước trong thập niên cuối thế kỷ XX."},{"id":729,"section":"ch3-2","q":"Trong 5 năm đầu thực hiện đường lối đổi mới (1986-1990), thành tựu nổi bật nhất về lương thực là gì?","options":["Từ thiếu lương thực triền miên, năm 1989 Việt Nam đủ nhu cầu trong nước và bắt đầu xuất khẩu gạo","Vẫn tiếp tục thiếu lương thực trầm trọng như trước đổi mới, phải nhập khẩu gạo hằng năm","Phải nhập khẩu lương thực với số lượng lớn hơn trước đổi mới do sản xuất trong nước giảm sút","Chuyển hoàn toàn sang nhập khẩu lương thực thay vì tự sản xuất, nông nghiệp bị thu hẹp"],"answer":0,"explain":"Nhờ những chính sách đổi mới trong nông nghiệp, sản xuất lương thực có bước phát triển vượt bậc: từ chỗ thiếu ăn triền miên, năm 1989 Việt Nam đã cơ bản đáp ứng nhu cầu lương thực trong nước và lần đầu tiên xuất khẩu gạo, khẳng định hướng đi đúng đắn của công cuộc đổi mới."},{"id":730,"section":"ch3-2","q":"Ý nghĩa lịch sử của 10 năm đầu thực hiện đường lối đổi mới (1986-1996) là gì?","options":["Đưa đất nước ra khỏi khủng hoảng kinh tế - xã hội, tạo tiền đề đẩy mạnh công nghiệp hóa, hiện đại hóa","Chưa đạt kết quả đáng kể, đất nước vẫn trong khủng hoảng sâu sắc nên chưa thể chuyển sang thời kỳ mới","Chỉ giải quyết được vấn đề lương thực, chưa có chuyển biến trên các lĩnh vực khác của đời sống","Chỉ có ý nghĩa đối với khu vực nông nghiệp, nông thôn, chưa tác động tới công nghiệp, dịch vụ"],"answer":0,"explain":"Qua 10 năm đổi mới (1986-1996), đất nước đã cơ bản ra khỏi khủng hoảng kinh tế - xã hội, đạt được những thành tựu quan trọng trên nhiều lĩnh vực, tạo tiền đề cần thiết để Đại hội VIII (1996) đưa đất nước chuyển sang thời kỳ đẩy mạnh công nghiệp hóa, hiện đại hóa."},{"id":731,"section":"ch3-2","q":"Đại hội VIII của Đảng (6/1996) đã đưa ra nhận định quan trọng gì về chặng đường phát triển của đất nước?","options":["Nước ta đã ra khỏi khủng hoảng kinh tế - xã hội, chuyển sang thời kỳ đẩy mạnh công nghiệp hóa, hiện đại hóa","Đất nước vẫn còn trong tình trạng khủng hoảng kinh tế - xã hội nghiêm trọng, chưa thể đẩy mạnh công nghiệp hóa","Nước ta đã hoàn thành công nghiệp hóa, hiện đại hóa, trở thành nước công nghiệp phát triển trong khu vực","Cần quay trở lại mô hình kinh tế kế hoạch hóa tập trung, bao cấp như trước thời kỳ đổi mới"],"answer":0,"explain":"Đại hội VIII (6/1996) nhận định nhiệm vụ đề ra cho chặng đường đầu của thời kỳ quá độ đã cơ bản hoàn thành, đưa nước ta ra khỏi khủng hoảng kinh tế - xã hội, chuyển sang thời kỳ mới - đẩy mạnh công nghiệp hóa, hiện đại hóa đất nước."},{"id":732,"section":"ch3-2","q":"Đại hội IX (2001) xác định thành phần kinh tế nhà nước cùng với thành phần kinh tế nào giữ vai trò nền tảng của nền kinh tế quốc dân?","options":["Kinh tế tập thể, với hợp tác xã là nòng cốt","Kinh tế cá thể, tiểu chủ, với hộ gia đình là nòng cốt","Kinh tế tư bản tư nhân, với doanh nghiệp tư là nòng cốt","Kinh tế có vốn nước ngoài, với liên doanh là nòng cốt"],"answer":0,"explain":"Đại hội IX (2001) xác định kinh tế nhà nước cùng với kinh tế tập thể ngày càng trở thành nền tảng vững chắc của nền kinh tế quốc dân trong nền kinh tế thị trường định hướng xã hội chủ nghĩa nhiều thành phần."},{"id":733,"section":"ch3-2","q":"Trước khi chính thức gia nhập WTO (2007), Việt Nam đã phải trải qua quá trình đàm phán kéo dài trong khoảng thời gian bao lâu, kể từ khi nộp đơn xin gia nhập?","options":["Khoảng 11 năm (nộp đơn năm 1995, gia nhập năm 2007)","Khoảng 1 năm (nộp đơn năm 2006, gia nhập năm 2007)","Khoảng 20 năm (nộp đơn năm 1987, gia nhập năm 2007)","Khoảng 3 năm (nộp đơn năm 2004, gia nhập năm 2007)"],"answer":0,"explain":"Việt Nam nộp đơn xin gia nhập WTO từ năm 1995 và trải qua quá trình đàm phán song phương, đa phương kéo dài khoảng 11 năm với nhiều đối tác thương mại trước khi chính thức trở thành thành viên WTO vào năm 2007."},{"id":734,"section":"ch3-2","q":"Đại hội X của Đảng (4/2006) đã có chủ trương đổi mới quan trọng nào về công tác xây dựng Đảng?","options":["Cho phép đảng viên làm kinh tế tư nhân, kể cả kinh tế tư bản tư nhân","Cấm đảng viên tham gia mọi hoạt động kinh tế tư nhân, kể cả kinh doanh nhỏ","Giải thể các tổ chức đảng trong các doanh nghiệp tư nhân và liên doanh","Quốc hữu hóa toàn bộ khu vực kinh tế tư nhân và các doanh nghiệp tư bản"],"answer":0,"explain":"Đại hội X (2006) có chủ trương đổi mới quan trọng, cho phép đảng viên được làm kinh tế tư nhân, kể cả kinh tế tư bản tư nhân, nhằm phát huy mọi nguồn lực xã hội cho phát triển, đồng thời tăng cường công tác xây dựng, chỉnh đốn Đảng."},{"id":735,"section":"ch3-2","q":"Bên cạnh công tác tư tưởng, lý luận, báo chí, Đại hội X (2006) còn đặc biệt nhấn mạnh yêu cầu đấu tranh phòng, chống hiện tượng tiêu cực nào trong đội ngũ cán bộ, đảng viên?","options":["Tệ tham nhũng, lãng phí, quan liêu, xa rời quần chúng","Tệ lười học ngoại ngữ, ngại tiếp cận tri thức khoa học mới","Tệ yếu kỹ năng tin học, chậm ứng dụng công nghệ thông tin","Tệ chưa hòa nhập văn hóa quốc tế, ngại giao lưu đối ngoại"],"answer":0,"explain":"Đại hội X (2006) đặc biệt nhấn mạnh yêu cầu kiên quyết đấu tranh phòng, chống tệ tham nhũng, lãng phí, quan liêu, xa rời quần chúng trong đội ngũ cán bộ, đảng viên, coi đây là nguy cơ đe dọa sự tồn vong của Đảng và chế độ."},{"id":736,"section":"ch3-2","q":"Nghị quyết Trung ương 4 khóa XI (1/2012, đầu nhiệm kỳ Đại hội XI) tập trung giải quyết vấn đề cấp bách nào trong xây dựng Đảng?","options":["Vấn đề cấp bách về xây dựng Đảng, nhất là suy thoái tư tưởng chính trị, đạo đức, lối sống","Vấn đề cấp bách về công tác đối ngoại, nhất là việc mở rộng quan hệ với các nước lớn trong khu vực và trên thế giới","Vấn đề cấp bách về kinh tế đối ngoại, nhất là thu hút vốn đầu tư nước ngoài vào các ngành công nghiệp then chốt","Vấn đề cấp bách về đào tạo cán bộ trẻ, nhất là chuẩn bị nguồn nhân sự cho nhiệm kỳ Đại hội tiếp theo của Đảng"],"answer":0,"explain":"Nghị quyết Trung ương 4 khóa XI (2012) \"Một số vấn đề cấp bách về xây dựng Đảng hiện nay\" thẳng thắn chỉ ra tình trạng suy thoái về tư tưởng chính trị, đạo đức, lối sống của một bộ phận không nhỏ cán bộ, đảng viên, đề ra các nhóm giải pháp khắc phục."},{"id":737,"section":"ch3-2","q":"Trong giai đoạn 1996-2011, Việt Nam đã ký kết Hiệp định Thương mại song phương quan trọng với quốc gia nào, có hiệu lực từ năm 2001, thúc đẩy mạnh mẽ quan hệ kinh tế - thương mại?","options":["Hiệp định Thương mại song phương Việt Nam - Hoa Kỳ (BTA)","Hiệp định Thương mại tự do Việt Nam - Liên minh châu Âu (EVFTA)","Hiệp định Đối tác Toàn diện xuyên Thái Bình Dương (CPTPP)","Hiệp định Thương mại tự do ASEAN - Trung Quốc (ACFTA)"],"answer":0,"explain":"Hiệp định Thương mại song phương Việt Nam - Hoa Kỳ (BTA) được ký năm 2000, có hiệu lực từ tháng 12/2001, tạo bước ngoặt quan trọng thúc đẩy quan hệ kinh tế - thương mại giữa hai nước, mở đường cho quá trình đàm phán gia nhập WTO của Việt Nam."},{"id":738,"section":"ch3-2","q":"Đại hội X (2006) đã tổng kết và bổ sung bao nhiêu đặc trưng của xã hội xã hội chủ nghĩa mà nhân dân ta xây dựng, so với Cương lĩnh 1991?","options":["Từ 6 đặc trưng (Cương lĩnh 1991) lên 8 đặc trưng, được bổ sung, phát triển","Giữ nguyên 6 đặc trưng của Cương lĩnh 1991, không bổ sung, phát triển nào","Giảm từ 6 đặc trưng (Cương lĩnh 1991) xuống còn 2 đặc trưng cơ bản nhất","Bỏ toàn bộ đặc trưng của Cương lĩnh 1991, không nêu lại đặc trưng nào"],"answer":0,"explain":"Qua các kỳ Đại hội, trên cơ sở tổng kết thực tiễn, nhận thức của Đảng về các đặc trưng của xã hội xã hội chủ nghĩa mà nhân dân ta xây dựng (nêu lần đầu trong Cương lĩnh 1991 với 6 đặc trưng) tiếp tục được bổ sung, phát triển toàn diện, sâu sắc hơn qua các văn kiện Đại hội tiếp theo."},{"id":739,"section":"ch3-2","q":"Chủ trương chủ động, tích cực hội nhập kinh tế quốc tế được Đảng ta xác định là một nội dung quan trọng trong đường lối đối ngoại thời kỳ nào?","options":["Thời kỳ đẩy mạnh công nghiệp hóa, hiện đại hóa từ sau Đại hội VIII (1996) đến nay","Thời kỳ trước đổi mới giai đoạn 1975-1985, khi cả nước thực hiện cơ chế kế hoạch hóa tập trung","Thời kỳ kháng chiến chống Mỹ cứu nước 1954-1975, khi miền Bắc xây dựng chủ nghĩa xã hội","Thời kỳ kháng chiến chống Pháp 1946-1954, khi tập trung toàn lực cho nhiệm vụ quân sự"],"answer":0,"explain":"Từ Đại hội VIII (1996) trở đi, cùng với chủ trương đẩy mạnh công nghiệp hóa, hiện đại hóa, Đảng xác định chủ động, tích cực hội nhập kinh tế quốc tế là một nội dung quan trọng, xuyên suốt trong đường lối đối ngoại, mở rộng quan hệ, thu hút nguồn lực cho phát triển đất nước."},{"id":740,"section":"ch3-2","q":"Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (bổ sung, phát triển năm 2011) được thông qua tại Đại hội nào?","options":["Đại hội XI (1/2011)","Đại hội VII (1991)","Đại hội XII (2016)","Đại hội X (2006)"],"answer":0,"explain":"Đại hội XI (1/2011) đã thông qua Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (bổ sung, phát triển năm 2011), kế thừa và phát triển Cương lĩnh năm 1991 phù hợp với tình hình mới."},{"id":741,"section":"ch3-2","q":"Đại hội XII (2016) tiếp tục khẳng định và cụ thể hóa mô hình tăng trưởng kinh tế theo hướng nào để khắc phục hạn chế của mô hình tăng trưởng cũ?","options":["Đổi mới mô hình tăng trưởng, cơ cấu lại nền kinh tế, kết hợp chiều rộng với chiều sâu","Duy trì mô hình tăng trưởng dựa vào khai thác tài nguyên, xuất khẩu thô, lao động giá rẻ","Quay lại mô hình kế hoạch hóa tập trung, bao cấp, chỉ huy hành chính như trước đổi mới","Ưu tiên tăng trưởng bằng mọi giá, mở rộng tín dụng ồ ạt, không quan tâm chất lượng"],"answer":0,"explain":"Đại hội XII (2016) chủ trương đổi mới mô hình tăng trưởng, cơ cấu lại nền kinh tế gắn với nâng cao chất lượng, hiệu quả và sức cạnh tranh, chuyển dần từ tăng trưởng chủ yếu theo chiều rộng (dựa vào vốn, tài nguyên, lao động giá rẻ) sang kết hợp hài hòa giữa chiều rộng và chiều sâu (dựa vào năng suất, khoa học công nghệ)."},{"id":742,"section":"ch3-2","q":"Đại hội XIII của Đảng (1/2021) đã xác định tầm nhìn, mục tiêu phát triển đất nước đến giữa thế kỷ XXI (năm 2045) là gì?","options":["Trở thành nước phát triển, thu nhập cao, theo định hướng xã hội chủ nghĩa","Vẫn là nước đang phát triển, thu nhập trung bình thấp, còn phụ thuộc nhiều","Giữ nguyên trạng như hiện tại, chưa đặt ra mục tiêu phát triển cụ thể nào","Là nước nông nghiệp là chủ yếu, chưa hoàn thành quá trình công nghiệp hóa"],"answer":0,"explain":"Đại hội XIII (1/2021) xác định tầm nhìn và định hướng đến năm 2045 (kỷ niệm 100 năm thành lập nước): phấn đấu đưa nước ta trở thành nước phát triển, thu nhập cao."},{"id":743,"section":"ch3-2","q":"Đại hội XIII (2021) tiếp tục khẳng định và bổ sung nội dung nào về mối quan hệ giữa Đảng với nhân dân?","options":["Kiên định quan điểm \"dân là gốc\", phát huy sức mạnh đại đoàn kết toàn dân tộc, gắn bó với nhân dân","Xem vai trò của nhân dân chỉ là lực lượng hỗ trợ, tập trung vào sức mạnh của bộ máy nhà nước","Tách vai trò lãnh đạo của Đảng khỏi ý chí, nguyện vọng của nhân dân, để Đảng chỉ lo công tác nội bộ","Thay thế cơ chế Đảng lãnh đạo bằng cơ chế đa nguyên, đa đảng nhằm mở rộng sự tham gia của nhân dân"],"answer":0,"explain":"Đại hội XIII tiếp tục khẳng định, bổ sung quan điểm \"dân là gốc\", coi trọng phát huy sức mạnh đại đoàn kết toàn dân tộc, thực hành và phát huy rộng rãi dân chủ xã hội chủ nghĩa, tăng cường mối quan hệ mật thiết giữa Đảng với nhân dân."},{"id":744,"section":"ch3-2","q":"Từ Đại hội XI đến nay, Đảng ta xác định một trong những nhiệm vụ trọng tâm là đẩy mạnh xây dựng Nhà nước pháp quyền xã hội chủ nghĩa theo hướng nào?","options":["Của nhân dân, do nhân dân, vì nhân dân, do Đảng lãnh đạo, thượng tôn Hiến pháp và pháp luật","Nhà nước tam quyền phân lập hoàn toàn độc lập theo mô hình phương Tây, không chịu sự lãnh đạo của Đảng","Nhà nước liên bang với các đơn vị hành chính có chủ quyền riêng, tự quyết định chính sách đối nội, đối ngoại","Nhà nước quân chủ lập hiến với vai trò biểu tượng của người đứng đầu, quyền lực chủ yếu thuộc nghị viện"],"answer":0,"explain":"Đảng ta xác định nhất quán mục tiêu xây dựng và hoàn thiện Nhà nước pháp quyền xã hội chủ nghĩa Việt Nam của nhân dân, do nhân dân, vì nhân dân, do Đảng Cộng sản Việt Nam lãnh đạo, thượng tôn Hiến pháp và pháp luật, bảo đảm quyền làm chủ thực sự của nhân dân."},{"id":745,"section":"ch3-2","q":"Nhìn lại chặng đường gần 40 năm đổi mới (từ 1986 đến nay), Đảng ta khẳng định bài học kinh nghiệm bao trùm, xuyên suốt nào?","options":["Kiên định, vận dụng sáng tạo chủ nghĩa Mác - Lênin, tư tưởng Hồ Chí Minh; độc lập dân tộc gắn liền chủ nghĩa xã hội","Kiên trì mô hình kinh tế đã chọn, không cần đổi mới tư duy lý luận và tư tưởng, giữ nguyên cách làm cũ trong mọi lĩnh vực","Sao chép nguyên mô hình phát triển của một quốc gia khác, không cần gắn với điều kiện thực tiễn của Việt Nam","Không cần tổng kết thực tiễn, chỉ dựa hoàn toàn vào lý luận có sẵn, bỏ qua yêu cầu đổi mới tư duy của Đảng"],"answer":0,"explain":"Tổng kết gần 40 năm đổi mới, Đảng khẳng định bài học bao trùm, xuyên suốt là phải kiên định và vận dụng, phát triển sáng tạo chủ nghĩa Mác - Lênin, tư tưởng Hồ Chí Minh; kiên định mục tiêu độc lập dân tộc gắn liền với chủ nghĩa xã hội; đồng thời không ngừng đổi mới tư duy, sáng tạo trên cơ sở tổng kết thực tiễn."}]};
